import{n as e}from"./rolldown-runtime-8BhlS34s.js";var t;function n(){return(n=e((()=>{t={configHints:{acp:{label:{"v1-w1ybzr-3":`ACP`},help:{"v1-gwlf91-44":`Yönlendirmeyi etkinleştirmek, arka uçları seçmek, izin verilen ajan hedeflerini sınırlamak ve akış hâlindeki tur yansıtma davranışını seçmek için ACP çalışma zamanı denetimleri.`}},"acp%2EallowedAgents":{label:{"v1-nvlwwz-i":`ACP İzin Verilen Ajanlar`},help:{"v1-f2mw0d-3a":`ACP çalışma zamanı oturumlarında kullanılmasına izin verilen ACP hedef ajan kimliklerinin listesi. Boş bırakıldığında ek bir izin listesi kısıtlaması uygulanmaz.`}},"acp%2Ebackend":{label:{"v1-vx60lb-b":`ACP Arka Ucu`},help:{"v1-1s1l6bz-2v":`Varsayılan ACP çalışma zamanı arka uç kimliği (örneğin: acpx). Kayıtlı bir ACP çalışma zamanı eklentisi arka ucuyla eşleşmelidir.`}},"acp%2EdefaultAgent":{label:{"v1-xso6e7-h":`ACP Varsayılan Ajanı`},help:{"v1-7donnu-2c":`ACP başlatma işlemlerinde açıkça bir hedef belirtilmediğinde kullanılan yedek ACP hedef ajan kimliği.`}},"acp%2Edispatch%2Eenabled":{label:{"v1-nw9kyy-k":`ACP Yönlendirmesi Etkin`},help:{"v1-1ug9t9m-3w":`ACP oturum turları için bağımsız yönlendirme denetimi (varsayılan: true). ACP turlarının yürütülmesini engellerken ACP komutlarını kullanılabilir tutmak için false olarak ayarlayın.`}},"acp%2Eenabled":{label:{"v1-5j1g3y-b":`ACP Etkin`},help:{"v1-1uonl1v-2a":`Genel ACP özellik denetimi. ACP çalışma zamanı ve ilkesi yapılandırılmadıkça devre dışı tutun.`}},"acp%2Efallbacks":{label:{"v1-j79b6g-l":`ACP Yedek Arka Uçları`},help:{"v1-1wvdifq-5m":`Birincil arka uç UNAVAILABLE hatasıyla başarısız olduğunda (örneğin: istek sınırı / kota tükenmesi) denenecek yedek ACP arka uç kimliklerinin sıralı listesi. Her girdi, kayıtlı bir ACP çalışma zamanı eklentisinin arka ucuyla eşleşmelidir.`}},"acp%2Eruntime%2EinstallCommand":{label:{"v1-14jcqqd-r":`ACP Çalışma Zamanı Kurulum Komutu`},help:{"v1-1jjuv9m-39":"ACP arka uç bağlantısı eksik olduğunda `/acp install` ve `/acp doctor` tarafından gösterilen, operatöre yönelik isteğe bağlı yükleme/kurulum komutu."}},"acp%2Estream":{label:{"v1-1j9fe39-a":`ACP Akışı`},help:{"v1-1bka5p-2v":`Parça boyutu, meta veri görünürlüğü ve yinelenen öğelerden arındırılmış iletim davranışı için ACP akış yansıtma denetimleri.`}},"acp%2Estream%2EdeliveryMode":{label:{"v1-mfvqy2-o":`ACP Akışı İletim Modu`},help:{"v1-19gdmx1-3s":`ACP iletim biçimi: live, yansıtılan çıktıyı aşamalı olarak aktarır; final_only, yansıtılan tüm ACP çıktısını tur sonu olaylarına kadar arabellekte tutar.`}},"acp%2Estream%2ErepeatSuppression":{label:{"v1-15imczj-t":`ACP Akışında Tekrarları Bastırma`},help:{"v1-manh32-3d":`true olduğunda (varsayılan), ham ACP olaylarını değiştirmeden bir tur içinde yinelenen ACP durum/araç yansıtma satırlarını bastırır.`}},"acp%2Estream%2EtagVisibility":{label:{"v1-6o90yj-p":`ACP Akışı Etiket Görünürlüğü`},help:{"v1-1ybhx22-34":`ACP yansıtması için sessionUpdate bazında görünürlük geçersiz kılmaları (örneğin usage_update, available_commands_update).`}},agents:{label:{"v1-1sa8ub3-6":`Ajanlar`},help:{"v1-2rc4v8-55":`Ajan çalışma zamanı yapılandırmasının kökü. Kökle aynı düzeydeki öğeler altyapıyı ve ajanlar arası varsayılanları yönetir; agents.defaults, ajan döngüsü davranışını yönetir; ajan girdileri, desteklenen yerlerde her ikisini de geçersiz kılabilir.`}},"agents%2Edefaults":{label:{"v1-16khodg-e":`Ajan Varsayılanları`},help:{"v1-1af7k5b-5a":`agents.entries içindeki girdilerde geçersiz kılınmadıkça ajanlar tarafından devralınan ortak varsayılan ayarlar. Tutarlı bir temel davranış sağlamak ve ajan başına yinelenen yapılandırmayı azaltmak için varsayılanları kullanın.`}},"agents%2Edefaults%2EauthInheritance":{label:{"v1-9wdrzg-n":`Kimlik Doğrulama Devralma Hedefi`},help:{"v1-2d16wl-2x":`Kimlik bilgileri ajan bazında taşınana kadar devralınan kimlik bilgisi deposunun yükseltme uyumluluğu için belirlenen sahibi.`}},"agents%2Edefaults%2EauthInheritance%2EagentId":{label:{"v1-bva26o-m":`Kimlik Doğrulama Devralma Sahibi`},help:{"v1-1a1s7nm-4s":`Varsayılan işaretçisi kaldırıldıktan sonra eski kimlik bilgisi deposu devralma kaynağı olarak kalan ajan. Önceki sahip main olmadığında yükseltme sırasında otomatik olarak yazılır.`}},"agents%2Edefaults%2EbootstrapMaxChars":{label:{"v1-dzxrwm-j":`Başlangıç Dosyası Maksimum Karakter Sayısı`},help:{"v1-drlo3i-37":`Sistem istemine eklenen her bir çalışma alanı başlangıç dosyasının kısaltılmadan önce içerebileceği maksimum karakter sayısı (varsayılan: 20000).`}},"agents%2Edefaults%2EbootstrapTotalMaxChars":{label:{"v1-brbs24-p":`Başlangıç Dosyaları Toplam Maksimum Karakter Sayısı`},help:{"v1-1evwsjb-2c":`Eklenen tüm çalışma alanı başlangıç dosyalarındaki maksimum toplam karakter sayısı (varsayılan: 60000).`}},"agents%2Edefaults%2Ecompaction":{label:{"v1-1d4drzc-a":`Sıkıştırma`},help:{"v1-1qxdwz8-5p":`Bağlam token sınırlarına yaklaştığında uygulanacak sıkıştırma davranışı; stratejiyi ve sıkıştırma öncesi belleği kalıcı depolamaya yazma davranışını içerir. Uzun süren oturumlarda dar bağlam pencereleri altında kararlı süreklilik gerektiğinde bunu kullanın.`}},"agents%2Edefaults%2Ecompaction%2Eenabled":{label:{"v1-iri7g4-o":`Yerleşik Otomatik Sıkıştırma`},help:{"v1-1et7vwu-5l":`Yerleşik proaktif otomatik sıkıştırmayı etkinleştirin (varsayılan: true). OpenClaw taşma kurtarmasını, ön kontrol sıkıştırmasını ve manuel /compact komutunu koruyarak eşiğe bağlı yerleşik sıkıştırmayı durdurmak için false olarak ayarlayın.`}},"agents%2Edefaults%2Ecompaction%2EidentifierPolicy":{label:{"v1-i1jgob-s":`Sıkıştırma Tanımlayıcı İlkesi`},help:{"v1-hby01l-4l":`Sıkıştırma özetleri için tanımlayıcı koruma ilkesi: "strict", başa opak tanımlayıcıların korunmasına yönelik yerleşik yönergeler ekler (varsayılan); "off" ise bu öneki devre dışı bırakır.`}},"agents%2Edefaults%2Ecompaction%2EkeepRecentTokens":{label:{"v1-ljajga-t":`Sıkıştırmada Korunacak Son Token Sayısı`},help:{"v1-tgysub-5h":`Sıkıştırma sırasında en son konuşma penceresinden korunacak minimum token bütçesi. Yakın bağlamın sürekliliğini korumak için daha yüksek, daha eski geçmişten daha fazla içerik tutmak için daha düşük değerler kullanın.`}},"agents%2Edefaults%2Ecompaction%2EmaxActiveTranscriptBytes":{label:{"v1-1il6xj6-17":`Sıkıştırma İçin Etkin Konuşma Dökümü Boyut Eşiği`},help:{"v1-u715n1-90":`Modelin gördüğü konuşma dökümü penceresi (son sıkıştırma veya sıfırlamadan itibaren) bu boyuta ulaştığında normal ön kontrol yerel sıkıştırmasını tetikleyen bayt eşiği (bayt cinsinden veya "20mb" gibi dizelerle). Devre dışı bırakmak için 0 olarak ayarlayın veya ayarlamadan bırakın. Ayrıca Codex app-server yerel yürütme dökümlerini de sınırlar; boyutu aşan yerel konuşma dizileri sıfırdan yeniden başlatılır.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush":{label:{"v1-1sphznd-n":`Sıkıştırmada Belleği Kalıcılaştırma`},help:{"v1-18q0ve9-55":`Yoğun sıkıştırmadan önce ajanın belleğe yazma işlemi gerçekleştirmesini sağlayan, sıkıştırma öncesi bellek kalıcılaştırma ayarları. Önemli bağlamın kapsamlı kırpmadan önce kalıcı olarak saklanması için uzun oturumlarda etkin tutun.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Eenabled":{label:{"v1-14wdoio-v":`Sıkıştırma Öncesi Belleğe Kaydetme Etkin`},help:{"v1-9xllgp-5o":`Çalışma zamanı, token sınırlarına yaklaşıldığında geçmişi daha kapsamlı biçimde azaltmadan önce belleğe kaydetmeyi etkinleştirir. Kısıtlı ortamlarda belleğe yönelik yan etkileri bilinçli olarak devre dışı bırakmıyorsanız etkin tutun.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EforceFlushTranscriptBytes":{label:{"v1-10u43o5-1d":`Sıkıştırma Öncesi Belleğe Kaydetme İçin Konuşma Dökümü Boyut Eşiği`},help:{"v1-1rzov1e-93":`Modelin görebildiği konuşma dökümü penceresi bu eşiğe ulaştığında sıkıştırma öncesi belleğe kaydetmeyi zorunlu kılar (bayt cinsinden veya "2mb" gibi dizelerle belirtilir). Sıkıştırmadan sonra bu pencere, atılan geçmiş yerine korunan son bölümü ve sonraki konuşma turlarını içerir. Token sayaçları güncel olmadığında bile uzun oturumlarda takılmaları önlemek için bunu kullanın; devre dışı bırakmak için 0 olarak ayarlayın.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2Emodel":{label:{"v1-z6o9nc-12":`Sıkıştırma Öncesi Belleğe Kaydetme İçin Alternatif Model`},help:{"v1-1r3ctyu-7w":`Yalnızca sıkıştırma öncesi belleğe kaydetme turlarında kullanılacak isteğe bağlı alternatif sağlayıcı/model. Kalıcı belleğe bilgi aktarımı sırasında etkin oturumun ücretli modelinin kullanılmaması gerekiyorsa bunu ollama/qwen3:8b gibi yerel bir modele ayarlayın. Belirtilen model doğrudan kullanılır ve etkin modelin yedek model zinciri devralınmaz.`}},"agents%2Edefaults%2Ecompaction%2EmemoryFlush%2EsoftThresholdTokens":{label:{"v1-1h1tkzc-12":`Sıkıştırma Öncesi Belleğe Kaydetme İçin Esnek Eşik`},help:{"v1-1dqo2l1-5c":`Sıkıştırma öncesi belleğe kaydetmeyi tetikleyen, sıkıştırma sınırına kalan mesafe (token cinsinden). Daha güvenli kalıcı kayıt için daha erken tetiklenen eşikler, daha düşük kaydetme sıklığı içinse sınıra daha yakın eşikler kullanın.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck":{label:{"v1-rb9ni9-s":`Sıkıştırma İçin Tur Ortası Ön Kontrolü`},help:{"v1-am6gbh-6x":`Araç sonucu eklendikten sonra ve bir sonraki model çağrısından önce bağlam kapasitesi üzerindeki baskıyı algılayan, gömülü OpenClaw araç döngüsüne yönelik isteğe bağlı ön kontrol. Etkinleştirildiğinde OpenClaw, yeniden denemeden önce araç sonuçlarını kısaltmak veya sıkıştırma yapmak için mevcut ön kontrol kurtarma mekanizmasını yeniden kullanır.`}},"agents%2Edefaults%2Ecompaction%2EmidTurnPrecheck%2Eenabled":{label:{"v1-1kxoip4-10":`Sıkıştırma İçin Tur Ortası Ön Kontrolü Etkin`},help:{"v1-engbwe-5u":`Gömülü OpenClaw araç döngüleri için tur ortasında yapılandırılmış bağlam kapasitesi baskısı kontrollerini etkinleştirir. Varsayılan: false. Araçların yoğun kullanıldığı uzun oturumlarda normal tur sonu sıkıştırması çalışamadan bağlam taşması yaşanmıyorsa devre dışı bırakın.`}},"agents%2Edefaults%2Ecompaction%2Emode":{label:{"v1-70zfez-f":`Sıkıştırma Modu`},help:{"v1-1unahwc-76":`Sıkıştırma stratejisi modu: "safeguard" (ayarlanmadığında geçerli olan varsayılan), yakın zamandaki bağlamı korumak için koruyucu önlemler uygular; "default" ise bu önlemler olmadan temel özetleme kullanır. Yalnızca safeguard özetlemesi sağlayıcınızda sorunlara neden oluyorsa "default" olarak ayarlayın.`}},"agents%2Edefaults%2Ecompaction%2Emodel":{label:{"v1-rqz37z-p":`Sıkıştırma İçin Modeli Geçersiz Kılma`},help:{"v1-cfeys9-6q":`Yalnızca sıkıştırma özetlemesi için kullanılan isteğe bağlı sağlayıcı/model veya yapılandırılmış yalın takma ad. Yalın takma adlar, istek gönderilmeden önce çözümlenir; yapılandırılmış bir model kimliği bir takma adla çakışırsa model kimliği önceliklidir. Birincil ajan modelini kullanmaya devam etmek için ayarlanmamış bırakın.`}},"agents%2Edefaults%2Ecompaction%2EnotifyUser":{label:{"v1-ub28vk-m":`Sıkıştırmada Kullanıcıyı Bilgilendir`},help:{"v1-lvymm8-bv":`Etkinleştirildiğinde kullanıcıya kısa bağlam bakımı bildirimleri gönderir: sıkıştırma başladığında ve tamamlandığında (örneğin, '🧹 Bağlam sıkıştırılıyor...' ve '🧹 Sıkıştırma tamamlandı') ve sıkıştırma öncesinde belleğe kaydetme denemeleri tükendiği için yanıtın kısıtlı işlevsellikle devam ettiği durumlarda (örneğin, '⚠️ Bellek bakımı geçici olarak başarısız oldu; yanıtınıza devam ediliyor.'). Bağlam bakımının sessizce ve kullanıcıyı rahatsız etmeden yürütülmesi için varsayılan olarak devre dışıdır.`}},"agents%2Edefaults%2Ecompaction%2EpostCompactionSections":{label:{"v1-x1uxbk-w":`Sıkıştırma Sonrası Bağlam Bölümleri`},help:{"v1-1n0ln2u-5f":`Sıkıştırmadan sonra isteğe bağlı olarak yeniden eklenen AGENTS.md H2/H3 bölüm adları. Yeniden eklemeyi devre dışı bırakmak için ayarlamayın veya [] olarak ayarlayın. Önceki varsayılan çifti etkinleştirmek için açıkça ["Session Startup", "Red Lines"] olarak ayarlayın.`}},"agents%2Edefaults%2Ecompaction%2EpostIndexSync":{label:{"v1-1p0j1ty-q":`Sıkıştırma Sonrası Dizin Eşitlemesi`},help:{"v1-ekpjeq-6l":`Sıkıştırma sonrası oturum belleğini yeniden dizinleme modunu belirler: "off", "async" veya "await" (varsayılan: "async"). En yüksek güncellik için "await", daha düşük sıkıştırma gecikmesi için "async" kullanın. "off" seçeneğini yalnızca oturum belleği eşitlemesi başka bir yerde yapılıyorsa kullanın.`}},"agents%2Edefaults%2Ecompaction%2Eprovider":{label:{"v1-1autmd-j":`Sıkıştırma Sağlayıcısı`},help:{"v1-kiwk91-86":`Özetleme için kullanılan kayıtlı sıkıştırma sağlayıcısı eklentisinin kimliği. Ayarlandığında ve sağlayıcı kayıtlı olduğunda, yerleşik summarizeInStages işlem hattı yerine sağlayıcının summarize() yöntemi çağrılır. Sağlayıcı başarısız olursa yerleşik yönteme dönülür. Varsayılan yerleşik özetlemeyi kullanmak için ayarlamayın.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard":{label:{"v1-nh0x1k-o":`Sıkıştırma Kalitesi Denetimi`},help:{"v1-u9ognp-4k":`Korumalı sıkıştırma özetleri için kalite denetimi yeniden deneme ayarları. Korumalı modda varsayılan olarak etkindir; özet denetimlerini ve yeniden oluşturmayı atlamak için enabled: false olarak ayarlayın.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2Eenabled":{label:{"v1-14z377t-w":`Sıkıştırma Kalite Koruması Etkin`},help:{"v1-1xk2vt3-36":`Korumalı sıkıştırma için özet kalitesi denetimlerini ve yeniden oluşturma denemelerini etkinleştirir. Varsayılan: korumalı modda true.`}},"agents%2Edefaults%2Ecompaction%2EqualityGuard%2EmaxRetries":{label:{"v1-1wbiubo-10":`Sıkıştırma Kalite Koruması Azami Yeniden Deneme Sayısı`},help:{"v1-n7l46y-3y":`Korumalı özet kalitesi denetimi başarısız olduktan sonra yapılacak azami yeniden oluşturma denemesi sayısı. Ek gecikmeyi ve token maliyetini sınırlamak için küçük değerler kullanın.`}},"agents%2Edefaults%2Ecompaction%2ErecentTurnsPreserve":{label:{"v1-lhuyqv-w":`Sıkıştırmada Son Konuşma Turlarını Koruma`},help:{"v1-y34ihi-5k":`Korumalı özetlemenin dışında, olduğu gibi saklanan en son kullanıcı/asistan konuşma turlarının sayısı (varsayılan: 3). Son konuşma bağlamını eksiksiz korumak için bu değeri artırın veya sıkıştırma tasarrufunu en üst düzeye çıkarmak için azaltın.`}},"agents%2Edefaults%2Ecompaction%2EthinkingLevel":{label:{"v1-5qtj6m-p":`Sıkıştırma Düşünme Düzeyi`},help:{"v1-1vafgaw-g1":`Yalnızca yerleşik OpenClaw sıkıştırma özetleri için kullanılan düşünme düzeyi: "off", "minimal", "low", "medium", "high", "xhigh", "adaptive", "max", "ultra" veya "inherit". Varsayılan olarak sağlayıcının sıkıştırma tercihi, yoksa "low" kullanılır; yerel olarak çalışan Ollama'nın yerleşik entegrasyonu "off" tercih eder. Oturum düzeyini yeniden kullanmak için "inherit" ayarlayın. Açıkça belirtilen ayarlar sağlayıcının varsayılanlarını geçersiz kılar ve seçilen düzey, kullanılan sıkıştırma modelinin/çalışma ortamının desteklediği aralıkla sınırlandırılır. Yerleşik Codex app-server sıkıştırması bu ayarı yok sayar; çünkü sıkıştırma isteği işlem başına düşünme düzeyini geçersiz kılmayı desteklemez ve OpenClaw bir uyarı kaydeder.`}},"agents%2Edefaults%2Ecompaction%2EtimeoutSeconds":{label:{"v1-1x6zijf-s":`Sıkıştırma Zaman Aşımı (Saniye)`},help:{"v1-2bhn29-7m":`Her yerleşik sıkıştırma modeli isteği için saniye cinsinden güvenlik süresi (varsayılan: 180). Çok aşamalı sıkıştırmada, sıralı isteklerin her biri başladığında süre yenilenir; bu nedenle sıkıştırmanın tamamlanması daha uzun sürebilir. Eklenti tarafından yönetilen sıkıştırmada ise işlemin tamamı için tek bir süre tanınır.`}},"agents%2Edefaults%2EcontextInjection":{label:{"v1-1blm5yl-h":`Bağlam Ekleme`},help:{"v1-u18x0-7u":`Gömülü çalışma zamanında çalışma alanı başlangıç dosyalarının bağlama eklenmesini kontrol eder: "always" normal ekleme davranışını kullanır (varsayılan), "continuation-skip" tam başlangıç bağlamının eklendiği kayıtlı bir turdan sonraki uygun devam turlarında eklemeyi atlar ve "never" eklemeyi devre dışı bırakır. CLI tabanlı istem hazırlığını kontrol etmez.`}},"agents%2Edefaults%2EcontextLimits":{label:{"v1-1lphwvv-m":`Varsayılan Bağlam Sınırları`},help:{"v1-1coeez8-5d":`Seçili yüksek hacimli alıntılar ve eklenen istem blokları için ajan bağlamı başına özel bütçe varsayılanları. Sınırsız çağrı yollarını yeniden açmadan, sınırlandırılmış okuma ve ekleme boyutlarını ayarlamak için bunu kullanın.`}},"agents%2Edefaults%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-197rwel-s":`Varsayılan memory_get Maksimum Karakter Sayısı`},help:{"v1-1qb40qv-4v":`Kırpma meta verileri ve devam bildirimi eklenmeden önce memory_get tarafından döndürülen varsayılan azami karakter sayısı. Önceki daha uzun alıntılara yaklaşmak için artırın, ancak sınırlı tutun.`}},"agents%2Edefaults%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-hh1flp-x":`Sıkıştırma Sonrası Varsayılan Azami Karakter Sayısı`},help:{"v1-64qo8g-5r":`Sıkıştırma sonrası bağlam yenileme içeriği eklenirken AGENTS.md dosyasından korunan varsayılan azami karakter sayısı. Sıkıştırma sonrası kurtarma maliyetini azaltmak için bu değeri düşürün veya daha uzun başlangıç yönergelerine ihtiyaç duyan ajanlar için artırın.`}},"agents%2Edefaults%2Ecwd":{label:{"v1-1akuwgr-h":`Çalışma Dizini`},help:{"v1-1y8wlxn-6a":`Ajan yanıt çalıştırmaları için kullanılan, çalışma alanı başlatma ve bellek dosyalarından ayrı çalışma dizini. Ajana özgü cwd ve oturum başlatılırken belirlenen cwd önceliklidir. ~ ve göreli yolları destekler; farklı bir cwd, korumalı alan dışında çalıştırma gerektirir.`}},"agents%2Edefaults%2EdecisionModel":{label:{"v1-45jwcu-e":`Karar Modeli`},help:{"v1-7nd7ze-64":`Türü belirlenmiş seçimler, puanlar ve mantıksal değer olasılıkları için isteğe bağlı sağlayıcı/model. Ayarlanmadığında veya boş bırakıldığında karar çağrıları devre dışı kalır. Destekleyen eklentiler bu sağlayıcıya sınırlı kapsamda görev kanıtları gönderir; sohbet ve yardımcı modeller değişmez.`}},"agents%2Edefaults%2EembeddedAgent":{label:{"v1-78x3fi-h":`Gömülü OpenClaw`},help:{"v1-1keek32-3k":`Çalışma alanına yerel ajan ayarlarına OpenClaw oturumlarında nasıl güvenileceğini ve bu ayarların nasıl uygulanacağını belirleyen gömülü OpenClaw çalıştırıcısı güvenlik güçlendirme denetimleri.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover":{label:{"v1-1qnu0am-l":`Siber politika için yedeğe geçiş`},help:{"v1-xvv6wl-2r":`Gömülü çalışma ortamında, yeniden yürütülmesi güvenli olan OpenAI siber politika retleri için otomatik olarak Daybreak'e yönlendirme.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2EcooloffMs":{label:{"v1-j5ckj0-t":`Siber politika için yedeğe geçiş bekleme süresi`},help:{"v1-16smtrl-25":`Kullanılamayan bir yönlendirme hedefinin geçerli oturumda ne kadar süreyle atlanacağı.`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emode":{label:{"v1-1mx8pup-q":`Siber politika için yedeğe geçiş modu`},help:{"v1-rzsd2b-2h":`Otomatik yönlendirmeyi etkinleştirin ("auto", varsayılan) veya sağlayıcı retlerinde işlemi sonlandırın ("off").`}},"agents%2Edefaults%2EembeddedAgent%2EcyberFailover%2Emodel":{label:{"v1-1oxd3p3-r":`Siber politika için yedeğe geçiş modeli`},help:{"v1-1aaj8nn-1t":`Siber politika nedeniyle otomatik yönlendirme için kullanılan sağlayıcı/model hedefi.`}},"agents%2Edefaults%2EembeddedAgent%2EexecutionContract":{label:{"v1-1e1r7sa-10":`Gömülü OpenClaw Yürütme Sözleşmesi`},help:{"v1-1fch2ig-66":`Gömülü OpenClaw yürütme sözleşmesi: "default" standart çalıştırıcı davranışını korurken "strict-agentic", desteklenen OpenAI/OpenAI Codex GPT-5 ailesi çalıştırmaları için yapılandırılmış plan takibini ve görünür olmayan tur kurtarmayı etkinleştirir.`}},"agents%2Edefaults%2EembeddedAgent%2EprojectSettingsPolicy":{label:{"v1-xaw8em-15":`Gömülü OpenClaw Proje Ayarları Politikası`},help:{"v1-fdyy04-65":'Gömülü OpenClaw\'ın çalışma alanına özgü `.openclaw/settings.json` dosyasını nasıl işlediğini belirler: "sanitize" (varsayılan), shellPath/shellCommandPrefix ayarlarını kaldırır; "ignore", proje ayarlarını tamamen devre dışı bırakır; "trusted" ise proje ayarlarını olduğu gibi uygular.'}},"agents%2Edefaults%2Eexperimental":{label:{"v1-biomsl-o":`Deneysel Ajan Bayrakları`},help:{"v1-cvv5cl-2w":`Ajan varsayılanlarına yönelik deneysel bayraklar. Bir önizleme özelliğini bilinçli olarak test etmiyorsanız bunları kapalı tutun.`}},"agents%2Edefaults%2Eexperimental%2ElocalModelLean":{label:{"v1-x4h50k-17":`Yalın Yerel Model Modunu Etkinleştir (Deneysel)`},help:{"v1-gj06u6-7b":`browser, automations ve message gibi isteğe bağlı araçları kısıtlayan gelişmiş sorun giderme ayarı. Varsayılan olarak kapalıdır; desteklenen yerel çalışma ortamları bu kısıtlama olmadan otomatik Tool Search kullanır. Açıkça verilen araç izinleri ve gerekli iletim araçları korunur.`}},"agents%2Edefaults%2EfastModeDefault":{label:{"v1-1l6uhpu-n":`Varsayılan Ajan Hızlı Modu`},help:{"v1-zv4y98-2z":`Ajan döngüsü için varsayılan hızlı mod ilkesi ("auto", true veya false). Tek tek ajan kayıtları bu ayarı geçersiz kılar.`}},"agents%2Edefaults%2Eheartbeat%2EagentId":{label:{"v1-1kugcom-f":`Yaşam Sinyali Ajanı`},help:{"v1-1jynxej-3w":`Ajana özgü yaşam sinyali yapılandırması bulunmadığında arka plandaki yaşam sinyali çalıştırmalarından sorumlu olan ajan. Yapılandırılmış varsayılan yönlendirmeyi korumak için ayarlamadan bırakın.`}},"agents%2Edefaults%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Yaşam Sinyali Doğrudan İletim İlkesi`},help:{"v1-nhyxa9-41":`Yaşam sinyali iletiminin doğrudan/özel mesaj sohbetlerini hedefleyip hedefleyemeyeceğini denetler: "allow" (varsayılan), özel mesaj iletimine izin verir; "block" ise doğrudan hedeflere gönderimleri engeller.`}},"agents%2Edefaults%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Kalp Atışı Zaman Aşımı (Saniye)`},help:{"v1-1se21py-5f":`Bir kalp atışı ajan turunun iptal edilmeden önce çalışmasına izin verilen saniye cinsinden azami süre. Ayarlanmışsa agents.defaults.timeoutSeconds değerini, aksi halde en fazla 600 saniye olacak şekilde kalp atışı aralığını kullanmak için boş bırakın.`}},"agents%2Edefaults%2EhumanDelay%2EmaxMs":{label:{"v1-1mrn73i-k":`İnsansı Gecikme Üst Sınırı (ms)`},help:{"v1-vnmvli-1m":`Özel humanDelay için ms cinsinden azami gecikme (varsayılan: 2500).`}},"agents%2Edefaults%2EhumanDelay%2EminMs":{label:{"v1-1wd5i8o-k":`İnsansı Gecikme Alt Sınırı (ms)`},help:{"v1-5nrtr5-1l":`Özel humanDelay için ms cinsinden asgari gecikme (varsayılan: 800).`}},"agents%2Edefaults%2EhumanDelay%2Emode":{label:{"v1-ck9798-g":`İnsansı Gecikme Modu`},help:{"v1-k7hyg3-1n":`Blok yanıtlar için gecikme tarzı ("off", "natural", "custom").`}},"agents%2Edefaults%2EimageMaxDimensionPx":{label:{"v1-qmer27-o":`Görsel Azami Boyutu (px)`},help:{"v1-vju8x-2u":`Konuşma dökümü/araç sonucu görsel verileri temizlenirken kullanılacak piksel cinsinden azami görsel kenar uzunluğu (varsayılan: 1200).`}},"agents%2Edefaults%2EimageModel%2Efallbacks":{label:{"v1-d75sz8-l":`Yedek Görsel Modelleri`},help:{"v1-1kgx5i9-1b":`Sıralı yedek görsel modelleri (provider/model).`}},"agents%2Edefaults%2EimageModel%2Eprimary":{label:{"v1-1533tn-b":`Görsel Modeli`},help:{"v1-dstqyh-2c":`Birincil model görsel girdisini desteklemediğinde kullanılacak isteğe bağlı görsel modeli (provider/model).`}},"agents%2Edefaults%2EimageQuality":{label:{"v1-1x0wkcr-d":`Görsel Kalitesi`},help:{"v1-1uyxc5s-6u":`Görsel aracının medya sıkıştırma tercihi: "auto", sağlayıcı/model sınırlarına ve görsel sayısına uyum sağlar; "efficient", token ve bayt tasarrufu sağlar; "balanced", mevcut dengeyi korur; "high" ise ekran görüntülerinde ve belge görsellerinde daha fazla ayrıntıyı korur.`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Efallbacks":{label:{"v1-104q8cy-w":`Yedek Görsel Oluşturma Modelleri`},help:{"v1-oljfk4-1m":`Sıralı yedek görsel oluşturma modelleri (sağlayıcı/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2Eprimary":{label:{"v1-hzzdnh-m":`Görsel Oluşturma Modeli`},help:{"v1-g4yw0h-2o":`Ortak görsel oluşturma özelliğinin kullandığı isteğe bağlı görsel oluşturma modeli (sağlayıcı/model).`}},"agents%2Edefaults%2EmediaModels%2Eimage%2EtimeoutMs":{label:{"v1-4y5oza-t":`Görsel Oluşturma Zaman Aşımı (ms)`},help:{"v1-9yesfj-31":`image_generate çağrıları için milisaniye cinsinden varsayılan sağlayıcı isteği zaman aşımı. Çağrı bazında belirlenen timeoutMs bu değeri geçersiz kılar.`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Efallbacks":{label:{"v1-qkwbmc-w":`Yedek Müzik Oluşturma Modelleri`},help:{"v1-wyg9xe-1m":`Sıralı yedek müzik oluşturma modelleri (sağlayıcı/model).`}},"agents%2Edefaults%2EmediaModels%2Emusic%2Eprimary":{label:{"v1-f7mzln-m":`Müzik Oluşturma Modeli`},help:{"v1-xs1e2h-2o":`Ortak müzik oluşturma özelliğinin kullandığı isteğe bağlı müzik oluşturma modeli (sağlayıcı/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Efallbacks":{label:{"v1-xoqak-w":`Yedek Video Oluşturma Modelleri`},help:{"v1-wpbf1e-1m":`Sıralı yedek video oluşturma modelleri (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2Eprimary":{label:{"v1-fokknn-m":`Video Oluşturma Modeli`},help:{"v1-hfmlbl-2o":`Paylaşılan video oluşturma özelliğinin kullandığı isteğe bağlı video oluşturma modeli (provider/model).`}},"agents%2Edefaults%2EmediaModels%2Evideo%2EtimeoutMs":{label:{"v1-1dtok9w-t":`Video Oluşturma Zaman Aşımı (ms)`},help:{"v1-1bqj80s-4i":`video_generate çağrılarında sağlayıcı istekleri için milisaniye cinsinden varsayılan zaman aşımı. Çağrı başına belirtilen timeoutMs bu değeri geçersiz kılar; bu değer de sağlayıcının belirlediği varsayılanları geçersiz kılar.`}},"agents%2Edefaults%2Emodel%2Efallbacks":{label:{"v1-dz2y4l-f":`Yedek Modeller`},help:{"v1-t4djq2-24":`Sıralı yedek modeller (provider/model). Birincil model başarısız olduğunda kullanılır.`}},"agents%2Edefaults%2Emodel%2Eprimary":{label:{"v1-1jjnzq0-d":`Birincil Model`},help:{"v1-1i8a1v4-v":`Birincil model (provider/model).`}},"agents%2Edefaults%2EmodelPolicy":{label:{"v1-m0l2o-c":`Model Politikası`},help:{"v1-z0txb7-2e":`Model değişiklikleri için açıkça tanımlanan politika. Herhangi bir modele izin vermek için bunu belirtmeyin veya allow alanını boş bırakın.`}},"agents%2Edefaults%2EmodelPolicy%2Eallow":{label:{"v1-a807hj-e":`İzin Verilen Modeller`},help:{"v1-1fqace-3x":`Model değişikliklerinde izin verilen model referansları. Takma adları, tam "provider/model" referanslarını ve "openai/*" gibi sağlayıcı joker karakterlerini kabul eder. Boş bırakıldığında herhangi bir modele izin verilir.`}},"agents%2Edefaults%2Emodels":{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-13cvq23-4i":`Yapılandırılmış model kataloğu ve model başına ayarlar. Girdiler takma adlar, parametreler, çalışma zamanı meta verileri ve Code Mode için geçersiz kılma ayarları sağlar; model değişikliklerini kısıtlamaz.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime":{label:{"v1-7nd0vy-r":`Varsayılan Ajan Modelinin Çalışma Zamanı`},help:{"v1-6km9kx-41":`Varsayılan ajan için isteğe bağlı, model bazında çalışma zamanı ilkesi. Ajanın tamamı için bir çalışma zamanı ayarlamak yerine modele özgü çalışma zamanı istisnaları için bunu kullanın.`}},"agents%2Edefaults%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-y10gjb-u":`Varsayılan Ajan Modelinin Çalışma Zamanı Kimliği`},help:{"v1-1co96w7-4a":`Varsayılan ajanın model çalışma zamanı kimliği: "openclaw", "auto", "codex" gibi kayıtlı bir eklenti yürütme altyapısı kimliği veya "claude-cli" gibi desteklenen bir CLI arka uç takma adı.`}},"agents%2Edefaults%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kod Modu`},help:{"v1-rsdl5o-6x":`Tam olarak bu sağlayıcı/model için OpenClaw Kod Modu: Açık, modu zorunlu olarak etkinleştirir; Kapalı, devre dışı bırakır; Varsayılan ise tools.codeMode.enabled ayarını devralır. Ajana özgü etkinleştirme ayarları önceliklidir. Bu, seçili çalışma zamanını veya Codex'in yerel Kod Modunu değiştirmez.`}},"agents%2Edefaults%2EmodelSelectionScope":{label:{"v1-rtarqk-l":`Model Seçimi Kapsamı`},help:{"v1-sj8owq-bl":`Açıkça kapsam belirtilmeyen sohbet komutları ve Gateway oturum modeli güncellemeleri için kapsam: "session" (varsayılan) yalnızca mevcut oturumu değiştirir, "agent" ayrıca ilgili ajanın birincil modelini günceller, "global" ise paylaşılan agents.defaults.model yedek ayarını da günceller. Açıkça belirtilen kapsam bayrakları önceliklidir; yapılandırılmış varsayılanları değiştirmek sahip/yönetici yetkisi gerektirir. Telegram geri çağrı seçicileri ve gömülü yerel TUI yalnızca oturum kapsamında kalır.`}},"agents%2Edefaults%2EpdfMaxMb":{label:{"v1-ked92u-h":`Maksimum PDF Boyutu (MB)`},help:{"v1-1uig1dr-1u":`PDF aracı için megabayt cinsinden maksimum PDF dosyası boyutu (varsayılan: 10).`}},"agents%2Edefaults%2EpdfMaxPages":{label:{"v1-1mbzuxr-d":`Maksimum PDF Sayfa Sayısı`},help:{"v1-11na7hp-1y":`PDF aracı için işlenecek en fazla PDF sayfası sayısı (varsayılan: 20).`}},"agents%2Edefaults%2EpdfModel%2Efallbacks":{label:{"v1-pu595v-j":`Yedek PDF Modelleri`},help:{"v1-89ebd8-19":`Sıralı yedek PDF modelleri (provider/model).`}},"agents%2Edefaults%2EpdfModel%2Eprimary":{label:{"v1-u2jryk-9":`PDF Modeli`},help:{"v1-2ktkxt-2y":`PDF analiz aracı için isteğe bağlı PDF modeli (provider/model). Varsayılan olarak imageModel, ardından oturum modeli kullanılır.`}},"agents%2Edefaults%2ErepoRoot":{label:{"v1-1wgofmz-9":`Depo Kök Dizini`},help:{"v1-j3sh74-2h":`Sistem isteminin çalışma zamanı satırında gösterilen isteğe bağlı depo kök dizini (otomatik algılamayı geçersiz kılar).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-a168yk-11":`Yalıtılmış Ortam Tarayıcısı CDP Kaynak Bağlantı Noktası Aralığı`},help:{"v1-1jkowdc-2b":`Konteyner sınırındaki gelen CDP trafiği için isteğe bağlı CIDR izin listesi (örneğin 172.21.0.1/32).`}},"agents%2Edefaults%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-w9qjiq-n":`Yalıtılmış Ortam Tarayıcısı Ağı`},help:{"v1-8m74ud-5w":`Yalıtılmış ortam tarayıcı konteynerleri için Docker ağı (varsayılan: openclaw-sandbox-browser). Özel olarak ayrılmış varsayılan ağı veya özel bir köprü ağı kullanın; tarayıcı denetimi dışarıya açılmış CDP bağlantı noktaları gerektirdiğinden "none" desteklenmez.`}},"agents%2Edefaults%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-m0t0f7-19":`Yalıtılmış Ortam Docker Konteyner Ad Alanına Katılmaya İzin Ver`},help:{"v1-qm39de-4c":`Yalıtılmış ortamda Docker'ın container:<id> ağ moduna izin veren, acil durumlara yönelik TEHLİKELİ bir geçersiz kılma ayarıdır. Başka bir konteynerin ad alanına katılır ve yalıtılmış ortamın izolasyonunu zayıflatır.`}},"agents%2Edefaults%2Esandbox%2Edocker%2Egpus":{label:{"v1-c8tb-j":`Korumalı Alan Docker GPU'ları`},help:{"v1-jj0yhw-4k":`--gpus parametresine iletilen isteğe bağlı Docker GPU geçiş değeri; örneğin "all" veya "device=GPU-uuid". NVIDIA Container Toolkit gibi uyumlu bir ana makine çalışma zamanı gerektirir.`}},"agents%2Edefaults%2EsessionStore":{label:{"v1-qna6lw-r":`Eski Oturum Deposu Hedefi`},help:{"v1-1xkej6i-2g":`Kullanımdan kaldırılmış ana ajan satırları ve sabit eski oturum depoları için yükseltme uyumluluğu sahibi.`}},"agents%2Edefaults%2EsessionStore%2EagentId":{label:{"v1-3s8frc-q":`Eski Oturum Deposu Sahibi`},help:{"v1-ommm7e-5w":`Varsayılan işaretçisi kullanımdan kaldırıldıktan sonra, sabit bir eski oturum deposundaki kullanımdan kaldırılmış ana ajan satırlarının veya kapsamı belirlenmemiş satırların sahibi olan ajan. Önceki sahip main veya tek ajan değilse yükseltme sırasında otomatik olarak yazılır.`}},"agents%2Edefaults%2Eskills":{label:{"v1-1bk7xrz-6":`Skills`},help:{"v1-1pbsu94-75":`agents.entries.*.skills belirtmeyen ajanların devraldığı, isteğe bağlı varsayılan beceri izin listesi. Becerileri kısıtlamamak için belirtmeyin; devralan ajanlara hiçbir beceri vermemek için [] olarak ayarlayın. Açıkça belirtilen agents.entries.*.skills değerinin bu varsayılanla birleştirilmek yerine onun yerini aldığını unutmayın.`}},"agents%2Edefaults%2EskipBootstrap":{label:{"v1-10c1qje-x":`Çalışma Alanı Başlangıç Dosyalarının Oluşturulmasını Atla`},help:{"v1-kbstgw-5v":`Çalışma alanı başlangıç dosyalarının otomatik oluşturulmasını atlar; mevcut dosyaların bağlama eklenmesini engellemez. Gömülü çalışma zamanında, ajan bazında geçersiz kılınmadığı sürece eklemeyi devre dışı bırakmak için agents.defaults.contextInjection değerini "never" olarak ayarlayın.`}},"agents%2Edefaults%2EskipOptionalBootstrapFiles":{label:{"v1-xzxxz4-w":`Atlanan İsteğe Bağlı Başlatma Dosyaları`},help:{"v1-1j2z4yj-4c":`Ajan çalışma alanlarında oluşturulmaması gereken isteğe bağlı başlatma dosyaları. Geçerli değerler: SOUL.md, USER.md, IDENTITY.md (HEARTBEAT.md kabul edilir ancak herhangi bir etkisi yoktur).`}},"agents%2Edefaults%2EstartupContext":{label:{"v1-2srlwp-f":`Başlangıç Bağlamı`},help:{"v1-1ugsihy-5o":`Tek başına kullanılan "/new" ve "/reset" komutları için çalışma zamanı tarafından yönetilen ilk tur ön metni. Modelden ne okuyacağına karar vermesini istemek yerine, son günlük bellek dosyalarının ilk isteme önceden yüklenip yüklenmeyeceğini kontrol etmek için bunu kullanın.`}},"agents%2Edefaults%2EstartupContext%2EapplyOn":{label:{"v1-8ngrte-o":`Başlangıç Bağlamının Uygulanacağı Komutlar`},help:{"v1-wav4a5-36":`Tek başına kullanılan hangi sıfırlama komutlarına başlangıç bağlamı ekleneceğini seçer: "new", "reset" veya her ikisini ekleyin (varsayılan: ["new","reset"]).`}},"agents%2Edefaults%2EstartupContext%2EdailyMemoryDays":{label:{"v1-oj0fzi-x":`Başlangıç Bağlamı Günlük Bellek Gün Sayısı`},help:{"v1-4i5xcm-3p":`Yapılandırılmış kullanıcı saat diliminde bugünden geriye doğru sayılarak yüklenecek tarihli bellek dosyalarının sayısı (varsayılan: bugün + dün için 2).`}},"agents%2Edefaults%2EstartupContext%2Eenabled":{label:{"v1-1iode8k-m":`Başlangıç Bağlamını Etkinleştir`},help:{"v1-1d5vz2u-4i":`Tek başına kullanılan oturum sıfırlama komutları için başlangıç bağlamı ön metnini etkinleştirir (varsayılan: true). Çalışma zamanı tarafından günlük bellek yüklenmeden, yalnızca isteme dayalı davranışa dönmek için bunu devre dışı bırakın.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileBytes":{label:{"v1-816erw-u":`Başlangıç Bağlamı Dosya Başına En Fazla Bayt`},help:{"v1-11cbian-41":`Başlangıç bağlamı oluşturulurken günlük bellek dosyası başına izin verilen en fazla bayt sayısı (varsayılan: 16384). Sınırları güvenli biçimde koruyan bu okuma limitini aşan dosyalar atlanır.`}},"agents%2Edefaults%2EstartupContext%2EmaxFileChars":{label:{"v1-1xzziaa-u":`Başlangıç Bağlamı Dosya Başına En Fazla Karakter`},help:{"v1-10z53s-2u":`Yüklenen her günlük bellek dosyasından başlangıç ön metninde tutulan en fazla karakter sayısı (varsayılan: 1200).`}},"agents%2Edefaults%2EstartupContext%2EmaxTotalChars":{label:{"v1-1gx8bpc-v":`Başlangıç Bağlamı Maksimum Toplam Karakter Sayısı`},help:{"v1-sf676u-54":`Başlangıç ön bağlamına yüklenen tüm günlük bellek dosyalarında tutulan maksimum toplam karakter sayısı (varsayılan: 2800). Bu sınıra ulaşıldığında ek dosyaların içeriği ön bağlamda kırpılır.`}},"agents%2Edefaults%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Alt Ajan Görev Devri Modu`},help:{"v1-pqewbk-5o":`Yalnızca istem aracılığıyla yönlendirilen alt ajana görev devrinin gücü. Varsayılan değer, her ajanın ana oturumunda "prefer", diğer yerlerde ise "suggest" olur; "prefer", ajana basit olmayan işleri sessions_spawn aracılığıyla devretmesi için güçlü bir talimat verir.`}},"agents%2Edefaults%2EsystemAgent":{label:{"v1-d8xvga-j":`Sistem Ajanı Hedefi`},help:{"v1-1wwimo9-34":`Arka planda çalışan OpenClaw sistem ajanı ve Custodian çıkarımları ile seçili, kapsamı belirtilmemiş operatör okuma işlemleri için hedef ayarları.`}},"agents%2Edefaults%2EsystemAgent%2EagentId":{label:{"v1-xsnrm-i":`Sistem Ajanı Sahibi`},help:{"v1-15rvt92-8c":`Arka plandaki sistem ajanı ve Custodian danışmalarında modeli ve kimlik bilgileri kullanılan ajan. Ayrıca models.list, models.authStatus, skills.status, doctor.memory.status veya ajana ait model ya da kimlik doğrulama durumunu çözümleyen bir infer CLI komutunda agentId ya da --agent belirtilmediğinde de kullanılır; istekte açıkça belirtilen agentId her zaman önceliklidir.`}},"agents%2Edefaults%2EtypingIntervalSeconds":{label:{"v1-5vbq6f-p":`Yazma Aralığı (Saniye)`},help:{"v1-1y701ox-42":`Her ajan için yazıyor göstergesinin etkin tutulma sıklığını saniye cinsinden kontrol eder. Yazıyor göstergesini destekleyen tüm kanallarda güncelleme sıklığını azaltmak için bu değeri artırın.`}},"agents%2Edefaults%2EtypingMode":{label:{"v1-17u58e1-b":`Yazma Modu`},help:{"v1-m2hvpw-3m":`Ajanlar için yazıyor göstergesinin ne zaman başlayacağını belirler: "never", "instant", "thinking" veya "message". Ajan bazında ayarlanan typingMode bu varsayılanı geçersiz kılar.`}},"agents%2Edefaults%2EutilityModel":{label:{"v1-7gi7gi-d":`Yardımcı Model`},help:{"v1-1wg7h1a-7s":`Başlık oluşturma ve ilerleme bilgisi verme gibi kısa dahili görevler için isteğe bağlı, daha düşük maliyetli model (provider/model veya takma ad). Ayarlanmazsa birincil sağlayıcının tanımladığı küçük model varsa o, yoksa birincil model kullanılır; yardımcı modele yönlendirmeyi devre dışı bırakmak için boş dize olarak ayarlayın.`}},"agents%2Edefaults%2EvoiceModel%2Efallbacks":{label:{"v1-v34llj-l":`Yedek Ses Modelleri`},help:{"v1-faazv4-1b":`Sırayla denenecek yedek ses modelleri (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2Eprimary":{label:{"v1-hvyby0-b":`Ses Modeli`},help:{"v1-1yeh3h4-2t":`Konuşma, sesi metne dönüştürme ve gerçek zamanlı ses özellikleri için kullanılan isteğe bağlı ses modeli (provider/model).`}},"agents%2Edefaults%2EvoiceModel%2EtimeoutMs":{label:{"v1-1hw6a5x-i":`Ses Zaman Aşımı (ms)`},help:{"v1-1sbergs-32":`Çağrıyı yapan bileşen zaman aşımını desteklediğinde, ses modeli işlemlerinde sağlayıcı istekleri için milisaniye cinsinden varsayılan zaman aşımı.`}},"agents%2Edefaults%2Eworkspace":{label:{"v1-aw4cba-9":`Çalışma alanı`},help:{"v1-1lssx8l-5w":`Başlatma ve bellek dosyaları için varsayılan ajan çalışma alanı. agents.defaults.cwd ayarlanmadığında çalışma dizini olarak da kullanılır. Sarmalayıcılar üzerinden çalıştırırken yol çözümlemesinin tutarlı kalması için bunu açıkça ayarlayın.`}},"agents%2Eentries":{label:{"v1-1ts48oe-a":`Ajan Listesi`},help:{"v1-yurood-5l":`Kimlikleri ve model, araçlar, kimlik bilgileri ile çalışma alanı için isteğe bağlı geçersiz kılma ayarlarıyla birlikte yapılandırılmış ajanların açık listesi. Bağlamaların, onayların ve oturum yönlendirmesinin tutarlı kalması için kimlikleri zaman içinde sabit tutun.`}},"agents%2Eentries%2E*%2EagentRuntime":{label:{"v1-rmaqyr-k":`Eski Ajan Çalışma Ortamı`}},"agents%2Eentries%2E*%2EagentRuntime%2Eid":{label:{"v1-mtthss-n":`Eski Ajan Çalışma Ortamı Kimliği`}},"agents%2Eentries%2E*%2EbootstrapMaxChars":{label:{"v1-beqsv3-p":`Ajan Başlangıç Dosyası Azami Karakter Sayısı`},help:{"v1-rsf1es-4j":`Bu ajanın sistem istemine eklenen her bir çalışma alanı başlangıç dosyasının azami karakter sayısı için ajana özel ayar. agents.defaults.bootstrapMaxChars değerini devralmak için belirtmeyin.`}},"agents%2Eentries%2E*%2EbootstrapTotalMaxChars":{label:{"v1-1hf8zr9-v":`Ajan Başlangıç Dosyaları Azami Toplam Karakter Sayısı`},help:{"v1-1bal68p-4y":`Bu ajanın sistem istemine eklenen tüm çalışma alanı başlangıç dosyalarının azami toplam karakter sayısı için ajana özel ayar. agents.defaults.bootstrapTotalMaxChars değerini devralmak için belirtmeyin.`}},"agents%2Eentries%2E*%2EcontextInjection":{label:{"v1-1rpaags-n":`Ajan Bağlam Ekleme`},help:{"v1-1j68ys8-50":`Gömülü çalışma zamanında çalışma alanı başlangıç dosyalarının eklenmesi için ajan bazında geçersiz kılma ayarı. agents.defaults.contextInjection ayarını devralmak için belirtmeyin. CLI tabanlı istem hazırlığını kontrol etmez.`}},"agents%2Eentries%2E*%2EcontextLimits":{label:{"v1-1nx137n-k":`Ajan Bağlam Sınırları`},help:{"v1-f1qxq8-3c":`Odaklanmış bağlam bütçesi ayarları için isteğe bağlı, ajana özel değerler. Belirtilmeyen alanlar agents.defaults.contextLimits değerlerini devralır.`}},"agents%2Eentries%2E*%2EcontextLimits%2EmemoryGetMaxChars":{label:{"v1-7rulph-q":`Ajan memory_get Azami Karakter Sayısı`},help:{"v1-12hlmsv-1v":`Varsayılan memory_get azami karakter bütçesi için ajana özel ayar.`}},"agents%2Eentries%2E*%2EcontextLimits%2EpostCompactionMaxChars":{label:{"v1-s7gnc5-v":`Ajan Sıkıştırma Sonrası Azami Karakter Sayısı`},help:{"v1-15s0npd-1w":`Sıkıştırma sonrası AGENTS.md alıntı bütçesi için ajan bazında geçersiz kılma.`}},"agents%2Eentries%2E*%2Ecwd":{label:{"v1-19t4x9u-n":`Ajan Çalışma Dizini`},help:{"v1-mv43ak-6a":`Bu ajanın yanıt çalıştırmaları için çalışma dizini. agents.defaults.cwd değerini geçersiz kılar, ancak oturum oluşturulurken belirlenen cwd değerini geçersiz kılmaz; başlangıç ve bellek dosyaları çalışma alanında kalır. ~ ve göreli yollar desteklenir; farklı bir cwd kullanmak, korumalı alan dışında çalıştırmayı gerektirir.`}},"agents%2Eentries%2E*%2EdecisionModel":{label:{"v1-73avf9-k":`Ajan Karar Modeli`},help:{"v1-1mih8bf-3j":`Ajana özel karar modeli. Ayarlanmadığında agents.defaults.decisionModel değerini devralır; boş bir dize bu ajan için karar çağrılarını devre dışı bırakır.`}},"agents%2Eentries%2E*%2EembeddedAgent":{label:{"v1-5clak7-n":`Ajanın Gömülü OpenClaw Ayarları`},help:{"v1-uoomza-4b":`Ajan bazında isteğe bağlı gömülü OpenClaw geçersiz kılmaları. Genel varsayılanı değiştirmeden belirli ajanlar için daha katı GPT-5 yürütme davranışını etkinleştirmek üzere kullanın.`}},"agents%2Eentries%2E*%2EembeddedAgent%2EexecutionContract":{label:{"v1-za8cop-16":`Ajanın Gömülü OpenClaw Yürütme Sözleşmesi`},help:{"v1-1d1jaoi-7k":`Ajan bazında isteğe bağlı gömülü OpenClaw yürütme sözleşmesi geçersiz kılması. Desteklenen OpenAI/OpenAI Codex GPT-5 ailesi çalıştırmalarında bu ajan için yapılandırılmış plan takibini ve görünür olmayan tur kurtarmayı etkinleştirmek üzere "strict-agentic", standart çalıştırıcı davranışını devralmak üzere "default" olarak ayarlayın.`}},"agents%2Eentries%2E*%2Eexperimental":{label:{"v1-lzii83-o":`Ajanın Deneysel Bayrakları`},help:{"v1-1r06jov-2a":`Ajan bazında deneysel bayraklar. Belirtilmeyen alanlar agents.defaults.experimental değerlerini devralır.`}},"agents%2Eentries%2E*%2Eexperimental%2ElocalModelLean":{label:{"v1-9htxgz-r":`Ajanın Yalın Yerel Model Modu`},help:{"v1-5o3tgx-58":`Yalın yerel model modu için ajan bazında sorun giderme ayarı. Yalnızca isteğe bağlı araçları kısıtlamak, tüm ajanların araçlarını azaltmadan kanıtlanmış bir model hatasını gideriyorsa etkinleştirin.`}},"agents%2Eentries%2E*%2EfastModeDefault":{label:{"v1-9gqmky-n":`Ajanın Varsayılan Hızlı Modu`},help:{"v1-1ujydjc-3o":`Ajan başına isteğe bağlı hızlı mod varsayılanı ("auto", true veya false). Mesaj veya oturum düzeyinde hızlı mod geçersiz kılma ayarı yapılmadığında uygulanır.`}},"agents%2Eentries%2E*%2Eheartbeat%2EdirectPolicy":{label:{"v1-19ubfku-n":`Yaşam Sinyali Doğrudan İletim Politikası`},help:{"v1-11gl9l0-41":`Yaşam sinyalinin doğrudan/DM iletim politikasını ajan başına geçersiz kılar; yaşam sinyali uyarılarını yalnızca DM dışındaki hedeflere göndermesi gereken ajanlar için "block" kullanın.`}},"agents%2Eentries%2E*%2Eheartbeat%2EtimeoutSeconds":{label:{"v1-17pcf3w-r":`Yaşam Sinyali Zaman Aşımı (Saniye)`},help:{"v1-kdetv4-6s":`Bir yaşam sinyali ajan turunun iptal edilmeden önce çalışmasına izin verilen, ajan başına saniye cinsinden azami süre. Önce birleştirilmiş yaşam sinyali zaman aşımını, ardından ayarlanmışsa agents.defaults.timeoutSeconds değerini, aksi takdirde 600 saniyeyle sınırlı yaşam sinyali aralığını devralmak için ayarlamadan bırakın.`}},"agents%2Eentries%2E*%2Eidentity%2Eavatar":{label:{"v1-fs5x3k-f":`Kimlik Avatarı`},help:{"v1-pzp9gr-1t":`Ajan avatarı (çalışma alanına göreli yol, http(s) URL'si veya data URI'si).`}},"agents%2Eentries%2E*%2EmodelPolicy":{label:{"v1-1locq7r-i":`Ajan Model Politikası`},help:{"v1-17d5je8-2r":`Ajan başına model geçersiz kılma politikası. Açıkça belirtilen bir izin listesi, bu ajanın varsayılan politikasının yerini alır.`}},"agents%2Eentries%2E*%2EmodelPolicy%2Eallow":{label:{"v1-xgq0i8-k":`İzin Verilen Ajan Modelleri`},help:{"v1-v1ueke-5b":`Bu ajan için izin verilen model geçersiz kılma referansları. Takma adları, tam "provider/model" referanslarını ve "provider/*" veya "provider/namespace/*" gibi sonunda joker karakter bulunan önekleri kabul eder; boş bırakılırsa tüm modellere izin verilir.`}},"agents%2Eentries%2E*%2Emodels":{label:{"v1-yawisy-l":`Ajan Model Geçersiz Kılmaları`},help:{"v1-nld1vq-1v":`Tam sağlayıcı/model kimlikleriyle anahtarlanmış, ajan bazında model kataloğu geçersiz kılmaları.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime":{label:{"v1-1cv283-j":`Ajan Modeli Çalışma Ortamı`},help:{"v1-7b59y-3s":`Bu ajan için model bazında isteğe bağlı çalışma ortamı politikası. Ajanın tamamı için bir çalışma ortamı ayarlamak yerine, ajana özgü model istisnaları için bunu kullanın.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EagentRuntime%2Eid":{label:{"v1-1j5q5p8-m":`Ajan Modeli Çalışma Ortamı Kimliği`},help:{"v1-1ckfc39-46":`Ajan bazında model çalışma ortamı kimliği: "openclaw", "auto", "codex" gibi kayıtlı bir eklenti yürütme altyapısı kimliği veya "claude-cli" gibi desteklenen bir CLI arka ucu takma adı.`}},"agents%2Eentries%2E*%2Emodels%2E*%2EcodeMode":{label:{"v1-194jdgf-9":`Kod Modu`},help:{"v1-91zu7f-7m":`Bu ajan ve tam olarak belirtilen sağlayıcı/model için OpenClaw Kod Modu: Açık, modu zorla etkinleştirir; Kapalı, devre dışı bırakır; Varsayılan ise önce ajanın etkinleştirme ayarını, ardından paylaşılan model geçersiz kılmasını, son olarak da tools.codeMode.enabled değerini devralır. Bu, seçilen çalışma ortamını veya Codex'in yerleşik Kod Modunu değiştirmez.`}},"agents%2Eentries%2E*%2EreasoningDefault":{label:{"v1-drq4cj-n":`Ajanın Varsayılan Akıl Yürütme Ayarı`},help:{"v1-13ly0xf-3m":`Ajan bazında isteğe bağlı varsayılan akıl yürütme görünürlüğü (on|off|stream). Mesaj veya oturum bazında akıl yürütme geçersiz kılması ayarlanmadığında uygulanır.`}},"agents%2Eentries%2E*%2Eruntime":{label:{"v1-10xv3pm-d":`Ajan Çalışma Ortamı`},help:{"v1-avjgkf-3l":`Bu ajan için isteğe bağlı çalışma ortamı tanımlayıcısı. Varsayılan OpenClaw yürütmesi için embedded, harici ACP yürütme altyapısının varsayılanları için acp kullanın.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp":{label:{"v1-81375y-h":`Ajan ACP Çalışma Ortamı`},help:{"v1-91zvdk-3i":`runtime.type=acp olduğunda bu ajan için ACP çalışma zamanı varsayılanları. Bağlama düzeyindeki ACP geçersiz kılmaları her konuşmada öncelikli olmaya devam eder.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Eagent":{label:{"v1-ildwsn-n":`Ajanın ACP Çalıştırma Altyapısı Ajanı`},help:{"v1-1pm98vp-37":`Bu OpenClaw ajanı için kullanılacak isteğe bağlı ACP çalıştırma altyapısı ajan kimliği (örneğin codex, claude, cursor, gemini, openclaw).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ebackend":{label:{"v1-1vygqw2-h":`Ajanın ACP Arka Ucu`},help:{"v1-1u3cdsg-2n":`Bu ajanın ACP oturumları için isteğe bağlı ACP arka uç geçersiz kılması (belirtilmezse genel acp.backend kullanılır).`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Ecwd":{label:{"v1-1ts2vd2-r":`Ajanın ACP Çalışma Dizini`},help:{"v1-d9p9rf-1t":`Bu ajanın ACP oturumları için isteğe bağlı varsayılan çalışma dizini.`}},"agents%2Eentries%2E*%2Eruntime%2Eacp%2Emode":{label:{"v1-1zgumd-e":`Ajanın ACP Modu`},help:{"v1-yatuk4-21":`Bu ajan için isteğe bağlı varsayılan ACP oturum modu (persistent veya oneshot).`}},"agents%2Eentries%2E*%2Eruntime%2Etype":{label:{"v1-8wr11a-i":`Ajanın Çalışma Zamanı Türü`},help:{"v1-139fbk6-2r":`Bu ajanın çalışma zamanı türü: "embedded" (varsayılan OpenClaw çalışma zamanı) veya "acp" (ACP çalıştırma altyapısı varsayılanları).`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2EcdpSourceRange":{label:{"v1-k202bg-12":`Ajanın Korumalı Alan Tarayıcısı CDP Kaynak Aralığı`},help:{"v1-1q1qyso-1d":`CDP kaynak CIDR izin listesi için ajana özel geçersiz kılma.`}},"agents%2Eentries%2E*%2Esandbox%2Ebrowser%2Enetwork":{label:{"v1-7jh9lr-t":`Ajanın Korumalı Alan Tarayıcısı Ağı`},help:{"v1-13bdfww-4c":`Korumalı alan tarayıcısının Docker ağı için ajan bazında geçersiz kılma ayarı. Bir köprü ağı kullanın; tarayıcı denetimi dışa açılmış CDP bağlantı noktaları gerektirdiğinden "none" desteklenmez.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2EdangerouslyAllowContainerNamespaceJoin":{label:{"v1-n1z0dm-1f":`Ajan Korumalı Alanı Docker Konteyner Ad Alanına Katılmaya İzin Ver`},help:{"v1-1xtnseb-2i":`Korumalı alan Docker ağ modunda konteyner ad alanlarına katılmak için ajan bazında TEHLİKELİ geçersiz kılma ayarı.`}},"agents%2Eentries%2E*%2Esandbox%2Edocker%2Egpus":{label:{"v1-nbwnmy-p":`Ajan Korumalı Alanı Docker GPU'ları`},help:{"v1-1kek1n2-1t":`Korumalı alan konteynerleri için ajan bazında Docker GPU doğrudan erişim geçersiz kılma ayarı.`}},"agents%2Eentries%2E*%2Eskills":{label:{"v1-nfmhzv-i":`Ajan Beceri Filtresi`},help:{"v1-igchue-6v":`Bu ajan için isteğe bağlı beceri izin listesi. Belirtilmezse ajan, ayarlanmışsa agents.defaults.skills değerini devralır; aksi takdirde beceriler sınırsız kalır. Hiçbir beceriye izin vermemek için [] olarak ayarlayın. Açıkça belirtilen bir liste, devralınan varsayılanlarla birleştirilmek yerine bunların tamamen yerini alır.`}},"agents%2Eentries%2E*%2EskillsLimits":{label:{"v1-dghtbk-j":`Ajan Skills Sınırları`},help:{"v1-1sv10v9-4y":`Beceri alt sistemi bütçeleri için isteğe bağlı ajan bazında geçersiz kılma ayarları. Bir ajan, ikinci bir genel bağlam sınırı yolu oluşturmadan farklı bir beceri istemi bütçesine ihtiyaç duyduğunda bunu kullanın.`}},"agents%2Eentries%2E*%2EskillsLimits%2EmaxSkillsPromptChars":{label:{"v1-mg9zup-t":`Ajan Skills İstemi Maksimum Karakter Sayısı`},help:{"v1-dys63y-52":`Beceri isteminin karakter bütçesi için aracıya özel geçersiz kılma ayarı. Aynı bütçeyi contextLimits üzerinden yönlendirmek yerine mevcut skills.limits.maxSkillsPromptChars yolunu genişletir.`}},"agents%2Eentries%2E*%2Esubagents%2EdelegationMode":{label:{"v1-bhpjpo-p":`Alt Aracıya Görev Devretme Modu`},help:{"v1-1rkgh6p-4s":`Alt aracıya görev devretme düzeyi için aracıya özel geçersiz kılma ayarı. Bu aracının ana oturumunda "prefer", diğer yerlerde "suggest" kullanmak için belirtmeyin; açıkça belirtilen "prefer" veya "suggest" her zaman önceliklidir.`}},"agents%2Eentries%2E*%2EthinkingDefault":{label:{"v1-ymctpn-m":`Aracının Varsayılan Düşünme Düzeyi`},help:{"v1-173q7vy-43":`Aracıya özel, isteğe bağlı varsayılan düşünme düzeyi. Mesaj veya oturum düzeyinde bir geçersiz kılma ayarlanmadığında bu aracı için agents.defaults.thinkingDefault değerini geçersiz kılar.`}},"agents%2Eentries%2E*%2Etools%2EalsoAllow":{label:{"v1-1kf1wpw-u":`Aracının Araç İzin Listesine Eklemeler`},help:{"v1-1550ui9-46":`Genel politikaya ve profil politikasına ek olarak uygulanan, aracıya özel araç izin listesi. Uzmanlaşmış aracılarda yanlışlıkla yetki genişlemesini önlemek için kapsamını dar tutun.`}},"agents%2Eentries%2E*%2Etools%2EbyProvider":{label:{"v1-w3qxm8-t":`Sağlayıcıya Göre Aracı Araç Politikası`},help:{"v1-mthxv9-4t":`Kanal kapsamındaki yetenekleri denetlemek için aracıya ve sağlayıcıya özel araç politikası geçersiz kılma ayarları. Bir aracının bir sağlayıcıda diğerlerine göre daha sıkı kısıtlamalara ihtiyacı olduğunda kullanın.`}},"agents%2Eentries%2E*%2Etools%2EcodeMode":{label:{"v1-1l1vsai-f":`Aracı Kod Modu`},help:{"v1-118t8u5-65":`Aracıya özel Code Mode seçenekleri. Açıkça belirtilen enabled, paylaşılan modelin ve genel etkinleştirme varsayılanlarının önüne geçer; aracıya özel model codeMode geçersiz kılması önceliklidir. Diğer seçenekler, etkinleştirmeyi değiştirmeden tools.codeMode üzerine birleştirilir.`}},"agents%2Eentries%2E*%2Etools%2Eexec%2EtimeoutSeconds":{label:{"v1-leof0k-s":`Aracı Çalıştırma Zaman Aşımı (Saniye)`}},"agents%2Eentries%2E*%2Etools%2Egithub":{label:{"v1-1nky9u1-y":`Aracı GitHub CLI Kimliğini Geçersiz Kılma`},help:{"v1-mjwdh4-38":`Bu aracı için yönetilen GitHub CLI kimliğini ve Git yazar bilgilerini tamamen geçersiz kılar. Sistem kimliğini devralmak için belirtmeyin.`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-1i4m01d-m":`Aracı Git Yazar E-postası`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-1j0pl20-l":`Aracı Git Yazar Adı`}},"agents%2Eentries%2E*%2Etools%2Egithub%2Ekind":{label:{"v1-14pqhd4-s":`Aracı GitHub Kimlik Bilgisi Türü`}},"agents%2Eentries%2E*%2Etools%2Egithub%2EprofileId":{label:{"v1-1fmzzvk-s":`Aracı GitHub Profil Sürümü`}},"agents%2Eentries%2E*%2Etools%2Emessage%2Eactions%2Eallow":{label:{"v1-1cpyq5g-u":`Aracı İçin İzin Verilen Mesaj Eylemleri Listesi`},help:{"v1-1g5gov3-67":`Mesaj aracı için aracıya özel izin verilen mesaj eylemleri listesi. Herkese açık korumalı alan aracıları için ["send"] gibi asgari bir liste belirleyin; böylece okuma, düzenleme, silme, tepki verme ve sağlayıcıya özel diğer mesaj eylemleri gizli ve engellenmiş kalır.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-1js3r9e-1c":`Aracı Bağlamlar Arası Mesajlaşma (Sağlayıcılar Arası)`},help:{"v1-pehesn-49":`Sağlayıcılar arası gönderim için ajan bazında geçersiz kılma ayarı. Genel ayarı devralır (varsayılan: true). Bu ajan için sağlayıcılar arası mesajlaşmayı engellemek üzere false olarak ayarlayın.`}},"agents%2Eentries%2E*%2Etools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-z29ji-19":`Ajanın Bağlamlar Arası Mesajlaşması (Aynı Sağlayıcı)`},help:{"v1-s9u09h-4t":`Aynı sağlayıcıdaki diğer konuşmalara gönderim için ajan bazında mesaj koruması. Yalnızca mevcut konuşmada mesajlaşabilen herkese açık ajanlar için hem bu ayarı hem de allowAcrossProviders ayarını false olarak ayarlayın.`}},"agents%2Eentries%2E*%2Etools%2Eprofile":{label:{"v1-kybcdd-i":`Ajan Araç Profili`},help:{"v1-1du76ix-57":`Bir ajan farklı bir temel yetenek kümesine ihtiyaç duyduğunda araç profili seçimini ajan bazında geçersiz kılar. Ajanlar arasındaki politika farklılıklarının bilinçli ve incelenebilir kalması için bunu sınırlı kullanın.`}},"agents%2Eentries%2E*%2Etools%2Eswarm":{label:{"v1-54zhti-b":`Ajan Sürüsü`},help:{"v1-420ljs-2c":`Ajan bazlı sürü ayarı geçersiz kılması. Değerler, üst düzey tools.swarm yapılandırmasıyla birleştirilir ve çakışan değerlerin yerini alır.`}},"agents%2Eentries%2E*%2EtypingMode":{label:{"v1-1nl61h4-h":`Ajan Yazma Modu`},help:{"v1-oxir52-2e":`Diğer ajanları değiştirmeden tek bir ajan için varsayılan yazmaya başlama politikasını geçersiz kılar.`}},"agents%2Eentries%2E*%2EutilityModel":{label:{"v1-1k6g1v3-j":`Ajan Yardımcı Modeli`},help:{"v1-1v9oskz-2z":`Kısa dahili görevler için isteğe bağlı, ajan bazlı yardımcı model ayarı. agents.defaults.utilityModel ayarını geçersiz kılar.`}},"agents%2Eownership":{label:{"v1-uuzaon-q":`Ajan Sahipliği Nesli`},help:{"v1-m2hp61-8g":`Çok ajanlı sahiplik için kalıcı nesil işaretçisi. "explicit", ortam kanalları, kalp atışı, sistem ajanına danışmalar, Talk, cron ve doğrudan CLI işlemlerinin ilgili yüzeye özgü bir sahip belirlemesi veya güvenli biçimde işlemi reddetmesi gerektiği anlamına gelir. OpenClaw, bir ajan filosu oluştururken veya taşırken bunu otomatik olarak ekler; tek bir ajan için bu alanı eklemeyin.`}},approvals:{label:{"v1-1m405m7-9":`Onaylar`},help:{"v1-4y3in-5w":`exec ve eklenti onay isteklerini kaynak oturum dışındaki sohbet hedeflerine iletmeye yönelik onay yönlendirme denetimleri. Operatörlerin onayları oturum dışında da açıkça görmesi gerekmiyorsa bunları devre dışı bırakın.`}},"approvals%2Eexec":{label:{"v1-hhphou-o":`exec Onayı İletimi`},help:{"v1-1r2mozk-5v":`Etkinleştirme, yönlendirme modu, filtreler ve açıkça belirtilen hedefler dahil olmak üzere exec onayı iletme davranışını gruplandırır. Onay istemlerinin yalnızca kaynak konuşma dizisine değil, operasyonel kanallara da ulaşması gerektiğinde buradan yapılandırın.`}},"approvals%2Eexec%2EagentFilter":{label:{"v1-1gg1zh3-l":`Onay Aracısı Filtresi`},help:{"v1-xbuhd3-5i":'Onayları iletilebilecek aracı kimliklerinin isteğe bağlı izin listesi; örneğin `["primary", "ops-agent"]`. İletimin etki alanını sınırlamak ve ilgisiz aracılar için kanallara bildirim göndermemek üzere bunu kullanın.'}},"approvals%2Eexec%2Eenabled":{label:{"v1-oukdkb-m":`exec Onaylarını İlet`},help:{"v1-1t0whe8-5s":`exec onay isteklerinin yapılandırılmış teslim hedeflerine iletilmesini etkinleştirir (varsayılan: false). Düşük riskli kurulumlarda devre dışı bırakın ve yalnızca onaylara yanıt verecek kişilerin kanalda görünen istemlere ihtiyacı olduğunda etkinleştirin.`}},"approvals%2Eexec%2Emode":{label:{"v1-733gc4-o":`Onay İletim Modu`},help:{"v1-1dedfo4-69":`Onay istemlerinin nereye gönderileceğini belirler: "session" kaynak sohbeti, "targets" yapılandırılmış hedefleri kullanır; "both" ise her iki yoldan da gönderir. Temel seçenek olarak "session" kullanın ve yalnızca operasyonel iş akışı yedeklilik gerektirdiğinde kapsamı genişletin.`}},"approvals%2Eexec%2EsessionFilter":{label:{"v1-1lqr9y4-n":`Onay Oturumu Filtresi`},help:{"v1-smeg8e-5u":'Alt dize veya düzenli ifade tarzı desenlerle eşleştirilen isteğe bağlı oturum anahtarı filtreleri; örneğin `["discord:", "^agent:ops:"]`. Paylaşılan hedeflere yalnızca amaçlanan onay bağlamlarının iletilmesi için dar kapsamlı desenler kullanın.'}},"approvals%2Eexec%2Etargets":{label:{"v1-uht69z-r":`Onay İletme Hedefleri`},help:{"v1-17ah848-5u":`İletme modu hedefleri içerdiğinde kullanılan, her biri kanal ve hedef ayrıntılarını içeren açıkça tanımlanmış teslim hedefleri. Hedef listelerini en az ayrıcalık ilkesine uygun tutun ve geniş kapsamlı iletmeyi etkinleştirmeden önce her hedefi doğrulayın.`}},"approvals%2Eexec%2Etargets%5B%5D%2EaccountId":{label:{"v1-1pizj1x-q":`Onay Hedefi Hesap Kimliği`},help:{"v1-16zopng-5e":`Onayların belirli bir hesap bağlamı üzerinden yönlendirilmesi gerektiğinde, çok hesaplı kanal kurulumları için isteğe bağlı hesap seçici. Bunu yalnızca hedef kanalda birden fazla kimlik yapılandırılmışsa kullanın.`}},"approvals%2Eexec%2Etargets%5B%5D%2Echannel":{label:{"v1-14ol0m8-n":`Onay Hedefi Kanalı`},help:{"v1-ji1igl-59":`İletilen onayların teslimi için kullanılan kanal/sağlayıcı kimliği; örneğin discord, slack veya bir eklenti kanalı kimliği. Bilinmeyen yönlendirmeler nedeniyle onayların sessizce başarısız olmaması için yalnızca geçerli kanal kimlikleri kullanın.`}},"approvals%2Eexec%2Etargets%5B%5D%2EthreadId":{label:{"v1-18ez6dm-p":`Onay Hedefi Konuşma Dizisi Kimliği`},help:{"v1-1axynw7-59":`İletilen onayların konuşma dizilerine teslimini destekleyen kanallar için isteğe bağlı konuşma dizisi/konu hedefi. Onay trafiğini ana kanallar yerine operasyonel konuşma dizileriyle sınırlı tutmak için bunu kullanın.`}},"approvals%2Eexec%2Etargets%5B%5D%2Eto":{label:{"v1-19bm483-r":`Onay Teslim Hedefi`},help:{"v1-1ijng7e-5n":`Hedef kanaldaki hedef tanımlayıcısı (sağlayıcıya bağlı olarak kanal kimliği, kullanıcı kimliği veya ileti dizisinin kök iletisi). Hedef biçimi kanal entegrasyonları arasında farklılık gösterdiğinden, her sağlayıcı için nasıl yorumlandığını doğrulayın.`}},"approvals%2Eplugin":{label:{"v1-swf7m4-q":`Eklenti Onayı İletimi`},help:{"v1-1m6pzxv-6b":`Etkinleştirme, yönlendirme modu, filtreler ve açıkça belirtilen hedefler dahil olmak üzere eklenti onayı iletim davranışını gruplar. Komut yürütme onayı iletiminden bağımsızdır. Eklenti onayı istemlerinin operasyonel kanallara ulaşması gerektiğinde buradan yapılandırın.`}},"approvals%2Eplugin%2EagentFilter":{label:{"v1-12csxm6-s":`Eklenti Onayı Ajan Filtresi`},help:{"v1-jb1bra-4b":'Eklenti onayları iletilebilecek ajan kimliklerini içeren isteğe bağlı izin listesi; örneğin `["primary", "ops-agent"]`. İletimin etki alanını sınırlamak için bunu kullanın.'}},"approvals%2Eplugin%2Eenabled":{label:{"v1-q9f62x-o":`Eklenti Onaylarını İlet`},help:{"v1-1ntctaf-3v":`Eklenti onayı isteklerinin yapılandırılmış teslim hedeflerine iletilmesini etkinleştirir (varsayılan: false). approvals.exec.enabled ayarından bağımsızdır.`}},"approvals%2Eplugin%2Emode":{label:{"v1-1mgp0vb-v":`Eklenti Onayı İletim Modu`},help:{"v1-1h62vy4-3z":`Eklenti onayı istemlerinin nereye gönderileceğini kontrol eder: "session" kaynak sohbeti kullanır, "targets" yapılandırılmış hedefleri kullanır ve "both" her iki yola da gönderir.`}},"approvals%2Eplugin%2EsessionFilter":{label:{"v1-15vplo5-u":`Eklenti Onayı Oturum Filtresi`},help:{"v1-1eppxmt-57":'Alt dize veya düzenli ifade tarzı desenler olarak eşleştirilen isteğe bağlı oturum anahtarı filtreleri; örneğin `["discord:", "^agent:ops:"]`. Yalnızca amaçlanan onay bağlamlarının iletilmesi için dar kapsamlı desenler kullanın.'}},"approvals%2Eplugin%2Etargets":{label:{"v1-1snpvju-y":`Eklenti Onayı İletim Hedefleri`},help:{"v1-o92qze-3k":`Eklenti onayı iletim modu hedefleri içerdiğinde kullanılan, her biri kanal ve varış noktası ayrıntılarına sahip açıkça belirtilmiş teslim hedefleri.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EaccountId":{label:{"v1-oxqv86-x":`Eklenti Onayı Hedef Hesap Kimliği`},help:{"v1-1wf3lqn-3j":`Eklenti onaylarının belirli bir hesap bağlamı üzerinden yönlendirilmesi gerektiğinde, çok hesaplı kanal kurulumları için isteğe bağlı hesap seçici.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Echannel":{label:{"v1-1jz34xt-u":`Eklenti Onayı Hedef Kanalı`},help:{"v1-1mzhzi9-34":`İletilen eklenti onaylarının tesliminde kullanılan kanal/sağlayıcı kimliği; örneğin discord, slack veya bir eklenti kanalı kimliği.`}},"approvals%2Eplugin%2Etargets%5B%5D%2EthreadId":{label:{"v1-1beipnf-w":`Eklenti Onayı Hedef İleti Dizisi Kimliği`},help:{"v1-1scaw9c-2v":`İletilen eklenti onaylarının ileti dizisi içinde teslimini destekleyen kanallar için isteğe bağlı ileti dizisi/konu hedefi.`}},"approvals%2Eplugin%2Etargets%5B%5D%2Eto":{label:{"v1-1df4m22-y":`Eklenti Onayı Hedef Varış Noktası`},help:{"v1-sh5te1-31":`Hedef kanal içindeki varış noktası tanımlayıcısı (sağlayıcıya bağlı olarak kanal kimliği, kullanıcı kimliği veya ileti dizisinin kök iletisi).`}},attachments:{label:{"v1-8925gh-b":`Ekler`},help:{"v1-1xvgkss-40":`Medyayı kalıcı olarak saklayan sağlayıcılar ve araçlar arasında paylaşılan üst düzey saklama davranışı. Genel amaçlı geçici medya dosyalarının belirli bir süre sonunda temizlenmesi gerektiğinde ttlHours kullanın.`}},"attachments%2EttlHours":{label:{"v1-m9sx0s-w":`Ek Saklama TTL Değeri (saat)`},help:{"v1-1g90day-9e":`Genel mtime taramasıyla işlenen, kalıcı olarak saklanan medya için saat cinsinden isteğe bağlı saklama süresi. Bu taramayı devre dışı bırakmak için ayarlamadan bırakın veya eski hazırlanmış medyayı düzenli olarak kaldırmak için 24 (1 gün) ya da 168 (7 gün) gibi değerler belirleyin. Yönetilen giden medya (sohbette oluşturulan ekler) kapsam dışındadır ve SQLite ile konuşma dökümlerini dikkate alan kendi saklama politikasını izler.`}},audio:{label:{"v1-11wczsp-5":`Ses`}},auth:{label:{"v1-5xz433-4":`Kimlik Doğrulama`},help:{"v1-1eu3aud-5c":`Birden çok profile ait sağlayıcı kimlik bilgileri ve bekleme süresine dayalı yedek geçiş sıralaması için kullanılan kimlik doğrulama profili kökü. Otomatik yedek geçiş davranışının denetlenebilir kalması için profilleri asgari düzeyde ve açıkça tanımlanmış tutun.`}},"auth%2Eorder":{label:{"v1-gadtii-i":`Kimlik Doğrulama Profili Sırası`},help:{"v1-1x6kknp-1w":`Sağlayıcı başına sıralı kimlik doğrulama profili kimlikleri (otomatik yedek geçiş için kullanılır).`}},"auth%2Eprofiles":{label:{"v1-nbj2kv-d":`Kimlik Doğrulama Profilleri`},help:{"v1-kzoqcn-1j":`Adlandırılmış kimlik doğrulama profilleri (sağlayıcı + mod + isteğe bağlı e-posta).`}},bindings:{label:{"v1-1hcih9f-8":`Bağlamalar`},help:{"v1-y7hrzb-4i":`Yönlendirme ve kalıcı ACP konuşma sahipliği için üst düzey bağlama kuralları. Normal yönlendirme için type=route, kalıcı ACP çalıştırma altyapısı bağlamaları için type=acp kullanın.`}},"bindings%5B%5D%2Eacp":{label:{"v1-1c1of5r-l":`ACP Bağlamasına Özel Ayarlar`},help:{"v1-1t4lisi-44":`bindings[].type=acp için bağlama başına isteğe bağlı ACP ayarları. Bu katman, eşleşen konuşma için agents.entries.*.runtime.acp varsayılanlarını geçersiz kılar.`}},"bindings%5B%5D%2Eacp%2Ebackend":{label:{"v1-1qfk8bu-j":`ACP Bağlaması Arka Ucu`},help:{"v1-rsrbkp-2x":`Bu bağlamaya özel ACP arka ucu ayarı (belirtilmezse önce ajanın çalışma zamanı ACP arka ucu, ardından genel acp.backend kullanılır).`}},"bindings%5B%5D%2Eacp%2Ecwd":{label:{"v1-1w2wp4u-t":`ACP Bağlaması Çalışma Dizini`},help:{"v1-ngpkj0-1y":`Bu bağlamadan oluşturulan ACP oturumları için çalışma dizini geçersiz kılma ayarı.`}},"bindings%5B%5D%2Eacp%2Elabel":{label:{"v1-mc3w70-h":`ACP Bağlama Etiketi`},help:{"v1-azce82-23":`Bu bağlı konuşmada ACP durumu ve tanılama bilgileri için kolay anlaşılır etiket.`}},"bindings%5B%5D%2Eacp%2Emode":{label:{"v1-1mko9zx-g":`ACP Bağlama Modu`},help:{"v1-cgq8xv-1v":`Bu bağlama için ACP oturum modu geçersiz kılma ayarı (persistent veya oneshot).`}},"bindings%5B%5D%2EagentId":{label:{"v1-1j1g5rg-g":`Bağlama Ajan Kimliği`},help:{"v1-17ra0cl-4m":`İlgili bağlama eşleşme kuralı sağlandığında trafiği alan hedef ajanın kimliği. Yönlendirmenin çalışma zamanında başarısız olmaması için yalnızca yapılandırılmış geçerli ajan kimliklerini kullanın.`}},"bindings%5B%5D%2Ematch":{label:{"v1-13eg2e3-i":`Bağlama Eşleşme Kuralı`},help:{"v1-sc1w2e-51":`Kanal ve isteğe bağlı hesap/eş kısıtlamaları dahil olmak üzere, bir bağlamanın ne zaman uygulanacağını belirleyen eşleşme kuralı nesnesi. Ajanın farklı bağlamlarda yanlışlıkla kontrolü devralmasını önlemek için kuralları dar kapsamlı tutun.`}},"bindings%5B%5D%2Ematch%2EaccountId":{label:{"v1-1csp6k6-i":`Bağlama Hesap Kimliği`},help:{"v1-1d209g7-56":`Çok hesaplı kanal kurulumlarında bağlamanın yalnızca tek bir kimliğe uygulanmasını sağlayan isteğe bağlı hesap seçici. Yönlendirme için hesap kapsamı gerektiğinde bunu kullanın, aksi takdirde ayarlamadan bırakın.`}},"bindings%5B%5D%2Ematch%2Echannel":{label:{"v1-mucsyp-f":`Bağlama Kanalı`},help:{"v1-d22m5-54":"Bu bağlamanın uygulandığı kanal/sağlayıcı tanımlayıcısı; örneğin `telegram`, `discord` veya bir eklenti kanal kimliği. Bağlama değerlendirmesinin güvenilir şekilde çalışması için yapılandırılmış kanal anahtarını aynen kullanın."}},"bindings%5B%5D%2Ematch%2EguildId":{label:{"v1-1hgwzxi-g":`Bağlama Sunucu Kimliği`},help:{"v1-jzzfj1-4x":`Çok sunuculu dağıtımlarda bağlama değerlendirmesi için isteğe bağlı Discord tarzı topluluk/sunucu kimliği kısıtlaması. Aynı eş kimlikleri farklı topluluklarda bulunabiliyorsa bunu kullanın.`}},"bindings%5B%5D%2Ematch%2Epeer":{label:{"v1-1x3w5cz-i":`Bağlama Eş Eşleştirmesi`},help:{"v1-gcjxff-4i":`Belirli konuşmalar için eş türünü ve eş kimliğini içeren isteğe bağlı eş eşleştiricisi. Yalnızca tek bir doğrudan konuşma, grup veya kanal hedefinin bir ajana sabitlenmesi gerektiğinde bunu kullanın.`}},"bindings%5B%5D%2Ematch%2Epeer%2Eid":{label:{"v1-181lr2n-f":`Bağlama Eş Kimliği`},help:{"v1-86fbh7-4b":`Eş eşleştirmesinde kullanılan, sağlayıcıdan alınan sohbet kimliği, kanal kimliği veya grup kimliği gibi konuşma tanımlayıcısı. Bildirim olmadan eşleşme başarısızlıkları yaşanmaması için bunu birebir aynı tutun.`}},"bindings%5B%5D%2Ematch%2Epeer%2Ekind":{label:{"v1-wii7p0-h":`Bağlama Eş Türü`},help:{"v1-uufscp-4x":`Eş konuşma türü: "direct", "group", "channel" veya eski "dm" (direct için kullanımdan kaldırılmış takma ad). Yeni yapılandırmalarda "direct" değerini tercih edin ve türü kanalın anlamıyla uyumlu tutun.`}},"bindings%5B%5D%2Ematch%2Eroles":{label:{"v1-1ishhl3-d":`Bağlama Rolleri`},help:{"v1-6s891m-4k":`Sohbet bağlamına roller ekleyen sağlayıcılar tarafından kullanılan isteğe bağlı rol tabanlı filtre listesi. Ayrıcalıklı veya operasyonel rollere ait trafiği uzmanlaşmış ajanlara yönlendirmek için bunu kullanın.`}},"bindings%5B%5D%2Ematch%2EteamId":{label:{"v1-1yh6sjs-f":`Bağlama Ekip Kimliği`},help:{"v1-hh9ps2-48":`Sohbetleri ekipler kapsamında tutan sağlayıcılar tarafından kullanılan isteğe bağlı ekip/çalışma alanı kimliği kısıtlaması. Bağlamaları tek bir çalışma alanı bağlamıyla sınırlandırmanız gerektiğinde bunu ekleyin.`}},"bindings%5B%5D%2Esession":{label:{"v1-1weokpm-f":`Bağlama Oturumu`},help:{"v1-x325l2-4v":`Bu bağlamayla eşleşen konuşmalar için isteğe bağlı rota oturumu geçersiz kılmaları. Dar kapsamlı bir rotanın aynı ajanı kullanmaya devam etmesi ancak oturum sürekliliğini farklı şekilde yalıtması gerektiğinde bunu kullanın.`}},"bindings%5B%5D%2Esession%2EdmScope":{label:{"v1-1jcplmp-o":`Bağlama Oturumunun Doğrudan Mesaj Kapsamı`},help:{"v1-10sg3xw-4s":`Bu rota bağlaması için isteğe bağlı doğrudan mesaj oturumu kapsamı geçersiz kılması. Örneğin, seçili doğrudan mesaj muhatapları için "per-account-channel-peer" kullanırken genel session.dmScope="main" ayarını koruyun.`}},"bindings%5B%5D%2Esession%2EgroupScope":{label:{"v1-1dkb0a1-r":`Bağlama Oturumunun Grup Kapsamı`},help:{"v1-1ys2u7k-6n":`Bu rota bağlaması için isteğe bağlı grup/kanal oturumu kapsamı geçersiz kılması. "per-group", eşleşen odaları ayrı tutar ve dmScope değerinden bağımsız olarak ajanın ana oturumu tarafından arka planda izlenmelerini sağlar; "main" ise bu odaların bağlamını ana oturumla birleştirir ve izleme gerektirmez.`}},"bindings%5B%5D%2Etype":{label:{"v1-1l3bpjq-c":`Bağlama Türü`},help:{"v1-172mhtk-3o":`Bağlama türü. Normal yönlendirme için "route" kullanın (veya eski rota girdilerinde bu alanı atlayın); kalıcı ACP konuşma bağlamaları için "acp" kullanın.`}},broadcast:{label:{"v1-awqjh0-j":`Ajan grubu konuşma dizileri`},help:{"v1-1tz72sr-6b":`Yapılandırılmış birden fazla ajanı, her biri kendi oturumunda olacak şekilde, gelen tek bir konuşmada çalıştırmak için ajan grubu konuşma dizilerini kullanın. Kanal bilgisi içeren girdiler, sınırlı sayıda takip turunu destekler; eski WhatsApp eş dizileri ise tek geçişli davranışı korur.`}},"broadcast%2E*":{label:{"v1-k5obp6-10":`Ajan grubu katılımcıları ve seçenekleri`},help:{"v1-1b63zmt-7d":`Bir ajan kimlikleri dizisi veya agents, mentionGating, maxRounds ve maxTurns alanlarını içeren katı kurallı bir nesne yapılandırmak için kanal bilgisi içeren bir eş kimliği (örneğin "telegram:-100123") kullanın. Kanal bilgisi içeren girdiler, eski WhatsApp eş anahtarlarına göre önceliklidir ve en fazla 16 ajana izin verir.`}},"broadcast%2E*%2Eagents":{label:{"v1-od29y1-o":`Ajan grubu katılımcıları`},help:{"v1-g5o0ky-43":`agents.entries içindeki katılımcı ajan kimlikleri (en fazla: 16). Her katılımcı bu kanal, hesap, konuşma ve konuşma dizisi için kendi oturumunu kullanır.`}},"broadcast%2E*%2EmaxRounds":{label:{"v1-1l8x0fc-q":`Ajan Grubu Maksimum Tur Sayısı`},help:{"v1-i6v4jc-5a":`İlk tur dahil, gelen mesaj başına maksimum tur sayısı (tam sayı: 1–4, varsayılan: 1). Sonraki turlarda diğer katılımcıların yanıtları, kime ait oldukları belirtilerek sınırlı biçimde paylaşılır ve tüm katılımcılar pas geçtiğinde turlar sona erer.`}},"broadcast%2E*%2EmaxTurns":{label:{"v1-aobwmz-p":`Ajan Grubu Maksimum Katılımcı Sırası Sayısı`},help:{"v1-1kiv8dy-72":`Tüm turlar boyunca gelen mesaj başına maksimum katılımcı sırası sayısı (tam sayı: 1–32, varsayılan: agents.length). Paralel gönderimden önce sıralar ayrılır; bu sınır, fiziksel mesaj parçalarını veya araç gönderimlerini değil, ajan sıralarını sınırlar. Yeniden başlatma sonrasında kullanım bütçeleri kaldığı yerden devam etmez.`}},"broadcast%2E*%2EmentionGating":{label:{"v1-1ykkdid-t":`Ajan Grubunda Bahsetmeye Göre Seçim`},help:{"v1-uay9zu-5u":`Eşleşme varsa yalnızca açıkça @ ile bahsedilen katılımcıları seçer; aksi halde tüm katılımcıları çalıştırır (varsayılan: true). Tek başına adlar veya emojiler katılımcı seçmez. Kanal izin listeleri ve kabul kuralları geçerliliğini korur.`}},"broadcast%2Estrategy":{label:{"v1-nm62ea-k":`Ajan Grubu Stratejisi`},help:{"v1-p4k9hu-4q":`Katılımcı yürütme sırası: "parallel" (varsayılan), ajanları eş zamanlı çalıştırırken "sequential", yapılandırılan sırayla çalıştırır. Her tur, bir sonraki başlamadan önce tamamlanır.`}},browser:{label:{"v1-13dzmen-7":`Tarayıcı`},help:{"v1-5b74wi-5l":`Yerel veya uzak CDP bağlantısı, profil yönlendirmesi ve ekran görüntüsü/anlık görüntü davranışı için tarayıcı çalışma zamanı kontrolleri. Otomasyon iş akışınız özel tarayıcı aktarım ayarları gerektirmediği sürece varsayılanları koruyun.`}},"browser%2EallowSystemProfileImport":{label:{"v1-17h3693-r":`Sistem Profilini İçe Aktarmaya İzin Ver`},help:{"v1-1lsvlxw-5w":`macOS ana makinelerinin, Chrome ailesine ait yerel bir sistem profilindeki çerezleri yönetilen bir OpenClaw tarayıcı profiline aktarmasına izin verir. Tarayıcı profili çerezlerinin içe aktarılmasını ve buna bağlı macOS Anahtar Zinciri izin istemini önlemek için bu seçeneği devre dışı bırakın.`}},"browser%2EattachOnly":{label:{"v1-1pt3uds-o":`Tarayıcı Yalnızca Bağlanma Modu`},help:{"v1-xaw7xm-4s":`Tarayıcı modunu, yerel tarayıcı işlemlerini başlatmadan yalnızca mevcut oturumlara bağlanacak şekilde kısıtlar. Tüm tarayıcı oturumları uzak bir CDP sağlayıcısı tarafından harici olarak yönetildiğinde bunu kullanın.`}},"browser%2EcdpUrl":{label:{"v1-oc982r-f":`Tarayıcı CDP URL'si`},help:{"v1-2n72jb-65":`Harici olarak yönetilen bir tarayıcı örneğine bağlanmak için kullanılan CDP/DevTools uç noktası URL'si. Bunu merkezi tarayıcı ana makineleri, tüneller veya mevcut oturumlara bağlanmak için kullanın ve URL erişimini güvenilir ağ yollarıyla sınırlı tutun.`}},"browser%2EdefaultProfile":{label:{"v1-gx1r6n-n":`Tarayıcı Varsayılan Profili`},help:{"v1-a6xo96-52":`Çağrıyı yapanlar açıkça bir profil seçmediğinde seçilen varsayılan tarayıcı profili adı. Yanlışlıkla farklı bağlamlara ait durum bilgilerinin kullanılmasını azaltmak için varsayılan olarak sabit, düşük yetkili bir profil kullanın.`}},"browser%2Eenabled":{label:{"v1-ur2izq-f":`Tarayıcı Etkin`},help:{"v1-19qr4oj-56":`Tarayıcı araçlarının ve CDP tabanlı iş akışlarının çalışabilmesi için Gateway'de tarayıcı özelliklerini etkinleştirir. Tarayıcı otomasyonu gerekmiyorsa saldırı yüzeyini ve başlatma yükünü azaltmak için devre dışı bırakın.`}},"browser%2EevaluateEnabled":{label:{"v1-17r8d2b-o":`Tarayıcıda Betik Değerlendirme Etkin`},help:{"v1-1oa79mq-59":`Desteklenen ortamlarda, çalışma zamanında betik değerlendirmesi için tarayıcı tarafındaki değerlendirme yardımcılarını etkinleştirir. İş akışlarınız anlık görüntü alma ve gezinmenin ötesinde betik değerlendirmesi gerektirmiyorsa devre dışı bırakın.`}},"browser%2EexecutablePath":{label:{"v1-nxumpk-n":`Tarayıcı Yürütülebilir Dosyasının Yolu`},help:{"v1-1plb4ki-6i":`Otomatik keşif ana makine ortamınız için yetersiz kaldığında kullanılacak açıkça belirtilmiş tarayıcı yürütülebilir dosyası yolu. Başlatma davranışının yeniden başlatmalar arasında tutarlı kalması için sabit bir mutlak yol veya işletim sisteminizin kullanıcı ana dizinini belirten ~ ile başlayan bir yol kullanın.`}},"browser%2EextensionRelay":{label:{"v1-1fifm3z-n":`Tarayıcı Uzantısı Aktarıcısı`},help:{"v1-6ywlwr-4e":`Chrome uzantısı aktarıcısının kimlik doğrulama uyumluluğu ayarları. Eski sürüm uyumluluk dönemini yalnızca eşleştirilmiş eski uzantılar veya harici CDP istemcileri hâlâ buna ihtiyaç duyuyorsa sürdürün.`}},"browser%2EextensionRelay%2EallowLegacyAuth":{label:{"v1-2qob0y-v":`Eski Tarayıcı Aktarıcısı Kimlik Doğrulamasına İzin Ver`},help:{"v1-pj2e90-63":`Eski Bearer, Basic ve token-subprotocol aktarıcı kimlik doğrulama yöntemlerini geçici olarak kabul eder. Varsayılan: bir geçiş dönemi boyunca true. Tüm uzantılar ve harici CDP istemcileri Browser Relay Authentication v2 kullanmaya başladıktan sonra false olarak ayarlayın.`}},"browser%2Eheadless":{label:{"v1-1ksb99t-l":`Tarayıcı Arayüzsüz Modu`},help:{"v1-1rswq8j-5a":`Yerel başlatıcı tarayıcı örneklerini başlattığında tarayıcının arayüzsüz modda açılmasını zorunlu kılar. Sunucu ortamlarında arayüzsüz modu etkin tutun ve yalnızca görünür kullanıcı arayüzü üzerinden hata ayıklama gerektiğinde devre dışı bırakın.`}},"browser%2EnoSandbox":{label:{"v1-nx4cbr-n":`Tarayıcı Korumalı Alanını Devre Dışı Bırakma Modu`},help:{"v1-slntux-4w":`Korumalı alanın çalışma zamanında başarısız olduğu ortamlar için Chromium korumalı alan yalıtımı bayraklarını devre dışı bırakır. İşlem yalıtımı korumaları azaldığından, mümkün olduğunca bu ayarı kapalı tutun.`}},"browser%2Eprofiles":{label:{"v1-fih34f-g":`Tarayıcı Profilleri`},help:{"v1-1x8lf05-51":`İsteğe bağlı meta verilerle CDP bağlantı noktalarına veya URL'lerine açıkça yönlendirme yapmak için kullanılan adlandırılmış tarayıcı profili bağlantı eşlemesi. Profil adlarını tutarlı tutun ve çakışan uç nokta tanımlarından kaçının.`}},"browser%2Eprofiles%2E*%2EattachOnly":{label:{"v1-32uv4v-w":`Tarayıcı Profili Yalnızca Bağlanma Modu`},help:{"v1-2b5zs0-5a":`Yerel tarayıcıyı başlatmayı atlayıp yalnızca mevcut bir CDP uç noktasına bağlanan, profile özel yalnızca bağlanma ayarı. Bir profil harici olarak yönetilirken diğerleri yerel olarak başlatıldığında kullanışlıdır.`}},"browser%2Eprofiles%2E*%2EcdpPort":{label:{"v1-1avgh1q-o":`Tarayıcı Profili CDP Bağlantı Noktası`},help:{"v1-gx1yiq-49":`Tarayıcı örneklerine URL yerine bağlantı noktası üzerinden bağlanırken kullanılan, profile özel yerel CDP bağlantı noktası. Bağlantı çakışmalarını önlemek için her profilde benzersiz bağlantı noktaları kullanın.`}},"browser%2Eprofiles%2E*%2EcdpUrl":{label:{"v1-elwsl2-n":`Tarayıcı Profili CDP URL'si`},help:{"v1-x491r0-64":`Profil adına göre açıkça tarayıcı yönlendirmesi yapmak için kullanılan, profile özel CDP/DevTools uç nokta URL'si. Bunu uzak CDP sunucuları, tüneller veya çalışan bir Chrome DevTools uç noktası üzerinden bağlanması gereken mevcut oturum profilleri için kullanın.`}},"browser%2Eprofiles%2E*%2Edriver":{label:{"v1-1j1f8vg-m":`Tarayıcı Profili Sürücüsü`},help:{"v1-17byyx6-5r":`Profile özgü tarayıcı sürücüsü modu. CDP tabanlı profiller için "openclaw" (veya eski "clawd"), Chrome DevTools MCP bağlantısı için "existing-session", kimliği doğrulanmış Chrome uzantısı aktarıcısı için "extension" kullanın.`}},"browser%2Eprofiles%2E*%2EexecutablePath":{label:{"v1-154onzh-v":`Tarayıcı Profili Yürütülebilir Dosya Yolu`},help:{"v1-29azyv-4w":`Yerel olarak başlatılan yönetilen tarayıcı profilleri için profile özgü tarayıcı yürütülebilir dosya yolu. browser.executablePath değerini geçersiz kılar ve işletim sisteminin kullanıcı ana dizinini belirtmek için ~ ile başlayan yolları kabul eder.`}},"browser%2Eprofiles%2E*%2Eheadless":{label:{"v1-1dkezh4-t":`Tarayıcı Profili Arayüzsüz Modu`},help:{"v1-p4jtgv-4u":`Yerel olarak başlatılan tarayıcı örnekleri için profile özgü arayüzsüz mod ayarı. Diğer tüm profillerde browser.headless ayarını zorunlu kılmadan bir profilin arayüzsüz kalması gerektiğinde bunu kullanın.`}},"browser%2Eprofiles%2E*%2EmcpArgs":{label:{"v1-1l3gwbt-v":`Tarayıcı Profili Chrome MCP Argümanları`},help:{"v1-rc45ke-5g":`existing-session bağlantısı için --no-usage-statistics gibi profile özgü ek Chrome DevTools MCP argümanları. Buradaki uç nokta argümanları, yerleşik otomatik bağlantı veya tarayıcı URL'si seçimini geçersiz kılar.`}},"browser%2Eprofiles%2E*%2EmcpCommand":{label:{"v1-fncq59-y":`Tarayıcı Profili Chrome MCP Komutu`},help:{"v1-1xpty8o-2h":`existing-session bağlantısı için profile özgü Chrome DevTools MCP komutu. Varsayılan olarak npx kullanılır.`}},"browser%2Eprofiles%2E*%2EuserDataDir":{label:{"v1-if29w-t":`Tarayıcı Profili Kullanıcı Verisi Dizini`},help:{"v1-5xvgex-9h":`Chrome DevTools MCP aracılığıyla mevcut oturuma bağlanmak için kullanılan, profile özgü Chromium kullanıcı verileri dizini. Yerleşik otomatik bağlantı yolu, seçilen ana makinede veya tarayıcı düğümünde yanlış tarayıcı verileri dizinini seçecekse Brave, Edge, Chromium veya varsayılan olmayan Chrome profilleri için bunu kullanın. ~ ile başlayan yollar, işletim sisteminin kullanıcı ana dizinine genişletilir.`}},"browser%2EsnapshotDefaults":{label:{"v1-1svdjip-p":`Tarayıcı Anlık Görüntüsü Varsayılanları`},help:{"v1-v19wdy-4y":`Çağıranlar açıkça anlık görüntü seçenekleri belirtmediğinde kullanılan varsayılan anlık görüntü yakalama yapılandırması. Kanallar ve otomasyon yolları genelinde tutarlı yakalama davranışı için bu ayarı düzenleyin.`}},"browser%2EsnapshotDefaults%2Emode":{label:{"v1-hishns-l":`Tarayıcı Anlık Görüntü Modu`},help:{"v1-joeyxp-5c":`Sayfa içeriğinin ajanın kullanımına uygun biçime nasıl dönüştürüleceğini belirleyen varsayılan anlık görüntü çıkarma modu. İş akışlarınız için okunabilirlik, aslına uygunluk ve token kullanımı arasında denge sağlayan modu seçin.`}},"browser%2EssrfPolicy":{label:{"v1-18gkqpb-j":`Tarayıcı SSRF Politikası`},help:{"v1-1qbp9im-5e":`Dahili ana makinelere erişebilecek tarayıcı/ağ veri alma yolları için sunucu tarafı istek sahteciliğine karşı koruma ayarları. Üretim ortamında kısıtlayıcı varsayılanları koruyun ve yalnızca açıkça onaylanmış hedeflere erişim izni verin.`}},"browser%2EssrfPolicy%2EallowedHostnames":{label:{"v1-198z5mx-p":`Tarayıcıda İzin Verilen Ana Makine Adları`},help:{"v1-1rng39-2k":`Tarayıcı SSRF politikası denetimlerinde izin verilen tam ana makine adları veya doğrudan IP adresleri. Listeyi olabildiğince kısa tutun.`}},"browser%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1phaujk-11":`Tarayıcıda IPv6 Benzersiz Yerel Adres Aralığına İzin Ver`},help:{"v1-1glx5cy-2c":`Güvenilir sahte IP proxy ortamları için IPv6 Benzersiz Yerel Adreslerine (fc00::/7) izin verin.`}},"browser%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-1tpn2sq-12":`Tarayıcıda RFC 2544 Kıyaslama Aralığına İzin Ver`},help:{"v1-10ateu3-2i":`Güvenilir sahte IP proxy ortamları için RFC 2544 kıyaslama aralığındaki IP adreslerine (198.18.0.0/15) izin verin.`}},"browser%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1iun7q1-p":`Tarayıcıda Engellenen Ana Makine Adları`},help:{"v1-nug0we-6k":`Özel ağ erişimi etkin olsa bile DNS ve izin kurallarından önce reddedilen ana makine adı kalıpları. Tam ana makine adlarını ve yalnızca alt alan adları için "*.example.com" kalıbını destekler; kök alan adını engellemek için "example.com" adresini ayrıca ekleyin. Boş bırakıldığında veya ayarlanmadığında ek engelleme uygulanmaz.`}},"browser%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1cr58dw-15":`Tarayıcıda Özel Ağa Tehlikeli Erişime İzin Ver`},help:{"v1-17103pi-4m":`Tarayıcı araçlarından özel ağ adres aralıklarına erişime izin verir. Ayarlanmadığında varsayılan olarak devre dışıdır; yalnızca açıkça güvenilen özel ağ hedefleri için etkinleştirin.`}},"browser%2EtabCleanup":{label:{"v1-gn8gk0-j":`Tarayıcı Sekmesi Temizliği`},help:{"v1-1ctwaad-4y":`Birincil ajan oturumlarının açtığı tarayıcı sekmeleri için mümkün olduğunca uygulanan temizleme politikası. Uzun süre çalışan ağ geçitlerinde eski korumalı alan veya yönetilen tarayıcı sekmelerinin birikmesini önlemek için etkin tutun.`}},"browser%2EtabCleanup%2Eenabled":{label:{"v1-1blo8gh-r":`Tarayıcı Sekmesi Temizliği Etkin`},help:{"v1-4sv97p-3u":`Birincil ajan oturumları için izlenen boşta kalmış tarayıcı sekmelerinin temizlenmesini etkinleştirir. Yalnızca sekmelerin yaşam döngüsünü tamamen harici araçlar yönetiyorsa devre dışı bırakın.`}},channels:{label:{"v1-1ju93md-8":`Kanallar`},help:{"v1-12yv6ma-5n":`Kanal sağlayıcısı yapılandırmaları ve erişim politikalarını, düzenli durum sinyallerinin görünürlüğünü ve arayüz bazındaki davranışları denetleyen ortak varsayılanlar. Varsayılanları merkezi olarak yönetin ve yalnızca gerektiğinde sağlayıcı bazında geçersiz kılın.`}},"channels%2Edefaults":{label:{"v1-1wd3bq-g":`Kanal Varsayılanları`},help:{"v1-uz6veb-4p":`Sağlayıcıya özel ayarlar belirlenmediğinde tüm sağlayıcılarda uygulanan varsayılan kanal davranışı. Sağlayıcı bazında ince ayar yapmadan önce tutarlı bir temel politika uygulamak için bunu kullanın.`}},"channels%2Edefaults%2EbotLoopProtection":{label:{"v1-8f25je-r":`Varsayılan Bot Döngüsü Koruması`},help:{"v1-1lpznyk-4w":`Botlar arası döngü korumasını destekleyen kanal sağlayıcıları için varsayılan çift bazlı döngü koruması ayarları. Sağlayıcıya özel geçersiz kılmaları yalnızca bir kanal farklı bir limite ihtiyaç duyduğunda kullanın.`}},"channels%2Edefaults%2EbotLoopProtection%2EcooldownSeconds":{label:{"v1-wfzv79-x":`Varsayılan Bot Döngüsü Bekleme Süresi (Saniye)`},help:{"v1-1yl5ird-2z":`Bir çift döngü limitini aştığında uygulanan saniye cinsinden bekleme süresi. Destekleyen kanallar için varsayılan değer 60'tır.`}},"channels%2Edefaults%2EbotLoopProtection%2Eenabled":{label:{"v1-1245lyz-z":`Varsayılan Bot Döngüsü Koruması Etkin`},help:{"v1-3ruik-4r":`Botların yazdığı mesajlar yönlendirme aşamasına ulaşabildiğinde, destekleyen kanallarda çift bazlı döngü korumasını varsayılan olarak etkinleştirir. Sağlayıcılar, botlar yok sayıldığında korumayı yine de devre dışı bırakabilir.`}},"channels%2Edefaults%2EbotLoopProtection%2EmaxEventsPerWindow":{label:{"v1-i8sfy1-y":`Varsayılan Bot Döngüsü Zaman Aralığı Başına Olay Sayısı`},help:{"v1-1u0mdjc-41":`Engelleme başlamadan önce bir gönderici/alıcı çiftinin yapılandırılan zaman aralığında karşılıklı iletebileceği en fazla olay sayısı. Destekleyen kanallar için varsayılan değer 20'dir.`}},"channels%2Edefaults%2EbotLoopProtection%2EwindowSeconds":{label:{"v1-vkrwg4-v":`Varsayılan Bot Döngüsü Zaman Aralığı (Saniye)`},help:{"v1-12xpmen-2m":`Çiftler arası döngü bütçeleri için saniye cinsinden kayan pencere uzunluğu. Destekleyen kanallarda varsayılan değer 60'tır.`}},"channels%2Edefaults%2EcontextVisibility":{label:{"v1-xrgozf-q":`Varsayılan Bağlam Görünürlüğü`},help:{"v1-1hze3g1-5o":`Getirilen alıntı/ileti dizisi/geçmiş içeriği için varsayılan ek bağlam görünürlüğü: "all" (tüm bağlamı koru), "allowlist" (yalnızca izin listesindeki gönderenler) veya "allowlist_quote" (izin listesi + açıkça belirtilen alıntıları koru).`}},"channels%2Edefaults%2EgroupPolicy":{label:{"v1-1tib8bt-k":`Varsayılan Grup Politikası`},help:{"v1-ntl9m4-4n":`Kanallar genelinde varsayılan grup politikası: "open", "disabled" veya "allowlist". Geniş kapsamlı grup katılımı amaçlanmıyorsa daha güvenli üretim ortamı kurulumları için "allowlist" değerini koruyun.`}},"channels%2Edefaults%2EheartbeatVisibility":{label:{"v1-knuq96-s":`Varsayılan Yaşam Sinyali Görünürlüğü`},help:{"v1-49bw75-4v":`Sağlayıcılar/kanallar tarafından gönderilen durum mesajları için varsayılan yaşam sinyali görünürlüğü ayarları. Uyarıları görünür tutarken normal çalışma durumuna ilişkin gereksiz güncellemeleri azaltmak için bu ayarı genel düzeyde düzenleyin.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowAlerts":{label:{"v1-8z6943-l":`Yaşam Sinyali Uyarılarını Göster`},help:{"v1-8dk8zx-4g":`true olduğunda, operatör kanallarında sorunların hızla fark edilmesi için bozulma/hata durumlarına ilişkin yaşam sinyali uyarılarını gösterir. Arızalı kanal durumlarının görünür olması için üretim ortamında etkin tutun.`}},"channels%2Edefaults%2EheartbeatVisibility%2EshowOk":{label:{"v1-z25yzy-h":`Normal Durum Yaşam Sinyallerini Göster`},help:{"v1-17tg3mk-4z":`true olduğunda kanal durumu çıktılarında sağlıklı/normal yaşam sinyali durumu kayıtlarını gösterir. Çok fazla bildirim üreten ortamlarda false olarak bırakın ve yalnızca operatörlerin sistemin sağlıklı olduğuna dair açık onaylara ihtiyacı olduğunda etkinleştirin.`}},"channels%2Edefaults%2EheartbeatVisibility%2EuseIndicator":{label:{"v1-16d7e6t-n":`Yaşam Sinyali İçin Gösterge Kullanımı`},help:{"v1-1w12cs2-4m":`Desteklenen yerlerde ayrıntılı durum metni yerine yaşam sinyalinin kısa bir göstergeyle sunulmasını sağlar. Çok sayıda etkin kanal içeren yoğun panolarda gösterge modunu kullanın.`}},"channels%2Edefaults%2EimplicitMentions":{label:{"v1-1xvvux0-p":`Varsayılan Örtük Bahsetmeler`},help:{"v1-4gtdyv-48":`Bota yanıt verme, bot mesajını alıntılama ve botun katıldığı bir ileti dizisinde bulunma durumlarının, açıkça bahsetme olmadan bu özelliği destekleyen mesaj kanallarını etkinleştirip etkinleştirmeyeceğine ilişkin varsayılan ilke.`}},"channels%2Edefaults%2EimplicitMentions%2EquotedBot":{label:{"v1-190ozts-10":`Bot Alıntıları İçin Varsayılan Örtük Bahsetmeler`},help:{"v1-va1u5v-2v":`Alıntılanan bot mesajlarını varsayılan olarak örtük bahsetme sayar. Geriye dönük uyumluluk için varsayılan değer true'dur.`}},"channels%2Edefaults%2EimplicitMentions%2EreplyToBot":{label:{"v1-1y8bnfy-12":`Bota Yanıtlar İçin Varsayılan Örtük Bahsetmeler`},help:{"v1-lm44c3-39":`Botun kendi mesajlarına verilen yanıtları varsayılan olarak örtük bahsetme sayar. Geriye dönük uyumluluk için varsayılan değer true'dur.`}},"channels%2Edefaults%2EimplicitMentions%2EthreadParticipation":{label:{"v1-lsf3e8-1a":`İleti Dizisine Katılım İçin Varsayılan Örtük Bahsetmeler`},help:{"v1-160205h-3o":`Botun katıldığı ileti dizilerindeki devam mesajlarını varsayılan olarak örtük bahsetme sayar. Geriye dönük uyumluluk için varsayılan değer true'dur.`}},"channels%2EmodelByChannel":{label:{"v1-k5b3gw-n":`Kanala Göre Model Geçersiz Kılmaları`},help:{"v1-1b01spx-2p":`Sağlayıcı -> kanal kimliği / DM eş kimliği -> model geçersiz kılması eşlemesi (değerler sağlayıcı/model veya takma adlardır).`}},cli:{label:{"v1-mb8vjd-3":`CLI`}},cloudWorkers:{label:{"v1-1un3411-d":`Bulut Çalışanları`},help:{"v1-10carc4-5v":`Geçici uzak ortamlar için isteğe bağlı bulut çalışanı profilleri. Bu bölüm belirtilmezse veya profil içermezse bulut çalışanı oluşturma kullanılamaz durumda kalır ve mevcut Gateway/düğüm durumu davranışı değişmez.`}},"cloudWorkers%2Edesktop":{label:{"v1-11xu2ur-r":`Bulut Çalışanı Masaüstü (Deneysel)`},help:{"v1-vllayc-3n":`Masaüstü desteği olan bulut çalışanı ortamları için deneysel worker.desktop.observe arayüzünü ve Control UI Masaüstü panelini etkinleştirir.`}},"cloudWorkers%2EpreparedPool":{label:{"v1-s34lt5-q":`Hazır Bulut Çalışanı Havuzu`},help:{"v1-rw51o5-6b":`Sonraki oturumlar için hazır tutulan bulut çalışanlarına yönelik sınırlar. Ayrılan kaynaklar, sağlayıcının temizleme işlemi tamamlanana kadar çalışan makine ücreti doğurur; sabit sona erme süreleri, projenin gerçek talebine ve sağlayıcının mevcut boşta kalma politikasına göre belirlenir.`}},"cloudWorkers%2EpreparedPool%2EmaxTotal":{label:{"v1-c8ff5f-u":`Bulut Çalışanı Hazır Rezerv Üst Sınırı`},help:{"v1-1mpd1dt-7u":`Projeler ve profiller genelinde atanmamış hazır bulut çalışanları için Gateway genelindeki üst sınır (varsayılan: 4). Hazırlanmakta olan çalışanlar ve temizlendiği henüz doğrulanmamış rezervler bu sınıra dahil edilir. Anlık görüntülerin yeniden kullanımını ve etkin oturumları korurken atanmamış rezervleri boşaltmak ve rezervlerin yenilenmesini devre dışı bırakmak için 0 olarak ayarlayın.`}},"cloudWorkers%2Eprofiles":{label:{"v1-xctezy-l":`Bulut Çalışanı Profilleri`},help:{"v1-eii67l-3j":`Adlandırılmış bulut çalışanı profilleri. Her profil, bir eklenti tarafından kaydedilen bir çalışan sağlayıcısını seçer ve sağlayıcıya ait ayarları içerir.`}},"cloudWorkers%2Eprofiles%2E*":{label:{"v1-lsdort-k":`Bulut Çalışanı Profili`},help:{"v1-1v2w7jl-4u":`Ortam oluşturulurken adıyla seçilen tek bir bulut çalışanı profili. Sağlayıcı kimlik bilgilerini bu bloğa gizli veriler eklemek yerine desteklenen referanslarda tutun.`}},"cloudWorkers%2Eprofiles%2E*%2Einstall":{label:{"v1-1y9aivk-r":`Bulut Çalışanı Kurulum Yöntemi`},help:{"v1-blrtbf-74":`Çalışan kurulum yöntemi: "bundle" (varsayılan), Gateway'in içerik karması alınmış kurulu derlemesini aktarır ve yayımlanmış, geliştirme aşamasındaki ve yayımlanmamış sürümleri destekler; "npm", Gateway'in tam olarak aynı sürümünü kurar ve yalnızca bu sürüm yayımlanmışsa kullanılabilir.`}},"cloudWorkers%2Eprofiles%2E*%2Eprovider":{label:{"v1-v7eu21-l":`Bulut Çalışanı Sağlayıcısı`},help:{"v1-1p4s4c1-44":`Bir eklenti tarafından kaydedilen çalışan sağlayıcısı kimliği. Gateway'in profilden ortamlar oluşturabilmesi için yapılandırılan eklentinin bu kimliği sunması gerekir.`}},"cloudWorkers%2Eprofiles%2E*%2EreadyWorkers":{label:{"v1-g69eog-x":`Bulut Çalışanı Hazır Rezerv Hedefi`},help:{"v1-1nwve9s-7w":`Bu profili kullanan her uygun proje için hedeflenen atanmamış hazır çalışan sayısı (varsayılan: 1); Gateway genelindeki hazır havuzu üst sınırına tabidir. Anlık görüntülerin yeniden kullanımını korurken bu profilin rezervlerini devre dışı bırakmak için 0 olarak ayarlayın. Hazırlanmakta olan çalışanlar ve temizlendiği henüz doğrulanmamış rezervler bu hedefe dahil edilir.`}},"cloudWorkers%2Eprofiles%2E*%2Esettings":{label:{"v1-p040za-u":`Bulut Çalışanı Sağlayıcı Ayarları`},help:{"v1-mq7u32-4j":`Seçilen eklenti tarafından doğrulanan, sağlayıcıya ait ayarlar. Gizli bilgi içeren değerler için SecretRef nesnelerini kullanın; içeriği yorumlanmayan ayarlarda gizli bilgiler otomatik olarak çözümlenmez.`}},"cloudWorkers%2Eprofiles%2E*%2EsuspendAfter":{label:{"v1-2izlgm-y":`Boştaki Bulut Çalışanını Askıya Alma Süresi`},help:{"v1-1keuwgh-4w":`Boştaki bir bulut çalışanının kaynaklarını 45m veya 2h gibi belirtilen süre sonunda otomatik olarak geri alır; sonraki mesaj yeni bir çalışan oluşturur. Minimum: 1m. Çalışanların çalışmaya devam etmesi için ayarlamadan bırakın.`}},"cloudWorkers%2EprojectProfiles":{label:{"v1-10hp68d-t":`Bulut Çalışanı Proje Profilleri`},help:{"v1-1kkfrif-46":`Normalleştirilmiş, küçük harfli depo kimliği (host/owner/repo) ile anahtarlanan varsayılan bulut çalışanı profil adları. Açıkça belirtilen yönlendirme profili kimlikleri önceliklidir.`}},"cloudWorkers%2EprojectProfiles%2E*":{label:{"v1-17lr59o-s":`Bulut Çalışanı Proje Profili`},help:{"v1-1mux5u0-30":`Bir oturumun çalışma ağacının origin değeri bu depo kimliğiyle eşleştiğinde varsayılan olarak kullanılan bulut çalışanı profil adı.`}},commands:{label:{"v1-15x4mpf-8":`Komutlar`},help:{"v1-1gi0dr2-5a":`Sağlayıcılar genelinde sohbet komutu arayüzlerini, sahiplik temelli erişim kısıtlamalarını ve yükseltilmiş yetkili komutlara erişim davranışını denetler. Daha sıkı operatör denetimlerine veya daha geniş komut erişimine ihtiyacınız yoksa varsayılanları koruyun.`}},"commands%2EallowFrom":{label:{"v1-axacxh-t":`Komutlar için Yükseltilmiş Yetkili Erişim Kuralları`},help:{"v1-7azkw-5g":`Sahip düzeyindeki komut arayüzleri için kanal ve gönderene göre yükseltilmiş yetkili komut izin kurallarını tanımlar. Ayrıcalıklı komutların geniş sohbet kitlelerine açılmaması için sağlayıcıya özgü, dar kapsamlı kimlikler kullanın.`}},"commands%2Ebash":{label:{"v1-1nbpj93-n":`Bash Sohbet Komutuna İzin Ver`},help:{"v1-83ah7w-36":"Bash sohbet komutunun (`!`; `/bash` takma adı) ana makinede kabuk komutları çalıştırmasına izin verir (varsayılan: false; tools.elevated gerektirir)."}},"commands%2EbashForegroundMs":{label:{"v1-1vfppjv-r":`Bash Ön Plan Süresi (ms)`},help:{"v1-1o0o4dw-2c":`Bash'in arka plana geçmeden önce ne kadar bekleyeceğini belirler (varsayılan: 2000; 0 hemen arka plana geçirir).`}},"commands%2Econfig":{label:{"v1-14wzjd5-d":`/config Komutuna İzin Ver`},help:{"v1-151bb7c-21":`/config sohbet komutunun diskteki yapılandırmayı okumasına/yazmasına izin verir (varsayılan: false).`}},"commands%2Edebug":{label:{"v1-12w2s6q-c":`/debug Komutuna İzin Ver`},help:{"v1-y1lc3j-1y":`/debug sohbet komutuyla yalnızca çalışma zamanında geçerli olan geçersiz kılmalara izin verir (varsayılan: false).`}},"commands%2Emcp":{label:{"v1-16ynh2x-a":`/mcp Komutuna İzin Ver`},help:{"v1-1rtwcgd-2o":`/mcp sohbet komutunun mcp.servers altındaki OpenClaw MCP sunucu yapılandırmasını yönetmesine izin verir (varsayılan: false).`}},"commands%2Enative":{label:{"v1-11r5pqs-f":`Yerel Komutlar`},help:{"v1-dighr2-5n":`Komut kaydını destekleyen kanallara (Discord, Slack, Telegram) yerel eğik çizgi/menü komutlarını kaydeder. Bilerek yalnızca metin tabanlı komut iş akışları kullanmıyorsanız, komutların kolayca bulunabilmesi için etkin tutun.`}},"commands%2EnativeSkills":{label:{"v1-hpi0k3-l":`Yerel Beceri Komutları`},help:{"v1-19gtqci-5h":`Kullanıcıların, desteklenen sağlayıcılarda becerileri doğrudan komut menülerinden çağırabilmesi için yerel beceri komutlarını kaydeder. Sunulan komutların operatörlerin beklentileriyle eşleşmesi için beceri politikanızla uyumlu tutun.`}},"commands%2EownerAllowFrom":{label:{"v1-1bc6u1a-e":`Komut Sahipleri`},help:{"v1-1di38gv-3y":`Sahiplere özel komutlar için açıkça tanımlanmış sahip izin listesi. Kanala özgü kimlikleri kullanın (isteğe bağlı olarak "whatsapp:+15551234567" gibi bir ön ekle). '*' yok sayılır.`}},"commands%2Eplugins":{label:{"v1-culv09-e":`/plugins Komutuna İzin Ver`},help:{"v1-akwy9y-33":`Keşfedilen eklentileri listelemek ve yapılandırmada eklentileri etkinleştirip devre dışı bırakmak için /plugins sohbet komutuna izin ver (varsayılan: false).`}},"commands%2Erestart":{label:{"v1-d0qh1l-d":`Yeniden Başlatmaya İzin Ver`},help:{"v1-m32fv2-27":`/restart, /update ve harici SIGUSR2 yeniden başlatma isteklerine izin verin (varsayılan: true).`}},"commands%2Etext":{label:{"v1-5g1c88-d":`Metin Komutları`},help:{"v1-1utu76s-5j":`Mevcut yerel komut arayüzlerine ek olarak sohbet girdisindeki metin komutlarının ayrıştırılmasını etkinleştirir. Yerel komut kaydını desteklemeyen kanallarla uyumluluk için bunu etkin tutun.`}},cron:{label:{"v1-1qlte4b-b":`Otomasyonlar`},help:{"v1-4md8ic-5u":`Kayıtlı otomasyonlar, eşzamanlı çalıştırma, yedek teslimat ve çalıştırma oturumlarının saklanması için genel zamanlayıcı ayarları. Otomasyon hacmini artırmıyor veya harici webhook alıcılarını entegre etmiyorsanız varsayılanları koruyun.`}},"cron%2Eenabled":{label:{"v1-1amdki2-j":`Otomasyonlar Etkin`},help:{"v1-y8otx6-5i":`Gateway tarafından yönetilen kayıtlı zamanlamalar için otomasyonların çalıştırılmasını etkinleştirir. Normal hatırlatıcı/otomasyon akışları için etkin tutun; yalnızca görevleri silmeden tüm otomasyonların çalıştırılmasını duraklatmak için devre dışı bırakın.`}},"cron%2EsessionRetention":{label:{"v1-1cvkclx-t":`Otomasyon Oturumlarını Saklama Süresi`},help:{"v1-4wagu6-7e":"Tamamlanan otomasyon çalıştırma oturumlarının temizlenmeden önce ne kadar süre saklanacağını belirler (`24h`, `7d`, `1h30m` veya temizlemeyi devre dışı bırakmak için `false`; `0h` gibi sıfır süre de temizlemeyi devre dışı bırakır; varsayılan: `24h`). Sık çalışan zamanlamalarda depolama alanı kullanımının artmasını azaltmak için daha kısa bir saklama süresi kullanın."}},"cron%2EskipMissedJobs":{label:{"v1-1wkngn0-x":`Kaçırılan Yinelenen Otomasyonları Atla`},help:{"v1-w9wfmo-66":`Gateway başlatılırken kaçırılmış yinelenen cron/every çalıştırmalarını atlar ve bunları telafi etmek yerine gelecekteki bir sonraki çalıştırmayı zamanlar. Varsayılan: false. Kesinti sonrasında güncelliğini yitirmiş hatırlatmaları önlemek için etkinleştirin; tek seferlik at görevleri yine de telafi edilir.`}},"cron%2EwebhookSsrfPolicy":{label:{"v1-xrkjiu-v":`Otomasyon Webhook SSRF Politikası`},help:{"v1-1xlfqnu-5h":`Giden her otomasyon webhook'una uygulanan SSRF politikası. Özel, geri döngü, yerel bağlantı ve dahili hedefler, bu politika açıkça izin vermediği sürece engellenir. Katı iletim kısıtlamaları için ayarlanmamış olarak bırakın.`}},"cron%2EwebhookSsrfPolicy%2EallowedHostnames":{label:{"v1-w1bhls-11":`Otomasyon Webhook'ları İçin İzin Verilen Ana Bilgisayar Adları`},help:{"v1-1i94hyz-3n":`Normalde engellenen hedefler dahil olmak üzere otomasyon webhook iletimine izin verilen tam ana bilgisayar adları veya doğrudan IP adresleri. Listeyi mümkün olduğunca kısa tutun.`}},"cron%2EwebhookSsrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-1p9upj5-1d":`Otomasyon Webhook'ları İçin IPv6 Benzersiz Yerel Adres Aralığına İzin Ver`},help:{"v1-rke0oj-3b":`IPv6 Benzersiz Yerel Adreslerine (fc00::/7) otomasyon webhook'ları gönderilmesine izin verir. Yalnızca güvenilir sahte IP proxy ortamlarında kullanın.`}},"cron%2EwebhookSsrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-y1ryjx-1e":`Otomasyon Webhook'ları İçin RFC 2544 Performans Testi Aralığına İzin Ver`},help:{"v1-x1usg4-3h":`Otomasyon webhook'larının RFC 2544 kıyaslama aralığındaki IP'lere (198.18.0.0/15) erişmesine izin verir. Yalnızca güvenilir sahte IP proxy ortamlarında kullanın.`}},"cron%2EwebhookSsrfPolicy%2EblockedHostnames":{label:{"v1-6c1248-11":`Otomasyon Webhook'ları İçin Engellenen Ana Makine Adları`},help:{"v1-16cv1ic-6a":`Otomasyon webhook gönderimlerinde DNS ve izin kurallarından önce reddedilen ana makine adı kalıpları. Tam ana makine adlarını ve yalnızca alt alan adları için "*.example.com" kalıbını destekler; kök alan adını engellemek için "example.com" değerini ayrıca ekleyin. Boş bırakılırsa veya ayarlanmazsa ek bir engelleme uygulanmaz.`}},"cron%2EwebhookSsrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-o4lenl-1h":`Otomasyon Webhook'ları İçin Özel Ağa İzin Ver (Tehlikeli)`},help:{"v1-1n9710c-3t":`Otomasyon webhook'larının özel ve dahili ağ hedeflerine erişmesine izin verir. Yapılandırılmış tüm webhook hedefleri güvenilir değilse devre dışı bırakın.`}},"cron%2EwebhookToken":{label:{"v1-18ivgo6-w":`Otomasyon Webhook Bearer Belirteci`},help:{"v1-1l90hxg-5l":`Webhook modu kullanıldığında otomasyon webhook POST gönderimlerine eklenen Bearer belirteci. Değeri gizli bilgi veya ortam değişkeninden almayı tercih edin ve paylaşılan webhook uç noktalarına internetten erişilebiliyorsa bu belirteci düzenli olarak yenileyin.`}},desktop:{label:{"v1-rs698z-7":`Masaüstü`}},"desktop%2Ehost":{label:{"v1-rh14ls-d":`Yerel Masaüstü`},help:{"v1-99weio-30":`Yerel bir VNC sunucusu üzerinden, eşleştirilmiş düğümler veya deneysel Gateway ana makine kaynağı için masaüstü izleme.`}},"desktop%2Ehost%2Eenabled":{label:{"v1-10wailb-f":`Masaüstü Paylaşımı`},help:{"v1-m9lbcj-83":`Bu makinenin masaüstü kaynağını etkinleştirir. Eşleştirilmiş macOS, Windows ve Linux düğümleri varsayılan olarak etkindir; açıkça belirtilmiş bir masaüstü uygulaması paylaşım tercihi önceliklidir. Gateway ana makinesinin Labs kaynağı varsayılan olarak devre dışıdır ve değişiklikleri anında uygular. Eşleştirilmiş bir düğümün masaüstü yapılandırmasını değiştirdikten sonra düğümü yeniden başlatın.`}},"desktop%2Ehost%2Emanaged":{label:{"v1-3hgdsm-q":`Yönetilen Linux Ana Makine Masaüstü`},help:{"v1-1r7n22m-49":`Linux üzerinde yalnızca geri döngü arayüzünden erişilebilen, başsız bir TigerVNC/XFCE masaüstünü çalıştırır ve denetler. Açıkça belirtilen bir bağlantı noktası veya varsayılan bağlantı noktasında çalışan mevcut bir VNC sunucusu yine önceliklidir.`}},"desktop%2Ehost%2EpasswordFile":{label:{"v1-pdfkek-n":`Yerel VNC Parola Dosyası`},help:{"v1-1m5lsox-37":`VNC parola dosyasının mutlak yolu. macOS'te masaüstü görüntüleyicisini açarken hesap kimlik bilgilerini girmek için bu alanı boş bırakın.`}},"desktop%2Ehost%2Eport":{label:{"v1-1bci0ps-e":`Yerel VNC Bağlantı Noktası`},help:{"v1-1ku4w9b-2b":`Bu makinede zaten çalışan bir VNC sunucusunun geri döngü RFB bağlantı noktası (varsayılan: 5900).`}},diagnostics:{label:{"v1-1stxhg7-b":`Tanılama`},help:{"v1-1d5rnym-5p":`Hata ayıklama sırasında hedefli izleme, telemetri dışa aktarımı ve önbellek incelemesi için tanılama denetimleri. Üretim ortamında temel tanılamayı minimum düzeyde tutun ve daha ayrıntılı sinyalleri yalnızca sorunları araştırırken etkinleştirin.`}},"diagnostics%2EcacheTrace":{label:{"v1-d7o58-b":`Önbellek İzleme`},help:{"v1-10523zm-5b":`Gömülü çalıştırmalarda önbellek kararlarını ve veri yükü bağlamını gözlemlemek için önbellek izleme günlüğü ayarları. Hata ayıklama için bunu geçici olarak etkinleştirin ve günlüklerdeki hassas veri miktarını azaltmak için sonrasında devre dışı bırakın.`}},"diagnostics%2EcacheTrace%2Eenabled":{label:{"v1-u2445x-j":`Önbellek İzleme Etkin`},help:{"v1-2c1umi-1v":`Gömülü ajan çalıştırmaları için önbellek izleme anlık görüntülerini günlüğe kaydeder (varsayılan: false).`}},"diagnostics%2Eenabled":{label:{"v1-17k9ppq-j":`Tanılama Etkin`},help:{"v1-a46pxt-4h":`Günlüklerdeki ve telemetri bağlantı yollarındaki tanılama araçlarının çıktısını kontrol eden ana anahtar. Varsayılan olarak etkindir; yalnızca kaynakları ciddi ölçüde kısıtlı ortamlarda false olarak ayarlayın.`}},"diagnostics%2Eflags":{label:{"v1-x05x98-h":`Tanılama Bayrakları`},help:{"v1-x4w5ok-33":`Bayrağa göre hedefli tanılama günlüklerini etkinleştirin (ör. ["telegram.http"]). "telegram.*" veya "*" gibi joker karakterleri destekler.`}},"diagnostics%2Eotel":{label:{"v1-wfx8h0-d":`OpenTelemetry`},help:{"v1-isgk7l-5b":`Gateway bileşenlerinin ürettiği izler, metrikler ve günlükler için OpenTelemetry dışa aktarma ayarları. Merkezi gözlemlenebilirlik arka uçları ve dağıtık izleme işlem hatlarıyla entegrasyon yaparken kullanın.`}},"diagnostics%2Eotel%2EcaptureContent":{label:{"v1-1xxk57n-t":`OpenTelemetry İçerik Yakalama`},help:{"v1-19tid4t-2t":`İsteğe bağlı OTEL span içeriği yakalama. Varsayılan olarak kapalıdır; true, sistem dışı mesajların ve araçların içeriğini yakalar.`}},"diagnostics%2Eotel%2Eenabled":{label:{"v1-bh3lp-l":`OpenTelemetry Etkin`},help:{"v1-193bm0-5b":`Yapılandırılmış uç nokta/protokol ayarlarına göre izler, metrikler ve günlükler için OpenTelemetry dışa aktarma işlem hattını etkinleştirir. Toplayıcı uç noktanız ve kimlik doğrulamanız tam olarak yapılandırılmadıkça devre dışı bırakın.`}},"diagnostics%2Eotel%2Eendpoint":{label:{"v1-mpv6hp-m":`OpenTelemetry Uç Noktası`},help:{"v1-4rrd1x-4y":`OpenTelemetry dışa aktarımında veri iletimi için kullanılan, şema ve bağlantı noktası dahil toplayıcı uç noktası URL'si. Erişilebilir, güvenilir bir toplayıcı uç noktası kullanın ve devreye aldıktan sonra veri alım hatalarını izleyin.`}},"diagnostics%2Eotel%2EflushIntervalMs":{label:{"v1-1rqdzae-x":`OpenTelemetry Tampon Boşaltma Aralığı (ms)`},help:{"v1-1moqogc-53":`Telemetri verilerinin tamponlardan toplayıcıya düzenli olarak aktarılması için milisaniye cinsinden aralık. Dışa aktarma trafiğini azaltmak için artırın veya aktif olay müdahalesi sırasında daha hızlı görünürlük sağlamak için azaltın.`}},"diagnostics%2Eotel%2Eheaders":{label:{"v1-kknm0u-l":`OpenTelemetry Üst Bilgileri`},help:{"v1-s26t2a-52":`OpenTelemetry dışa aktarma istekleriyle gönderilen, genellikle kiracı kimlik doğrulaması veya yönlendirme için kullanılan ek HTTP istek başlıkları. Gizli bilgileri ortam değişkenlerine dayalı değerlerde tutun ve gereksiz başlık kullanımından kaçının.`}},"diagnostics%2Eotel%2Elogs":{label:{"v1-1o5ymv2-q":`OpenTelemetry Günlükleri Etkin`},help:{"v1-12wo6rv-4k":`Yerel günlük kayıt hedeflerine ek olarak OpenTelemetry üzerinden günlük sinyallerinin dışa aktarılmasını etkinleştirin. Hizmetler ve ajanlar arasında merkezi günlük ilişkilendirmesi gerektiğinde bunu kullanın.`}},"diagnostics%2Eotel%2ElogsEndpoint":{label:{"v1-7bltwc-r":`OpenTelemetry Günlük Uç Noktası`},help:{"v1-1vgzldu-40":`Günlük sinyaline özel OTLP/HTTP uç noktası. Ayarlandığında yalnızca günlük dışa aktarımı için diagnostics.otel.endpoint ve OTEL_EXPORTER_OTLP_ENDPOINT değerlerini geçersiz kılar.`}},"diagnostics%2Eotel%2ElogsExporter":{label:{"v1-16nvfm8-r":`OpenTelemetry Günlük Dışa Aktarıcısı`},help:{"v1-9bzywd-5q":`diagnostics.otel.logs için günlük dışa aktarma hedefi. Yapılandırılmış OTLP günlük uç noktası için "otlp", konteyner günlük işleme hatlarında stdout satırı başına bir JSON kaydı için "stdout" ve her iki hedef de gerektiğinde "both" kullanın.`}},"diagnostics%2Eotel%2EmetricNamePrefix":{label:{"v1-hrys5-w":`OpenTelemetry Metrik Adı Ön Eki`},help:{"v1-1epdpi9-b2":`OpenClaw'a ait metrik adlarındaki varsayılan "openclaw." ön ekini değiştirir. Ön eki kaldırmak için boş bir dize kullanın veya bir harfle başlayan, en fazla 128 ASCII harfi, rakam, alt çizgi, nokta, kısa çizgi ve eğik çizgiden oluşan bir değer girin. İhtiyacınız olan ayırıcıyı da ekleyin; örneğin "acme.". Standart gen_ai.* metrik adları değişmez. Bu değerin değiştirilmesi, eski adları sorgulayan panoların ve uyarıların güncellenmesini gerektirir.`}},"diagnostics%2Eotel%2Emetrics":{label:{"v1-1o16jew-t":`OpenTelemetry Metrikleri Etkin`},help:{"v1-13r4cf4-4x":`Metrik sinyallerinin yapılandırılmış OpenTelemetry toplayıcı uç noktasına aktarılmasını etkinleştirin. Çalışma zamanı sağlık panoları için etkin tutun ve yalnızca metrik hacminin en aza indirilmesi gerekiyorsa devre dışı bırakın.`}},"diagnostics%2Eotel%2EmetricsEndpoint":{label:{"v1-ahl7w6-u":`OpenTelemetry Metrik Uç Noktası`},help:{"v1-qlfh7x-47":`Sinyale özgü OTLP/HTTP metrik uç noktası. Ayarlandığında, yalnızca metrik aktarımı için diagnostics.otel.endpoint ve OTEL_EXPORTER_OTLP_ENDPOINT değerlerini geçersiz kılar.`}},"diagnostics%2Eotel%2Eprotocol":{label:{"v1-4ikcpk-m":`OpenTelemetry Protokolü`},help:{"v1-17ine8s-5e":`Telemetri aktarımı için OTel taşıma protokolü. Yalnızca "http/protobuf" kabul edilir; kaydedilmiş eski bir "grpc" değerini düzeltmek veya kaynağa özgü elle düzenleme yönergeleri almak için "openclaw doctor --fix" komutunu çalıştırın.`}},"diagnostics%2Eotel%2EsampleRate":{label:{"v1-1qd4hmt-v":`OpenTelemetry İz Örnekleme Oranı`},help:{"v1-brcwep-50":`İz trafiğinin ne kadarının gözlemlenebilirlik arka uçlarına aktarılacağını kontrol eden iz örnekleme oranı (0-1). Düşük oranlar ek yükü ve maliyeti azaltırken yüksek oranlar hata ayıklama doğruluğunu artırır.`}},"diagnostics%2Eotel%2EserviceName":{label:{"v1-1b6j4ku-q":`OpenTelemetry Hizmet Adı`},help:{"v1-1hpiqon-5d":`Bu Gateway örneğini gözlemlenebilirlik arka uçlarında tanımlamak için telemetri kaynak özniteliklerinde bildirilen hizmet adı. Panoların ve uyarıların dağıtımlar arasında tutarlı kalması için sabit adlar kullanın.`}},"diagnostics%2Eotel%2Etraces":{label:{"v1-ypycsr-s":`OpenTelemetry İzleri Etkin`},help:{"v1-j7zrrp-4s":`İz sinyallerinin yapılandırılmış OpenTelemetry toplayıcı uç noktasına aktarılmasını etkinleştirin. Gecikme analizi veya hata ayıklama için izleme gerektiğinde etkin tutun; yalnızca metrikler ve günlükler istiyorsanız devre dışı bırakın.`}},"diagnostics%2Eotel%2EtracesEndpoint":{label:{"v1-1m2hzmb-t":`OpenTelemetry İz Uç Noktası`},help:{"v1-8yw5p1-43":`Sinyale özgü OTLP/HTTP iz uç noktası. Ayarlandığında, yalnızca iz dışa aktarımı için diagnostics.otel.endpoint ve OTEL_EXPORTER_OTLP_ENDPOINT değerlerini geçersiz kılar.`}},discovery:{label:{"v1-l2sr05-9":`Keşif`},help:{"v1-1sqleij-4w":`Yerel mDNS duyurusu ve isteğe bağlı geniş alan varlık bildirimi için hizmet keşfi ayarları. Hizmet meta verilerinin sızmasını önlemek için keşfi beklenen ağlarla sınırlı tutun.`}},"discovery%2Emdns":{label:{"v1-1sefhx1-e":`mDNS Keşfi`},help:{"v1-vtbyyq-4w":`Yerel ağ duyurusu ve keşif davranışını ayarlamak için mDNS keşif yapılandırma grubu. Ek meta veri gerekmedikçe, rutin LAN keşfi için minimal modu kullanın.`}},"discovery%2Emdns%2Emode":{label:{"v1-ybee7c-j":`mDNS Keşif Modu`},help:{"v1-1p28pd5-2m":`mDNS yayın modu ("minimal" varsayılandır, "full" cliPath/sshPort içerir, "off" mDNS'yi devre dışı bırakır).`}},"discovery%2EwideArea":{label:{"v1-1u2kx7q-j":`Geniş Alan Keşfi`},help:{"v1-1akkqjm-53":`Keşif sinyallerini yerel bağlantı kapsamının ötesine sunmak için geniş alan keşfi yapılandırma grubu. Yalnızca farklı konumlardaki Gateway varlık bilgilerini bilinçli olarak bir araya getiren dağıtımlarda etkinleştirin.`}},"discovery%2EwideArea%2Edomain":{label:{"v1-1uxd2qe-q":`Geniş Alan Keşif Etki Alanı`},help:{"v1-rxrygo-4m":`Geniş alan keşfi için openclaw.internal gibi isteğe bağlı tek noktaya yayın DNS-SD etki alanı. Gateway keşfini bilinçli olarak yerel mDNS kapsamının ötesinde yayımladığınızda bunu kullanın.`}},env:{label:{"v1-1zc80q-b":`Ortam`},help:{"v1-1ao5po6-55":`Gateway sürecine çalışma zamanı değişkenleri sağlamak için kullanılan ortam içe aktarma ve geçersiz kılma ayarları. Kabuk ortamının yüklenmesini ve değişkenlerin açıkça eklenmesi davranışını denetlemek için bu bölümü kullanın.`}},"env%2EshellEnv":{label:{"v1-hd6v1l-o":`Kabuk Ortamını İçe Aktarma`},help:{"v1-1gw487t-4y":`Başlangıç sırasında oturum açma kabuğunuzdan değişken yüklemeye yönelik kabuk ortamını içe aktarma denetimleri. Profilde tanımlanan gizli bilgilere veya PATH özelleştirmelerine bağımlıysanız bu seçeneği etkin tutun.`}},"env%2EshellEnv%2Eenabled":{label:{"v1-9bbyvk-w":`Kabuk Ortamını İçe Aktarma Etkin`},help:{"v1-5tiuup-5u":`Başlangıç hazırlığı sırasında kullanıcı kabuk profilinden ortam değişkenlerinin yüklenmesini sağlar. Geliştirici makinelerinde etkin tutun; ortam değişkenlerinin açıkça yönetildiği, erişimi kısıtlı hizmet ortamlarında devre dışı bırakın.`}},"env%2EshellEnv%2EtimeoutMs":{label:{"v1-g0i751-11":`Kabuk Ortamını İçe Aktarma Zaman Aşımı (ms)`},help:{"v1-nsk2yf-5c":`Alternatif davranış devreye girmeden önce kabuk ortamının çözümlenmesi için izin verilen milisaniye cinsinden azami süre. Daha hızlı başlangıç için daha kısa zaman aşımları kullanın; kabuğun başlatılması uzun sürüyorsa süreyi artırın.`}},"env%2Evars":{label:{"v1-grhbhj-u":`Ortam Değişkenlerini Geçersiz Kılan Değerler`},help:{"v1-yxc3z7-5n":`OpenClaw çalışma zamanı süreç ortamına birleştirilen, ortam değişkenlerini geçersiz kılan açık anahtar/değer çiftleri. Yalnızca kabuk profilinin yan etkilerine güvenmek yerine, öngörülebilir bir ortam yapılandırması için bunu kullanın.`}},gateway:{label:{"v1-7gz34p-7":`Gateway`},help:{"v1-19p5env-5v":`Bağlanma modu, kimlik doğrulama, kontrol arayüzü, uzaktan aktarım ve operasyonel güvenlik denetimleri için Gateway çalışma zamanı ayarları. Gateway'i bilinçli olarak güvenilir yerel arayüzlerin ötesine açmıyorsanız temkinli varsayılanları koruyun.`}},"gateway%2EallowRealIpFallback":{label:{"v1-1xoyrfn-w":`Gateway için x-real-ip Alternatifine İzin Ver`},help:{"v1-1wr3qmw-4c":`Proxy senaryolarında x-forwarded-for eksik olduğunda alternatif olarak x-real-ip kullanılmasını sağlar. Gelen trafik altyapınız bu uyumluluk davranışını gerektirmiyorsa devre dışı tutun.`}},"gateway%2Eauth":{label:{"v1-1uh91et-c":`Gateway Kimlik Doğrulaması`},help:{"v1-70b6ni-50":`Gateway HTTP/WebSocket erişimi için mod, kimlik bilgileri, güvenilir proxy davranışı ve hız sınırlamasını içeren kimlik doğrulama politikası. Yerel geri döngü dışındaki tüm dağıtımlarda kimlik doğrulamayı etkin tutun.`}},"gateway%2Eauth%2EallowTailscale":{label:{"v1-fyw82a-11":`Gateway Kimlik Doğrulamasında Tailscale Kimliğine İzin Ver`},help:{"v1-vqtmgw-53":`Yapılandırıldığında, güvenilir Tailscale kimlik yollarının Gateway kimlik doğrulama kontrollerini karşılamasına izin verir. Bunu yalnızca tailnet kimlik güvenliğiniz güçlü olduğunda ve operatör iş akışları buna bağlı olduğunda kullanın.`}},"gateway%2Eauth%2EidentityScopes":{label:{"v1-1y4ivis-t":`Gateway Kimlik Kapsamı Yetkileri`},help:{"v1-1h0zxy7-5n":`Doğrulanmış güvenilir proxy veya Tailscale kimliklerini yalnızca bağlantı için geçerli operatör kapsamı yetkileriyle eşler. E-posta anahtarları büyük/küçük harfe duyarsız olarak eşleştirilir; yetkiler, bağlantı kapsamı üst sınırı uygulanmadan önce cihaz kapsamlarını genişletir.`}},"gateway%2Eauth%2Emode":{label:{"v1-av63g8-h":`Gateway Kimlik Doğrulama Modu`},help:{"v1-j8rodq-9t":`Gateway kimlik doğrulama modu: uç mimarinize bağlı olarak "none", "token", "password" veya "trusted-proxy". Token/parola modu, yapılandırılmış gizli değeri (gateway.auth.token veya gateway.auth.password) seçer; istemciler bunu bağlantının kimlik doğrulama alanlarından herhangi birinde gönderebilir. Doğrudan dış erişim için token/parola kullanın; trusted-proxy modunu ise yalnızca güvenliği sıkılaştırılmış, kimlik farkındalığına sahip proxy'lerin arkasında kullanın.`}},"gateway%2Eauth%2Epassword":{label:{"v1-1b8jhsq-g":`Gateway Parolası`},help:{"v1-1ndt0u2-4g":`gateway.auth.mode=password ile seçilen paylaşılan gizli değer. İstemciler bunu auth.token veya auth.password alanlarından herhangi birinde gönderebilir. Tailscale Funnel için parola modu gereklidir.`}},"gateway%2Eauth%2ErateLimit":{label:{"v1-cb86oa-n":`Gateway Kimlik Doğrulama Hız Sınırı`},help:{"v1-1kstr42-54":`Gateway sınırında kimlik bilgilerine yönelik kaba kuvvet saldırısı riskini azaltan oturum açma ve kimlik doğrulama denemesi sınırlama kontrolleri. Dış erişime açık ortamlarda etkin tutun ve eşikleri normal trafik düzeyinize göre ayarlayın.`}},"gateway%2Eauth%2Etoken":{label:{"v1-nq7dbs-d":`Gateway Belirteci`},help:{"v1-16i7cxs-5q":`Yeni yerel kurulumlarda varsayılan olan gateway.auth.mode=token ile seçilen paylaşılan gizli anahtar. İstemciler bunu auth.token veya auth.password içinde gönderebilir. Geri döngü dışındaki adreslere bağlanmak için etkin bir kimlik doğrulama modu gerekir.`}},"gateway%2Eauth%2EtrustedProxy":{label:{"v1-17f14p4-q":`Gateway Güvenilir Proxy Kimlik Doğrulaması`},help:{"v1-12fsi5d-58":`Kullanıcı kimlik beyanları ekleyen üst katman kimlik sağlayıcıları için güvenilir proxy kimlik doğrulama başlığı eşlemesi. Sahte kimlik başlıklarını önlemek için yalnızca bilinen proxy CIDR'leri ve katı başlık izin listeleriyle kullanın.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc":{label:{"v1-1hiowhq-12":`Cloudflare Access OIDC GitHub Kimliği`},help:{"v1-1puth4k-6t":`Seçilen bir Cloudflare Access OIDC sağlayıcısından alınan, isteğe bağlı doğrulanmış GitHub kimliği. Standart Access e-posta ve doğrulama beyanı üstbilgilerini gerektirir. Beyanlar eksikse profiller yalnızca e-posta bilgisiyle kalır; mevcut profil rolleri ve ortak yazar tercihleri korunur.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EgithubAccountIdClaim":{label:{"v1-appie6-n":`GitHub Hesap Kimliği Beyanı`},help:{"v1-pcaaw7-57":`Değeri, pozitif ondalık sayı dizesi biçiminde doğrulanmış bir GitHub hesap kimliği olan, iletilmiş OIDC beyanının tam adı. Access'i bunu oidc_fields içinde iletecek şekilde yapılandırın; kullanıcının düzenleyebildiği, doğrulanmamış bir beyanı asla kullanmayın.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2Eissuer":{label:{"v1-8flf1b-o":`Cloudflare Access Veren Kuruluşu`},help:{"v1-gykv03-56":`Güvenilen Cloudflare Access ekibinin tam HTTPS kökeni; örneğin https://example.cloudflareaccess.com, sonunda eğik çizgi olmadan. Diğer verenlerden gelen beyanlar GitHub kimliği sağlamaz.`}},"gateway%2Eauth%2EtrustedProxy%2EcloudflareAccessOidc%2EproviderId":{label:{"v1-1vne6sn-y":`Cloudflare Access OIDC Sağlayıcı Kimliği`},help:{"v1-kbyo5w-44":`Güvenilen OIDC entegrasyonu için tam Access kimlik sağlayıcısı kimliği. Bir sağlayıcının görünen adı veya eşleşen bir beyan adı tek başına güven oluşturmaz.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove":{label:{"v1-19sx4ub-y":`Güvenilir Proxy Cihaz Otomatik Onayı`},help:{"v1-uh32ha-6z":`Güvenilir proxy kimlik doğrulamasından sonra yeni tarayıcı ve yerel kullanıcı arayüzü operatör cihazlarını ve aynı anahtarın kapsam genişletmelerini otomatik olarak onaylayan isteğe bağlı politika. Verilen yetkiler, deviceAutoApprove.scopes ve varsa proxy'nin x-openclaw-scopes başlığıyla sınırlandırılır.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Eenabled":{label:{"v1-1hdecc2-16":`Güvenilir Proxy Cihaz Otomatik Onayı Etkin`},help:{"v1-1nntwls-78":`Ters proxy izin verilen bir kullanıcının kimliğini doğruladıktan sonra yeni tarayıcı ve yerel kullanıcı arayüzü operatör cihazlarını ve aynı anahtarın kapsam genişletmelerini otomatik olarak onaylar. Varsayılan: false. Yalnızca proxy kimlik doğrulama sınırı, manuel cihaz eşleştirmenin yerini alacak kadar güçlü olduğunda etkinleştirin.`}},"gateway%2Eauth%2EtrustedProxy%2EdeviceAutoApprove%2Escopes":{label:{"v1-erslbw-15":`Güvenilir Proxy Cihaz Otomatik Onay Kapsamları`},help:{"v1-raeila-g3":`Otomatik onaylanan operatör cihazlarına verilen en geniş yetki kapsamları. Varsayılan değerler operator.read, operator.write, operator.approvals ve operator.questions şeklindedir. İstenen kapsamlar bu listeyle sınırlıdır; kapsam belirtilmeyen isteklere bu liste atanır. Ayarlanmadığında, otomatik onay eski UI istemcileri için operator.questions kapsamını da ekler; açıkça belirtilen bir liste hiçbir zaman genişletilmez. operator.admin kapsamını açıkça listelemek, proxy üzerinden kimliği doğrulanan her kullanıcının tam yönetici yetkisi için otomatik onay almasına ve kapsam belirtilmeyen isteklere otomatik olarak tam yönetici yetkisi verilmesine olanak tanır; ayrıca kritik bir güvenlik denetimi bulgusunu ve Gateway başlangıç uyarısını tetikler.`}},"gateway%2Ebind":{label:{"v1-1g0dmdr-h":`Gateway Bağlanma Modu`},help:{"v1-1unqude-4y":`Arayüzlerin erişime açılmasını kontrol eden ağ bağlanma profili: "auto", "lan", "loopback", "custom" veya "tailnet". Yalnızca yerel kullanım için "loopback" değerini koruyun; "auto" tüm arayüzleri erişime açabilir.`}},"gateway%2EcliAgents":{label:{"v1-1noo169-a":`CLI Ajanları`},help:{"v1-1qqo8m2-5a":`Gateway oturum kataloğunun sunduğu harici CLI oturum motorlarının Control UI üzerinden keşfedilmesi. Varsayılan olarak etkindir; bu motorların yeni oturum model seçicisinden başlatılmasını önlemek için devre dışı bırakın.`}},"gateway%2EcliAgents%2Eenabled":{label:{"v1-11gsfq0-i":`CLI Ajanları Etkin`},help:{"v1-ufu7fx-8p":`true olduğunda, katalog tarafından desteklenen CLI ajanlarını Control UI yeni oturum model seçicisinde gösterir (varsayılan: true). CLI ajanlarını ve yerel CLI oturumu oluşturmayı devre dışı bırakmak için false olarak ayarlayın. Yalnızca oturum oluşturma desteğini bildiren kataloglar listelenir ve Gateway oturum kataloğu desteği bildirmediğinde seçici gizli kalır.`}},"gateway%2EcontrolUi":{label:{"v1-1cl7zto-a":`Control UI`},help:{"v1-bkw4g1-5i":`Etkinleştirme, yol yapılandırması ve tarayıcı kaynağı/kimlik doğrulama güvenliğini güçlendirme davranışı dahil olmak üzere Control UI barındırma ayarları. Arayüzün dışarıya açıklığını en aza indirin ve internete açık dağıtımlardan önce güçlü kimlik doğrulama denetimleriyle destekleyin.`}},"gateway%2EcontrolUi%2EallowedOrigins":{label:{"v1-11jcj2v-q":`Control UI İçin İzin Verilen Kaynaklar`},help:{"v1-1stgitk-9i":`Control UI/WebChat websocket bağlantıları için izin verilen tarayıcı kaynakları (yalnızca tam kaynak adresleri, ör. https://control.example.com). Tehlikeli Host üst bilgisi geri dönüşü açıkça etkinleştirilmedikçe, loopback dışındaki Control UI dağıtımları için gereklidir. ["*"] ayarı, tüm tarayıcı kaynaklarına izin verir ve sıkı denetlenen yerel testler dışında kullanılmamalıdır.`}},"gateway%2EcontrolUi%2EallowExternalEmbedUrls":{label:{"v1-1flu103-10":`Control UI İçinde Harici Gömülü İçerik URL'lerine İzin Ver`},help:{"v1-obwpfg-6s":`Barındırılan gömülü içeriklerin mutlak harici http(s) URL'lerini yüklemesine izin veren TEHLİKELİ seçenek. Control UI içinde güvenilir üçüncü taraf sayfalarını bilerek gömmüyorsanız bunu kapalı tutun; barındırılan /__openclaw__/canvas ve /__openclaw__/a2ui belgeleri buna ihtiyaç duymaz.`}},"gateway%2EcontrolUi%2EautomaticallyFetchFavicons":{label:{"v1-spcu6r-x":`Bağlantı Site Simgelerini Otomatik Getir`},help:{"v1-bn9u34-ag":`Bağlantıların site simgelerini ve tarayıcı sekmelerinin sosyal paylaşım önizlemelerini Gateway üzerinden getirir (varsayılan olarak açık). Tarayıcı sekmesi kartları, tarayıcı çerezlerini veya site kimlik bilgilerini kullanmadan herkese açık sayfa meta verilerini ve sayfada belirtilen görselleri yükler. Tüm isteklerde katı SSRF denetimleri uygulanır ve HTML/görsel işleme sınırlandırılır. Hem site simgelerinin hem de sayfa önizlemelerinin otomatik olarak getirilmesini devre dışı bırakmak için false olarak ayarlayın; canlı tarayıcı ekran görüntüleri bundan etkilenmez.`}},"gateway%2EcontrolUi%2EbasePath":{label:{"v1-qnzlec-k":`Control UI Temel Yolu`},help:{"v1-1dx68ar-1w":`Control UI'ın sunulduğu isteğe bağlı URL öneki (ör. /openclaw).`}},"gateway%2EcontrolUi%2EcommunityInvite":{label:{"v1-1j7cpqc-v":`Control UI Topluluk Daveti`},help:{"v1-1rz3zsx-73":`Bu Gateway tarafından sunulan Control UI içinde Discord topluluk davetini gösterir (varsayılan olarak açık). Bu arayüz dağıtımını kullanan tüm tarayıcılarda gizlemek için false olarak ayarlayın. Değişiklikler, tarayıcı yenilendikten veya yeniden bağlandıktan sonra uygulanır; yeniden etkinleştirildiğinde tarayıcıda yerel olarak kaydedilen kapatma tercihleri korunur.`}},"gateway%2EcontrolUi%2EdangerouslyAllowHostHeaderOriginFallback":{label:{"v1-vvl359-19":`Host Üstbilgisine Dayalı Kaynak Yedeğine Tehlikeli Biçimde İzin Ver`},help:{"v1-1t1qi4c-7v":`Control UI/WebChat WebSocket denetimlerinde Host üstbilgisine dayalı yedek kaynak belirlemeyi etkinleştiren TEHLİKELİ ayar. Bu mod, dağıtımınız bilinçli olarak Host üstbilgisine dayalı kaynak ilkesini kullanıyorsa desteklenir; gateway.controlUi.allowedOrigins değerinin açıkça belirtilmesi, güvenliği artırılmış varsayılan yaklaşım olarak önerilmeye devam eder.`}},"gateway%2EcontrolUi%2EembedSandbox":{label:{"v1-1hknvfl-t":`Control UI Gömülü İçerik Korumalı Alan Modu`},help:{"v1-d54l3a-7c":'Barındırılan Control UI gömülü içerikleri için iframe korumalı alan ilkesi. "strict" betikleri devre dışı bırakır, "scripts" kaynak yalıtımını koruyarak etkileşimli gömülü içeriklere izin verir (varsayılan) ve "trusted", bilinçli olarak daha yüksek ayrıcalıklar gerektiren aynı siteye ait belgeler için `allow-same-origin` ekler.'}},"gateway%2EcontrolUi%2Eenabled":{label:{"v1-1jokhv9-i":`Control UI Etkin`},help:{"v1-1hhyymc-4w":`true olduğunda Gateway Control UI arayüzünün Gateway HTTP sürecinden sunulmasını etkinleştirir. Yerel yönetim için etkin tutun; yerini harici bir kontrol arayüzü aldığında devre dışı bırakın.`}},"gateway%2EcontrolUi%2Eenvironment":{label:{"v1-tmefut-m":`Control UI Ortamı`},help:{"v1-paarso-4n":`Control UI şeridinde, ajan avatarında, etiket rozetlerinde, tarayıcı başlığında ve site simgesinde gösterilen, herkese açık isteğe bağlı ortam kimliği. Varsayılan görünümü korumak için belirtmeyin.`}},"gateway%2EcontrolUi%2Eenvironment%2Ecolor":{label:{"v1-vy6f72-s":`Control UI Ortam Rengi`},help:{"v1-mp6cta-2i":`Adlandırılmış ortam renk skalası: teal, amber, purple, coral, pink, blue, green, red veya gray.`}},"gateway%2EcontrolUi%2Eenvironment%2Elabel":{label:{"v1-1yr90xz-s":`Control UI Ortam Etiketi`},help:{"v1-1njve3z-3z":`Control UI içinde ve tarayıcı sekmesinde gösterilen ortam etiketi; başındaki ve sonundaki boşluklar kaldırılır ve etiket 1 ila 24 karakter içermelidir.`}},"gateway%2EcontrolUi%2Eexperimental":{label:{"v1-10uccgr-w":`Deneysel Control UI Özellikleri`},help:{"v1-1qobi2m-3g":`İsteğe bağlı olarak etkinleştirilen deneysel Control UI özellikleri. Bu özellikler sürümler arasında değişebilir ve açıkça etkinleştirilmedikçe devre dışı kalır.`}},"gateway%2EcontrolUi%2Eexperimental%2EcustomPlugins":{label:{"v1-1gaae1x-g":`Özel Eklenti Arayüzü`},help:{"v1-108u6ts-9e":`Kullanıcı tarafından yüklenen eklentilerin Control UI içinde doğrudan JavaScript çalıştırmasına izin verin (varsayılan: false). Yerleşik eklenti görünümleri kullanılabilir olmaya devam eder. Özel arayüz, oturum açmış operatörün Gateway izinlerini paylaşır; yalnızca güvenilir eklentiler için etkinleştirin. Değişiklikler Gateway yeniden başlatılmadan uygulanır. Daha önce yüklenen eklenti kodunu temizlemek için açık Control UI sayfalarını yeniden yükleyin.`}},"gateway%2EcontrolUi%2Egithub%2Etoken":{label:{"v1-1036yk1-10":`Control UI GitHub Hizmeti Kimlik Bilgisi`},help:{"v1-1p31phh-d6":`Yönetilen bir kimlik olmadan Control UI proje keşfi ve GitHub üzerine gelme önizlemeleri için SecretRef destekli hizmet kimlik bilgisi. Üzerine gelme önizlemeleri, seçilen ajanın yapılandırılmış GitHub kimliğini tercih eder; geçersiz kılma yoksa sistem kimliğini devralır. Hizmet sahipliğinin net olması için açık yapılandırmayı tercih edin. Paylaşılan Gateway işlem ortamındaki GH_TOKEN/GITHUB_TOKEN yedek seçeneğini korumak için bunu belirtmeyin. Açıkça yapılandırılmış ancak kullanılamayan bir kimlik bilgisi, erişimin reddedilmesine neden olur.`}},"gateway%2EcontrolUi%2Eroot":{label:{"v1-t5p3aj-m":`Control UI Varlıklarının Kök Dizini`},help:{"v1-elck04-25":`Control UI varlıkları için isteğe bağlı dosya sistemi kök dizini (varsayılan: dist/control-ui).`}},"gateway%2EcontrolUi%2EsessionObserver":{label:{"v1-tjwi96-r":`Control UI Oturum Gözlemcisi`},help:{"v1-1ahs80-8a":`Her ajanın yardımcı modelini kullanarak abone olan Control UI istemcileri için canlı oturum durumu özetleri üretir (varsayılan olarak açık). Gözlemci model çağrılarını Gateway genelinde devre dışı bırakmak için false olarak ayarlayın; agents.defaults.utilityModel değerini boş bir dize olarak ayarlamak, bu ayarı geçersiz kılmayan ajanlar için yardımcı modelle gözlemlemeyi devre dışı bırakır.`}},"gateway%2EcustomBindHost":{label:{"v1-upmb47-o":`Gateway Özel Bağlama Ana Bilgisayarı`},help:{"v1-lwjcyo-4d":`Özel bağlama için kullanılan IPv4 adresi. Belirli IPv4 adresleri, 127.0.0.1 üzerinde de aynı Gateway bağlantı noktasını gerektirir; tüm ağ arayüzlerinden erişim gerekmiyorsa 0.0.0.0 kullanmaktan kaçının.`}},"gateway%2Ehttp":{label:{"v1-1dyy3ff-g":`Gateway HTTP API`},help:{"v1-ebtex7-4j":`Uç nokta etkinleştirme ayarlarını ve aktarım katmanına yönelik API erişime açma kontrollerini gruplandıran Gateway HTTP API yapılandırması. Saldırı yüzeyini azaltmak için yalnızca gerekli uç noktaları etkin tutun.`}},"gateway%2Ehttp%2Eendpoints":{label:{"v1-1hyy5m9-m":`Gateway HTTP Uç Noktaları`},help:{"v1-1a0r104-55":`Gateway API kapsamındaki uyumluluk rotaları ve isteğe bağlı entegrasyonlar için HTTP uç noktası özellik anahtarları. Uç noktaları bilinçli olarak etkinleştirin ve kullanıma sunulduktan sonra erişim örüntülerini izleyin.`}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eenabled":{label:{"v1-1lv2qyt-w":`OpenAI Chat Completions Uç Noktası`},help:{"v1-1271mpb-2b":"OpenAI uyumlu `POST /v1/chat/completions` uç noktasını etkinleştirin (varsayılan: false)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages":{label:{"v1-9q1ao7-10":`OpenAI Chat Completions Görsel Sınırları`},help:{"v1-xgscw1-20":"OpenAI uyumlu `image_url` bölümleri için görsel alma/doğrulama denetimleri."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowedMimes":{label:{"v1-1acpvsy-18":`OpenAI Chat Completions İzin Verilen Görsel MIME Türleri Listesi`},help:{"v1-1guijf3-1t":"`image_url` bölümleri için izin verilen MIME türleri (büyük/küçük harfe duyarsız liste)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EallowUrl":{label:{"v1-ivns2a-14":`OpenAI Chat Completions Görsel URL'lerine İzin Ver`},help:{"v1-55cb3n-47":"`image_url` bölümleri için sunucu tarafında URL'den veri alınmasına izin verin (varsayılan: false; veri URI'leri desteklenmeye devam eder). URL'den veri almayı tamamen devre dışı bırakmak için bunu `false` olarak ayarlayın."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxBytes":{label:{"v1-1aakvdk-13":`OpenAI Chat Completions Görsel Başına Azami Bayt`},help:{"v1-d920yx-1s":"Alınan/kodu çözülen her `image_url` görseli için azami bayt sayısı (varsayılan: 10 MB)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EmaxRedirects":{label:{"v1-gi6vbe-17":`OpenAI Chat Completions Görselleri için Maksimum Yönlendirme Sayısı`},help:{"v1-1enujsk-1z":"`image_url` URL'leri alınırken izin verilen maksimum HTTP yönlendirmesi sayısı (varsayılan: 3)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EtimeoutMs":{label:{"v1-rg0i4t-16":`OpenAI Chat Completions Görsel Zaman Aşımı (ms)`},help:{"v1-89w2b9-1x":"`image_url` URL'lerini alma işlemleri için milisaniye cinsinden zaman aşımı (varsayılan: 10000)."}},"gateway%2Ehttp%2Eendpoints%2EchatCompletions%2Eimages%2EurlAllowlist":{label:{"v1-1sb0si1-17":`OpenAI Chat Completions İzin Verilen Görsel URL'leri Listesi`},help:{"v1-n4hlt1-4r":"`image_url` URL'lerini alma işlemleri için isteğe bağlı izin verilen ana makine adları listesi; tam ana makine adlarını ve `*.example.com` joker karakterlerini destekler. Listenin boş bırakılması veya belirtilmemesi, ana makine adı açısından izin listesi kısıtlaması olmadığı anlamına gelir."}},"gateway%2Ehttp%2EsecurityHeaders":{label:{"v1-5g4go1-t":`Gateway HTTP Güvenlik Üstbilgileri`},help:{"v1-n8z1hb-44":`Doğrudan Gateway işlemi tarafından uygulanan isteğe bağlı HTTP yanıt güvenlik üstbilgileri. TLS ters proxy'nizde sonlandırılıyorsa bunları orada ayarlamayı tercih edin.`}},"gateway%2Ehttp%2EsecurityHeaders%2EstrictTransportSecurity":{label:{"v1-16ryvji-w":`Katı Aktarım Güvenliği Üstbilgisi`},help:{"v1-1buwhc3-3v":`Strict-Transport-Security yanıt üstbilgisinin değeri. Yalnızca tamamen kontrolünüzde olan HTTPS kaynaklarında ayarlayın; açıkça devre dışı bırakmak için false kullanın.`}},"gateway%2Emode":{label:{"v1-1f0xa2s-c":`Gateway Modu`},help:{"v1-nfjirv-5m":`Gateway çalışma modu: "local", kanalları ve ajan çalışma ortamını bu ana makinede çalıştırırken "remote", uzak bağlantı üzerinden bağlanır. Bilinçli olarak ayrık bir uzak Gateway topolojisi kullanmıyorsanız "local" olarak bırakın.`}},"gateway%2Enodes%2EallowSkills":{label:{"v1-bnyeyy-r":`Gateway Düğümü Skills Etkin`},help:{"v1-1xwu6at-3g":`Eşleştirilmiş düğümlerin bağlı oldukları sürece yayımladıkları becerileri kabul edin (varsayılan: true). Düğümlerin yayımladığı becerileri yok saymak için false olarak ayarlayın.`}},"gateway%2Enodes%2Ebrowser%2Emode":{label:{"v1-no31im-p":`Gateway Düğümü Tarayıcı Modu`},help:{"v1-oeu1nc-69":`Düğüm tarayıcı yönlendirmesi ("auto" = ana makinedeki tarayıcıyı tercih et, yerel özellik kullanılamadığında bağlı tek bir tarayıcı düğümünü kullan; "manual" = açıkça bir düğüm seçilmesini veya yapılandırılmış bir düğüm sabitlemesi olmasını gerektir; "off" = düğüm yönlendirmesini devre dışı bırak).`}},"gateway%2Enodes%2Ebrowser%2Enode":{label:{"v1-1fqwdc0-o":`Gateway Düğümü Tarayıcı Sabitlemesi`},help:{"v1-1cykty2-1p":`Tarayıcı yönlendirmesini belirli bir düğüm kimliğine veya adına sabitleyin (isteğe bağlı).`}},"gateway%2Enodes%2Ecommands%2Eallow":{label:{"v1-9snt7h-13":`Gateway Düğümü İzin Listesi (Ek Komutlar)`},help:{"v1-6l4otb-5m":"Gateway varsayılanlarına ek olarak izin verilecek node.invoke komutları (komut dizelerinden oluşan bir dizi). Tehlikeli komutları burada etkinleştirmek, güvenlik açısından hassas bir geçersiz kılma işlemidir ve `openclaw security audit` tarafından işaretlenir."}},"gateway%2Enodes%2Ecommands%2Edeny":{label:{"v1-vauwib-l":`Gateway Düğümü Engelleme Listesi`},help:{"v1-u7c8wx-53":"Düğüm beyanlarında veya varsayılan izin listesinde bulunsalar bile engellenecek düğüm komutu adları (yalnızca komut adıyla tam eşleşme, ör. `system.run`; bu komutun içindeki kabuk metnini incelemez)."}},"gateway%2Enodes%2Epairing":{label:{"v1-1skp3xv-k":`Gateway Düğümü Eşleştirmesi`},help:{"v1-gldsi2-4s":`Düğüm eşleştirme ilkesi ayarları. SSH ile doğrulanan otomatik onay varsayılan olarak etkindir; güvenilir CIDR/IP izin listeleri açıkça yapılandırılmadıkça CIDR otomatik onayı devre dışı kalır.`}},"gateway%2Enodes%2Epairing%2EautoApproveCidrs":{label:{"v1-11ih0u1-13":`Gateway Düğüm Eşleştirmesinde Otomatik Onay CIDR'leri`},help:{"v1-1m6jsxj-6x":`Herhangi bir kapsam talep etmeyen, düğüm rolündeki cihazların ilk eşleştirmesini otomatik onaylamak için isteğe bağlı CIDR/IP izin listesi. Ayarlanmadığında devre dışıdır. Operatör, tarayıcı ve Control UI eşleştirmeleri ile rol, kapsam, meta veri veya açık anahtar yükseltmesi içeren tüm eşleştirmeler yine de manuel onay gerektirir.`}},"gateway%2Enodes%2Epairing%2EautoApproveLocal":{label:{"v1-178lial-13":`Gateway Yerel Düğüm Eşleştirmesini Otomatik Onaylama`},help:{"v1-glzm36-41":`Güvenilir yerel eşleştirmeleri ve erişim yükseltmelerini sessizce onaylar (varsayılan: true); kolaylık yerine her cihaz için açık onay istemeyi tercih ediyorsanız false olarak ayarlayın.`}},"gateway%2Enodes%2Epairing%2EsshVerify":{label:{"v1-muqemo-11":`Gateway Düğüm Eşleştirmesinde SSH Doğrulaması`},help:{"v1-1e4da92-ct":"Düğüm rolündeki cihazların ilk eşleştirmesi için SSH ile doğrulanan otomatik onay (varsayılan: etkin). Gateway, eşleştirme yapan ana makineye SSH ile geri bağlanır (BatchMode, katı ana makine anahtarı denetimi) ve yalnızca uzaktaki `openclaw node identity` çıktısı bekleyen cihaz anahtarıyla eşleştiğinde onay verir. SSH doğrulamasını devre dışı bırakmak için false olarak ayarlayın (etkin kalmaya devam eden autoApproveCidrs ayarından bağımsızdır); yalnızca manuel eşleştirme için autoApproveCidrs ayarını da kaldırın. user/identity/timeoutMs/cidrs değerlerini geçersiz kılmak için bir nesne iletin."}},"gateway%2Enodes%2EpluginTools":{label:{"v1-1cgl9u5-p":`Gateway Düğüm Eklenti Araçları`},help:{"v1-1c24iq3-28":`Eşleştirilmiş düğümlerin, ajanların görebileceği eklenti aracı tanımlayıcıları yayımlayıp yayımlayamayacağını denetler.`}},"gateway%2Enodes%2EpluginTools%2Eenabled":{label:{"v1-1osj3kc-x":`Gateway Düğümü Eklenti Araçları Etkin`},help:{"v1-14lgfu6-47":`Eşleştirilmiş düğümlerin yayımladığı, aracının görebildiği eklenti aracı tanımlayıcılarını kabul eder (varsayılan: true). Düğümlerin yayımladığı tüm eklenti araçlarını yok saymak ve kaldırmak için false olarak ayarlayın.`}},"gateway%2Eport":{label:{"v1-sqxdfo-c":`Gateway Bağlantı Noktası`},help:{"v1-for8t5-54":`Gateway dinleyicisinin API, Control UI ve kanallara yönelik giriş yolları için kullandığı TCP bağlantı noktası. Özel bir bağlantı noktası kullanın ve ters proxy'lerle veya yerel geliştirici hizmetleriyle çakışmalardan kaçının.`}},"gateway%2Eportals":{label:{"v1-zf0m5q-f":`Gateway Portalları`},help:{"v1-1v2lkw9-1c":`Portal yayımlama ve özel giriş ayarları.`}},"gateway%2Eportals%2Eingress":{label:{"v1-1cafvtp-m":`Özel Portal Girişi`},help:{"v1-20w4gq-69":`İsteğe bağlı, operatör tarafından yönetilen özel HTTPS joker alan adı ters proxy'si. Özgün Host başlığını, yolları ve WebSocket yükseltmelerini özel geri döngü dinleyicisine iletin. Portal için bearer kimlik doğrulaması yine gereklidir. Gateway'in yeniden başlatılmasını gerektirir.`}},"gateway%2Eportals%2Eingress%2Edomain":{label:{"v1-iitxfx-m":`Portal Joker Alan Adı`},help:{"v1-1ipbfad-53":`Rastgele portal alt alan adları için yalın DNS alan adı (örneğin previews.example.net). Joker DNS ve HTTPS'yi özel erişim için yapılandırın; Gateway veya Control UI ana makine adı alanını ortak kullanmayın.`}},"gateway%2Eportals%2Eingress%2Eport":{label:{"v1-1o3yr58-s":`Portal Girişi Geri Döngü Bağlantı Noktası`},help:{"v1-1mb98cv-4g":`Özel joker karakterli HTTPS proxy'sinden gelen trafiği alan, bu amaç için ayrılmış geri döngü HTTP portu. Gateway portundan farklı olmalıdır. Bu, genel HTTPS portu değil, arka uç portudur.`}},"gateway%2EpublicOrigin":{label:{"v1-b3jhw4-l":`Gateway Genel Erişim Kaynağı`},help:{"v1-17vekvx-87":`Gateway'in dışarıdan erişilebilen HTTPS kaynağı. HTTP'ye yalnızca localhost, 127.0.0.1 veya [::1] için izin verilir. İstekte bulunan tarafa özel MCP OAuth, /oauth/mcp/callback yolundaki geri çağırma URL'sini oluşturmak için bunu kullanır; kanal oturumu bağlantıları ve eklentilerin oluşturduğu görüntüleyici bağlantıları ise Control UI ve Gateway yollarına ulaşmak için bunu kullanır.`}},"gateway%2Epush":{label:{"v1-1o9y10t-l":`Gateway Anlık Bildirim İletimi`},help:{"v1-h23oz7-5s":`Gateway'in eşleştirilmiş cihazları uyandırması veya bu cihazlara bildirim göndermesi gerektiğinde kullandığı anlık bildirim iletim ayarları. Resmî iOS derlemeleri için aktarıcı destekli APNs'yi burada yapılandırın; yerel veya manuel derlemelerde doğrudan APNs kimlik doğrulaması ortam değişkenlerine dayalı olmaya devam eder.`}},"gateway%2Epush%2Eapns":{label:{"v1-gd06d3-l":`Gateway APNs İletimi`},help:{"v1-4bbafr-4e":`Bu Gateway ile eşleştirilmiş iOS cihazları için APNs iletim ayarları. Haricî anlık bildirim aktarıcısı üzerinden kaydolan resmî App Store derlemeleri için aktarıcı ayarlarını kullanın.`}},"gateway%2Epush%2Eapns%2Erelay":{label:{"v1-4sjqkk-i":`Gateway APNs Aktarıcısı`},help:{"v1-7glbel-6x":`Aracı destekli APNs gönderimleri için harici aracı ayarları. Eşleştirilmiş resmî bir iOS derlemesi aracı destekli bir kayıt yayımladıktan sonra Gateway, push.test, uyandırma bildirimleri ve yeniden bağlanma için uyandırma işlemlerinde varsayılan olarak barındırılan OpenClaw aracısını veya bu özel aracıyı kullanır.`}},"gateway%2Epush%2Eapns%2Erelay%2EbaseUrl":{label:{"v1-m977u4-r":`Gateway APNs Aracısı Temel URL'si`},help:{"v1-1o8mgnq-69":`Resmî App Store iOS derlemelerinin kullandığı harici APNs aracı hizmeti için isteğe bağlı özel temel HTTPS URL'si. Kayıt ve gönderim trafiğinin aynı dağıtıma ulaşması için bunu iOS derlemesine gömülü aracı URL'siyle uyumlu tutun.`}},"gateway%2Epush%2Eapns%2Erelay%2EtimeoutMs":{label:{"v1-1s3crai-v":`Gateway APNs Aracısı Zaman Aşımı (ms)`},help:{"v1-a0jkb1-4z":`Gateway'den APNs aracısına yapılan gönderim istekleri için milisaniye cinsinden zaman aşımı (varsayılan: 10000). Daha yavaş aracılar veya ağlar için artırın ya da uyandırma girişimlerinin daha hızlı başarısız olması için azaltın.`}},"gateway%2Ereload":{label:{"v1-vobbcc-d":`Yapılandırmayı Yeniden Yükleme`},help:{"v1-d02mvq-4w":`Düzenlemelerin nasıl uygulanacağını ve tam yeniden başlatmaların ne zaman tetikleneceğini belirleyen canlı yapılandırma yeniden yükleme ilkesi. Yeniden yükleme mekanizmasında hata ayıklamıyorsanız, en güvenli operasyonel güncellemeler için karma davranışı koruyun.`}},"gateway%2Ereload%2Emode":{label:{"v1-1qw6ix3-i":`Yapılandırmayı Yeniden Yükleme Modu`},help:{"v1-1q1etcf-3m":`Yapılandırma düzenlemelerinin nasıl uygulanacağını kontrol eder: "off" canlı düzenlemeleri yok sayar; "hybrid" ise çalışma sırasında güvenle uygulanabilen değişiklikleri uygular ve ardından gerektiğinde yeniden başlatır.`}},"gateway%2Eremote":{label:{"v1-aaj9cl-e":`Uzak Gateway`},help:{"v1-6xv7gd-5a":`Bu örnek başka bir çalışma zamanı sunucusuna vekillik yaptığında doğrudan veya SSH üzerinden iletişim için kullanılan uzak Gateway bağlantı ayarları. Uzak modu yalnızca ayrı sunucularda çalışma bilinçli olarak yapılandırıldığında kullanın.`}},"gateway%2Eremote%2EedgeAuth":{label:{"v1-5c8ezy-w":`Uzak Gateway Uç Kimlik Doğrulama Üstbilgileri`},help:{"v1-jg9p7d-5o":`Yapılandırılmış uzak Gateway'in önündeki kimlik bilgisine duyarlı bir proxy'ye sunulan, gizli bilgilere dayalı HTTP üstbilgileri. Üstbilgiler yalnızca WSS üzerinden tam olarak gateway.remote.url kaynağına gönderilir ve yönlendirmeleri asla izlemez.`}},"gateway%2Eremote%2Epassword":{label:{"v1-xfnwjq-n":`Uzak Gateway Parolası`},help:{"v1-16jc0yx-7y":`Bu istemcinin uzak bir Gateway'de kimliğini doğrulamak için parola alanında gönderilen paylaşılan gizli bilgi. Sunucunun gateway.auth.mode ayarı, yapılandırılmış gizli bilgisini seçer; istemcinin belirteç veya parola alanlarından herhangi biri kabul edilir. Bu gizli bilgiyi harici olarak yönetin ve sürüm kontrolüne kaydedilen yapılandırmada düz metin değerler kullanmaktan kaçının.`}},"gateway%2Eremote%2EsshHostKeyPolicy":{label:{"v1-3hl9l5-y":`Uzak Gateway SSH Ana Makine Anahtarı Politikası`},help:{"v1-7qoxtb-49":`macOS SSH ana makine anahtarı doğrulama politikası. "strict", önceden güvenilen bir ana makine anahtarı gerektirir; "openssh", doğrulamayı açıkça geçerli OpenSSH yapılandırmasına devreder.`}},"gateway%2Eremote%2EsshIdentity":{label:{"v1-1rgof8r-r":`Uzak Gateway SSH Kimliği`},help:{"v1-hz2hsm-1f":`İsteğe bağlı SSH kimlik dosyası yolu (ssh -i komutuna iletilir).`}},"gateway%2Eremote%2EsshTarget":{label:{"v1-nvjmc8-p":`Uzak Gateway SSH Hedefi`},help:{"v1-85w39w-2t":`SSH üzerinden uzak Gateway (Gateway bağlantı noktasını localhost'a tüneller). Biçim: user@host veya user@host:port.`}},"gateway%2Eremote%2EtlsFingerprint":{label:{"v1-akxcgg-u":`Uzak Gateway TLS Parmak İzi`},help:{"v1-1ri16lk-23":`Uzak Gateway için beklenen sha256 TLS parmak izi (MITM saldırılarını önlemek için sabitleyin).`}},"gateway%2Eremote%2Etoken":{label:{"v1-kw3r38-k":`Uzak Gateway Belirteci`},help:{"v1-1pb9q8w-7v":`Bu istemcinin uzak bir Gateway üzerinde kimliğini doğrulamak için token alanında gönderilen paylaşılan gizli değer. Sunucunun gateway.auth.mode ayarı, yapılandırılmış gizli değeri seçer; istemcinin token veya password alanlarından herhangi biri kabul edilir. Gizli değer/ortam değişkeni ikamesi yoluyla saklayın ve uzak Gateway kimlik doğrulama değişiklikleriyle birlikte yenileyin.`}},"gateway%2Eremote%2Etransport":{label:{"v1-hn4r18-o":`Uzak Gateway Aktarım Yöntemi`},help:{"v1-1acfs7m-54":`Uzak bağlantı aktarım yöntemi: "direct", yapılandırılmış URL üzerinden bağlantı kurarken "ssh", SSH üzerinden tünel oluşturur. Uzak bağlantı noktalarını dışarıya açmadan şifreli tünel işlevine ihtiyaç duyduğunuzda SSH kullanın.`}},"gateway%2Eremote%2Eurl":{label:{"v1-1i53o94-i":`Uzak Gateway URL'si`},help:{"v1-va7exe-1b":`Uzak Gateway WebSocket URL'si (ws:// veya wss://).`}},"gateway%2Eroles":{label:{"v1-189p1ru-m":`Gateway Operatör Rolleri`},help:{"v1-b59sc5-6w":`Ekip Gateway'leri için profile bağlı isteğe bağlı operatör rolleri. Adlandırılmış her rol, diğer kişilerin oturumlarına erişimi, korumalı alan yalıtımını, oturum ve çalıştırma ajanlarını ve verilen operatör yetki kapsamlarını denetler; bu bölümün atlanması mevcut operatör davranışını korur.`}},"gateway%2Eroles%2Edefault":{label:{"v1-1ykt1qe-l":`Varsayılan Operatör Rolü`},help:{"v1-1v8add8-4u":`Operatör rolleri yapılandırıldığında, geçerli bir açık ataması olmayan, kimliği doğrulanmış profillere atanan zorunlu rol. Adı, yapılandırılmış bir rol tanımıyla eşleşmelidir.`}},"gateway%2Eroles%2Edefinitions":{label:{"v1-sw4idp-p":`Operatör Rolü Tanımları`},help:{"v1-uv91an-53":`Kimliği doğrulanmış kullanıcı profillerine uygulanan, seçenekleri önceden belirlenmiş oturum paylaşımı, korumalı alan yalıtımı, ajan erişimi ve operatör yetki kapsamı politikalarını bir araya getiren, yönetici tarafından adlandırılmış, boş olmayan rol tanımları.`}},"gateway%2Eroles%2Edefinitions%2E*":{label:{"v1-irzm3w-o":`Operatör Rolü Tanımı`},help:{"v1-p8tfws-6q":`Adlandırılmış tek bir operatör rolü. Her tanım; oturum paylaşım politikasını, izin verilen oturum ve çalıştırma ajanlarını ve operatör yetki kapsamının üst sınırını açıkça belirtmelidir. Ayrıca yeni oluşturulan oturumlar için korumalı alan yalıtımını ve bir eklenti erişim politikasını zorunlu kılabilir.`}},"gateway%2Eroles%2Edefinitions%2E*%2EaccessPolicyPlugin":{label:{"v1-yhsyhu-y":`Operatör Rolü Erişim Politikası Eklentisi`},help:{"v1-1gq4q08-9n":`Gateway erişim politikasının bu role yetki vermesi gereken eklentinin tam kimliği; isteğe bağlıdır. Eklenti eksikse, devre dışıysa, yüklenemiyorsa veya geçerli bir yetki sağlamıyorsa erişim reddedilir. Bağımsız personel rolleri ve Gateway sahibi erişimi düzeltebilsin diye kullanılamayan eklenti kimlikleri yapılandırmada geçerli kalır. Bu alanın belirtilmemesi herhangi bir eklenti bağımlılığı eklemez.`}},"gateway%2Eroles%2Edefinitions%2E*%2Eagents":{label:{"v1-1u0v1av-s":`Operatör Rolü İçin İzin Verilen Ajanlar`},help:{"v1-fvun18-4v":`Bu rol oturum oluşturduğunda veya çalıştırma başlattığında kullanılabilecek ajanlar: Tüm ajanlara izin vermek için "*" kullanın, yalnızca belirli ajanlara izin vermek için ajan kimliklerini listeleyin veya her iki işlemi de devre dışı bırakmak için boş bir liste kullanın.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esandbox":{label:{"v1-1h433k8-v":`Operatör Rolü Korumalı Alan Yalıtımı`},help:{"v1-sknx21-66":`Yeni oluşturulan oturumlar için yürütme yalıtımı: "inherit" (varsayılan), ajan politikasını kullanır; "required", ajanın korumalı alan modu kapalı olsa bile korumalı alanı kalıcı olarak zorunlu kılar ve arka uç kullanılamıyorsa güvenliği korumak için yürütmeyi engeller.`}},"gateway%2Eroles%2Edefinitions%2E*%2Escopes":{label:{"v1-1qejq9c-r":`Operatör Rolü Kapsam Üst Sınırı`},help:{"v1-1selr2i-4s":`Bu rolün azami bağlantı yetkisi olarak verilen operatör kapsamlarının kapalı listesi. Talep edilen, eşleştirme yoluyla verilen, kimlik üzerinden verilen ve yükseltilen kapsamların bu listeyle kesişimi alınır.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions":{label:{"v1-1t2w5en-s":`Operatör Rolü Oturum Erişimi`},help:{"v1-hsoiop-45":`Kimliği doğrulanmış diğer kişilerin oluşturduğu oturumlar için bu role verilen oturum paylaşım izinleri; kişinin kendi oturumları, sahibi tarafından erişilebilir olmaya devam eder.`}},"gateway%2Eroles%2Edefinitions%2E*%2Esessions%2Eothers":{label:{"v1-lcjhtz-12":`Operatör Rolünün Diğer Oturumlara Erişimi`},help:{"v1-vf8umx-5r":`Başkalarının oturumlarına erişim: "none" oturumları gizler, "view" okumaya izin verir, "suggest" öneri akışına izin verir ve "write" katılıma izin verir. Açıkça tanımlanmış oturum üyeliği ek erişim sağlayabilir.`}},"gateway%2Etailscale":{label:{"v1-1gi7nvp-h":`Gateway Tailscale`},help:{"v1-6ar9o-4x":`Serve/Funnel üzerinden erişime açma ve Gateway başlatıldığında veya kapatıldığında yaşam döngüsü yönetimi için Tailscale entegrasyon ayarları. Dağıtımınız bilinçli olarak Tailscale üzerinden gelen trafiğe dayanmıyorsa kapalı tutun.`}},"gateway%2Etailscale%2Emode":{label:{"v1-n7wv5k-m":`Gateway Tailscale Modu`},help:{"v1-6l2099-5a":`Tailscale yayın modu: özel veya herkese açık erişim yolları için "off", "serve" veya "funnel". Yalnızca tailnet erişimi için "serve", yalnızca genel internetten erişilebilirlik gerektiğinde "funnel" kullanın.`}},"gateway%2Etailscale%2EpreserveFunnel":{label:{"v1-h174rt-1d":`Gateway Tailscale Harici Funnel Geçiş Koruması`},help:{"v1-1mntkor-7q":`mode='serve' için kullanımdan kaldırılmış geçiş koruması. Harici bir Funnel hâlâ normal Gateway dinleyicisini hedefliyorsa OpenClaw erişime açma ayarlarını değiştirmez ve parola ile kimlik doğrulama yapılandırılıp mod 'funnel' olarak değiştirilene kadar yalnızca eklenti üzerinden kimlik doğrulaması yapılan webhook'ların kullanılabilir kalacağı konusunda uyarır.`}},"gateway%2Eterminal":{label:{"v1-11obn6j-h":`Operatör Terminali`},help:{"v1-18f5rgm-8b":`Control UI ve mobil istemcilere sunulan operatör terminali: Gateway ana makinesinde çalışan, yönetici kapsamındaki operatör oturumlarıyla sınırlı, PTY destekli bir kabuk. Hedef ajanın çalışma alanında başlar ve tam olarak korumalı alanda çalışan ajanlar (sandbox.mode 'all') için kısıtlanmamış bir ana makine kabuğu sunmak yerine erişimi reddeder.`}},"gateway%2Eterminal%2EdetachedSessionTimeoutSeconds":{label:{"v1-g247t4-16":`Operatör Terminali Ayrılmış Oturum Zaman Aşımı`},help:{"v1-k6qbgr-9e":`Bir terminal oturumunun bağlantısı kesildikten sonra (dizüstü bilgisayarın uykuya geçmesi, sayfanın yeniden yüklenmesi) kaç saniye açık kalacağını belirler. Bu süre boyunca terminal.attach aracılığıyla oturuma yeniden bağlanılabilir ve son çıktılar tekrar gösterilir. Bağlantı kesildiği anda oturumları sonlandırmak için 0 olarak ayarlayın. Varsayılan: 300 (5 dakika). Bağlantısı kesilmiş oturumlar komutlarını çalıştırmaya devam eder; bu nedenle paylaşılan veya dışarıya açık ana makinelerde bu süreyi kısaltın.`}},"gateway%2Eterminal%2Eenabled":{label:{"v1-6xiiwa-p":`Operatör Terminali Etkin`},help:{"v1-1nez06v-7p":`Yönetici yetki kapsamına sahip istemciler için operatör terminalini etkinleştirir (varsayılan: true). Bu, Gateway işleminin ortamıyla çalışan, tarayıcıdan veya mobil cihazdan erişilebilen bir kabuk sunar; yönetici operatörlerin ana makine kabuğuna erişmemesi gereken dağıtımlarda devre dışı bırakmak için false olarak ayarlayın. Değişiklikler Gateway yeniden başlatılmadan uygulanır.`}},"gateway%2Eterminal%2Eshell":{label:{"v1-1qte0r1-n":`Operatör Terminali Kabuğu`},help:{"v1-19mfe6t-5i":`Operatör terminalinin başlatacağı kabuk yürütülebilir dosyası. Ana makinenin oturum açma kabuğunu (Unix'te $SHELL, Windows'ta %ComSpec%) kullanmak için ayarlamadan bırakın veya tutarlı bir operatör ortamı için belirli bir yorumlayıcı seçin.`}},"gateway%2Etls":{label:{"v1-103eqog-b":`Gateway TLS`},help:{"v1-1dx77dq-4z":`HTTPS'yi doğrudan Gateway sürecinde sonlandırmak için TLS sertifikası ve anahtar ayarları. Üretim ortamında sertifikaları açıkça belirtin ve güvenilmeyen ağlarda şifrelenmemiş erişimden kaçının.`}},"gateway%2Etls%2EautoGenerate":{label:{"v1-17g0gmx-u":`Gateway TLS Sertifikasını Otomatik Oluştur`},help:{"v1-1ld6uiu-4w":`Dosyalar açıkça yapılandırılmadığında otomatik olarak yerel bir TLS sertifikası/anahtar çifti oluşturur. Yalnızca yerel veya geliştirme kurulumlarında kullanın ve üretim trafiği için gerçek sertifikalarla değiştirin.`}},"gateway%2Etls%2EcaPath":{label:{"v1-h9qtpb-j":`Gateway TLS CA Yolu`},help:{"v1-andqlu-52":`Gateway sınırında istemci doğrulaması veya özel güven zinciri gereksinimleri için isteğe bağlı CA paketi yolu. Dağıtımda özel PKI veya özel sertifika zincirleri kullanılıyorsa bunu kullanın.`}},"gateway%2Etls%2EcertPath":{label:{"v1-160lhdi-s":`Gateway TLS Sertifikası Yolu`},help:{"v1-1wznaof-4q":`TLS etkin olduğunda Gateway tarafından kullanılan TLS sertifika dosyasının dosya sistemi yolu. Yönetilen sertifika yollarını kullanın ve yenileme otomasyonunu bu konumla uyumlu tutun.`}},"gateway%2Etls%2Eenabled":{label:{"v1-1hdsowh-j":`Gateway TLS Etkin`},help:{"v1-ykhwp0-4o":`İstemcilerin doğrudan HTTPS/WSS üzerinden bağlanabilmesi için Gateway dinleyicisinde TLS sonlandırmasını etkinleştirir. Doğrudan internete açık olduğunda veya güvenilmeyen herhangi bir ağ sınırında etkin tutun.`}},"gateway%2Etls%2EkeyPath":{label:{"v1-1a645em-k":`Gateway TLS Anahtarı Yolu`},help:{"v1-15knri0-4i":`TLS etkin olduğunda Gateway tarafından kullanılan TLS özel anahtar dosyasının dosya sistemi yolu. Bu anahtar dosyasına erişimi izinlerle kısıtlayın ve anahtarı güvenlik politikanıza göre düzenli olarak değiştirin.`}},"gateway%2Etools":{label:{"v1-1b7s1vg-s":`Gateway Araç Erişim Politikası`},help:{"v1-1ffol26-5a":`Çalışma zamanında araç kullanılabilirliğini ajan/araç profillerinden bağımsız olarak kısıtlayabilen, Gateway düzeyinde araç erişimine izin verme/erişimi reddetme politikası. Bunu genel kapsamlı acil durum kontrolleri ve üretim ortamının güvenliğini güçlendirmek için kullanın.`}},"gateway%2Etools%2Eallow":{label:{"v1-tfn15c-m":`Gateway İzin Verilen Araçlar Listesi`},help:{"v1-163khb1-4y":`Çalışma zamanında sınırlı bir araç kümesinin kullanılabilir olmasını istediğinizde, Gateway düzeyinde açıkça tanımlanan izin verilen araçlar listesi. Araç kapsamının sıkı biçimde denetlenmesi gereken, erişimi kısıtlanmış ortamlarda bunu kullanın.`}},"gateway%2Etools%2Edeny":{label:{"v1-1a8nr3t-l":`Gateway Engellenen Araçlar Listesi`},help:{"v1-1lhssnf-4o":`Alt düzey politikalar izin verse bile riskli araçları engelleyen, Gateway düzeyinde açıkça tanımlanmış araç engelleme listesi. Acil müdahale ve çok katmanlı güvenliği güçlendirmek için engelleme kurallarını kullanın.`}},"gateway%2EtrustedProxies":{label:{"v1-8g5i45-r":`Gateway Güvenilir Proxy CIDR'leri`},help:{"v1-n5zcvf-4f":`İletilen istemci kimliği üstbilgilerini sağlamasına izin verilen üst ağ proxy'lerinin CIDR/IP izin listesi. Güvenilmeyen ara noktaların kullanıcıların kimliğine bürünmesini önlemek için bu listeyi dar kapsamlı tutun.`}},hooks:{label:{"v1-j9ywl7-5":`Kancalar`},help:{"v1-1mzh0ry-5v":`Harici olayları OpenClaw'da uyandırma veya ajan eylemlerine eşleyen, gelen webhook otomasyon arayüzü. Güvenilir ağların dışına açmadan önce açıkça tanımlanmış belirteç, oturum ve ajan denetimleriyle erişimi sıkı biçimde kısıtlayın.`}},"hooks%2EallowedAgentIds":{label:{"v1-1dan5ok-n":`Kancalar İçin İzin Verilen Ajan Kimlikleri`},help:{"v1-hree88-7c":`agentId belirtilmediğinde varsayılan ajana yönlendirme de dahil olmak üzere, kanca isteklerinin ve eşlemelerinin hedeflemesine izin verilen etkin ajan kimliklerinin izin listesi. Otomasyon olaylarını özel hizmet ajanlarıyla sınırlamak ve bir kanca belirteci açığa çıkarsa etki alanını azaltmak için bunu kullanın.`}},"hooks%2EallowedSessionKeyPrefixes":{label:{"v1-4rmaac-y":`Kancalar İçin İzin Verilen Oturum Anahtarı Önekleri`},help:{"v1-b346oh-4r":`Çağıranın sağladığı anahtarlar etkinleştirildiğinde, gelen kanca istekleri için kabul edilen oturum anahtarı öneklerinin izin listesi. İsteğe göre oturum anahtarı enjekte edilmesini önlemek için dar kapsamlı önekler kullanın.`}},"hooks%2EallowRequestSessionKey":{label:{"v1-u7mvac-v":`Kancalarda İstek Oturum Anahtarına İzin Ver`},help:{"v1-11n9ps-52":`true olduğunda çağıranların kanca isteklerinde bir oturum anahtarı sağlamasına izin vererek çağıran tarafından denetlenen yönlendirmeyi etkinleştirir. Güvenilir entegratörler özel oturum ilişkilendirmesine açıkça ihtiyaç duymadıkça false olarak tutun.`}},"hooks%2EdefaultSessionKey":{label:{"v1-bn0nb9-p":`Kancalar İçin Varsayılan Oturum Anahtarı`},help:{"v1-bzdgkn-57":`Bir istek izin verilen kanallardan bir oturum anahtarı sağlamadığında kanca teslimatları için kullanılan yedek oturum anahtarı. Birbiriyle ilgisiz otomasyon konuşmalarının karışmasını önlemek için sabit ancak kapsamı sınırlı bir anahtar kullanın.`}},"hooks%2Eenabled":{label:{"v1-1gty8ga-d":`Kancalar Etkin`},help:{"v1-1mixmjf-4n":`Gelen webhook istekleri için kanca uç noktasını ve eşleme yürütme işlem hattını etkinleştirir. Harici olayları etkin olarak Gateway'e yönlendirmiyorsanız devre dışı bırakın.`}},"hooks%2Egmail":{label:{"v1-o8tl94-a":`Gmail Kancası`},help:{"v1-4cibmt-4r":`Pub/Sub bildirimleri ve isteğe bağlı yerel geri çağrı hizmeti için kullanılan Gmail anlık bildirim entegrasyonu ayarları. Mümkün olduğunda bu kapsamı otomasyona ayrılmış Gmail hesaplarıyla sınırlayın.`}},"hooks%2Egmail%2Eaccount":{label:{"v1-11iw2zb-i":`Gmail Kancası Hesabı`},help:{"v1-12l1h96-4v":`Bu kanca entegrasyonunda Gmail izleme/abonelik işlemleri için kullanılan Google hesabı tanımlayıcısı. İşlemsel izinleri ayrı tutmak için otomasyona ayrılmış bir posta kutusu hesabı kullanın.`}},"hooks%2Egmail%2EallowUnsafeExternalContent":{label:{"v1-6617w5-14":`Gmail Kancasında Güvenli Olmayan Harici İçeriğe İzin Ver`},help:{"v1-1w3gdvs-55":`Etkinleştirildiğinde, daha az arındırılmış harici Gmail içeriğinin işlenmesine izin verir. Daha güvenli varsayılanlar için devre dışı bırakın ve yalnızca kontrollü dönüşümlerin uygulandığı güvenilir posta akışları için etkinleştirin.`}},"hooks%2Egmail%2EhookUrl":{label:{"v1-1xypore-n":`Gmail Kancası Geri Çağrı URL'si`},help:{"v1-19fhn6q-4z":`Gmail'in veya aracıların bu kanca işlem hattına bildirim iletmek için çağırdığı, herkese açık geri çağrı URL'si. Bu URL'yi belirteç doğrulaması ve kısıtlı ağ erişimiyle koruyun.`}},"hooks%2Egmail%2EincludeBody":{label:{"v1-x6h6eo-n":`Gmail Kancasında İleti Gövdesini Dahil Et`},help:{"v1-14cf1c3-52":`true olduğunda, sonraki eşleme/ajan işlemleri için e-posta gövdesi içeriğini alır ve dahil eder. Yük boyutunu ve veri hassasiyetini artırdığı için, gövde metni gerekmedikçe false olarak bırakın.`}},"hooks%2Egmail%2Elabel":{label:{"v1-75v7g6-g":`Gmail Kancası Etiketi`},help:{"v1-9zpdg8-4g":`Hangi etiketli iletilerin kanca olaylarını tetikleyeceğini sınırlayan isteğe bağlı Gmail etiketi filtresi. Otomasyonların ilgisiz gelen kutusu trafiğiyle dolmasını önlemek için filtreleri dar kapsamlı tutun.`}},"hooks%2Egmail%2EmaxBytes":{label:{"v1-nk9y9t-p":`Gmail Kancası Maksimum Gövde Boyutu (bayt)`},help:{"v1-2aaxx1-4b":`includeBody etkin olduğunda olay başına işlenen Gmail yükünün bayt cinsinden maksimum boyutu. Çok büyük iletileri işlemenin maliyetini ve riskini azaltmak için sınırları düşük tutun.`}},"hooks%2Egmail%2Emodel":{label:{"v1-15jx1vj-p":`Gmail Kancası Model Geçersiz Kılma`},help:{"v1-1var65t-59":`Posta kutusu otomasyonlarının özel model davranışı kullanması gerektiğinde, Gmail tarafından tetiklenen çalıştırmalar için isteğe bağlı model geçersiz kılma ayarı. Posta kutusu görevleri özelleştirme gerektirmedikçe, ajanın varsayılan ayarlarını devralmak için ayarlamadan bırakın.`}},"hooks%2Egmail%2EpushToken":{label:{"v1-1u1u1rl-l":`Gmail Kancası Anlık Bildirim Belirteci`},help:{"v1-h1vx01-4o":`Bildirimler işlenmeden önce Gmail anlık bildirim kancası geri çağrılarında gerekli olan paylaşılan gizli belirteç. Ortam değişkeni ikamesini kullanın ve geri çağrı uç noktaları dış erişime açıksa belirteci düzenli olarak yenileyin.`}},"hooks%2Egmail%2ErenewEveryMinutes":{label:{"v1-bcw0nt-v":`Gmail Kancası Yenileme Aralığı (dk)`},help:{"v1-pr1z9-49":`Gmail izleme aboneliklerinin süresinin dolmasını önlemek için dakika cinsinden yenileme sıklığı. Sağlayıcının geçerlilik süresinden kısa bir süre belirleyin ve yenileme hatalarını günlüklerden izleyin.`}},"hooks%2Egmail%2Eserve":{label:{"v1-djm9vi-n":`Gmail Kancası Yerel Sunucusu`},help:{"v1-hom4wq-54":`Gmail bildirimlerini ayrı bir giriş katmanı olmadan doğrudan almak için yerel geri çağrı sunucusu ayarları bloğu. Yalnızca bu işlemin webhook trafiğini kendisinin sonlandırması gerektiğinde etkinleştirin.`}},"hooks%2Egmail%2Eserve%2Ebind":{label:{"v1-1f9dlu6-u":`Gmail Kanca Sunucusu Bağlama Adresi`},help:{"v1-55bieu-4d":`Kancalara doğrudan hizmet verilirken kullanılan yerel Gmail geri çağrı HTTP sunucusunun bağlama adresi. Dışarıdan erişim özellikle gerekli değilse yalnızca yerel döngü adresiyle sınırlı tutun.`}},"hooks%2Egmail%2Eserve%2Epath":{label:{"v1-1fmz9ci-m":`Gmail Kanca Sunucusu Yolu`},help:{"v1-1jqhcw4-4h":`Yerel Gmail geri çağrı sunucusunda anlık bildirimlerin kabul edildiği HTTP yolu. Olayların kaybolmasını önlemek için bunu abonelik yapılandırmasıyla tutarlı tutun.`}},"hooks%2Egmail%2Eserve%2Eport":{label:{"v1-hvr7cq-m":`Gmail Kanca Sunucusu Bağlantı Noktası`},help:{"v1-1yku7dz-43":`Sunum modu etkinleştirildiğinde yerel Gmail geri çağrı HTTP sunucusunun kullanacağı bağlantı noktası. Gateway/kontrol arayüzleriyle çakışmaları önlemek için özel bir bağlantı noktası kullanın.`}},"hooks%2Egmail%2Esubscription":{label:{"v1-19s0hm9-n":`Gmail Kanca Aboneliği`},help:{"v1-127h8vg-5b":`Yapılandırılmış konudan Gmail değişiklik bildirimlerini almak için Gateway tarafından kullanılan Pub/Sub aboneliği. Birden fazla tüketicinin beklenmedik şekilde yarışmasını önlemek için abonelik sahipliğini net tutun.`}},"hooks%2Egmail%2Etailscale":{label:{"v1-gxsxe8-k":`Gmail Kancası Tailscale`},help:{"v1-7jzidp-4l":`Gmail geri çağrılarını Serve/Funnel yolları üzerinden yayımlamak için Tailscale erişime açma yapılandırması bloğu. Herkese açık herhangi bir giriş yolunu etkinleştirmeden önce özel tailnet modlarını kullanın.`}},"hooks%2Egmail%2Etailscale%2Emode":{label:{"v1-1jsc22r-p":`Gmail Kancası Tailscale Modu`},help:{"v1-vhm395-4u":`Gmail geri çağrıları için Tailscale erişime açma modu: "off", "serve" veya "funnel". Özel tailnet üzerinden iletim için "serve", yalnızca herkese açık internetten gelen erişim gerektiğinde "funnel" kullanın.`}},"hooks%2Egmail%2Etailscale%2Epath":{label:{"v1-1nkowt3-p":`Gmail Kancası Tailscale Yolu`},help:{"v1-fr8qi-4m":`Etkinleştirildiğinde Gmail geri çağrılarını yönlendirmek için Tailscale Serve/Funnel tarafından yayımlanan yol. İsteklerin beklenen işleyiciye ulaşması için bu yolu Gmail webhook yapılandırmasıyla uyumlu tutun.`}},"hooks%2Egmail%2Etailscale%2Etarget":{label:{"v1-1u75uvt-r":`Gmail Kancası Tailscale Hedefi`},help:{"v1-1twwxge-47":`Tailscale Serve/Funnel tarafından yönlendirme yapılan yerel hizmet hedefi (örneğin http://127.0.0.1:8787). Yönlendirme belirsizliğini önlemek için açıkça belirtilmiş geri döngü hedefleri kullanın.`}},"hooks%2Egmail%2Ethinking":{label:{"v1-rxxhgo-s":`Gmail Kancası Düşünme Ayarını Geçersiz Kılma`},help:{"v1-17owk9q-4z":`Gmail tarafından tetiklenen ajan çalıştırmalarında düşünme çabasını geçersiz kılan ayar: "off", "minimal", "low", "medium" veya "high". Maliyet ve gecikmeyi kontrol altında tutmak için rutin gelen kutusu otomasyonlarında düşük varsayılan değerler kullanın.`}},"hooks%2Egmail%2Etopic":{label:{"v1-1n1wncx-o":`Gmail Kancası Pub/Sub Konusu`},help:{"v1-iled0e-4p":`Gmail izleme özelliğinin bu hesap için değişiklik bildirimleri yayımlamak üzere kullandığı Google Pub/Sub konu adı. İzlemeyi etkinleştirmeden önce konunun IAM ayarlarının Gmail'e yayımlama erişimi verdiğinden emin olun.`}},"hooks%2Einternal":{label:{"v1-1hsfqas-e":`Dahili Kancalar`},help:{"v1-piq9k-4v":`Modül yollarından yüklenen, paketle gelen veya özel olay işleyicileri için dahili kanca çalışma zamanı ayarları. Bunu güvenilir süreç içi otomasyonlar için kullanın ve işleyici yükleme kapsamını sıkı biçimde sınırlandırın.`}},"hooks%2Einternal%2Eenabled":{label:{"v1-1kouv99-m":`Dahili Kancalar Etkin`},help:{"v1-1wv0289-4c":`Dahili kanca çalışma zamanında dahili kancaların ve yapılandırılmış kayıtların işlenmesini etkinleştirir. Dahili kancalar bilinçli olarak yapılandırılmadıkça devre dışı bırakın.`}},"hooks%2Einternal%2Eentries":{label:{"v1-1coawdn-l":`Dahili Kanca Kayıtları`},help:{"v1-1ovi38l-4o":`Belirli çalışma zamanı işleyicilerini ve meta verileri kaydetmek için kullanılan, yapılandırılmış dahili kanca kayıtları. Üretim ortamındaki davranışın denetlenebilmesi için kayıtları açıkça tanımlayın ve sürümleyin.`}},"hooks%2Einternal%2Eload":{label:{"v1-e71kzu-k":`Dahili Kanca Yükleyicisi`},help:{"v1-11re5ph-4p":`Başlangıçta işleyici modüllerinin nerelerde aranacağını belirleyen dahili kanca yükleyicisi ayarları. İstenmeyen modül çakışmalarını veya gölgelenmelerini azaltmak için yükleme kök dizinlerini sınırlayın.`}},"hooks%2Einternal%2Eload%2EextraDirs":{label:{"v1-1oj9uqa-v":`Dahili Kanca Ek Dizinleri`},help:{"v1-1xfdqxg-4c":`Varsayılan yükleme yollarına ek olarak dahili kanca modüllerinin arandığı dizinler. İstenmeyen modül gölgelenmelerini azaltmak için bu dizinleri mümkün olduğunca az sayıda ve denetim altında tutun.`}},"hooks%2Emappings":{label:{"v1-16wwkft-d":`Kanca Eşlemeleri`},help:{"v1-frhp3v-5i":`Gelen kanca isteklerini eşleştirip isteğe bağlı teslimat yönlendirmesiyle uyandırma veya aracı eylemlerini seçen sıralı eşleme kuralları. Geniş kapsamlı örüntü kurallarının her şeyi yakalamasını önlemek için daha belirli eşlemeleri önce yerleştirin.`}},"hooks%2Emappings%5B%5D%2Eaction":{label:{"v1-bvm5m2-j":`Kanca Eşleme Eylemi`},help:{"v1-1r5zt5f-5f":`Eşleme eylemi türü: "wake", aracının uyandırma akışını tetikler; "agent" ise doğrudan aracı tarafından işlenmek üzere gönderir. Hemen yürütme için "agent", kalp atışı temelli işleme tercih edildiğinde ise "wake" kullanın.`}},"hooks%2Emappings%5B%5D%2EagentId":{label:{"v1-r93mi6-l":`Kanca Eşlemesi Aracı Kimliği`},help:{"v1-l0uioz-4y":`Eylem yönlendirmesinin varsayılanları kullanmaması gerektiğinde eşleme yürütmesi için hedef ajan kimliği. Webhook davranışını etkileşimli operatör oturumlarından ayırmak için özel otomasyon ajanları kullanın.`}},"hooks%2Emappings%5B%5D%2EallowUnsafeExternalContent":{label:{"v1-1nlag5p-16":`Kanca Eşlemesinde Güvenli Olmayan Harici İçeriğe İzin Ver`},help:{"v1-1np9426-57":`true olduğunda eşleme içeriği, oluşturulan mesajlarda daha az temizlenmiş harici yük verileri içerebilir. Varsayılan olarak false bırakın ve yalnızca dönüşüm mantığı incelenmiş güvenilir kaynaklar için etkinleştirin.`}},"hooks%2Emappings%5B%5D%2Echannel":{label:{"v1-f719ab-t":`Kanca Eşlemesi Teslim Kanalı`},help:{"v1-oz7pu5-5s":`Eşleme çıktıları için teslim kanalı geçersiz kılma ayarı (örneğin "last", "telegram", "discord", "slack", "signal", "imessage" veya "msteams"). Yanlışlıkla başka kanallara gönderim yapılmasını önlemek için kanal geçersiz kılma ayarlarını açıkça belirtin.`}},"hooks%2Emappings%5B%5D%2Edeliver":{label:{"v1-2h4axx-q":`Kanca Eşlemesi Yanıtını Teslim Et`},help:{"v1-12tbbam-5o":`Eşleme yürütme sonuçlarının sessizce işlenmesi yerine bir kanal hedefine iletilip iletilmeyeceğini belirler. Kullanıcıya yönelik çıktı paylaşmaması gereken arka plan otomasyonları için teslimi devre dışı bırakın.`}},"hooks%2Emappings%5B%5D%2EforEach":{label:{"v1-fzd0ar-o":`Kanca Eşlemesi Dağıtım Anahtarı`},help:{"v1-1d593op-7e":`Eşlemenin öğelerini ayrı ayrı işlediği üst düzey yük dizisinin anahtarı: her öğe kendi eylemini tetikler; şablonlar veya dönüşümler ise dizisinde yalnızca geçerli öğenin bulunduğu bir yük görür. Gmail ön ayarı forEach: messages kullanır; böylece toplu gönderimler her e-posta için bir çalıştırma başlatır.`}},"hooks%2Emappings%5B%5D%2Eid":{label:{"v1-1nctnx-f":`Kanca Eşlemesi Kimliği`},help:{"v1-q1t4zw-57":`Denetim, sorun giderme ve hedefli güncellemeler için kullanılan, kanca eşleme girdisine ait isteğe bağlı sabit tanımlayıcı. Günlüklerin ve yapılandırma farklarının eşlemelere açıkça başvurabilmesi için benzersiz kimlikler kullanın.`}},"hooks%2Emappings%5B%5D%2Ematch":{label:{"v1-rbsioh-i":`Kanca Eşleme Eşleşmesi`},help:{"v1-6u73k2-5a":`Eylem yönlendirmesi uygulanmadan önce yol ve kaynak gibi eşleme eşleşme koşullarını gruplandıran nesne. İlgisiz webhook trafiğinin otomasyonları tetiklememesi için eşleşme ölçütlerini dar kapsamlı tutun.`}},"hooks%2Emappings%5B%5D%2Ematch%2Epath":{label:{"v1-mc6fc4-n":`Kanca Eşleme Eşleşme Yolu`},help:{"v1-1d7dc5j-4k":`Bir kanca eşlemesi için genellikle gelen isteğin yoluyla karşılaştırılan yol eşleşme koşulu. Otomasyon davranışını webhook uç noktası yol gruplarına göre ayırmak için bunu kullanın.`}},"hooks%2Emappings%5B%5D%2Ematch%2Esource":{label:{"v1-1mx72t2-p":`Kanca Eşleme Eşleşme Kaynağı`},help:{"v1-177zgy7-52":`Bir kanca eşlemesi için genellikle güvenilir üst kaynak meta verileri veya bağdaştırıcı mantığı tarafından belirlenen kaynak eşleşme koşulu. Yeniden denemeler boyunca yönlendirmenin deterministik kalması için sabit kaynak tanımlayıcıları kullanın.`}},"hooks%2Emappings%5B%5D%2EmessageTemplate":{label:{"v1-1h1bgln-t":`Kanca Eşleme Mesaj Şablonu`},help:{"v1-ggqszl-5c":`Yapılandırılmış eşleme girdisini, hedef eylem yoluna gönderilen nihai mesaj içeriğine dönüştürmek için kullanılan şablon. Sonraki aşamalardaki ayrıştırma ve davranışın tutarlı kalması için şablonları deterministik tutun.`}},"hooks%2Emappings%5B%5D%2Emodel":{label:{"v1-17bx393-r":`Kanca Eşleme Modelini Geçersiz Kılma`},help:{"v1-10qyo4j-5e":`Otomasyonun aracı varsayılanlarından farklı bir model kullanması gerektiğinde, eşlemenin tetiklediği çalıştırmalar için isteğe bağlı model geçersiz kılma ayarı. Eşleme çalıştırmalarında davranışın öngörülebilir kalması için bu ayarı sınırlı kullanın.`}},"hooks%2Emappings%5B%5D%2Ename":{label:{"v1-gos70z-h":`Kanca Eşleme Adı`},help:{"v1-zrd9tn-4v":`Tanılama araçlarında ve operatörlere yönelik yapılandırma arayüzlerinde kullanılan, okunabilir eşleme görünen adı. Olay incelemesi sırasında yönlendirme amacının açık olması için adları kısa ve açıklayıcı tutun.`}},"hooks%2Emappings%5B%5D%2EsessionKey":{label:{"v1-1g7byfn-o":`Kanca Eşleme Oturum Anahtarı`},help:{"v1-lfnt1n-58":`Konuşma sürekliliğini denetlemek için eşleme yoluyla iletilen mesajlarda kullanılan açık oturum anahtarı geçersiz kılma ayarı. Tekrarlanan olayların ilgisiz konuşmalara karışmadan ilişkilendirilmesi için kapsamı belirli, sabit anahtarlar kullanın.`}},"hooks%2Emappings%5B%5D%2EsessionMode":{label:{"v1-p4nrxz-p":`Kanca Eşleme Oturum Modu`},help:{"v1-1ggtdze-5k":`Eşleme oturumunun sürekliliğini denetler: "isolated" yeni bir çalıştırma oturumu başlatırken "persistent" çözümlenen sessionKey değerini yeniden kullanır. Entegrasyon özellikle kalıcı bağlam gerektirmiyorsa isolated değerini koruyun.`}},"hooks%2Emappings%5B%5D%2EtextTemplate":{label:{"v1-1jch0ob-q":`Kanca Eşleme Metin Şablonu`},help:{"v1-1rg732b-4y":`Zengin veri içeriğinin görüntülenmesi istenmediğinde veya desteklenmediğinde kullanılan, yalnızca metin içeren yedek şablon. Sohbet iletim arayüzlerinde kısa ve tutarlı bir özet metni sunmak için bunu kullanın.`}},"hooks%2Emappings%5B%5D%2Ethinking":{label:{"v1-omlp34-u":`Kanca Eşleme Düşünme Geçersiz Kılma Ayarı`},help:{"v1-17hq8me-57":`Eşleme tarafından tetiklenen çalıştırmalarda gecikme ile akıl yürütme derinliği arasındaki dengeyi ayarlamak için isteğe bağlı düşünme çabası geçersiz kılma ayarı. Daha derin akıl yürütme açıkça gerekli olmadıkça yüksek hacimli kancalar için düşük veya en düşük düzeyde tutun.`}},"hooks%2Emappings%5B%5D%2EtimeoutSeconds":{label:{"v1-9tp4s7-q":`Kanca Eşlemesi Zaman Aşımı (sn)`},help:{"v1-1r44ox2-4i":`Zaman aşımı işlemleri uygulanmadan önce eşleme eyleminin yürütülmesi için izin verilen azami süre. Kuyrukta birikmeyi önlemek için yüksek hacimli webhook kaynaklarında daha sıkı sınırlar kullanın.`}},"hooks%2Emappings%5B%5D%2Eto":{label:{"v1-hpcs3s-x":`Kanca Eşlemesi İletim Hedefi`},help:{"v1-1p7928e-55":`Eşleme yanıtlarının sabit bir hedefe yönlendirilmesi gerektiğinde kullanılacak, seçili kanal içindeki hedef tanımlayıcısı. Üretim ortamı eşlemelerini etkinleştirmeden önce sağlayıcıya özgü hedef biçimlerini doğrulayın.`}},"hooks%2Emappings%5B%5D%2Etransform":{label:{"v1-yiku9o-m":`Kanca Eşlemesi Dönüşümü`},help:{"v1-14igxpm-5m":`Eşleme eylemi işlenmeden önce modül/dışa aktarım ön işlemesini tanımlayan dönüşüm yapılandırma bloğu. Yalnızca incelenmiş kod yollarındaki dönüşümleri kullanın ve tekrarlanabilir otomasyon için davranışı deterministik tutun.`}},"hooks%2Emappings%5B%5D%2Etransform%2Eexport":{label:{"v1-10vpr1c-l":`Kanca Dönüşümü Dışa Aktarımı`},help:{"v1-atn8v-4b":`Dönüşüm modülünden çağrılacak adlandırılmış dışa aktarım; belirtilmezse modülün varsayılan dışa aktarımı kullanılır. Tek bir dosya birden fazla dönüşüm işleyicisi barındırıyorsa bunu ayarlayın.`}},"hooks%2Emappings%5B%5D%2Etransform%2Emodule":{label:{"v1-qukz8e-l":`Kanca Dönüşümü Modülü`},help:{"v1-56futq-4v":`Gelen yükleri teslimden önce yeniden düzenlemek için hooks.transformsDir dizininden yüklenen dönüştürme modülünün göreli yolu. Modülleri yerel tutun, incelemeden geçirin ve dizin dışına çıkmaya olanak tanıyan yol kalıpları içermediklerinden emin olun.`}},"hooks%2Emappings%5B%5D%2EwakeMode":{label:{"v1-vk3gk3-m":`Kanca Eşlemesi Uyandırma Modu`},help:{"v1-1dzqfnw-59":`Uyandırma zamanlama modu: "now" hemen uyandırır, "next-heartbeat" ise bir sonraki kalp atışı döngüsüne kadar erteler. Kısa bir gecikmeyi tolere edebilen düşük öncelikli otomasyonlar için ertelenmiş modu kullanın.`}},"hooks%2Epath":{label:{"v1-1uhbsf3-j":`Kanca Uç Noktası Yolu`},help:{"v1-1l9ijzv-4u":"Gateway kontrol sunucusundaki kanca uç noktasının kullandığı HTTP yolu (örneğin `/hooks`). Katmanlı savunma için tahmin edilemeyen bir yol kullanın ve bunu belirteç doğrulamasıyla birleştirin."}},"hooks%2Epresets":{label:{"v1-4shxcz-d":`Kanca Ön Ayarları`},help:{"v1-dp8m0l-4v":`Standart eşlemeleri ve varsayılan davranışları oluşturmak için yükleme sırasında uygulanan adlandırılmış kanca ön ayarı paketleri. Operatörlerin hangi otomasyonların etkin olduğunu denetleyebilmesi için ön ayar kullanımını açıkça belirtin.`}},"hooks%2Etoken":{label:{"v1-1uqdexy-g":`Kanca Kimlik Doğrulama Belirteci`},help:{"v1-1ihf6mv-82":`Eşlemeler çalıştırılmadan önce istek kimlik doğrulaması için kanca girişinde kontrol edilen paylaşılan taşıyıcı belirteci. Belirteç sahiplerini, sahip olmayan ayrı bir rol olarak değil, kanca giriş arayüzü için tam güvenilen çağıranlar olarak değerlendirin. Webhook uç noktaları internetten erişilebilir olduğunda ortam değişkeni ikamesi kullanın ve belirteci düzenli olarak yenileyin.`}},"hooks%2EtransformsDir":{label:{"v1-1sc7ulb-q":`Kanca Dönüştürmeleri Dizini`},help:{"v1-1ayj9p0-4t":`Eşlemelerdeki transform.module yollarının başvurduğu kanca dönüştürme modüllerinin temel dizini. Dinamik içe aktarımların incelenebilir ve öngörülebilir kalması için denetim altında tutulan bir kod deposu dizini kullanın.`}},logging:{label:{"v1-rq08xq-7":`Günlük Kaydı`},help:{"v1-11an9pb-5e":`Önem derecesi, çıktı hedefleri, biçimlendirme ve hassas verilerin maskelenmesi için günlük kaydı denetimleri. Yararlı tanılama bilgilerini korurken düzeyleri ve maskeleme kurallarını üretim ortamı için yeterince sıkı tutun.`}},"logging%2Eaudit":{label:{"v1-7v96zt-c":`Denetim Defteri`},help:{"v1-1lauvy2-6w":`Operatör incelemesi için yalnızca meta verilerden oluşan sınırlı denetim geçmişi. Çalıştırma ve araç kayıtları varsayılan olarak etkindir; mesaj yaşam döngüsü meta verileri ise gizlilik açısından hassastır ve ayrıca açıkça etkinleştirilmelidir. Arka planda yazma işlemi mümkün olduğunca gerçekleştirilir; kayıpsız bir uyumluluk arşivi garantisi sunmaz.`}},"logging%2Eaudit%2Eenabled":{label:{"v1-pxk7dc-k":`Denetim Defteri Etkin`},help:{"v1-snknxb-4v":`Yeni çalıştırma, araç ve etkinleştirilmiş mesaj denetim olaylarını kaydeder. Varsayılan: true. Değişiklikler hemen uygulanır; kabul edilen yazma işlemleri tamamlanır ve saklanan satırlar, süreleri dolana kadar sorgulanabilir durumda kalır.`}},"logging%2Eaudit%2EexecutionIdentity":{label:{"v1-163ujga-o":`Yürütme Kimliği Denetimi`},help:{"v1-1ucirwv-5b":`Belirli bir çalıştırmanın incelenebilmesi için sınırlı yürütme kimliği ilişkilendirme bilgilerini saklar. Varsayılan: false. logging.audit.enabled gerektirir ve yeni kabul edilen çalıştırmalara uygulanır; mevcut bağlamlar değişmez.`}},"logging%2Eaudit%2Emessages":{label:{"v1-1bguzvj-j":`Mesaj Denetimi Kapsamı`},help:{"v1-1yg4lc3-76":`İçerik barındırmayan mesaj yaşam döngüsü kayıtlarını kontrol eder: "off" (varsayılan), yalnızca bilinen doğrudan konuşmalar için "direct" veya doğrudan, grup, kanal ve bilinmeyen konuşma türleri için "all". logging.audit.enabled gerektirir. Değişiklikler sonraki yaşam döngüsü olaylarına uygulanır.`}},"logging%2EconsoleLevel":{label:{"v1-1mambfm-h":`Konsol Günlük Düzeyi`},help:{"v1-16badbd-5u":`Terminal çıktısını kontrol etmek için konsola özel günlük eşiği: "silent", "fatal", "error", "warn", "info", "debug" veya "trace". Gerektiğinde dosyalarda daha ayrıntılı günlük kaydı tutarken yerel konsol çıktısını azaltmak için bunu kullanın.`}},"logging%2EconsoleStyle":{label:{"v1-1buy3td-h":`Konsol Günlüğü Biçimi`},help:{"v1-d7u0iq-3q":`Konsol çıktısı biçimi: "pretty" veya "json". Makine tarafından ayrıştırılan işlem hatları için json, insan odaklı terminal iş akışları için pretty kullanın.`}},"logging%2Efile":{label:{"v1-1o25uj4-d":`Günlük Dosyası Yolu`},help:{"v1-16gaitv-4w":`Konsol günlüğüne ek olarak veya onun yerine kalıcı günlük çıktısı için isteğe bağlı dosya yolu. Yönetilen, yazılabilir bir yol kullanın ve saklama/döndürme ayarlarını operasyonel politikanızla uyumlu tutun.`}},"logging%2Elevel":{label:{"v1-1vskr8z-9":`Günlük Düzeyi`},help:{"v1-1r5yku0-5o":`Çalışma zamanı günlükleyici çıktısı için birincil günlük düzeyi eşiği: "silent", "fatal", "error", "warn", "info", "debug" veya "trace". Üretim ortamında "info" veya "warn" kullanın; debug/trace düzeylerini yalnızca inceleme sırasında kullanın.`}},"logging%2EredactPatterns":{label:{"v1-17ykioa-p":`Özel Maskeleme Kalıpları`},help:{"v1-1esa6eg-7k":`Özel regex dizeleri, günlük/transkript çıktısı için varsayılan dize listesinin yerini alır ve güvenlik sınırlarına ilişkin kullanıcı arayüzü/araç/tanılama kurallarına eklenir. Yerleşik form gövdesi, yapılandırılmış kimlik doğrulama ve AWS yalın anahtar korumaları her zaman uygulanır. Dağıtıma özgü belirteçleri ve tanımlayıcıları maskelemek için bunu kullanın.`}},mcp:{label:{"v1-4jhiv7-3":`MCP`},help:{"v1-cyzwkt-51":`OpenClaw tarafından yönetilen genel MCP sunucu tanımları. Gömülü OpenClaw ve diğer çalışma zamanı bağdaştırıcıları, bu sunucuları çalışma zamanına ait proje ayarlarında saklamadan kullanabilir.`}},"mcp%2Eapps":{label:{"v1-1p7rgdd-8":`MCP Uygulamaları`},help:{"v1-amyd91-38":`MCP Apps arayüz desteği. Etkinleştirildiğinde, yapılandırılmış MCP sunucuları araç sonuçları için etkileşimli HTML görünümleri sağlayabilir.`}},"mcp%2Eapps%2Eenabled":{label:{"v1-15iqtvs-g":`MCP Apps Etkin`},help:{"v1-ghqy98-3w":`İsteğe bağlı MCP Apps görüntüleme ve uygulama-sunucu köprüsü. Uygulama arayüzü kaynakları sağlayan yapılandırılmış MCP sunucularına güvenmiyorsanız devre dışı bırakın.`}},"mcp%2Eapps%2EsandboxOrigin":{label:{"v1-es3gf8-n":`MCP Apps Yalıtılmış Ortam Kaynağı`},help:{"v1-1sxv3mf-6v":`MCP Apps için isteğe bağlı, özel ve herkese açık HTTP(S) kaynağı. Bunu bir ters proxy veya TLS sonlandırıcısının arkasında kullanın ve trafiğini yalnızca yapılandırılmış MCP Apps yalıtılmış ortam bağlantı noktasına yönlendirin. Control UI kaynağından farklı olmalı ve kimlik doğrulaması gerektiren içerik sunmamalıdır.`}},"mcp%2Eapps%2EsandboxPort":{label:{"v1-15qo425-l":`MCP Apps Yalıtılmış Ortam Bağlantı Noktası`},help:{"v1-1b8n71l-4p":`MCP Apps yalıtılmış ortamına özel dinleyici bağlantı noktası. Varsayılan olarak Gateway bağlantı noktası numarasının bir fazlasıdır. Başka bir yerel hizmet veya Gateway profili bu bağlantı noktasını zaten kullanıyorsa kullanılmayan bir bağlantı noktası belirleyin.`}},"mcp%2Eservers":{label:{"v1-1mnexav-b":`MCP Sunucuları`},help:{"v1-157ozoz-42":`Adlandırılmış MCP sunucusu tanımları. OpenClaw bunları kendi yapılandırmasında saklar ve çalışma zamanı bağdaştırıcıları, yürütme sırasında hangi aktarım yöntemlerinin desteklendiğine karar verir.`}},"mcp%2Eservers%2E*%2Eauth":{label:{"v1-4i7ar4-f":`MCP Sunucusu Kimlik Doğrulaması`}},"mcp%2Eservers%2E*%2Eclient_cert":{label:{"v1-8xj19d-m":`MCP İstemci Sertifikası`}},"mcp%2Eservers%2E*%2Eclient_key":{label:{"v1-14y3g3x-e":`MCP İstemci Anahtarı`}},"mcp%2Eservers%2E*%2EclientCert":{label:{"v1-8xj19d-m":`MCP İstemci Sertifikası`}},"mcp%2Eservers%2E*%2EclientKey":{label:{"v1-14y3g3x-e":`MCP İstemci Anahtarı`}},"mcp%2Eservers%2E*%2Ecodex":{label:{"v1-1abejxp-k":`Codex MCP Yansıtması`},help:{"v1-slcmq1-6x":`Yalnızca Codex app-server iş parçacıkları için OpenClaw yansıtma meta verileri. ACP oturumlarını veya genel Codex çalıştırma altyapısı yapılandırmasını etkilemez. Sunucunun, Codex'in varsayılan MCP onay davranışıyla tüm Codex app-server ajanlarına sunulması için bu bloğu eklemeyin.`}},"mcp%2Eservers%2E*%2Ecodex%2Eagents":{label:{"v1-tu0z1y-g":`Codex MCP Ajanları`},help:{"v1-8q98n8-67":`Codex app-server iş parçacığı yapılandırmasında bu MCP sunucusunu alması gereken OpenClaw ajanlarının isteğe bağlı, boş olmayan kimlikleri. Boş, yalnızca boşluk içeren veya geçersiz listelerde erişim engellenir; belirtilmediğinde sunucu tüm Codex app-server ajanlarına yansıtılır.`}},"mcp%2Eservers%2E*%2Ecodex%2Edefault_tools_approval_mode":{label:{"v1-uwmd-n":`Codex MCP Araç Onayı`},help:{"v1-1xql0qr-3d":`Aynı sunucu bazlı MCP araç onay modunun Codex'e özgü yazımı. OpenClaw yapılandırmasında defaultToolsApprovalMode kullanmayı tercih edin.`}},"mcp%2Eservers%2E*%2Ecodex%2EdefaultToolsApprovalMode":{label:{"v1-uwmd-n":`Codex MCP Araç Onayı`},help:{"v1-y5vsqq-3s":`Bu sunucu için isteğe bağlı Codex MCP araç onay modu: "auto", "prompt" veya "approve". Yalnızca bilinçli olarak güvendiğiniz MCP sunucuları için kullanın.`}},"mcp%2Eservers%2E*%2EconnectionTimeoutMs":{label:{"v1-1ofxxy1-o":`MCP Bağlantı Zaman Aşımı (ms)`}},"mcp%2Eservers%2E*%2Eenabled":{label:{"v1-hkfmxj-i":`MCP Sunucusu Etkin`}},"mcp%2Eservers%2E*%2Eoauth":{label:{"v1-j06h60-9":`MCP OAuth`}},"mcp%2Eservers%2E*%2Eoauth%2EauthProfileId":{label:{"v1-1xxlhb-m":`MCP OAuth Kimlik Doğrulama Profili`},help:{"v1-fcrb4u-5z":`Geçerli bearer belirtecini bu uzak MCP sunucusuna aktarmak için kullanılan, yenilemeyi destekleyen kimlik doğrulama profili kimliği. Ayarlandığında OpenClaw, çalışma zamanında profili çözümler ve yeniler; yenileme verilerini alt bileşenlere iletmez.`}},"mcp%2Eservers%2E*%2Eoauth%2EclientMetadataUrl":{label:{"v1-1d7wndt-t":`MCP OAuth İstemci Meta Verileri URL'si`}},"mcp%2Eservers%2E*%2Eoauth%2Eidentity":{label:{"v1-1l48ph6-i":`MCP OAuth Kimliği`},help:{"v1-1ie6ys7-59":`Bu sunucu için OAuth kimlik bilgilerinin sahipliği. Operatör tarafından yönetilen kimlik bilgileri için bu alanı atlayın veya "shared" kullanın; kimliği doğrulanmış her gönderenin kendi hesabını bağlamasına izin vermek için "per-requester" kullanın.`}},"mcp%2Eservers%2E*%2Eoauth%2EredirectUrl":{label:{"v1-1yf3yu9-m":`MCP OAuth Yönlendirme URL'si`}},"mcp%2Eservers%2E*%2Eoauth%2Escope":{label:{"v1-xvnbwc-f":`MCP OAuth Kapsamı`}},"mcp%2Eservers%2E*%2ErequestTimeoutMs":{label:{"v1-7skvfk-o":`MCP İstek Zaman Aşımı (ms)`}},"mcp%2Eservers%2E*%2Essl_verify":{label:{"v1-16l2l8l-k":`MCP TLS Doğrulaması`}},"mcp%2Eservers%2E*%2EsslVerify":{label:{"v1-16l2l8l-k":`MCP TLS Doğrulaması`}},"mcp%2Eservers%2E*%2Esupports_parallel_tool_calls":{label:{"v1-14b32qt-n":`MCP Paralel Araç Çağrıları`}},"mcp%2Eservers%2E*%2EsupportsParallelToolCalls":{label:{"v1-14b32qt-n":`MCP Paralel Araç Çağrıları`}},"mcp%2Eservers%2E*%2EtoolFilter":{label:{"v1-m19ao9-i":`MCP Araç Seçimi`},help:{"v1-10poyzb-4v":`Sunucu bazında MCP araç seçimi. Yalnızca seçilen MCP araç adlarını kullanıma sunmak için include, seçilen MCP araç adlarını gizlemek için exclude kullanın. Girdiler, tam adları ve basit '*' joker karakter kalıplarını kabul eder.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Eexclude":{label:{"v1-bikffc-i":`Hariç Tutulan MCP Araçları`},help:{"v1-ijrc5y-1u":`Bu sunucudan gizlenecek MCP araçlarının tam adları veya basit '*' joker karakter kalıpları.`}},"mcp%2Eservers%2E*%2EtoolFilter%2Einclude":{label:{"v1-qa5hua-i":`Dahil Edilen MCP Araçları`},help:{"v1-89fdfq-3o":`Bu sunucudan kullanıma sunulacak MCP araçlarının tam adları veya basit '*' joker karakter kalıpları. Belirtilmediğinde, hariç tutulmadıkları sürece tüm sunucu araçları kullanılabilir durumda kalır.`}},"mcp%2EsessionIdleTtlMs":{label:{"v1-1teh0v2-p":`MCP Oturumu Boşta Kalma TTL Değeri (ms)`},help:{"v1-j9si74-87":`OpenClaw oturumlarının MCP çalışma zamanları için milisaniye cinsinden isteğe bağlı boşta kalma sonrası kaldırma süresi. Ayarlanmazsa veya 0 olarak ayarlanırsa çalışma zamanları, oturum temizlenene ya da Gateway kapatılana kadar etkin kalır. Pozitif değerler aşağı yuvarlanır; etkin kiralamalar ve bekleyen edinme istekleri kaldırmayı önler. Tek bir çalıştırmaya ait çalışma zamanları ise tek seferlik çalıştırmaları sona erdiğinde yine sonlandırılır.`}},memory:{label:{"v1-oopaku-6":`Bellek`},help:{"v1-1wlx40m-13":`Yerleşik bellek yapılandırması (genel).`}},"memory%2Ecitations":{label:{"v1-1cdo86v-l":`Bellek Kaynak Gösterimi Modu`},help:{"v1-1q6dxr5-4u":`Yanıtlarda kaynak gösteriminin görünürlüğünü kontrol eder: "auto" yararlı olduğunda kaynakları gösterir, "on" her zaman gösterir, "off" ise gizler. Bilgi ile gereksiz ayrıntı arasında dengeli bir varsayılan ayar için "auto" değerini koruyun.`}},"memory%2Esearch":{label:{"v1-dvkpxe-d":`Bellek Araması`},help:{"v1-1ukbud1-25":`MEMORY.md ve memory/*.md üzerinde vektör araması (ajan bazında ayarların geçersiz kılınması desteklenir).`}},"memory%2Esearch%2Ecache%2Eenabled":{label:{"v1-kv1t3d-t":`Bellek Araması Gömme Önbelleği`},help:{"v1-d8h2e4-5b":`Yeniden dizin oluşturma ve artımlı güncellemelerin daha hızlı çalışması için hesaplanan parça gömmelerini SQLite içinde önbelleğe alır (varsayılan: true). Önbellek doğruluğunu araştırmıyor veya disk kullanımını en aza indirmeye çalışmıyorsanız bu ayarı etkin tutun.`}},"memory%2Esearch%2EdocumentInputType":{label:{"v1-mmpk8t-x":`Bellek Araması Belge Girdi Türü`},help:{"v1-1ui33sv-5f":"Belge ve dizinleme amaçlı bellek vektörleri için sağlayıcıya özgü isteğe bağlı `input_type` değeri. Bunu, pasaj veya belge etiketi gerektiren OpenAI uyumlu asimetrik vektörleştirme uç noktalarıyla kullanın."}},"memory%2Esearch%2Eenabled":{label:{"v1-ed34tb-k":`Bellek Aramasını Etkinleştir`},help:{"v1-14f11b9-4t":`Bu ajan profilinde bellek aramasının dizinleme ve bilgi getirme davranışını yöneten ana anahtar. Anlamsal hatırlama için etkin tutun; tamamen durumsuz yanıtlar istediğinizde devre dışı bırakın.`}},"memory%2Esearch%2Eexperimental%2EsessionMemory":{label:{"v1-1jhaosz-16":`Bellek Araması Oturum Dizini (Deneysel)`},help:{"v1-qvhv8z-3i":`Oturum dökümlerini bellek araması için dizine ekler. Kök düzeyindeki ve ajan bazındaki hatırlama ayarlarının devralınması farklılık gösterdiğinde bu gelişmiş geçersiz kılma ayarını koruyun.`}},"memory%2Esearch%2EextraPaths":{label:{"v1-1ommwo8-i":`Ek Bellek Yolları`},help:{"v1-ojqokq-7i":`Varsayılan bellek dosyalarının yanı sıra ek dizinleri veya .md dosyalarını bellek dizinine ekler. Girdiler, yol dizeleri veya köke göreli bir glob deseni içeren nesneler olabilir. Çok modlu bellek etkinleştirildiğinde, bu yollar altındaki eşleşen görüntü/ses dosyaları da dizine eklenebilir.`}},"memory%2Esearch%2EextraPaths%2E*%2Epath":{label:{"v1-1htq423-h":`Ek Bellek Yolu`},help:{"v1-b9mbq8-3m":`Ek bellek dizinini veya dosyasını ayarlar. Göreli yollar, ajanın çalışma alanına göre çözümlenir; doğrudan belirtilen dosyalar aynen dizine eklenir.`}},"memory%2Esearch%2EextraPaths%2E*%2Epattern":{label:{"v1-eunp4t-p":`Ek Bellek Yolu Deseni`},help:{"v1-j8br1v-4e":`Bir dizin girdisini, köke göreli bu glob deseniyle eşleşen desteklenen dosyalarla sınırlar; örneğin "runbooks/**/*.md". Desteklenen tüm dosyaları alt dizinler dahil taramak için bu alanı boş bırakın.`}},"memory%2Esearch%2Efallback":{label:{"v1-nj3gc-m":`Bellek Araması Yedek Sağlayıcısı`},help:{"v1-1r6368w-6p":`Birincil gömme işlemleri başarısız olduğunda kullanılan yedek sağlayıcı: "openai", "gemini", "voyage", "mistral", "bedrock", "lmstudio", "ollama", "local" veya "none". Üretim ortamında güvenilirlik için gerçek bir yedek sağlayıcı ayarlayın; yalnızca hataların açıkça bildirilmesini tercih ediyorsanız "none" kullanın.`}},"memory%2Esearch%2EinputType":{label:{"v1-aslwem-o":`Bellek Araması Girdi Türü`},help:{"v1-26vbwe-5u":"Sağlayıcıya özgü bu isteğe bağlı `input_type` değerini yalnızca aynı etiketin hem sorgu hem de belge gömme isteklerine uygulanması gerektiğinde kullanın. Asimetrik sağlayıcılar için queryInputType ve documentInputType kullanmayı tercih edin."}},"memory%2Esearch%2Elocal%2EmodelPath":{label:{"v1-1jkif8j-q":`Yerel Gömme Modeli Yolu`},help:{"v1-13ymbnt-5q":"Yerel bellek araması için GGUF dosya yolu veya `hf:` URI'si gibi bir yerel gömme modeli kaynağı belirtir. Bunu yalnızca sağlayıcı `local` olduğunda kullanın ve büyük dizinleri yeniden oluşturmadan önce model uyumluluğunu doğrulayın."}},"memory%2Esearch%2Emodel":{label:{"v1-1sfre8j-j":`Bellek Araması Modeli`},help:{"v1-11pohrl-59":`Varsayılan dışında bir model gerektiğinde seçili bellek sağlayıcısının kullanacağı gömme modeli. Bunu yalnızca sağlayıcının varsayılan ayarlarının ötesinde, bilgiye erişim kalitesi ve maliyet için özel ayarlamaya ihtiyaç duyduğunuzda ayarlayın.`}},"memory%2Esearch%2Emultimodal":{label:{"v1-1lnhiq0-o":`Bellek Aramasında Çok Modluluk`},help:{"v1-1jn02s-9e":'Yapılandırılmış ek yollardaki görüntü ve ses dosyalarını dizine eklemek için isteğe bağlı çok modlu bellek ayarları. Gömme modeliniz modlar arası gömmeleri açıkça desteklemiyorsa bunu kapalı tutun ve etkin olduğunda `memory.search.fallback` değerini "none" olarak ayarlayın. Eşleşen dosyalar, dizine ekleme sırasında yapılandırılmış uzak gömme sağlayıcısına yüklenir.'}},"memory%2Esearch%2Emultimodal%2Eenabled":{label:{"v1-vp9cgj-v":`Bellek Aramasında Çok Modlu Desteği Etkinleştir`},help:{"v1-1dk5d7o-7e":`extraPaths içindeki görüntü ve ses dosyalarının bellekte dizine eklenmesini etkinleştirir. Bu özellik şu anda Gemini embedding-2 gerektirir, varsayılan bellek köklerini yalnızca Markdown ile sınırlar, bellek araması için yedek sağlayıcıları devre dışı bırakır ve eşleşen ikili içeriği yapılandırılmış uzak gömme sağlayıcısına yükler.`}},"memory%2Esearch%2Emultimodal%2EmaxFileBytes":{label:{"v1-ewn32n-13":`Çok Modlu Bellek Aramasında Dosya Başına En Fazla Bayt`},help:{"v1-1mmdrvk-5d":`Bellek dizinleme sırasında atlanmadan önce çok modlu bir dosya için izin verilen en yüksek bayt sayısını belirler. Yükleme maliyetini ve dizinleme gecikmesini sınırlamak için bu ayarı kullanın veya kısa, yüksek kaliteli ses klipleri için değeri artırın.`}},"memory%2Esearch%2Emultimodal%2Emodalities":{label:{"v1-ako4xr-z":`Çok Modlu Bellek Aramasının Veri Türleri`},help:{"v1-alp4vh-4l":`extraPaths içinden hangi çok modlu dosya türlerinin dizine ekleneceğini seçer: "image", "audio" veya "all". Büyük ikili veri koleksiyonlarının istemeden dizine eklenmesini önlemek için bu seçimi dar tutun.`}},"memory%2Esearch%2EoutputDimensionality":{label:{"v1-9cim9y-z":`Bellek Araması Çıktı Boyut Sayısı`},help:{"v1-1f7zu53-93":`Bellek gömmeleri için sağlayıcıya özgü çıktı vektörü boyutunu geçersiz kılar. Gemini modelleri 128-3072 boyutu destekler ve 768, 1536 veya 3072 boyutu önerir; Titan V2, Cohere V4 ve Nova gibi Bedrock model ailelerinin kendilerine özgü izin verilen boyutları vardır. Saklanan vektörlerin boyutları tutarlı kalmak zorunda olduğundan, bu değeri değiştirdiğinizde tam bir yeniden dizinleme yapılacağını göz önünde bulundurun.`}},"memory%2Esearch%2Eprovider":{label:{"v1-1i03ysj-m":`Bellek Araması Sağlayıcısı`},help:{"v1-5evseb-71":`Bellek vektörlerini oluşturmak ve sorgulamak için kullanılan gömme arka ucunu seçer. Varsayılan değer "openai" şeklindedir; farklı bir arka uç istediğinizde "openai-compatible", "gemini", "voyage", "mistral", "bedrock", "deepinfra", "github-copilot", "lmstudio", "ollama" veya "local" olarak ayarlayın.`}},"memory%2Esearch%2Equery%2EmaxResults":{label:{"v1-5g82o6-p":`Bellek Araması Maksimum Sonuç Sayısı`},help:{"v1-13ekath-4x":`Sonraki yeniden sıralama ve isteme ekleme işlemlerinden önce aramadan döndürülen maksimum bellek eşleşmesi sayısı. Daha kapsamlı hatırlama için artırın; daha kısa istemler ve daha hızlı yanıtlar için azaltın.`}},"memory%2Esearch%2Equery%2EminScore":{label:{"v1-1hsndok-n":`Bellek Araması Minimum Puanı`},help:{"v1-1ww231l-4v":`Bellek sonuçlarının nihai hatırlama çıktısına dahil edilmesi için gereken minimum alaka puanı eşiği. Zayıf veya alakasız eşleşmeleri azaltmak için artırın; daha esnek bir bilgi getirme işlemi gerektiğinde azaltın.`}},"memory%2Esearch%2EqueryInputType":{label:{"v1-ita7p2-u":`Bellek Araması Sorgu Girdi Türü`},help:{"v1-831yrv-4q":"Sorgu sırasında kullanılan bellek gömmeleri için sağlayıcıya özgü, isteğe bağlı `input_type` değeri. Bunu, sorgu etiketi gerektiren OpenAI uyumlu asimetrik gömme uç noktalarıyla kullanın."}},"memory%2Esearch%2ErememberAcrossConversations":{label:{"v1-1iqw2nv-t":`Konuşmalar Arasında Hatırla`},help:{"v1-k1itm8-7y":`Korumalı konuşma dökümü hatırlama yoluyla bu aracının diğer özel konuşmalarındaki ilgili bağlamı kullanın. Yalnızca genel session.dmScope ayarlanmamışsa veya "main" ise ve hiçbir bağlama DM kapsamını geçersiz kılmıyorsa varsayılan olarak açıktır; herhangi bir DM yalıtımı yapılandırıldığında varsayılan olarak kapanır. Açıkça belirtilen true veya false değeri her zaman önceliklidir.`}},"memory%2Esearch%2Eremote%2EapiKey":{label:{"v1-3ejsqh-o":`Uzak Gömme API Anahtarı`},help:{"v1-nfuuu-62":`Bellek indeksleme ve sorgu sırasında gömme oluşturma işlemlerinde kullanılan uzak gömme çağrıları için özel bir API anahtarı sağlar. Bellek gömmeleri için genel varsayılanlardan veya ortam değişkenlerinden farklı kimlik bilgileri kullanılması gerektiğinde bunu kullanın.`}},"memory%2Esearch%2Eremote%2EbaseUrl":{label:{"v1-pd1jie-p":`Uzak Gömme Temel URL'si`},help:{"v1-1ugvqgt-5p":`Gömme API uç noktasını, örneğin OpenAI uyumlu bir proxy veya özel bir Gemini temel URL'si ile geçersiz kılar. Bunu yalnızca kendi ağ geçidiniz veya sağlayıcı uç noktanız üzerinden yönlendirme yaparken kullanın; aksi takdirde sağlayıcının varsayılanlarını koruyun.`}},"memory%2Esearch%2Eremote%2Ebatch%2Eenabled":{label:{"v1-av398b-u":`Uzak Toplu Gömme Etkin`},help:{"v1-1fehqi-5x":`Desteklendiğinde (OpenAI/Gemini), gömme işleri için sağlayıcının toplu işlem API'lerini etkinleştirerek büyük indeksleme işlemlerinde verimi artırır. Sağlayıcının toplu işlem hatalarını ayıklamıyorsanız veya çok küçük iş yükleri çalıştırmıyorsanız bunu etkin tutun.`}},"memory%2Esearch%2Eremote%2Eheaders":{label:{"v1-13jt5eg-o":`Uzak Gömme Üst Bilgileri`},help:{"v1-1uic0kd-5i":`Uzak gömme isteklerine, sağlayıcının varsayılanlarıyla birleştirilen özel HTTP üst bilgileri ekler. Bunu proxy kimlik doğrulaması ve kiracı yönlendirme üst bilgileri için kullanın; hassas meta verilerin sızmasını önlemek için değerleri asgari düzeyde tutun.`}},"memory%2Esearch%2Esources":{label:{"v1-po677s-l":`Bellek Arama Kaynakları`},help:{"v1-btxtzg-57":`Hangi kaynakların indeksleneceğini seçer: "memory", MEMORY.md ve bellek dosyalarını okur; "sessions" ise konuşma dökümü geçmişini içerir. Önceki sohbet dökümlerinden bilgi getirmeye ihtiyacınız yoksa ["memory"] ayarını koruyun.`}},"memory%2Esearch%2Estore%2Evector%2Eenabled":{label:{"v1-17q1dz1-q":`Bellek Arama Vektör İndeksi`},help:{"v1-fbybkj-37":`sqlite-vec anlamsal dizinini kontrol eder. Kök düzeyindeki ve ajan bazındaki vektör ilkeleri farklı olduğunda bu gelişmiş geçersiz kılma ayarını koruyun.`}},"memory%2Esearch%2Estore%2Evector%2EextensionPath":{label:{"v1-1w275c7-z":`Bellek Araması Vektör Uzantısı Yolu`},help:{"v1-1hysv5q-58":"Otomatik olarak bulunan sqlite-vec uzantı kitaplığı yolunu (`.dylib`, `.so` veya `.dll`) geçersiz kılar. Çalışma ortamınız sqlite-vec'i otomatik olarak bulamıyorsa veya çalıştığı doğrulanmış bir derlemeyi sabitlemek istiyorsanız bunu kullanın."}},messages:{label:{"v1-1wwzqad-8":`Mesajlar`},help:{"v1-i5k0iw-5k":`Mesaj altyapısı ve ajanlar arası varsayılan ayarlar. Kök düzeyindeki eş öğeler altyapıyı ve ajanlar arası varsayılan ayarları yönetir; agents.defaults ajan döngüsü davranışını yönetir; ajan girdileri, desteklendiği durumlarda her ikisini de geçersiz kılabilir.`}},"messages%2EackReaction":{label:{"v1-qhntnj-i":`Alındı Tepkisi Emojisi`},help:{"v1-1iip0zs-1x":`Gelen mesajların alındığını bildirmek için kullanılan emoji tepkisi (boş bırakılırsa devre dışı kalır).`}},"messages%2EackReactionScope":{label:{"v1-7m6k7l-i":`Alındı Tepkisi Kapsamı`},help:{"v1-1jvdg5n-7s":`Alındı tepkilerinin ne zaman gönderileceğini belirler ("group-mentions", "group-all", "direct", "all", "off", "none"). "group-mentions", grupta bahsetme zorunlu olsun veya olmasın, ajandan bahseden grup mesajlarına alındı tepkisi verir; "group-all" her grup mesajına alındı tepkisi verir. "off"/"none", alındı tepkilerini tamamen devre dışı bırakır.`}},"messages%2EgroupChat":{label:{"v1-aqzwi1-g":`Grup Sohbeti Kuralları`},help:{"v1-chqsvh-4l":`Bahsetme tetikleyicileri ve geçmiş penceresi boyutlandırması dahil grup mesajı işleme denetimleri. Grup kanallarında her mesajın tetikleme yapmaması için bahsetme kalıplarını dar kapsamlı tutun.`}},"messages%2EgroupChat%2EhistoryLimit":{label:{"v1-i0bob3-j":`Grup Geçmişi Sınırı`},help:{"v1-1mkbpw-9k":`Grup oturumlarında her turda bağlam olarak yüklenen önceki grup mesajlarının en fazla sayısı. Daha kapsamlı bir devamlılık için daha yüksek, daha hızlı ve daha düşük maliyetli yanıtlar için daha düşük değerler kullanın. Otomatik istem geçmişi 200 mesajla sınırlıdır. JSON tamsayı türünün en yüksek değeri, sınırsız bir pencere yerine kanalın varsayılan penceresini (paylaşılan grup geçmişi için 50) seçer.`}},"messages%2EgroupChat%2EmentionPatterns":{label:{"v1-1367gbd-m":`Grupta Bahsetme Kalıpları`},help:{"v1-i7h7qc-6f":`Grup sohbetlerinde açık bahsetmeleri/tetikleyici ifadeleri algılamak için kullanılan, büyük/küçük harfe duyarsız güvenli düzenli ifade kalıpları. Yoğun kanallarda yanlış pozitifleri azaltmak için kesin kalıplar kullanın; geçersiz veya güvenli olmayan iç içe tekrar kalıpları yok sayılır.`}},"messages%2EgroupChat%2EunmentionedInbound":{label:{"v1-1hc12l7-p":`Grupta Bahsetme İçermeyen Gelen Mesajlar`},help:{"v1-17wef8h-5f":`Sürekli etkin grup sohbetlerinde bahsetme içermeyen mesajların nasıl iletileceğini kontrol eder. "user_request" bunları kullanıcı isteği olarak ele alır; "room_event" ise görünür çıktı için mesaj aracının kullanılmasını gerektiren sessiz bağlam olarak iletir.`}},"messages%2EgroupChat%2EvisibleReplies":{label:{"v1-1hqf9qu-l":`Grupta Görünür Yanıtlar`},help:{"v1-qa4z1s-aa":`Grup/kanal sohbetleri için model tarafından oluşturulan kaynak yanıtları geçersiz kılar. Genel bir görünür yanıt politikası ayarlanmamışsa varsayılan değer "automatic" olur. "message_tool", normal asistan çıktısı ve genel araç medyası için message(action=send) kullanımını gerektirir; açıkça ana sisteme ait çalışma zamanı çıktıları, arka plandaki oda olayları dışında iletilebilir olmaya devam eder. "automatic", normal yanıtları eskisi gibi gönderir.`}},"messages%2Einbound":{label:{"v1-10n88z1-g":`Gelen Mesajları Birleştirme Gecikmesi`},help:{"v1-ebyu5x-4a":`Kuyruk/tur işleme başlamadan önce kullanılan doğrudan gelen mesajları birleştirme gecikmesi ayarları. Aynı göndericiden art arda hızla gelen mesajlar için bunu sağlayıcıya özel olarak yapılandırın.`}},"messages%2Einbound%2EbyChannel":{label:{"v1-bsp0no-w":`Kanala Göre Gelen Mesajları Birleştirme Gecikmesi (ms)`},help:{"v1-wbz54j-4g":`Sağlayıcı kimliğine göre anahtarlanmış, kanal bazında gelen ileti birleştirme bekleme süresi geçersiz kılmaları (milisaniye). Bazı sağlayıcılar diğerlerinden daha sık ileti parçaları gönderdiğinde bunu kullanın.`}},"messages%2Einbound%2EdebounceMs":{label:{"v1-1dqihif-t":`Gelen İleti Birleştirme Bekleme Süresi (ms)`},help:{"v1-1616yo2-7w":`Aynı göndericiden art arda hızla gelen mesajları toplu işlemek için sessizlik süresi (ms). Genel düzeyde veya kanal düzeyinde bir geçersiz kılma ayarı yapılmadığında Telegram için varsayılan değer 300 ms, diğer kanallar için 0'dır. Sıfır, normal mesaj serilerinin toplu işlenmesini devre dışı bırakır; ancak Telegram, uzun mesajların sınıra yakın boyuttaki parçalarını yine de birleştirir.`}},"messages%2Equeue":{label:{"v1-yvcqg5-d":`Gelen İleti Kuyruğu`},help:{"v1-hm2o31-48":`Bir oturum çalışması etkinken gelen iletiler için kuyruk stratejisi. Yönlendirmeyi, ertelenmiş takip iletilerini, toplu işlemeyi veya kesintiyi ayarlamak için bunu kullanın.`}},"messages%2Equeue%2EbyChannel":{label:{"v1-15qfdgr-l":`Kanala Göre Kuyruk Modu`},help:{"v1-4rf8z8-54":`Sağlayıcı kimliğine göre anahtarlanmış, kanal bazında kuyruk modu geçersiz kılmaları (örneğin telegram, discord, slack). Bir kanalın trafik düzeni genel varsayılanlardan farklı bir davranış gerektirdiğinde bunu kullanın.`}},"messages%2Equeue%2Ecap":{label:{"v1-1dxqjbg-e":`Kuyruk Kapasitesi`},help:{"v1-16ql8c7-4j":`Kuyruktan çıkarma ilkesi uygulanmadan önce kuyrukta tutulan maksimum gelen öğe sayısı. Varsayılan değer 20'dir; bellek kullanımının öngörülebilir kalması için yoğun kanallarda kapasiteyi sınırlı tutun.`}},"messages%2Equeue%2EdebounceMsByChannel":{label:{"v1-yp9b0s-13":`Kanala Göre Yedek Kuyruk Birleştirme Bekleme Süresi (ms)`},help:{"v1-4tpyt7-4e":`Sağlayıcı kimliğine göre anahtarlanmış, kuyruk davranışı için kanal bazında birleştirme bekleme süresi geçersiz kılmaları. Farklı ileti hızlarına sahip sohbet arayüzlerinde ani ileti yoğunluğunun işlenmesini bağımsız olarak ayarlamak için bunu kullanın.`}},"messages%2Equeue%2Edrop":{label:{"v1-ywb1ky-j":`Kuyruktan Çıkarma Stratejisi`},help:{"v1-ydb2rw-6m":`Kuyruk sınırı aşıldığında uygulanacak eleme stratejisi. "summarize" en eski girdileri kaldırır ancak kısa özetlerini korur; "old" en eskileri özet olmadan kaldırır; "new" en yeni öğeyi reddeder. Bağlamın önemli olduğu uzun süreli sohbetlerde "summarize" kullanın.`}},"messages%2Equeue%2Emode":{label:{"v1-x1nejf-a":`Kuyruk Modu`},help:{"v1-19k7gy1-67":`Etkin çalıştırmalar için kuyruk modu. İstemleri etkin çalıştırmaya eklemek için "steer", daha sonra çalıştırmak için "followup", uyumlu mesajları daha sonra toplu olarak işlemek için "collect" veya en yeni istemi başlatmadan önce etkin çalıştırmayı iptal etmek için "interrupt" kullanın.`}},"messages%2EresponsePrefix":{label:{"v1-1cwunbc-o":`Giden Yanıt Ön Eki`}},"messages%2EresponseUsage":{label:{"v1-nh6iuv-p":`Varsayılan Kullanım Alt Bilgisi Modu`},help:{"v1-l3shsx-dv":`/usage aracılığıyla bir mod seçmemiş oturumlara uygulanan, yanıt başına varsayılan kullanım alt bilgisi modu ("off"|"tokens"|"full"). "tokens" için eski bir takma ad olan "on" değerini de kabul eder. Tek başına bir mod veya "default" yedek değerini içeren kanal bazlı bir eşleme kabul eder. Öncelik sırası: oturum değeri -> kanal girdisi -> default -> off; açıkça yapılan bir /usage seçimi (off dahil) kalıcı olarak kaydedilir ve varsayılanı geçersiz kılar. Oturuma özel ayarı temizlemek ve yapılandırılmış bu varsayılanı yeniden devralmak için /usage reset (takma adlar: inherit, clear, default) kullanın.`}},"messages%2EstatusReactions":{label:{"v1-17ysjar-g":`Durum Tepkileri`},help:{"v1-193764l-3s":`Ajan ilerledikçe tetikleyici mesajdaki emojiyi güncelleyen yaşam döngüsü durum tepkileri (kuyrukta → düşünüyor → araç → tamamlandı/hata).`}},"messages%2EstatusReactions%2Eenabled":{label:{"v1-rqjrr0-n":`Durum Tepkilerini Etkinleştir`},help:{"v1-1qnmmnc-7x":`Desteklenen kanallarda yaşam döngüsü durum tepkilerini etkinleştirir. Discord, alındı tepkileri etkinken ayarlanmamış değeri etkin olarak kabul eder; Slack, Signal, Telegram ve WhatsApp, yaşam döngüsü tepkilerini kullanmadan önce bu değerin true olmasını gerektirir. Slack, ilerlemeyi göstermek için varsayılan olarak yerel asistan ileti dizisi durumunu kullanır.`}},"messages%2EusageTemplate":{label:{"v1-1pj1fhz-l":`Kullanım Alt Bilgisi Şablonu`},help:{"v1-1xibc23-47":`Satır içi bir nesne veya JSON dosyası yolu olarak belirtilen özel /usage full alt bilgi şablonu. Şablon geçersizse veya kullanılamıyorsa yerleşik kullanım satırı kullanılır.`}},"messages%2EvisibleReplies":{label:{"v1-awhafd-f":`Görünür Yanıtlar`},help:{"v1-7yfwc2-8t":`Doğrudan, grup ve kanal konuşmalarında model tarafından oluşturulan kaynak yanıtlarını kontrol eder. "message_tool", normal asistan çıktısı ve genel araç medyası için message(action=send) kullanılmasını gerektirir; açıkça ana sisteme ait olan çalışma zamanı çıktısı, arka plandaki oda olayları dışında iletilmeye devam eder. "automatic", normal yanıtları eskisi gibi gönderir.`}},meta:{label:{"v1-1xpfxac-m":`Uyumluluk Meta Verileri`},help:{"v1-1owqhgn-2w":`Eski ikili dosyaların güvenli olmayan yapılandırma sürümü düşürmelerini reddedebilmesi için saklanan, eski sürümlerce okunabilen uyumluluk meta verileri.`}},"meta%2ElastTouchedVersion":{label:{"v1-m6hgn7-r":`Yapılandırmayı Son Değiştiren Sürüm`},help:{"v1-qykpv1-1i":`Bu yapılandırmayı en son yazan OpenClaw sürümü.`}},"meta%2Emigrations":{label:{"v1-1yu19k0-o":`Yapılandırma Geçişi İşaretleri`},help:{"v1-burt8q-1q":`Tamamlanan yapılandırma geçişleri için sınırlı uyumluluk işaretleri.`}},"meta%2Emigrations%2EmodelPolicyAllowlist":{label:{"v1-1yjkbc1-w":`Model Politikası İzin Listesi Geçişi`},help:{"v1-5psop1-1z":`Eski model eşlemesi kısıtlamalarının korunduğunu veya değerlendirildiğini kaydeder.`}},"meta%2Emigrations%2EutilityModelSeparation":{label:{"v1-qvzwo6-y":`Yardımcı Model Ayrımı Geçişi`},help:{"v1-vzdfqx-2t":`Yardımcı model seçimi ayrılmadan önce eski örtük birincil modellerin korunduğunu kaydeder.`}},models:{label:{"v1-hzmwb-6":`Modeller`},help:{"v1-1h1niol-5q":`Sağlayıcı tanımları, birleştirme/değiştirme davranışı ve isteğe bağlı Bedrock keşif entegrasyonu için model kataloğunun kök yapılandırması. Üretim ortamındaki yük devretme yollarına güvenmeden önce sağlayıcı tanımlarının açıkça belirtilmiş ve doğrulanmış olduğundan emin olun.`}},"models%2EcatalogRefresh":{label:{"v1-1v6rbia-l":`Model Kataloğunu Yenileme`},help:{"v1-1hess4t-40":`Birlikte sunulan model kataloğunun arka planda güncellenmesini kontrol eder. Uzak kayıtlar model meta verilerini güncelleyebilir ancak sağlayıcı uç noktalarını veya üst bilgilerini değiştiremez.`}},"models%2EcatalogRefresh%2Eenabled":{label:{"v1-1a5yfw3-t":`Model Kataloğunu Yenileme Etkin`},help:{"v1-1fogpjj-3j":`Barındırılan model kataloğunun güncellemelerini arka planda getirir (varsayılan: true). Tüm uzak model kataloğu trafiğini devre dışı bırakmak için false olarak ayarlayın.`}},"models%2EcatalogRefresh%2Eurl":{label:{"v1-1piibdj-p":`Model Kataloğunu Yenileme URL'si`},help:{"v1-e02ai2-44":`Barındırılan model kataloğunun URL'sini, kendi barındırdığınız bir HTTPS aynasının URL'siyle değiştirin (test için localhost üzerinde HTTP kullanımına izin verilir). Değişiklikler Gateway yeniden başlatıldıktan sonra uygulanır.`}},"models%2Emode":{label:{"v1-wl6vg8-i":`Model Kataloğu Modu`},help:{"v1-1ofrnsp-es":`Sağlayıcı kataloğunun davranışını kontrol eder: "merge", yerleşik sağlayıcıları korur ve özel sağlayıcılarınızı bunların üzerine uygular; "replace" ise yalnızca yapılandırdığınız sağlayıcıları kullanır. "merge" modunda, eşleşen sağlayıcı kimlikleri ajanın models.json dosyasındaki boş olmayan baseUrl değerlerini korurken apiKey değerleri yalnızca sağlayıcı geçerli yapılandırma/kimlik doğrulama profili bağlamında SecretRef ile yönetilmiyorsa korunur; SecretRef ile yönetilen sağlayıcılar apiKey değerini geçerli kaynak işaretçilerinden yeniler ve eşleşen modellerin contextWindow/maxTokens değerleri için açıkça belirtilen ve örtük kayıtlar arasındaki daha yüksek değer kullanılır.`}},"models%2Eproviders":{label:{"v1-1y3b8o-f":`Model Sağlayıcıları`},help:{"v1-1y5jg0v-8p":`Sağlayıcı kimliğine göre anahtarlanmış, bağlantı/kimlik doğrulama ayarlarını ve somut model tanımlarını içeren sağlayıcı eşlemesi. Yerleşik sağlayıcılar, sağlayıcı düzeyindeki geçersiz kılma ayarlarıyla özelleştirilebilir; özel sağlayıcılar baseUrl ve models içermelidir. Ajanlardan ve araçlardan yapılan başvuruların ortamlar arasında taşınabilir kalması için sabit sağlayıcı anahtarları kullanın.`}},"models%2Eproviders%2E*%2EagentRuntime":{label:{"v1-3c30on-m":`Model Sağlayıcısı Çalışma Zamanı`},help:{"v1-1luy4fb-5o":`Bu sağlayıcı için isteğe bağlı, alt düzey ajan çalışma zamanı ilkesi. Ajan genelinde çalışma zamanını sabitlemek yerine sağlayıcı/model çalışma zamanı ilkesini kullanın; belirtilmediğinde veya varsayılan değer kullanıldığında OpenClaw, seçilen sağlayıcının çalışma zamanını seçer.`}},"models%2Eproviders%2E*%2EagentRuntime%2Eid":{label:{"v1-1myzd5c-p":`Model Sağlayıcısı Çalışma Zamanı Kimliği`},help:{"v1-1gusd9s-69":`Sağlayıcı ajanının çalışma zamanı kimliği: "openclaw", "auto", "codex" gibi kayıtlı bir eklenti yürütme altyapısı kimliği veya "claude-cli" gibi desteklenen bir CLI arka uç takma adı. Belirtilmediğinde, resmi uç noktadaki OpenAI varsayılan olarak Codex yürütme altyapısını kullanır.`}},"models%2Eproviders%2E*%2Eapi":{label:{"v1-13lvq34-q":`Model Sağlayıcısı API Bağdaştırıcısı`},help:{"v1-16c28rb-57":`Model çağrılarında istek/yanıt uyumluluğunun nasıl ele alınacağını belirleyen sağlayıcı API bağdaştırıcısı seçimi. Özellik uyumsuzluğunu önlemek için üst sağlayıcınızın protokolüyle eşleşen bağdaştırıcıyı kullanın.`}},"models%2Eproviders%2E*%2EapiKey":{label:{"v1-461pfc-m":`Model Sağlayıcısı API Anahtarı`},help:{"v1-1p84k96-54":`Sağlayıcı doğrudan anahtarla kimlik doğrulama gerektirdiğinde, API anahtarı tabanlı kimlik doğrulama için kullanılan sağlayıcı kimlik bilgisi. Gizli değer/ortam değişkeni ikamesi kullanın ve sürüm kontrolüne eklenen yapılandırma dosyalarında gerçek anahtarları saklamaktan kaçının.`}},"models%2Eproviders%2E*%2Eauth":{label:{"v1-5tjzpa-o":`Model Sağlayıcısı Kimlik Doğrulama Modu`},help:{"v1-1l1lwxr-5p":`Sağlayıcının kimlik doğrulama türünü seçer: API anahtarıyla kimlik doğrulama için "api-key", bearer token ile kimlik doğrulama için "token", OAuth kimlik bilgileri için "oauth" ve AWS kimlik bilgilerini çözümlemek için "aws-sdk". Bunu sağlayıcınızın gereksinimlerine göre ayarlayın.`}},"models%2Eproviders%2E*%2EauthHeader":{label:{"v1-1d6ejif-z":`Model Sağlayıcısı Authorization Üst Bilgisi`},help:{"v1-1gn3lt3-59":`true olduğunda, alternatif kimlik doğrulama mümkün olsa bile kimlik bilgileri HTTP Authorization üst bilgisi aracılığıyla gönderilir. Bunu yalnızca sağlayıcınız veya proxy'niz açıkça Authorization iletimini gerektiriyorsa kullanın.`}},"models%2Eproviders%2E*%2EbaseUrl":{label:{"v1-169qlbh-n":`Model Sağlayıcısı Temel URL'si`},help:{"v1-1ku88v8-53":`İlgili sağlayıcı kaydının model isteklerini karşılamak için kullanılan sağlayıcı uç noktasının temel URL'si. HTTPS uç noktalarını kullanın ve gerektiğinde yapılandırma şablonları aracılığıyla URL'leri ortama özgü tutun.`}},"models%2Eproviders%2E*%2Eheaders":{label:{"v1-6e7t45-m":`Model Sağlayıcısı Üst Bilgileri`},help:{"v1-chg59u-4x":`Kiracı yönlendirmesi, proxy kimlik doğrulaması veya özel ağ geçidi gereksinimleri için sağlayıcı isteklerine eklenen sabit HTTP üst bilgileri. Bunu ölçülü kullanın ve hassas üst bilgi değerlerini gizli bilgi deposunda saklayın.`}},"models%2Eproviders%2E*%2EinjectNumCtxForOpenAICompat":{label:{"v1-3u41lp-19":`Model Sağlayıcısı num_ctx Ekleme (OpenAI Uyumluluğu)`},help:{"v1-53rmcr-6n":"OpenClaw'ın, OpenAI uyumlu bağdaştırıcıyla (`openai-completions`) yapılandırılmış Ollama sağlayıcıları için `options.num_ctx` ekleyip eklemeyeceğini denetler. Varsayılan değer true'dur. Yalnızca proxy'niz veya üst sunucunuz istek gövdesindeki bilinmeyen `options` alanlarını reddediyorsa false olarak ayarlayın."}},"models%2Eproviders%2E*%2ElocalService":{label:{"v1-gokf3z-s":`Model Sağlayıcısı Yerel Hizmeti`},help:{"v1-19zkcow-4y":`Bu sağlayıcı için isteğe bağlı, talep üzerine çalışan yerel model sunucusu süreci. OpenClaw, healthUrl adresini kontrol eder, gerektiğinde komutu başlatır, hazır olmasını bekler ve ardından model isteğini gönderir.`}},"models%2Eproviders%2E*%2ElocalService%2Eargs":{label:{"v1-18ua8bb-12":`Model Sağlayıcısı Yerel Hizmet Argümanları`},help:{"v1-t12wib-27":`Yerel model sunucusu komutuna kabuk genişletmesi uygulanmadan iletilen argüman listesi.`}},"models%2Eproviders%2E*%2ElocalService%2Ecommand":{label:{"v1-1i9zwui-10":`Model Sağlayıcısı Yerel Hizmet Komutu`},help:{"v1-1x6hz64-4j":`Yerel model sunucusu sürecinin yürütülebilir dosyasının mutlak yolu. Sağlayıcının başlatılmasının deterministik olması ve kabuğun PATH aramasına bağlı kalmaması için bu yolu açıkça belirtin.`}},"models%2Eproviders%2E*%2ElocalService%2Ecwd":{label:{"v1-1p16qmb-1a":`Model Sağlayıcısı Yerel Hizmet Çalışma Dizini`},help:{"v1-fi3xlx-1h":`Yerel model sunucusu sürecinin çalışma dizini.`}},"models%2Eproviders%2E*%2ElocalService%2Eenv":{label:{"v1-txm98y-14":`Model Sağlayıcısı Yerel Hizmet Ortamı`},help:{"v1-1lwb9k1-3k":`Yerel model sunucusu süreci için ek ortam değişkenleri. Gizli bilgi gibi görünen değerler, yapılandırma anlık görüntülerinde maskelenir.`}},"models%2Eproviders%2E*%2ElocalService%2EhealthUrl":{label:{"v1-2w1iqm-13":`Model Sağlayıcısı Yerel Hizmet Sağlık Kontrolü URL'si`},help:{"v1-jv7aw-35":`Model isteklerinden önce kontrol edilen hazır olma durumu URL'si. Belirtilmezse OpenClaw, sağlayıcının baseUrl adresine /models ekleyerek kullanır.`}},"models%2Eproviders%2E*%2ElocalService%2EidleStopMs":{label:{"v1-1ktyg8x-12":`Model Sağlayıcısı Yerel Hizmet Boştayken Durdurma`},help:{"v1-1efg054-3z":`OpenClaw tarafından başlatılan yerel model sunucusunun son istek tamamlandıktan sonra çalışır durumda tutulacağı süre (milisaniye). OpenClaw kapanana kadar çalışır durumda tutmak için 0 olarak ayarlayın.`}},"models%2Eproviders%2E*%2ElocalService%2EreadyTimeoutMs":{label:{"v1-1hj089b-16":`Model Sağlayıcısı Yerel Hizmet Hazır Olma Zaman Aşımı`},help:{"v1-4gp0f0-2r":`İşlem başlatıldıktan sonra yerel model sunucusunun hazır olma denetimi için beklenecek en uzun süre (milisaniye).`}},"models%2Eproviders%2E*%2EmaxTokens":{label:{"v1-662xo5-p":`Model Sağlayıcısı Maksimum Token Sayısı`},help:{"v1-fnj50y-38":`Bir model kaydında maxTokens ayarlanmadığında bu sağlayıcının modellerine uygulanan varsayılan maksimum çıktı token bütçesi.`}},"models%2Eproviders%2E*%2Emodels":{label:{"v1-19fsoem-p":`Model Sağlayıcısı Model Listesi`},help:{"v1-1vbm0gt-63":`Bir sağlayıcı için tanımlanan; tanımlayıcıları, meta verileri, sağlayıcıya özgü parametreleri ve isteğe bağlı uyumluluk/maliyet ipuçlarını içeren model listesi. Seçim ve yedek modele geçişin doğru çalışması için kimlikleri sağlayıcı kataloğundaki değerlerle birebir aynı tutun.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime":{label:{"v1-17rzml2-d":`Model Çalışma Ortamı`},help:{"v1-1k70g2n-3g":`Bu modele özgü, isteğe bağlı düşük seviyeli ajan çalışma ortamı ilkesi. Model çalışma ortamı ilkesi, sağlayıcı çalışma ortamı ilkesini geçersiz kılar.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EagentRuntime%2Eid":{label:{"v1-1035lu7-g":`Model Çalışma Ortamı Kimliği`},help:{"v1-1llzv33-42":`Model ajan çalışma ortamı kimliği: "openclaw", "auto", "codex" gibi kayıtlı bir eklenti yürütme altyapısı kimliği veya "claude-cli" gibi desteklenen bir CLI arka ucu takma adı.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput":{label:{"v1-x3fby6-h":`Model Medya Girdisi`},help:{"v1-wxtj8e-2x":`Araçların temkinli görüntü sıkıştırma varsayılanlarını seçmek için kullandığı, modelin medya yeteneklerine ilişkin isteğe bağlı meta veriler.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage":{label:{"v1-5448tb-h":`Model Görüntü Girdisi`},help:{"v1-1nviirq-3c":`Bu model için maksimum kenar uzunluğu, maksimum piksel sayısı ve tercih edilen sıkıştırma kenar uzunluğu gibi isteğe bağlı görüntü girdisi sınırları.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxBytes":{label:{"v1-4chdj6-l":`Model Görüntüsü Maksimum Bayt Boyutu`},help:{"v1-c2469j-23":`Sağlayıcının bu model için kabul ettiği maksimum kodlanmış görüntü verisi boyutu.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxPixels":{label:{"v1-4hbb56-m":`Model Görüntüsü Maksimum Piksel Sayısı`},help:{"v1-9d6yqp-1u":`Sağlayıcının bu model için kabul ettiği maksimum görüntü piksel sayısı.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EmaxSidePx":{label:{"v1-1otuj2k-k":`Model Görüntüsü Maksimum Kenar Uzunluğu`},help:{"v1-1gbci08-1y":`Sağlayıcının bu model için kabul ettiği maksimum görüntü genişliği veya yüksekliği.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EpreferredSidePx":{label:{"v1-1d35u85-q":`Model Görüntüsü Tercih Edilen Kenar Uzunluğu`},help:{"v1-1u1mpcg-2x":`Dengeli sıkıştırma için görüntü yeniden boyutlandırılırken tercih edilen kenar uzunluğu. OpenClaw'ın temkinli varsayılanını kullanmak için ayarlamadan bırakın.`}},"models%2Eproviders%2E*%2Emodels%5B%5D%2EmediaInput%2Eimage%2EtokenMode":{label:{"v1-1oh830x-m":`Model Görsel Token Modu`},help:{"v1-1oy6z7v-1z":`Sağlayıcının görsel token hesaplama biçimi: "tile", "detail" veya "provider".`}},"models%2Eproviders%2E*%2Eparams":{label:{"v1-tv1h1l-x":`Model Sağlayıcısı Çalışma Zamanı Parametreleri`},help:{"v1-464sgu-4t":`Sağlayıcı eklentileri tarafından yorumlanan, sağlayıcıya özgü çalışma zamanı parametreleri. Sağlayıcının belgelediği anahtarları kullanın ve genel varsayımlar yerine sağlayıcının açık belgelerini tercih edin.`}},"models%2Eproviders%2E*%2Eregion":{label:{"v1-9wgoh5-l":`Model Sağlayıcısı Bölgesi`},help:{"v1-yq7rxk-5h":`Bölgesel uç noktalar sunan sağlayıcılar tarafından yorumlanan, isteğe bağlı sağlayıcı dağıtım/API bölgesi. Desteklenen değerler için sağlayıcı belgelerine bakın; her ikisi de ayarlandığında baseUrl geçersiz kılmaları genellikle önceliklidir.`}},"models%2Eproviders%2E*%2Erequest":{label:{"v1-1yv8vnf-w":`Model Sağlayıcısı İstek Geçersiz Kılmaları`},help:{"v1-1lkxryk-87":`Model sağlayıcısı istekleri için ek üst bilgiler, kimlik doğrulama geçersiz kılmaları, proxy yönlendirmesi, TLS istemci ayarları ve kendi sunucunuzda barındırılan güvenilir uç noktalar için isteğe bağlı allowPrivateNetwork dahil olmak üzere isteğe bağlı istek geçersiz kılmaları. Bunları yalnızca üst hizmetiniz veya kurumsal ağ yolunuz aktarım özelleştirmesi gerektirdiğinde kullanın.`}},"models%2Eproviders%2E*%2Erequest%2EallowPrivateNetwork":{label:{"v1-1etevm-18":`Model Sağlayıcısı İsteklerinde Özel Ağa İzin Ver`},help:{"v1-1nbtcjk-fo":`true olduğunda, model sağlayıcısının özel, CGNAT veya benzer adres aralıklarına yönelik HTTP isteklerine sağlayıcının HTTP fetch koruması (fetchWithSsrFGuard) üzerinden izin verir. Özel/yerel sağlayıcı temel URL'leri, meta veri, bağlantı yerel ve yerel kullanıma yönelik NAT64 (64:ff9b:1::/48) kaynakları hariç, yapılandırılan kaynağa zaten tam olarak güvenir; bu güveni devre dışı bırakmak için bunu false olarak ayarlayın. OpenAI Responses WebSocket, üstbilgiler/TLS için request ayarını yeniden kullanır ancak bu fetch SSRF yolunu kullanmaz. true değerini yalnızca, yapılandırılan baseUrl kaynağı dışındaki özel kaynaklara erişmesi gereken, operatör denetimindeki kendi barındırdığınız uç noktalar için kullanın.`}},"models%2Eproviders%2E*%2Erequest%2Eauth":{label:{"v1-uw1fmg-10":`Model Sağlayıcısı İstek Kimlik Doğrulamasını Geçersiz Kılma`},help:{"v1-ucdgnf-1w":`Bu sağlayıcı için sağlayıcı isteklerinin kimlik doğrulama davranışını geçersiz kılın.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2EheaderName":{label:{"v1-1jwzygk-13":`Model Sağlayıcısı İstek Kimlik Doğrulama Üstbilgisi Adı`},help:{"v1-1881nqr-1i":`Kimlik doğrulama modu header olduğunda kullanılan özel kimlik doğrulama üstbilgisi adı.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Emode":{label:{"v1-1prff17-w":`Model Sağlayıcısı İstek Kimlik Doğrulama Modu`},help:{"v1-1lhv8hs-24":`Kimlik doğrulamayı geçersiz kılma modu: "provider-default", "authorization-bearer" veya "header".`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Eprefix":{label:{"v1-1fxbu5n-15":`Model Sağlayıcısı İstek Kimlik Doğrulama Üstbilgisi Öneki`},help:{"v1-1rbm9lz-21":`Kimlik doğrulama modu header olduğunda request.auth.value değerinin başına eklenen isteğe bağlı önek.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Etoken":{label:{"v1-31rmhm-z":`Model Sağlayıcısı İstek Bearer Belirteci`},help:{"v1-6rcasw-1l":`Kimlik doğrulama modu authorization-bearer olduğunda kullanılan Bearer belirteci.`}},"models%2Eproviders%2E*%2Erequest%2Eauth%2Evalue":{label:{"v1-gx2woc-14":`Model Sağlayıcısı İsteği Kimlik Doğrulama Üstbilgisi Değeri`},help:{"v1-1v69ej-1j":`Kimlik doğrulama modu header olduğunda kullanılan özel kimlik doğrulama üstbilgisi değeri.`}},"models%2Eproviders%2E*%2Erequest%2Eheaders":{label:{"v1-72ia6g-u":`Model Sağlayıcısı İstek Üstbilgileri`},help:{"v1-zj3orj-2i":`Varsayılan kaynak ilişkilendirmesi ve kimlik doğrulama çözümlemesinden sonra sağlayıcı isteklerine eklenen ek üstbilgiler.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy":{label:{"v1-1drhe6m-s":`Model Sağlayıcısı İstek Ara Sunucusu`},help:{"v1-md5uj8-4j":`Model sağlayıcısı istekleri için isteğe bağlı ara sunucu geçersiz kılma ayarı. Ortamın ara sunucu ayarlarını kullanmak için "env-proxy", belirli bir ara sunucu URL'si üzerinden yönlendirmek için "explicit-proxy" kullanın.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Emode":{label:{"v1-2ea1ht-x":`Model Sağlayıcısı İstek Ara Sunucusu Modu`},help:{"v1-1dx0ozg-29":`Model sağlayıcısı istekleri için ara sunucu geçersiz kılma modu: "env-proxy" veya "explicit-proxy".`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls":{label:{"v1-y7ygtf-w":`Model Sağlayıcısı İstek Ara Sunucusu TLS Ayarları`},help:{"v1-rdx62w-1v":`Yapılandırılan ara sunucuya bağlanırken kullanılan isteğe bağlı TLS ayarları.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Eca":{label:{"v1-xp5zz1-z":`Model Sağlayıcısı İstek Ara Sunucusu TLS CA Paketi`},help:{"v1-11pg2fd-1s":`Ara sunucunun TLS sertifika zincirini doğrulamak için kullanılan özel CA paketi.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ecert":{label:{"v1-1p0kbsn-11":`Model Sağlayıcısı İstek Ara Sunucusu TLS Sertifikası`},help:{"v1-x8nk2q-22":`Karşılıklı TLS gerektiğinde proxy'ye sunulan istemci TLS sertifikası.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EinsecureSkipVerify":{label:{"v1-1gmlhnv-18":`Model Sağlayıcısı İstek Proxy'si TLS Doğrulamasını Atla`},help:{"v1-12vjdm9-2j":`Proxy TLS sertifikası doğrulamasını atlar. Yalnızca kontrollü geliştirme ortamlarında kullanın.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Ekey":{label:{"v1-1rjms34-10":`Model Sağlayıcısı İstek Proxy'si TLS Anahtarı`},help:{"v1-1skyr56-1w":`Proxy ile karşılıklı TLS için request.proxy.tls.cert ile eşleştirilen özel anahtar.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2Epassphrase":{label:{"v1-xwzjbl-17":`Model Sağlayıcısı İstek Proxy'si TLS Parolası`},help:{"v1-wjvoxd-1m":`request.proxy.tls.key şifresini çözmek için kullanılan isteğe bağlı parola.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Etls%2EserverName":{label:{"v1-9wzzxd-18":`Model Sağlayıcısı İstek Proxy'si TLS Sunucu Adı`},help:{"v1-b4oabu-22":`Proxy'ye TLS bağlantısı kurulurken varsayılanın yerine kullanılan isteğe bağlı SNI/sunucu adı.`}},"models%2Eproviders%2E*%2Erequest%2Eproxy%2Eurl":{label:{"v1-1r3x1tf-w":`Model Sağlayıcısı İstek Proxy'si URL'si`},help:{"v1-kvbgou-48":`request.proxy.mode değeri explicit-proxy olduğunda kullanılan, açıkça belirtilmiş proxy URL'si. URL'ye gömülü kimlik bilgileri hassas kabul edilir ve anlık görüntülerde gizlenir.`}},"models%2Eproviders%2E*%2Erequest%2Etls":{label:{"v1-1xtk31n-q":`Model Sağlayıcısı İstek TLS'i`},help:{"v1-16u7v7h-2b":`Üst model uç noktasına doğrudan bağlanırken kullanılan isteğe bağlı TLS ayarları.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Eca":{label:{"v1-oselmd-t":`Model Sağlayıcısı İsteği TLS CA Paketi`},help:{"v1-ny8y3e-1v":`Üst sunucunun TLS sertifika zincirini doğrulamak için kullanılan özel CA paketi.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ecert":{label:{"v1-trr9e7-v":`Model Sağlayıcısı İsteği TLS Sertifikası`},help:{"v1-1lltmhw-2e":`Karşılıklı TLS gerektiğinde üst uç noktaya sunulan istemci TLS sertifikası.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EinsecureSkipVerify":{label:{"v1-1dmxiab-12":`Model Sağlayıcısı İsteğinde TLS Doğrulamasını Atla`},help:{"v1-1006cuy-2m":`Üst sunucunun TLS sertifikasının doğrulanmasını atlar. Yalnızca kontrollü geliştirme ortamlarında kullanın.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Ekey":{label:{"v1-13sjm0o-u":`Model Sağlayıcısı İsteği TLS Anahtarı`},help:{"v1-w2agir-1t":`Üst sunucuyla karşılıklı TLS için request.tls.cert ile eşleştirilen özel anahtar.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2Epassphrase":{label:{"v1-19c5oux-11":`Model Sağlayıcısı İsteği TLS Parolası`},help:{"v1-10ds42f-1g":`request.tls.key şifresini çözmek için kullanılan isteğe bağlı parola.`}},"models%2Eproviders%2E*%2Erequest%2Etls%2EserverName":{label:{"v1-oe4b49-12":`Model Sağlayıcısı İsteği TLS Sunucu Adı`},help:{"v1-18yt7x9-1y":`Üst sunucuyla TLS bağlantısı kurulurken SNI/sunucu adı yerine kullanılan isteğe bağlı değer.`}},"models%2Eproviders%2E*%2EtimeoutSeconds":{label:{"v1-itszd1-u":`Model Sağlayıcısı İsteği Zaman Aşımı`},help:{"v1-t3yn8l-ih":`Sağlayıcı başına isteğe bağlı model isteği zaman aşımı (saniye). Sağlayıcı düzeyindeki istek ayarları, sağlayıcıya ait açıkça tanımlanmış model satırlarını etkiler; örtük modeller oluşturmaz. Özel sağlayıcılarda bunu sağlayıcının baseUrl ve models ayarlarıyla birlikte belirleyin. Bağlantı, başlıklar, gövde ve isteğin tamamının iptal edilmesinin yönetimi dahil olmak üzere sağlayıcı HTTP isteklerine uygulanır. Ayrıca bu sağlayıcı için LLM boşta kalma/akış izleyicisinin üst sınırını örtük ~120 saniyelik varsayılan değerin üzerine çıkarır. Genel ajan zaman aşımlarını değiştirmek yerine, yavaş yerel veya kendi barındırdığınız model sunucuları ya da akıl yürütme token'larını ağ üzerinden veri göndermeden arabelleğe alan bulut sağlayıcıları (Gemini önizleme sürümü, büyük araç yükleriyle çalışan Claude/Opus) için bu ayarı kullanın.`}},nodeHost:{label:{"v1-nb8lk1-9":`Düğüm Ana Bilgisayarı`},help:{"v1-8recuz-4z":`Bu Gateway düğümünden diğer düğümlere veya istemcilere sunulan özellikler için düğüm ana makinesi denetimleri. Yerel yetenekleri düğüm ağınız üzerinden bilinçli olarak vekil aracılığıyla sunmuyorsanız varsayılan ayarları koruyun.`}},"nodeHost%2EagentRuns":{label:{"v1-s71x8m-f":`Düğüm Ajan Çalıştırmaları`},help:{"v1-4uz5ur-2k":`Bu grafik arayüzü olmayan düğüm ana makinesinde onaya tabi yerel ajan turlarını etkinleştirin. Varsayılan olarak devre dışıdır.`}},"nodeHost%2EagentRuns%2Eclaude":{label:{"v1-10xgkda-m":`Düğüm Claude Ajan Çalıştırmaları`},help:{"v1-g8az5y-2l":`Bu grafik arayüzü olmayan düğüm ana makinesinin Claude CLI ajan turlarını Gateway'e kullanılabilir olarak bildirip bildiremeyeceğini denetler.`}},"nodeHost%2EagentRuns%2Eclaude%2Eenabled":{label:{"v1-15o3u53-u":`Düğüm Claude Ajan Çalıştırmaları Etkin`},help:{"v1-1ke804l-44":`Yerel claude yürütülebilir dosyası mevcut olduğunda, eşleştirilmiş düğümde Claude oturumunu sürdürme özelliğini kullanılabilir olarak bildirin (varsayılan: false). Çalıştırmalar yine de düğümde komut yürütme onayı gerektirir.`}},"nodeHost%2EautoUpdate":{label:{"v1-fmh4qs-m":`Düğüm Otomatik Güncellemeleri`},help:{"v1-16xjk4e-5n":`Paketlenmiş, grafik arayüzü olmayan düğüm ana makinelerinin ayrı çalışma zamanına yönelik otomatik güncellemeleri denetler. Saatte bir kontrol eder ve yeniden başlatmadan önce tüm düğüm işlerinin tamamlanmasını bekler; otomatik yeniden başlatmalar arasında en az 12 saat vardır.`}},"nodeHost%2EautoUpdate%2Eenabled":{label:{"v1-89maql-u":`Düğüm Otomatik Güncellemeleri Etkin`},help:{"v1-1sa0yeg-7w":`Uzun süre çalışan, paketlenmiş ve grafik arayüzü olmayan düğümler için otomatik stable veya beta güncellemelerini etkinleştirir (varsayılan: true). Devre dışı bırakmak için false olarak ayarlayın. update.checkOnStart=false veya OPENCLAW_NO_AUTO_UPDATE=1 ile de devre dışı bırakılır; kaynak kod kopyalarında, yerel uygulamalarda, özel çalışan süreçlerde, dev ve extended-stable kanallarında güncellemeler otomatik uygulanmaz.`}},"nodeHost%2EbrowserProxy":{label:{"v1-1bm9i0h-i":`Düğüm Tarayıcı Vekili`},help:{"v1-2xrew7-4f":`Yerel tarayıcı denetimini düğüm yönlendirmesi üzerinden kullanıma açan tarayıcı proxy ayarlarını gruplandırır. Yalnızca uzak düğüm iş akışları yerel tarayıcı profillerinize ihtiyaç duyduğunda etkinleştirin.`}},"nodeHost%2EbrowserProxy%2EallowProfiles":{label:{"v1-cq2v55-z":`Düğüm Tarayıcı Proxy'sinde İzin Verilen Profiller`},help:{"v1-1ew5dkm-8b":`Düğüm proxy yönlendirmesi üzerinden kullanıma açılan tarayıcı profili adlarının isteğe bağlı izin listesi. Profil oluşturma/silme yolları dahil varsayılan tam profil erişimini korumak için boş bırakın. Ayarlandığında OpenClaw, profillere en az ayrıcalık ilkesiyle erişim sağlar ve proxy üzerinden kalıcı profil oluşturma/silme işlemlerini engeller.`}},"nodeHost%2EbrowserProxy%2Eenabled":{label:{"v1-1dlbo60-q":`Düğüm Tarayıcı Proxy'si Etkin`},help:{"v1-pa04pd-5b":`Uzak istemcilerin bu ana makinenin tarayıcı özelliklerini kullanabilmesi için yerel tarayıcı denetim sunucusunu düğüm proxy yönlendirmesi üzerinden kullanıma açar. Uzak otomasyon açıkça buna bağlı olmadıkça devre dışı bırakın.`}},"nodeHost%2Emcp":{label:{"v1-4hkwkx-d":`Düğüm Ana Makinesi MCP`},help:{"v1-1mdhrwl-48":`Grafik arayüzü olmayan düğüm ana makinesi tarafından başlatılan ve eşleştirildiği ağ geçidinde yayımlanan MCP sunucularını ajan araçları olarak kullanın. Bu bölümü değiştirdikten sonra düğüm ana makinesini yeniden başlatın.`}},"nodeHost%2Emcp%2Eservers":{label:{"v1-6lpscp-l":`Düğüm Ana Makinesi MCP Sunucuları`},help:{"v1-19m002f-3x":`Bu düğüme yerel, adlandırılmış MCP sunucusu tanımları. mcp.servers ile aynı sunucu yapısını kullanır; OAuth sunucuları düğüm ana makinesi tarafından desteklenmez.`}},"nodeHost%2Eskills":{label:{"v1-1n58xs9-g":`Düğüm Ana Makinesi Skills`},help:{"v1-v8txza-41":`~/.openclaw/skills konumunda yüklü becerileri grafik arayüzü olmayan düğüm ana makinesinden yayımlamak için bu bölümü kullanın. Beceri dosyalarını değiştirdikten sonra düğüm ana makinesini yeniden başlatın.`}},"nodeHost%2Eskills%2Eenabled":{label:{"v1-uf23u8-o":`Düğüm Ana Makinesi Skills Etkin`},help:{"v1-1ggpkqb-36":`Bağlandıktan sonra düğümde barındırılan becerileri tara ve yayımla (varsayılan: true). Düğüm becerilerinin yayımlanmasını devre dışı bırakmak için false olarak ayarlayın.`}},"nodeHost%2EworkerRuns":{label:{"v1-1aab8yp-g":`Düğüm Çalışanı Çalıştırmaları`},help:{"v1-1w83rox-2p":`Gateway tarafından yönetilen paketlerden tam OpenClaw çalışan oturumlarının barındırılmasını etkinleştirin. Varsayılan olarak devre dışıdır.`}},"nodeHost%2EworkerRuns%2Ecapacity":{label:{"v1-1tquo3g-o":`Düğüm Çalışanı Çalıştırma Kapasitesi`},help:{"v1-10nvk8f-3w":`Bu düğümün eşzamanlı olarak barındırabileceği en fazla çalışan oturumu sayısı (varsayılan: kullanılabilir CPU çekirdeği sayısı). 1 ile 1024 arasında bir tam sayı olmalıdır.`}},"nodeHost%2EworkerRuns%2EcontainerImage":{label:{"v1-1fujssi-v":`Düğüm Çalışanı Çalıştırma Konteyner İmajı`},help:{"v1-1oqx50o-5t":`Konteyner ile yalıtılmış çalışanlar için isteğe bağlı Node 24.16+ veya 26.1+ imajı (varsayılan: "node:24.19.0-slim"). Gerektiğinde özet değeriyle sabitlenmiş, özel imaj deposunda bulunan veya önceden yüklenmiş bir imaj kullanın; eksik imajlar ilk kullanımda indirilir.`}},"nodeHost%2EworkerRuns%2Eenabled":{label:{"v1-t3la2w-o":`Düğüm Çalışanı Çalıştırmaları Etkin`},help:{"v1-b3t0xp-2t":`Bu eşleştirilmiş düğümün, bağlı olduğu Gateway tarafından yüklenen paketlerin birebir aynılarından oturumlar barındırmasına izin verin (varsayılan: false).`}},"nodeHost%2EworkerRuns%2Eisolation":{label:{"v1-1qqd8iw-p":`Düğüm Çalışanı Çalıştırma Yalıtımı`},help:{"v1-19i6swo-58":`Çalışan oturumunun süreç sınırını seçin: "none" doğrudan düğüm ana makinesinde çalışır (varsayılan); "container" çalışan bir Docker uyumlu motor gerektirir ve hiçbir zaman ana makinede çalıştırmaya geri dönmez.`}},plugins:{label:{"v1-10renyj-7":`Eklentiler`},help:{"v1-1qbev2k-5c":`Uzantıları etkinleştirmek, yükleme kapsamını sınırlamak, girdileri yapılandırmak ve kurulumları izlemek için eklenti sistemi denetimleri. Üretim ortamlarında eklenti politikasını açıkça tanımlayın ve en az ayrıcalık ilkesine uygun tutun.`}},"plugins%2Eallow":{label:{"v1-19jw4yj-g":`Eklenti İzin Listesi`},help:{"v1-pupwbe-7z":`İsteğe bağlı eklenti kimlikleri izin listesi; ayarlandığında yalnızca listedeki eklentiler yüklenebilir. Yapılandırılmış yerleşik sohbet kanalları, yapılandırmada açıkça etkinleştirildiğinde kendi yerleşik eklentilerini yine de etkinleştirebilir. Kontrollü ortamlarda yalnızca onaylı uzantıların kullanılmasını sağlamak için bunu kullanın.`}},"plugins%2Edeny":{label:{"v1-arkuus-f":`Eklenti Engelleme Listesi`},help:{"v1-4gyt4z-4i":`İzin listelerinde veya yollarda yer alsalar bile engellenecek eklenti kimliklerinin isteğe bağlı listesi. Acil geri alma işlemleri ve riskli eklentileri kesin olarak engellemek için engelleme kurallarını kullanın.`}},"plugins%2Eenabled":{label:{"v1-461fte-e":`Eklentileri Etkinleştir`},help:{"v1-pnygd7-50":`Başlangıçta ve yapılandırma yeniden yüklenirken eklenti/uzantı yüklemeyi genel olarak etkinleştirin veya devre dışı bırakın (varsayılan: true). Yalnızca dağıtımınız uzantı özellikleri gerektiriyorsa etkin tutun.`}},"plugins%2Eentries":{label:{"v1-1q3x0gu-e":`Eklenti Girdileri`},help:{"v1-cn74rf-54":`Eklenti kimliğine göre anahtarlanmış, etkinleştirme durumu ve eklentiye özgü çalışma zamanı yapılandırma verilerini içeren eklenti bazlı ayarlar. Genel yükleyici politikasını değiştirmeden belirli eklentilerin ayarlarını düzenlemek için bunu kullanın.`}},"plugins%2Eentries%2E*%2EapiKey":{label:{"v1-1c5cpg5-e":`Eklenti API Anahtarı`},help:{"v1-ctytg2-53":`Girdi ayarlarında doğrudan anahtar yapılandırmasını kabul eden eklentilerin kullandığı isteğe bağlı API anahtarı alanı. Gizli değer/ortam değişkeni ikamesi kullanın ve gerçek kimlik bilgilerini yapılandırma dosyalarına kaydetmekten kaçının.`}},"plugins%2Eentries%2E*%2Econfig":{label:{"v1-1i42kk8-d":`Eklenti Yapılandırması`},help:{"v1-1he672p-51":`Eklenti tarafından tanımlanan ve eklentinin kendi şemasına ve doğrulama kurallarına göre yorumlanan yapılandırma verileri. Ayarların yok sayılmasını veya geçersiz olmasını önlemek için yalnızca eklentinin belgelerinde belirtilen alanları kullanın.`}},"plugins%2Eentries%2E*%2Eenabled":{label:{"v1-87au17-e":`Eklenti Etkin`},help:{"v1-12soc0h-9a":`Belirli bir kayıt için genel eklenti politikasının üzerine uygulanan, eklentiye özel etkinleştirme ayarı. Varsayılan karma yeniden yükleme modunda değişiklikler, eklenti bu ayar yolu için yeniden başlatma gerektirmediği sürece Gateway yeniden başlatılmadan, yeni ajan turları için eklenti çalışma zamanına anında uygulanır. Eklentiyi farklı ortamlarda aşamalı olarak kullanıma sunmak için bu ayarı kullanın.`}},"plugins%2Eentries%2E*%2Eenv":{label:{"v1-1vsubm6-s":`Eklenti Ortam Değişkenleri`},help:{"v1-p39pu4-52":`Yalnızca ilgili eklentinin çalışma zamanı bağlamına aktarılan, eklentiye özel ortam değişkeni eşlemesi. Genel süreç ortamını paylaşmak yerine sağlayıcı kimlik bilgilerini tek bir eklentiyle sınırlamak için bu ayarı kullanın.`}},"plugins%2Eentries%2E*%2Ehooks":{label:{"v1-1miceel-i":`Eklenti Kanca Politikası`},help:{"v1-1oslnrf-4c":`Çekirdeğin uyguladığı güvenlik denetimleri için eklentiye özel, tür tanımlı kanca politikası kontrolleri. Eklentinin tamamını devre dışı bırakmadan yüksek etkili kanca kategorilerini sınırlamak için bu ayarı kullanın.`}},"plugins%2Eentries%2E*%2Ehooks%2EallowConversationAccess":{label:{"v1-ckd9n5-v":`Konuşmaya Erişim Kancalarına İzin Ver`},help:{"v1-xqz31z-7e":"Bu eklentinin `before_agent_run`, `before_model_resolve`, `before_agent_reply`, `llm_input`, `llm_output`, `before_agent_finalize` ve `agent_end` gibi tür tanımlı kancalardan ham konuşma içeriğini okuyup okuyamayacağını belirler. Paketle birlikte gelmeyen eklentiler için bu erişim açıkça etkinleştirilmelidir."}},"plugins%2Eentries%2E*%2Ehooks%2EallowPromptInjection":{label:{"v1-1p7f9k9-s":`İstem Enjeksiyonu Kancalarına İzin Ver`},help:{"v1-7y6cny-32":"Bu eklentinin tür tanımlı kancalar aracılığıyla istemleri değiştirip değiştiremeyeceğini belirler. `before_prompt_build` kancasını engellemek için false olarak ayarlayın."}},"plugins%2Eentries%2E*%2Ehooks%2EtimeoutMs":{label:{"v1-zg658l-o":`Eklenti Kancası Zaman Aşımı (ms)`},help:{"v1-4ra6b7-74":`Bu eklentinin tür tanımlı kancaları için milisaniye cinsinden varsayılan zaman aşımı; üst sınır 600000'dir. Ayarlanmadığında her kanca, eklentinin bildirdiği zaman aşımını veya Gateway'in kanca başına politikasını kullanır; tek bir sabit varsayılan değer yoktur. hooks.timeouts içindeki kanca bazlı değerler önceliklidir.`}},"plugins%2Eentries%2E*%2Ehooks%2Etimeouts":{label:{"v1-1k80g2z-t":`Eklenti Kancasına Özel Zaman Aşımı Değerleri`},help:{"v1-yphl9b-5s":`Tür tanımlı kanca adlarıyla anahtarlanmış, milisaniye cinsinden kancaya özel zaman aşımı değerleri; üst sınır 600000'dir. Tüm kancaların zaman aşımını artırmak yerine before_prompt_build veya agent_end gibi yavaş olduğu bilinen kancalara özel değerler kullanın.`}},"plugins%2Eentries%2E*%2Ellm":{label:{"v1-tnwzbh-h":`Eklenti LLM Politikası`},help:{"v1-dlca6c-4j":`Model ve ajan geçersiz kılma işlemlerinin güvenilirliğine yönelik, eklenti başına api.runtime.llm.complete denetimleri. Bir eklentinin ana uygulamaya ait tamamlama çağrılarını açıkça yönlendirmesi gerekmiyorsa bunu ayarlamayın.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAgentIdOverride":{label:{"v1-14o9l6p-v":`Eklentinin LLM Ajanını Geçersiz Kılmasına İzin Ver`},help:{"v1-k8c08b-4n":`Bu eklentinin varsayılan dışı bir ajan kimliğiyle api.runtime.llm.complete isteğinde bulunmasına açıkça izin verir. Eklentiye ajanlar arası model erişimi konusunda güvenilmiyorsa false olarak bırakın.`}},"plugins%2Eentries%2E*%2Ellm%2EallowAuthProfileOverride":{label:{"v1-8zsq4z-12":`Eklentinin LLM Kimlik Doğrulama Profilini Geçersiz Kılmasına İzin Ver`},help:{"v1-9ityw9-4x":`Bu eklentinin yalıtılmış ajan çalışma zamanı tamamlamaları için varsayılan dışı bir kimlik doğrulama profili seçmesine izin verir. Eklentiye açıkça belirtilen yalıtılmış kimlik bilgisi yönlendirmesi konusunda güvenilmiyorsa false olarak bırakın.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedCompletionModels":{label:{"v1-13e4e1t-10":`Eklenti LLM İzin Verilen Tamamlama Modelleri`},help:{"v1-1ul08he-54":`Ana sistem tarafından çözümlenen varsayılanlar ve geçersiz kılmalar dahil, her eklenti LLM tamamlama işlemi için izin verilen hedefler; standart "provider/model" referansları olarak belirtilir. "*" değerini yalnızca herhangi bir modele bilinçli olarak izin verdiğinizde kullanın.`}},"plugins%2Eentries%2E*%2Ellm%2EallowedModels":{label:{"v1-1vuyyz9-p":`Eklenti LLM'si için İzin Verilen Modeller`},help:{"v1-154sk45-47":`Güvenilen eklentilerin LLM çağrılarında modeli geçersiz kılmak için izin verilen hedefler; standart "provider/model" referansları olarak belirtilir. "*" değerini yalnızca herhangi bir modelle geçersiz kılmaya bilinçli olarak izin verdiğinizde kullanın.`}},"plugins%2Eentries%2E*%2Ellm%2EallowModelOverride":{label:{"v1-1wtocu9-v":`Eklenti LLM Modelini Geçersiz Kılmaya İzin Ver`},help:{"v1-uw4jmc-47":`Bu eklentinin api.runtime.llm.complete içinde modeli geçersiz kılma isteğinde bulunmasına açıkça izin verir. Model seçimini yönlendirmesi için eklentiye güvenilmiyorsa false olarak bırakın.`}},"plugins%2Eentries%2E*%2Esubagent":{label:{"v1-1dea8kh-m":`Eklenti Alt Ajan Politikası`},help:{"v1-wbf4m1-4d":`Modeli geçersiz kılma güveni ve izin listeleri için eklenti bazında alt ajan çalışma zamanı denetimleri. Bir eklentinin alt ajan model seçimini açıkça yönlendirmesi gerekmiyorsa bunu ayarlamayın.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowedModels":{label:{"v1-1axw70h-u":`Eklenti Alt Ajanı için İzin Verilen Modeller`},help:{"v1-2pvkow-42":`Güvenilen eklentilerin alt ajan çalıştırmalarında modeli geçersiz kılmak için izin verilen hedefler; standart "provider/model" referansları olarak belirtilir. "*" değerini yalnızca herhangi bir modele bilinçli olarak izin verdiğinizde kullanın.`}},"plugins%2Eentries%2E*%2Esubagent%2EallowModelOverride":{label:{"v1-1wes28b-10":`Eklenti Alt Ajan Modelini Geçersiz Kılmaya İzin Ver`},help:{"v1-1r5tzm1-4g":`Bu eklentinin arka plandaki alt ajan çalıştırmalarında sağlayıcı/model geçersiz kılmaları istemesine açıkça izin verir. Model seçimini yönlendirme konusunda eklentiye güvenilmiyorsa false olarak bırakın.`}},"plugins%2Eload":{label:{"v1-9stn89-d":`Eklenti Yükleyicisi`},help:{"v1-1myjwbi-52":`Eklentilerin keşfedileceği dosya sistemi yollarını belirtmek için kullanılan eklenti yükleyicisi yapılandırma grubu. Güvenilmeyen uzantıların yanlışlıkla yüklenmesini önlemek için yükleme yollarını açıkça belirtin ve gözden geçirin.`}},"plugins%2Eload%2Epaths":{label:{"v1-nk4cri-h":`Eklenti Yükleme Yolları`},help:{"v1-o689p1-4z":`Yükleyicinin yerleşik varsayılanlara ek olarak taradığı eklenti dosyaları veya dizinleri. Uzantılara özel dizinler kullanın ve ilgisiz yürütülebilir içerik barındıran geniş kapsamlı yollardan kaçının.`}},"plugins%2Eslots":{label:{"v1-oamycb-c":`Eklenti Yuvaları`},help:{"v1-zx6crl-5f":`Bellek gibi özel çalışma zamanı yuvalarının hangi eklentilere ait olacağını seçerek her bir yeteneğin yalnızca tek bir eklenti tarafından sağlanmasını sağlar. Çakışan davranışlara sahip sağlayıcıların örtüşmesini önlemek için yuva sahipliğini açıkça belirtin.`}},"plugins%2Eslots%2EcontextEngine":{label:{"v1-1371nb9-l":`Bağlam Motoru Eklentisi`},help:{"v1-4v13iw-2t":`Etkin bağlam motoru eklentisini kimliğine göre seçerek bağlam düzenleme işlevinin tek bir eklenti tarafından sağlanmasını sağlar.`}},"plugins%2Eslots%2Ememory":{label:{"v1-1948lbp-d":`Bellek Eklentisi`},help:{"v1-80ngcl-23":`Etkin bellek eklentisini kimliğine göre seçin veya bellek eklentilerini devre dışı bırakmak için "none" kullanın.`}},presence:{label:{"v1-10fdwo4-8":`Çevrimiçi Durumu`}},proxy:{label:{"v1-ji57pa-d":`Yönetilen Proxy`},help:{"v1-vui6bx-58":`OpenClaw çalışma zamanındaki HTTP, HTTPS, WebSocket ve desteklenen ham çıkış yolları için operatör tarafından yönetilen ileri proxy yönlendirmesi. Merkezi çıkış denetimi dağıtım sınırının bir parçası olduğunda bunu kullanın.`}},"proxy%2Eenabled":{label:{"v1-8i199z-l":`Yönetilen Proxy Etkin`},help:{"v1-1456xdw-49":`Yönetilen proxy için açık geçersiz kılma ayarı. URL'nin mevcut olması yönlendirmeyi varsayılan olarak etkinleştirir; yapılandırılmış veya ortamda tanımlanmış proxy URL'lerini silmeden yok saymak için false olarak ayarlayın.`}},"proxy%2EloopbackMode":{label:{"v1-1y356w6-r":`Yönetilen Proxy Geri Döngü Modu`},help:{"v1-1kaiuh0-3c":`Yönetilen proxy modu etkinken Gateway geri döngü kontrol düzlemi yönlendirmesini denetler: "gateway-only", "proxy" veya "block".`}},"proxy%2EproxyUrl":{label:{"v1-b5s3c3-h":`Yönetilen Proxy URL'si`},help:{"v1-p36b5l-3v":`Yönetilen ileri proxy URL'si. Düz bir CONNECT proxy için http://, proxy uç noktasına yapılan bağlantının kendisi TLS kullanmak zorundaysa https:// kullanın.`}},"proxy%2Etls":{label:{"v1-qr3npv-h":`Yönetilen Proxy TLS`},help:{"v1-6i0vu-3q":`Yönetilen proxy uç noktasına bağlanırken kullanılan TLS ayarları. Bu ayarlar, CONNECT sonrasındaki hedef TLS bağlantısına değil, proxy TLS bağlantısına uygulanır.`}},"proxy%2Etls%2EcaFile":{label:{"v1-1mel3ux-p":`Yönetilen Proxy TLS CA Dosyası`},help:{"v1-1ntzjia-2p":`HTTPS kullanan yönetilen proxy uç noktasının sertifikasını doğrulamak için kullanılan özel CA paketinin dosya sistemi yolu.`}},secrets:{label:{"v1-1sihgpy-7":`Gizli Bilgiler`},help:{"v1-jgn0o9-2l":`Gizli bilgi başvurusu sağlayıcıları, paylaşılan depo davranışı ve isteğe bağlı alt süreç çıkış koruması.`}},"secrets%2EegressProxy":{label:{"v1-ni0kq4-j":`Gizli Bilgi Çıkış Proxy'si`},help:{"v1-1qfgid-4n":`Paylaşılan depodaki gizli bilgi yer tutucularını yalnızca giden istek sırasında değiştiren, Gateway'e ait geri döngü proxy'si. Başlangıçta uygulanan bu bölümü değiştirdikten sonra Gateway'i yeniden başlatın.`}},"secrets%2EegressProxy%2EallowedHosts":{label:{"v1-1jt4jwf-x":`Gizli Bilgi Çıkış Proxy'si İçin İzin Verilen Ana Makineler`},help:{"v1-9ypodl-6t":`İstekler ve CONNECT tünelleri için isteğe bağlı trafik izin listesi. Tanımlandığında hedefler bu listede, gizli bilgiye özel bir ana makine bağlamasında veya bypassHosts içinde yer almalıdır. Boş bir liste yalnızca bağlanmış veya atlama kapsamındaki ana makinelere izin verir. Değişiklik yaptıktan sonra Gateway'i yeniden başlatın.`}},"secrets%2EegressProxy%2EbypassHosts":{label:{"v1-1keo1yv-w":`Gizli Bilgi Çıkış Proxy'sini Atlayan Ana Makineler`},help:{"v1-1oiiomv-57":`Sertifika sabitlemesi kullanan istemciler için kimliği doğrulanmış kör CONNECT tünellerini kullanan tam ana makine adları. İşaretçi değerler şifreli metin olarak kalır ve düz metni açığa çıkarmak yerine sağlayıcı kimlik doğrulamasının başarısız olmasına neden olur.`}},"secrets%2EegressProxy%2Eenabled":{label:{"v1-ugzvlx-r":`Gizli Bilgi Çıkış Proxy'si Etkin`},help:{"v1-u99b1i-2h":`Gateway üzerinde barındırılan aracı alt süreçleri için çıkış trafiğinde gizli bilgi ikamesini etkinleştirir. Varsayılan: false.`}},session:{label:{"v1-8yh9jr-7":`Oturum`},help:{"v1-j86s32-5d":`Konuşma geçmişinin davranışına yönelik genel oturum yönlendirme, sıfırlama, iletim ilkesi ve bakım denetimleri. Daha sıkı yalıtım, saklama veya iletim kısıtlamalarına ihtiyacınız yoksa varsayılanları koruyun.`}},"session%2EdmScope":{label:{"v1-ukjin6-g":`DM Oturum Kapsamı`},help:{"v1-ql362c-5l":`DM oturum kapsamı: "main" sürekliliği korurken "per-peer", "per-channel-peer" ve "per-account-channel-peer" yalıtımı artırır. Paylaşılan gelen kutuları veya çok hesaplı dağıtımlar için yalıtılmış modları kullanın.`}},"session%2EgroupScope":{label:{"v1-7kncqs-j":`Grup Oturum Kapsamı`},help:{"v1-1fdezx2-6i":`Grup/kanal oturum kapsamı: "per-group", odaları ayrı tutarken aracının ana oturumu dmScope'tan bağımsız olarak onları arka planda izler; "main", oda bağlamını ana oturumla birleştirir ve izleme gerektirmez. "main" seçeneğini yalnızca güvenilir odalar için kullanın.`}},"session%2EidentityLinks":{label:{"v1-b28nnm-m":`Oturum Kimliği Bağlantıları`},help:{"v1-1y5jnsm-5n":`Aynı kullanıcıların tek bir doğrudan mesaj dizisinde birleştirilmesi için temel kimlikleri sağlayıcı öneki taşıyan eş kimlikleriyle eşler (örnek: telegram:123456). Aynı kişi birden fazla kanalda veya hesapta yer alıyorsa bunu kullanın.`}},"session%2EmainKey":{label:{"v1-r57g0n-g":`Oturum Ana Anahtarı`},help:{"v1-18p638h-3q":`Kabul edilir ancak yok sayılır: aracı başına ana oturum son eki her zaman "main" olur. Bu alanı belirtmeyin; genel oturum kapsamında bunun yerine "global" kullanılır.`}},"session%2Emaintenance":{label:{"v1-p1iywg-j":`Oturum Bakımı`},help:{"v1-imr441-66":`Pano oturumlarını arşivleme, eski kayıtları temizleme süresi, kayıt sınırları, sıfırlama arşivlerini saklama ve disk bütçesi temizliği için otomatik oturum deposu bakım denetimleri. Etkisini gözlemlemek için warn modunda başlayın, ardından eşikler ayarlandığında enforce moduna geçin.`}},"session%2Emaintenance%2EarchiveDashboardAfter":{label:{"v1-1ok5zsl-15":`Etkin Olmayan Pano Oturumlarını Arşivleme Süresi`},help:{"v1-1frdtub-5n":"Etkin olmayan pano oturumlarını bu süre sonunda (örneğin `7d`) arşivler; böylece etkin oturum listesini kalabalıklaştırmadan erişilebilir kalırlar. Otomatik pano arşivlemesini devre dışı bırakmak için `false` veya `0` olarak ayarlayın."}},"session%2Emaintenance%2EcoldStorage":{label:{"v1-353bpe-n":`Transkript Soğuk Depolaması`},help:{"v1-1kp9s9h-5s":`Etkin olmayan transkriptleri, oturum meta verilerini koruyarak sıkıştırılmış JSONL arşivlerine taşır. Arşiv dosyaları geçmişin gerekli bir parçası hâline gelir ve yedeklemelere dahil edilmelidir. Değişiklikler Gateway yeniden başlatılmadan uygulanır.`}},"session%2Emaintenance%2EcoldStorage%2EafterDays":{label:{"v1-1ay0en7-r":`Arşivleme İçin Gereken Etkin Olmayan Gün Sayısı`},help:{"v1-zay1q3-5b":`Bu kadar gün etkin olmayan transkriptleri arşivler (pozitif tam sayı, varsayılan 30). Etkin çalışmalar korunur; eşik değişikliği, Gateway yeniden başlatılmadan arka plan görevinin bir sonraki çalışmasında geçerli olur.`}},"session%2Emaintenance%2EcoldStorage%2Eenabled":{label:{"v1-85gcoy-11":`Eski Transkriptleri Otomatik Olarak Arşivle`},help:{"v1-6p6vmb-5a":`Konuşma dökümlerinin arka planda arşivlenmesini etkinleştirir (varsayılan: false). Bir arka plan görevi, arşivlenmeye uygun dökümleri her dakika kontrol eder. Bu açıkça tanımlanmış arşivleme ilkesi, silme ve disk bütçesi temizliğinden ayrıdır.`}},"session%2Emaintenance%2EhighWaterBytes":{label:{"v1-1t9qv0z-u":`Oturum Disk Kullanımı Üst Sınır Hedefi`},help:{"v1-143vh09-7z":`Disk bütçesi temizliğinden sonraki hedef boyut (üst sınır). Varsayılan olarak maxDiskBytes değerinin %80'idir; kısıtlı disklerde daha fazla alan geri kazanmak için açıkça ayarlayın. Sıfır olarak çözümlenen bir değer, varsayılan değere geri döner; negatif değerler geçersizdir. Bütçeyi devre dışı bırakmak için bunun yerine maxDiskBytes kullanın.`}},"session%2Emaintenance%2EmaxDiskBytes":{label:{"v1-14omfzj-n":`Oturum İçin Maksimum Disk Bütçesi`},help:{"v1-147lxk3-cj":'SQLite ana/WAL dosyalarını ve hesaba katılan oturum dizini öğelerini kapsayan, ajan başına fiziksel disk bütçesi (örneğin `500mb`). Varsayılan değer `10gb`\'dir; korunan veriler kullanımı hedefin üzerinde tutabilir. Bütçe aşıldığında warn modu disk baskısını bildirir; enforce modu ise sırasıyla eski sıfırlama/silme öğelerini, başvurulmayan geçmişi ve sınır nedeniyle oluşturulan arşivleri kaldırır. Manuel arşivler, yaşa dayalı saklama arşivleri, gösterge paneli arşivleri, kurtarma arşivleri ve eski sistem arşivleri korunmaya devam eder. Devre dışı bırakmak için `false`, `0` veya `"0"` olarak ayarlayın.'}},"session%2Emaintenance%2EmaxEntries":{label:{"v1-1n4txc9-j":`Maksimum Oturum Kaydı Sayısı`},help:{"v1-1w2egrh-7u":`Arşivlenmemiş oturum kayıtlarının sayısını sınırlar (varsayılan 5000). Sınırı aşan ve arşivlenmeye uygun kalıcı konuşmalar, geçmişleriyle birlikte arşivlenir; geçici otomasyon kayıtları kaldırılır. Mevcut arşivler sınıra dahil edilmez. Korunan etkin kayıtlar sayılmaya devam eder ve depodaki kayıt sayısını sınırın üzerinde tutabilir.`}},"session%2Emaintenance%2Emode":{label:{"v1-fudr6r-o":`Oturum Bakım Modu`},help:{"v1-bq39hk-6v":`Budama ve disk bütçesi ilkelerinin yalnızca raporlanacağını mı ("warn") yoksa etkin olarak uygulanacağını mı ("enforce") belirler. Kademeli kullanıma alma sırasında "warn" değerini koruyun ve güvenli eşikleri doğruladıktan sonra "enforce" değerine geçin. Soğuk depolamanın kendi açıkça tanımlanmış enabled ayarı vardır.`}},"session%2Emaintenance%2EpreserveRecent":{label:{"v1-i6rkx1-o":`Son Oturumları Koru`},help:{"v1-138q5wx-89":"Bu süre içinde (örneğin `7d`) etkin olan etkileşimli oturumları, yaş, sayı ve disk bütçesi nedeniyle geçmişin otomatik olarak silinmesine karşı korur. Ayarlanmaması veya `false` olarak ayarlanması, normal en eskiyi önce silme politikasını korur. Sentetik model çalıştırma, cron, hook, heartbeat, ACP ve alt ajan satırları, sınırlandırılmış temizlemeye uygun olmaya devam eder."}},"session%2Emaintenance%2EpruneAfter":{label:{"v1-1hxlne1-j":`Oturum Temizleme Süresi`},help:{"v1-1xn50w7-76":"Bu süreden eski, arşivlenmeye uygun kalıcı konuşmaları arşivler ve geçici otomasyon kayıtlarını kaldırır (varsayılan `30d`; örneğin `12h`). Arşivlenen konuşmaların geçmişi korunur ve bu konuşmalar geri yüklenebilir; korunan veya yönlendirilebilir konuşmalar etkin kalır."}},"session%2Emaintenance%2EresetArchiveRetention":{label:{"v1-1k23ggw-v":`Oturum Sıfırlama Arşivi Saklama Süresi`},help:{"v1-16amrs1-7r":"Arşivlenmiş konuşma dökümleri (`*.reset.<timestamp>` ve `*.deleted.<timestamp>`) için yaşa dayalı saklama süresi. Varsayılan olarak arşivler, disk bütçesi nedeniyle en eskiden başlayarak kaldırılana kadar saklanır; geçen gerçek süreye göre silmeyi etkinleştirmek için bir süre (örneğin `30d`), açıkça devre dışı bırakmak için ise `false` ayarlayın."}},"session%2EnotifyOnCreate":{label:{"v1-19qwl5t-v":`Oturum Oluşturulduğunda Ana Sayfaya Bildir`},help:{"v1-c4prn5-8b":`Bir oturum oluşturulduğunda, oturumun sahibi olan ajanın Ana Sayfa oturumunda bir sistem bildirimini kuyruğa ekler (varsayılan: true). Bildirimler, mevcut başlık ve oluşturan kişiye ait meta verileri içerir ve bir sonraki Ana Sayfa turunda veya periyodik kontrolde okunur. Devre dışı bırakmak için false olarak ayarlayın; taslaklar, gizli oturumlar, dahili oturumlar ve zamanlanmış cron çalıştırmaları kapsam dışındadır.`}},"session%2Ereset":{label:{"v1-oh2sxm-k":`Oturum Sıfırlama İlkesi`},help:{"v1-1hmt7n3-6r":`Türe veya kanala özgü bir geçersiz kılma uygulanmadığında kullanılan varsayılan sıfırlama ilkesi nesnesini tanımlar. Varsayılan olarak oturumlar otomatik sıfırlanmaz; bunu etkinleştirmek için günlük veya boşta kalma temelli zamanlamaları kullanın. /new ve /reset her zaman kullanılabilir.`}},"session%2Ereset%2EatHour":{label:{"v1-3sjhvl-o":`Oturumun Günlük Sıfırlanma Saati`},help:{"v1-wry8cv-59":`Oturumların öngörülebilir zamanlarda yenilenmesi için günlük sıfırlama modunun yerel saat sınırını (0-23) ayarlar. mode=daily ile kullanın ve davranışın kolay anlaşılması için operatörün saat dilimi beklentileriyle uyumlu hale getirin.`}},"session%2Ereset%2EidleMinutes":{label:{"v1-yoxr77-q":`Oturum Sıfırlama İçin Boşta Kalma Süresi (Dakika)`},help:{"v1-1kzj0id-5e":`Boşta kalma modunda sıfırlamadan önceki hareketsizlik süresini ayarlar; günlük modda ek bir koruma olarak da kullanılabilir. Sürekliliği korumak için daha büyük, kısa ömürlü konuşmaları daha sık yenilemek için daha küçük değerler kullanın.`}},"session%2Ereset%2Emode":{label:{"v1-ern6ub-i":`Oturum Sıfırlama Modu`},help:{"v1-e5ie4w-5b":`Sıfırlama stratejisini seçer: "none" otomatik sıfırlamayı devre dışı bırakır (varsayılan), "daily" yapılandırılan saatte sıfırlar ve "idle" hareketsizlik sonrasında sıfırlar. /new ve /reset her modda kullanılabilir.`}},"session%2EresetByChannel":{label:{"v1-xmfipi-o":`Kanala Göre Oturum Sıfırlama`},help:{"v1-1uxsulx-5h":`Davranışı ayrıntılı olarak kontrol etmek için sağlayıcı/kanal kimliğiyle anahtarlanan, kanala özgü sıfırlama geçersiz kılmaları sağlar. Bunu yalnızca bir kanal, tür düzeyindeki politikaların ötesinde özel bir sıfırlama davranışı gerektiriyorsa kullanın.`}},"session%2EresetByType":{label:{"v1-1pqdf9f-q":`Sohbet Türüne Göre Oturum Sıfırlama`},help:{"v1-ypdr7u-52":`Varsayılanlar yeterli olmadığında sohbet türüne (direct, group, thread) göre sıfırlama davranışını geçersiz kılar. Grup veya konu trafiği, doğrudan mesajlardan farklı bir sıfırlama sıklığı gerektirdiğinde bunu kullanın.`}},"session%2EresetByType%2Edirect":{label:{"v1-ysq32o-m":`Oturum Sıfırlama (Doğrudan)`},help:{"v1-fjnlp5-56":`Doğrudan sohbetler için sıfırlama politikasını tanımlar ve bu tür için temel session.reset yapılandırmasının yerine geçer. Eski dm takma adı yerine, doğrudan mesajlar için standart geçersiz kılma ayarı olarak bunu kullanın.`}},"session%2EresetByType%2Egroup":{label:{"v1-kpfypy-l":`Oturum Sıfırlama (Grup)`},help:{"v1-hl1200-4u":`Süreklilik ve gürültü örüntülerinin doğrudan mesajlardan farklı olduğu grup sohbeti oturumları için sıfırlama politikasını tanımlar. Bağlam kayması sorun hâline gelirse yoğun gruplar için daha kısa hareketsizlik süreleri kullanın.`}},"session%2EresetByType%2Ethread":{label:{"v1-1jznvzn-m":`Oturum Sıfırlama (Konu)`},help:{"v1-1hgpeke-4w":`Belirli kanal konularına odaklanan iş akışları da dahil olmak üzere, konu kapsamındaki oturumlar için sıfırlama politikasını tanımlar. Konu oturumlarının diğer sohbet türlerinden daha erken veya daha geç sona ermesi gerektiğinde bunu kullanın.`}},"session%2EresetTriggers":{label:{"v1-k9d2el-m":`Oturum Sıfırlama Tetikleyicileri`},help:{"v1-rcabsw-5a":`Gelen içerikle eşleştiğinde oturumu zorunlu olarak sıfırlayan mesaj tetikleyicilerini listeler. Normal konuşma sırasında bağlamın beklenmedik şekilde kaybolmaması için yalnızca açık sıfırlama ifadeleriyle ve sınırlı olarak kullanın.`}},"session%2Escope":{label:{"v1-1j9i0l7-d":`Oturum Kapsamı`},help:{"v1-axt4ds-5z":`Temel oturum gruplama stratejisini belirler: "per-sender" gönderene göre ayırır, "global" ise her kanal bağlamında tek bir oturumu paylaşır. Özellikle paylaşılan bir bağlam gerekmiyorsa daha güvenli çok kullanıcılı işleyiş için "per-sender" seçeneğini koruyun.`}},"session%2EsendPolicy":{label:{"v1-1nxtvjb-j":`Oturum Gönderim Politikası`},help:{"v1-17qpipb-5l":`channel, chatType ve anahtar öneklerine göre değerlendirilen izin verme/reddetme kurallarıyla oturumlar arası gönderim izinlerini kontrol eder. Karmaşık ortamlarda oturum araçlarının mesaj gönderebileceği yerleri sınırlamak için bunu kullanın.`}},"session%2EsendPolicy%2Edefault":{label:{"v1-17hik48-y":`Oturum Gönderim Politikası Varsayılan Eylemi`},help:{"v1-15plhut-53":`Hiçbir sendPolicy kuralı eşleşmediğinde uygulanacak eylemi belirler: "allow" veya "deny". Daha basit kurulumlarda "allow" seçeneğini koruyun; her hedef için açık izin kuralları gerekiyorsa "deny" seçeneğini belirleyin.`}},"session%2EsendPolicy%2Erules":{label:{"v1-uomm0w-p":`Oturum Gönderim Politikası Kuralları`},help:{"v1-o217za-5h":'Varsayılan eylemden önce değerlendirilen sıralı izin verme/reddetme kurallarıdır; örneğin `{ action: "deny", match: { channel: "discord" } }`. Genel kuralların istisnaları geçersiz kılmaması için en özel kuralları ilk sıraya koyun.'}},"session%2EsendPolicy%2Erules%5B%5D%2Eaction":{label:{"v1-sk8rxf-o":`Oturum Gönderim Kuralı Eylemi`},help:{"v1-178vm80-54":`İlgili eşleşme ölçütleri karşılandığında kural kararını "allow" veya "deny" olarak tanımlar. Açık izin istisnalarıyla katı sınırlar uygularken önce reddetme kurallarını sıralayın.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch":{label:{"v1-i5lkne-n":`Oturum Gönderim Kuralı Eşleşmesi`},help:{"v1-18qh5qg-5d":`channel, chatType ve anahtar öneki kısıtlamalarını birleştirebilen isteğe bağlı kural eşleşme koşullarını tanımlar. Politikanın amacı anlaşılır kalsın ve hata ayıklama kolay olsun diye eşleşmeleri dar kapsamlı tutun.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2Echannel":{label:{"v1-dti9lk-p":`Oturum Gönderim Kuralı Kanalı`},help:{"v1-u5erwx-50":`Kuralın uygulanmasını belirli bir kanal/sağlayıcı kimliğiyle (örneğin discord, telegram, slack) eşleştirir. Bir kanalın diğerlerinden bağımsız olarak iletime izin vermesi veya iletimi reddetmesi gerektiğinde bunu kullanın.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EchatType":{label:{"v1-dod3v9-r":`Oturum Gönderim Kuralı Sohbet Türü`},help:{"v1-7cv4f9-4z":`Davranışın konuşma biçimine göre değişmesi için kuralın uygulanmasını sohbet türüyle (direct, group, thread) eşleştirir. Doğrudan mesaj ve grup hedefleri farklı güvenlik sınırları gerektirdiğinde bunu kullanın.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2EkeyPrefix":{label:{"v1-145jj50-s":`Oturum Gönderim Kuralı Anahtar Öneki`},help:{"v1-ac4dee-5n":`Politikayı kullanan bileşenlerdeki dahili anahtar normalleştirme adımlarından sonra normalleştirilmiş bir oturum anahtarı önekiyle eşleştirir. Genel önek denetimleri için bunu kullanın; tam anahtarın birebir eşleşmesi gerektiğinde rawKeyPrefix seçeneğini tercih edin.`}},"session%2EsendPolicy%2Erules%5B%5D%2Ematch%2ErawKeyPrefix":{label:{"v1-9eqaoe-w":`Oturum Gönderim Kuralı Ham Anahtar Öneki`},help:{"v1-1g9w044-5e":`İlkeyi tam anahtara göre kesin olarak hedeflemek için ham, normalleştirilmemiş oturum anahtarı önekiyle eşleşir. Normalleştirilmiş keyPrefix çok geniş kapsamlı olduğunda ve aracı önekine veya aktarım türüne özgü hassasiyet gerektiğinde bunu kullanın.`}},"session%2Esharing":{label:{"v1-ua4axr-l":`Oturum Paylaşım Modları`},help:{"v1-xbh52d-5a":`Oturum sahiplerinin ve yöneticilerin hangi iş birliği modlarını seçebileceğini denetler. Belirtilmeyen boole değerleri varsayılan olarak etkin kabul edilir; bir modu seçiciden kaldırmak ve yeni seçimleri reddetmek için false olarak ayarlayın.`}},"session%2Esharing%2Edrafts":{label:{"v1-egpd9a-k":`Taslak Oturumlara İzin Ver`},help:{"v1-1lzap27-2p":`Oturumları, oturum sahibi veya yönetici olmayan operatörlerden gizleyen taslak görünürlüğüne izin verir. Varsayılan: true.`}},"session%2Esharing%2EreadOnly":{label:{"v1-wl9bhk-o":`Salt Okunur Oturumlara İzin Ver`},help:{"v1-upl3nu-21":`Oturumların katılımcı olmayanlar için salt okunur hale getirilmesine izin verir. Varsayılan: true.`}},"session%2Esharing%2Esuggest":{label:{"v1-1a87tux-m":`Öneri Modundaki Oturumlara İzin Ver`},help:{"v1-4i8owu-4g":`Öneri görünürlüğüne izin verir. Bu aşamada salt okunur moduyla aynı kabul ilkesini uygular; öneri kuyrukları daha sonra sunulacak bir özellikle yapılandırılır. Varsayılan: true.`}},"session%2Estore":{label:{"v1-1udxgtl-i":`Oturum Depolama Yolu`},help:{"v1-hreznz-56":`Oturum kayıtlarını yeniden başlatmalar arasında korumak için kullanılan oturum depolama dosyasının yolunu ayarlar. Yalnızca özel disk düzenine, yedekleme yönlendirmesine veya bağlı bir birimde depolamaya ihtiyaç duyduğunuzda açık bir yol belirtin.`}},"session%2EthreadBindings":{label:{"v1-hldn3x-n":`Oturum Konu Bağlamaları`},help:{"v1-zbzihu-4s":`Desteklenen kanallarda ileti dizisine bağlı oturum oluşturma ve yönlendirme için ortak varsayılanlar. Genel varsayılanları burada yapılandırın ve yalnızca davranış farklı olduğunda kanal bazında geçersiz kılın.`}},"session%2EthreadBindings%2EdefaultSpawnContext":{label:{"v1-yj4mot-k":`İleti Dizisinde Oluşturma Bağlamı`},help:{"v1-1set6nw-4c":`İleti dizisine bağlı oluşturma işlemleri için varsayılan yerel alt ajan bağlamı. İstekte bulunanın konuşma dökümünden başlamak için "fork", temiz bir alt oturum için "isolated" kullanın. Varsayılan: "fork".`}},"session%2EthreadBindings%2Eenabled":{label:{"v1-15vicbp-m":`İleti Dizisine Bağlama Etkin`},help:{"v1-foomtc-3f":`İleti dizisine bağlı oturum oluşturma, yönlendirme ve teslim için genel ana anahtar. İleti dizisine bağlamayı genel olarak kapatmak için devre dışı bırakın.`}},"session%2EthreadBindings%2EidleHours":{label:{"v1-frd27j-z":`İleti Dizisine Bağlama Boşta Kalma Zaman Aşımı (saat)`},help:{"v1-gffnx3-3h":`Sağlayıcılar/kanallar genelinde ileti dizisine bağlı oturumlar için saat cinsinden varsayılan hareketsizlik süresi (0, hareketsizlik nedeniyle sona ermeyi devre dışı bırakır). Varsayılan: 24.`}},"session%2EthreadBindings%2EmaxAgeHours":{label:{"v1-1pyqt5n-u":`İleti Dizisine Bağlama Azami Süresi (saat)`},help:{"v1-1xfcyhw-39":`Sağlayıcılar/kanallar genelinde ileti dizisine bağlı oturumlar için saat cinsinden isteğe bağlı kesin azami süre (0, kesin üst sınırı devre dışı bırakır). Varsayılan: 0.`}},"session%2EthreadBindings%2EspawnSessions":{label:{"v1-hsfsa4-r":`İleti Dizisine Bağlı Oturum Oluşturma`},help:{"v1-1lqwbdl-46":`sessions_spawn ve ACP ileti dizisi oluşturma işlemlerinden ileti dizisine bağlı çalışma oturumları oluşturmak için genel varsayılan izin ayarı. Varsayılan: ileti dizisine bağlama etkin olduğunda true.`}},skills:{label:{"v1-1bk7xrz-6":`Skills`}},"skills%2Eload%2EallowSymlinkTargets":{label:{"v1-i5s6ov-t":`İzin Verilen Beceri Sembolik Bağlantı Hedefleri`},help:{"v1-xzybiq-4t":`Beceri sembolik bağlantılarının, yapılandırılmış kaynak köklerinin dışına işaret ettiklerinde çözümlenmesine izin verilen güvenilir gerçek hedef kökleri. Bu kapsamı dar tutun; örneğin, aynı üst dizindeki bir deponun beceri diziniyle sınırlayın.`}},"skills%2Eload%2EextraDirs":{label:{"v1-1ufjbnf-n":`Ek Beceri Dizinleri`},help:{"v1-11o7opu-53":`En düşük öncelikle taranacak ek paylaşılan beceri kökleri. Bunu, OpenClaw çalışma alanına kopyalanmadan kullanılabilmesi gereken aynı üst dizindeki depolar veya paylaşılan beceri paketleri için kullanın.`}},"skills%2Eload%2Ewatch":{label:{"v1-fhhyqq-c":`Skills Değişikliklerini İzle`},help:{"v1-1ckr2l5-5d":`Güncellemelerin süreç tamamen yeniden başlatılmadan uygulanabilmesi için beceri tanımı değişikliklerini dosya sistemi üzerinden izlemeyi etkinleştirin. Geliştirme iş akışlarında etkin tutun ve değiştirilemez üretim imajlarında devre dışı bırakın.`}},"skills%2Eworkshop%2Eautonomous%2Emode":{label:{"v1-1hrc7h4-u":`Skill Workshop Otonom Modu`},help:{"v1-1s3kgit-6j":`Arka planda öğrenmeyi kontrol eder: "off" yalnızca öneri hatırlatmasını korur, "propose" bekleyen öneriler oluşturur, "auto" ise kaydedilen önerileri uygular ve Workshop'a ait becerileri normal dosya düzenlemeleriyle haftalık olarak gözden geçirir. Varsayılan: "auto".`}},surfaces:{label:{"v1-exl2ye-g":`Yüzey Politikaları`},help:{"v1-vgtjbs-50":`Çözümlenen teslimat yüzeyi kimliğine göre anahtarlanmış, yüzey bazında mesaj politikası geçersiz kılmaları. Bunu yalnızca dağıtıma alınmış bir yüzeyin, ajanın varsayılanına göre daha katı sessiz yanıt işleme kurallarına ihtiyaç duyduğu durumlarda kullanın.`}},"surfaces%2E*%2EsilentReply":{label:{"v1-1n816d1-r":`Yüzey Sessiz Yanıt Politikası`},help:{"v1-12zgc3n-60":`Çözümlenen tek bir teslimat yüzeyi için sessiz yanıt politikasını geçersiz kılar. Ayarlanmamış alanlar agents.defaults.silentReply değerlerini devralır; dahili veya gruba özgü davranışların diğer hedeflere yayılmaması için dar kapsamlı yüzey kimlikleri kullanın.`}},talk:{label:{"v1-15ukbjj-4":`Konuşma`},help:{"v1-1gx10xa-5g":`Ses kimliği, model seçimi, çıktı biçimi ve kesinti davranışı için konuşma modu ses sentezi ayarları. Gecikmeyi ve maliyeti kontrol altında tutarken kullanıcıya yönelik ses deneyimini ayarlamak için bu bölümü kullanın.`}},"talk%2EagentId":{label:{"v1-17bcfby-a":`Konuşma Aracısı`},help:{"v1-iee5l9-2b":`Açıkça belirtilmiş, aracı kapsamlı bir oturum anahtarı olmadan oluşturulan konuşma oturumlarının sahibi olan aracı.`}},"talk%2EconsultFastMode":{label:{"v1-12natsq-m":`Konuşma Danışması Hızlı Modu`},help:{"v1-syf3xk-2o":`Gerçek zamanlı konuşma danışmalarının arkasında yürütülen normal aracı çalışması için hızlı modu true veya false olarak ayarlamak üzere bunu kullanın.`}},"talk%2EconsultThinkingLevel":{label:{"v1-f04pev-r":`Konuşma Danışması Düşünme Düzeyi`},help:{"v1-1ft5njw-2o":`Gerçek zamanlı konuşma danışmalarının arkasında yürütülen normal aracı çalışmasının düşünme düzeyini geçersiz kılmak için bunu kullanın.`}},"talk%2EinterruptOnSpeech":{label:{"v1-12q9u31-o":`Konuşma Modunda Söz Kesme`},help:{"v1-8n9q4o-3l":`true ise (varsayılan), kullanıcı konuşma modunda konuşmaya başladığında asistanın konuşmasını durdurur. Karşılıklı konuşmada sırayla söz almak için etkin tutun.`}},"talk%2Eprovider":{label:{"v1-1y50zho-k":`Etkin Konuşma Sağlayıcısı`},help:{"v1-wgnxhg-1g":`Etkin konuşma sağlayıcısının kimliği (örneğin "acme-speech").`}},"talk%2Eproviders":{label:{"v1-1ifkkv5-m":`Konuşma Sağlayıcısı Ayarları`},help:{"v1-oh0yuv-30":`Sağlayıcı kimliğine göre anahtarlanmış, sağlayıcıya özgü konuşma ayarları. Geçiş sırasında eski talk.* anahtarları yerine bunu tercih edin.`}},"talk%2Eproviders%2E*":{label:{"v1-1bo3c2y-k":`Konuşma Sağlayıcısı Yapılandırması`},help:{"v1-36pblg-1r":`Eşleşen sağlayıcı kimliği için sağlayıcıya ait konuşma yapılandırma alanları.`}},"talk%2Eproviders%2E*%2EapiKey":{label:{"v1-ln76q3-l":`Konuşma Sağlayıcısı API Anahtarı`},help:{"v1-1a1p9wp-v":`Konuşma modu için sağlayıcı API anahtarı.`}},"talk%2Erealtime":{label:{"v1-xsdfxg-d":`Gerçek Zamanlı Talk`},help:{"v1-c2re7j-3z":`Gerçek zamanlı Talk sağlayıcısı, modeli, sesi, modu, aktarım yöntemi ve akıl yürütme stratejisi. Konuşma/TTS sağlayıcısı yapılandırmasını talk.provider ve talk.providers içinde tutun.`}},"talk%2Erealtime%2Ebrain":{label:{"v1-7nqi8o-j":`Gerçek Zamanlı Talk Akıl Yürütmesi`},help:{"v1-opsatw-37":`Talk akıl yürütme stratejisi: Gateway aracılığıyla ajan yardımı için agent-consult, yerel araç çağrıları için direct-tools veya none.`}},"talk%2Erealtime%2EconsultRouting":{label:{"v1-1nxl3sq-t":`Gerçek Zamanlı Talk Danışma Yönlendirmesi`},help:{"v1-10qjcvk-5f":`Gerçek zamanlı sağlayıcı openclaw_agent_consult çağrısını atladığında, kullanıcının kesinleşmiş konuşma dökümleri için yedek Gateway aktarımı. provider-direct sağlayıcı yanıtlarını korur; force-agent-consult OpenClaw üzerinden yönlendirir.`}},"talk%2Erealtime%2Einstructions":{label:{"v1-1aogivp-q":`Gerçek Zamanlı Talk Talimatları`},help:{"v1-1jaaj84-5p":`OpenClaw'ın yerleşik gerçek zamanlı Talk istemine eklenen sistem talimatları. agent-consult yönergelerini değiştirmeden ses tarzını, tonunu ve sağlayıcıya yönelik diğer gerçek zamanlı davranışları belirlemek için bunu kullanın.`}},"talk%2Erealtime%2Emode":{label:{"v1-1ulyfkf-i":`Gerçek Zamanlı Talk Modu`},help:{"v1-1u2xui1-1l":`Talk çalışma modu: realtime, stt-tts veya transcription.`}},"talk%2Erealtime%2Emodel":{label:{"v1-3tgxll-j":`Gerçek Zamanlı Talk Modeli`},help:{"v1-amou5a-27":`Tarayıcı veya Gateway tarafından yönetilen Talk oturumlarında gerçek zamanlı sağlayıcının varsayılan model kimliğinin yerine kullanılacak değer.`}},"talk%2Erealtime%2EprefixPaddingMs":{label:{"v1-1n2zx1c-x":`Gerçek Zamanlı Talk Ön Ses Payı (ms)`},help:{"v1-1cwg07n-22":`Gerçek zamanlı ses etkinliği algılanmadan önce saklanan sesin milisaniye cinsinden süresi.`}},"talk%2Erealtime%2Eprovider":{label:{"v1-13pps61-m":`Gerçek Zamanlı Talk Sağlayıcısı`},help:{"v1-wwsmpt-1o":`openai veya google gibi etkin gerçek zamanlı ses sağlayıcısının kimliği.`}},"talk%2Erealtime%2Eproviders":{label:{"v1-zi8arq-v":`Talk Gerçek Zamanlı Sağlayıcı Ayarları`},help:{"v1-ruagcu-1r":`Sağlayıcı kimliğine göre anahtarlanmış, sağlayıcıya özel gerçek zamanlı ses ayarları.`}},"talk%2Erealtime%2Eproviders%2E*":{label:{"v1-n5oah5-t":`Talk Gerçek Zamanlı Sağlayıcı Yapılandırması`},help:{"v1-edfpxm-1u":`Eşleşen sağlayıcı kimliği için sağlayıcıya ait gerçek zamanlı ses yapılandırması.`}},"talk%2Erealtime%2Eproviders%2E*%2EapiKey":{label:{"v1-1kd7m42-u":`Talk Gerçek Zamanlı Sağlayıcı API Anahtarı`},help:{"v1-1fbmgpx-z":`Gerçek zamanlı Talk için sağlayıcı API anahtarı.`}},"talk%2Erealtime%2EreasoningEffort":{label:{"v1-1cxnmcm-u":`Talk Gerçek Zamanlı Akıl Yürütme Çabası`},help:{"v1-157xd3e-2t":`Gerçek zamanlı Talk oturumları için minimal, low, medium veya high gibi sağlayıcıya özel akıl yürütme çabası.`}},"talk%2Erealtime%2EsilenceDurationMs":{label:{"v1-190chw8-z":`Talk Gerçek Zamanlı Sessizlik Süresi (ms)`},help:{"v1-1grnu06-1y":`Gerçek zamanlı Talk oturumunda kullanıcının konuşma sırasının tamamlandığı kabul edilmeden önce beklenecek sessizlik süresi (milisaniye).`}},"talk%2Erealtime%2EspeakerVoice":{label:{"v1-hgae7v-r":`Talk Gerçek Zamanlı Konuşmacı Sesi`},help:{"v1-1kgb166-2h":`Tarayıcı veya Gateway tarafından yönetilen Talk oturumlarında gerçek zamanlı sağlayıcının varsayılan konuşmacı sesi adı yerine kullanılacak ad.`}},"talk%2Erealtime%2EspeakerVoiceId":{label:{"v1-10l8f2s-u":`Talk Gerçek Zamanlı Konuşmacı Sesi Kimliği`},help:{"v1-1k8w6vk-2f":`Tarayıcı veya Gateway tarafından yönetilen Talk oturumlarında gerçek zamanlı sağlayıcının varsayılan konuşmacı sesi kimliği yerine kullanılacak kimlik.`}},"talk%2Erealtime%2Etransport":{label:{"v1-1mlwsll-n":`Talk Gerçek Zamanlı İletim`},help:{"v1-2otjgn-2g":`Talk bayt/oturum aktarımı: webrtc, provider-websocket, gateway-relay veya managed-room.`}},"talk%2Erealtime%2EvadThreshold":{label:{"v1-1plwtg4-r":`Talk Gerçek Zamanlı VAD Eşiği`},help:{"v1-nf5l2t-2j":`0 (en hassas) ile 1 (en az hassas) arasında gerçek zamanlı ses etkinliği algılama eşiği.`}},"talk%2EsilenceTimeoutMs":{label:{"v1-q6e4ju-p":`Talk Sessizlik Zaman Aşımı (ms)`},help:{"v1-1kim32f-59":`Talk modunun mevcut konuşma dökümünü tamamlayıp göndermesi için kullanıcının sessiz kalması gereken süre (milisaniye). Platformun varsayılan duraklama süresini korumak için ayarlamadan bırakın (macOS ve Android'de 700 ms, iOS'te 900 ms).`}},"talk%2EspeechLocale":{label:{"v1-gbwzpr-i":`Talk Konuşma Yerel Ayarı`},help:{"v1-1un3x4l-4c":`Cihaz düğümlerinde Talk konuşma tanıması ve iOS sistem sesine geri dönüş için BCP 47 yerel ayar kimliği; örneğin "ru-RU". Her cihazın varsayılanını kullanmak için ayarlamadan bırakın.`}},telemetry:{label:{"v1-sqprmo-9":`Telemetri`},help:{"v1-1o5tru3-55":`Günlük güncelleme kontrolüne eklenen anonim özellik istatistikleri için açık rıza. Özellik istatistikleri varsayılan olarak devre dışıdır ve hiçbir zaman mesaj, kimlik bilgisi veya tanımlayıcı içermez.`}},"telemetry%2EconsentedAt":{label:{"v1-1cb2euy-10":`Özellik İstatistikleri Rıza Zaman Damgası`},help:{"v1-1t051az-3t":`Operatörün anonim özellik istatistiklerini ne zaman kabul ettiğini veya reddettiğini kaydeden ISO zaman damgası. Kurulum sihirbazının tekrar sormasını önler.`}},"telemetry%2Eenabled":{label:{"v1-166i16f-s":`Anonim Özellik İstatistikleri`},help:{"v1-1ptrwuq-4r":`Etkin kanal ve sağlayıcı adlarını, eklenti sayısını ve son oturumların sayısını günlük güncelleme kontrolüyle birlikte paylaşır. Varsayılan olarak devre dışıdır ve DO_NOT_TRACK=1 olduğunda her zaman devre dışı kalır.`}},tools:{label:{"v1-15cdqf0-5":`Araçlar`},help:{"v1-1el54kl-5h":`Araç altyapısı ve ajanlar arası varsayılan ayarlar. Kök düzeyindeki eş öğeler altyapıyı ve ajanlar arası varsayılan ayarları yönetir; agents.defaults ajan döngüsü davranışını yönetir; ajan girdileri, desteklenen durumlarda her iki ayar grubunu da geçersiz kılabilir.`}},"tools%2EagentToAgent":{label:{"v1-19yyyqk-q":`Ajanlar Arası Araç Erişimi`},help:{"v1-1ynpa5f-cf":`Ajanlar arası oturum aracı çağrıları için ilke: gönderme, listeleme, geçmiş, arama ve durum okuma (varsayılan: etkin). Ajan çiftlerini kısıtlamak için allow kullanın; enabled=false normal ajanlar arası erişimi engeller. İstekte bulunan ajana ait yerel alt ajan oturumları ve ACP alt oturumları, tree veya all görünürlüğünde erişilebilir kalır. Kesin ayrım için tools.sessions.visibility değerini agent veya self olarak ayarlayın (tree, istekte bulunan ajana ait yerel/ACP alt oturumlarına yine de izin verir) ya da ayrı ağ geçitleri kullanın.`}},"tools%2EagentToAgent%2Eallow":{label:{"v1-96jndk-v":`Ajanlar Arası Hedef İzin Listesi`},help:{"v1-1jt2ari-76":`Ajanlar arası çağrılara katılabilecek ajan kimlikleri veya * kalıpları; hem istekte bulunan ajan hem de hedef ajan eşleşmelidir. Ajanlar arası erişim varsayılan olarak açıktır; allow belirtilmezse veya boşsa her çifte izin verilir. Erişimi kısıtlamak için açık bir liste belirleyin; boş girdiler erişimi reddeder.`}},"tools%2EagentToAgent%2Eenabled":{label:{"v1-1petv53-q":`Ajanlar Arası Aracı Etkinleştir`},help:{"v1-w950oq-ba":`Ajanlar arası oturum aracı erişimini etkinleştirir (varsayılan: true); allow belirtilmezse veya boşsa her ajan çiftine izin verilir. Normal ajanlar arası erişimi engellemek için false olarak ayarlayın; istekte bulunan ajana ait yerel alt ajan oturumları ve ACP alt oturumları, tree veya all görünürlüğünde erişilebilir kalır. Kesin ayrım için tools.sessions.visibility değerini agent veya self olarak ayarlayın (tree, istekte bulunan ajana ait yerel/ACP alt oturumlarına yine de izin verir) ya da ayrı ağ geçitleri kullanın.`}},"tools%2Eallow":{label:{"v1-1hmvki6-e":`Araç İzin Listesi`},help:{"v1-1is3eaq-4v":`Katı ortamlar için profilden türetilen varsayılanların yerini alan mutlak araç izin listesi. Bunu yalnızca araç yeteneklerinin özenle seçilmiş dar bir alt kümesini bilerek kullanıyorsanız kullanın.`}},"tools%2EalsoAllow":{label:{"v1-x011gj-o":`Araç İzin Listesi Eklemeleri`},help:{"v1-1xw9zp8-57":`Seçilen araç profili ve varsayılan politikayla birleştirilen ek araç izin listesi girdileri. Denetimlerde bilinçli politika istisnalarının hızla belirlenebilmesi için bu listeyi kısa ve açık tutun.`}},"tools%2EbyProvider":{label:{"v1-ca7c4x-n":`Sağlayıcıya Göre Araç Politikası`},help:{"v1-1ecljob-4y":`Yetenekleri kullanım arayüzüne göre uyarlamak için kanal/sağlayıcı kimliğiyle anahtarlanan, sağlayıcıya özel araç izin/ret geçersiz kılmaları. Bir sağlayıcının genel araç politikasından daha sıkı denetimlere ihtiyacı olduğunda bunu kullanın.`}},"tools%2EcodeMode":{label:{"v1-194jdgf-9":`Kod Modu`},help:{"v1-1ecc39k-6k":'Genel OpenClaw Kod Modu. Genel düzeyde belirtilmediğinde varsayılan değer `"auto"` olur; `enabled` içermeyen, açıkça tanımlanmış bir nesne devre dışı kalır. Modun etkin olduğu ajan çalıştırmalarında modele yalnızca `exec` ve `wait` sunulur ve normal araçlara katalog köprüsü üzerinden erişilir.'}},"tools%2EcodeMode%2Eenabled":{label:{"v1-162yoj6-g":`Kod Modunu Etkinleştir`},help:{"v1-rgstxz-aj":'Genel OpenClaw Kod Modu etkinleştirmesi. Genel ayar hiç tanımlanmamışsa varsayılan değer `"auto"` olur; `enabled` içermeyen, açıkça tanımlanmış bir nesne devre dışı kalır. `"auto"`, kataloğu tercih eden modellerde modu etkinleştirirken `true`, araç kullanabilen çalıştırmalarda modu etkinleştirir. Ajan ve model düzeyindeki etkinleştirme geçersiz kılmaları önceliklidir. Modun etkin olduğu bir çalıştırmada çalışma zamanı kullanılamıyorsa, tüm araç listesini sunmak yerine çalıştırma güvenli biçimde başarısız olur.'}},"tools%2EcodeMode%2Eexecutor":{label:{"v1-lbpzic-i":`Kod Modu Yürütücüsü`},help:{"v1-l8nlk2-6x":`JavaScript yürütücüsü: "node" (varsayılan), güvenilir kod için Node vm kullanır ve bir güvenlik korumalı alanı değildir; "quickjs", güçlendirilmiş konuk yürütmesi için birlikte sunulan QuickJS WASM eklentisini kullanır. Araç izinleri her ikisi için de geçerlidir. Seçilen yürütücü bulunamazsa güvenlik gereği yürütme engellenir.`}},"tools%2EcodeMode%2EmaxOutputBytes":{label:{"v1-aewvtz-m":`Kod Modu Çıktı Sınırı`},help:{"v1-1hmij9q-1n":`Kod modu çıktısı üzerinden döndürülen serileştirilmiş verinin bayt cinsinden azami boyutu.`}},"tools%2EcodeMode%2EmaxPendingToolCalls":{label:{"v1-1keh21t-s":`Kod Modu Bekleyen Araç Çağrısı Sınırı`},help:{"v1-3b5tyd-2i":`Bir kod modu sanal makinesinin daha sonra devam etmek üzere duraklaması gerekmeden başlatabileceği en fazla eşzamanlı iç içe araç çağrısı sayısı.`}},"tools%2EcodeMode%2EmaxSearchLimit":{label:{"v1-1f02yk9-s":`Kod Modu En Fazla Arama Sonucu Sayısı`},help:{"v1-1gpue5r-28":`Bir kod modu programının isteyebileceği en fazla gizli katalog arama sonucu sayısı.`}},"tools%2EcodeMode%2EmaxSnapshotBytes":{label:{"v1-1tt9adm-o":`Kod Modu Anlık Görüntü Sınırı`},help:{"v1-1mmgkqy-1x":`Askıya alınmış tek bir QuickJS anlık görüntüsü için saklanan serileştirilmiş verinin bayt cinsinden üst sınırı.`}},"tools%2EcodeMode%2EmemoryLimitBytes":{label:{"v1-5bockh-m":`Kod Modu Bellek Sınırı`},help:{"v1-xetora-6n":`Bayt cinsinden QuickJS konuk yığın sınırı veya Node worker V8 için mümkün olduğunca uyulmaya çalışılan yığın bütçesi. Node çalışma zamanı ek yükü ve motorun minimum bellek tahsisleri, fiilen kullanılabilen bütçeyi etkiler; harici arabellekler ve süreç RSS değeri hariç tutulur. Bu bir güvenlik garantisi değildir.`}},"tools%2EcodeMode%2Emode":{label:{"v1-1a1ijjo-h":`Kod Modu Arayüzü`},help:{"v1-dsp2b9-2x":'Modele sunulan arayüz. Yalnızca "only" desteklenir: kod modunun `exec` ve `wait` araçlarını kullanıma sunar ve normal araçları gizler.'}},"tools%2EcodeMode%2EsearchDefaultLimit":{label:{"v1-1xkxvss-w":`Kod Modu Varsayılan Arama Sonucu Sayısı`},help:{"v1-1io42lu-2m":"Kod modu içinde `catalog.search` tarafından döndürülen varsayılan gizli katalog arama sonucu sayısı."}},"tools%2EcodeMode%2EsnapshotTtlSeconds":{label:{"v1-xs8rwp-m":`Kod Modu Anlık Görüntü Yaşam Süresi`},help:{"v1-1nxfczz-28":"Askıya alınmış Code Mode çalıştırmalarının, süreleri dolmadan önce `wait` ile ne kadar süre boyunca sürdürülebileceği."}},"tools%2EcodeMode%2EtimeoutMs":{label:{"v1-1rjrbio-h":`Kod Modu Zaman Aşımı`},help:{"v1-8csycm-1p":"Kod modunda tek bir `exec` veya `wait` çağrısı için milisaniye cinsinden azami süre."}},"tools%2Edeny":{label:{"v1-fwuia7-d":`Araç Engelleme Listesi`},help:{"v1-wilr1b-4p":`Profil veya sağlayıcı kuralları izin verse bile listedeki araçları engelleyen genel araç engelleme listesi. Acil erişim engellemeleri ve uzun vadeli katmanlı savunma için engelleme kurallarını kullanın.`}},"tools%2Eelevated":{label:{"v1-15z7aw7-k":`Yükseltilmiş Yetkili Araç Erişimi`},help:{"v1-ehcm0r-5a":`Yalnızca güvenilir göndericilerin erişebilmesi gereken ayrıcalıklı komut arayüzleri için yükseltilmiş yetkili araç erişim denetimleri. Operatör iş akışları açıkça yükseltilmiş yetki gerektiren işlemlere ihtiyaç duymadıkça devre dışı bırakın.`}},"tools%2Eelevated%2EallowFrom":{label:{"v1-yx3m99-p":`Yükseltilmiş Yetkili Araç İzin Kuralları`},help:{"v1-1u9bhih-54":`Yükseltilmiş yetkili araçlar için genellikle kanal/sağlayıcı kimlik biçimlerine göre anahtarlanan gönderici izin kuralları. Yükseltilmiş yetkili komutların istenmeyen kullanıcılar tarafından tetiklenememesi için kapsamı dar, açıkça belirtilmiş kimlikler kullanın.`}},"tools%2Eelevated%2Eenabled":{label:{"v1-15kpc2g-r":`Yükseltilmiş Yetkili Araç Erişimini Etkinleştir`},help:{"v1-1n8oyal-4l":`Gönderici ve ilke denetimleri başarılı olduğunda yükseltilmiş yetkili araç yürütme yolunu etkinleştirir. Herkese açık/paylaşılan kanallarda devre dışı bırakın ve yalnızca sahibinin yönettiği güvenilir ortamlarda etkinleştirin.`}},"tools%2Eexec":{label:{"v1-33cqoe-9":`Exec Aracı`},help:{"v1-p5piic-56":`Kabuk yürütme ana makinesi, güvenlik modu, onay davranışı ve çalışma zamanı bağlamaları için Exec aracı ilke grubu. Üretim ortamında ihtiyatlı varsayılan ayarları koruyun ve yükseltilmiş yetkili yürütme yollarına yönelik kısıtlamaları sıkılaştırın.`}},"tools%2Eexec%2EapplyPatch%2EallowModels":{label:{"v1-1pc6erm-r":`apply_patch Model İzin Listesi`},help:{"v1-4q5ovf-1x":`İsteğe bağlı izin verilen model kimlikleri listesi (ör. "gpt-5.4" veya "openai/gpt-5.4").`}},"tools%2Eexec%2EapplyPatch%2Eenabled":{label:{"v1-c3mjij-i":`apply_patch'i etkinleştir`},help:{"v1-1erkir4-31":`Araç politikası izin verdiğinde OpenAI ve OpenAI Codex modelleri için apply_patch'i etkinleştirin veya devre dışı bırakın (varsayılan: true).`}},"tools%2Eexec%2EapplyPatch%2EworkspaceOnly":{label:{"v1-1mlvoxc-q":`apply_patch yalnızca çalışma alanında`},help:{"v1-x2z207-3o":`apply_patch yollarını çalışma alanı diziniyle sınırlayın (varsayılan: true). Çalışma alanı dışına yazmaya izin vermek için false olarak ayarlayın (tehlikelidir).`}},"tools%2Eexec%2EapprovalRunningNoticeMs":{label:{"v1-s8uk67-x":`Yürütme onayı sonrası devam ediyor bildirimi (ms)`},help:{"v1-1gwwann-4z":`Yürütme onayı verildikten sonra devam ediyor bildiriminin gösterilmesine kadar geçen milisaniye cinsinden gecikme. Hızlı komutlarda titremeyi azaltmak için artırın veya operatöre daha hızlı geri bildirim sağlamak için azaltın.`}},"tools%2Eexec%2Eask":{label:{"v1-1kx7cwd-8":`Yürütme için onay isteme`}},"tools%2Eexec%2EcommandHighlighting":{label:{"v1-1n3ojuz-p":`Yürütme komutu vurgulama`},help:{"v1-kyxd4o-4n":`Yürütme onayı istemlerinde ayrıştırıcıdan türetilen komut vurgularını gösterin (varsayılan: false). Yürütme onay politikasını değiştirmeden vurgulanmış komut metni görüntülemek için bunu etkinleştirin.`}},"tools%2Eexec%2EgrantExpiryDays":{label:{"v1-2d156s-s":`Kalıcı iznin geçerlilik süresi (gün)`},help:{"v1-5uxe2j-6r":`Otomasyon onaylarında allow-always ile oluşturulan kalıcı izinlerin gün cinsinden varsayılan geçerlilik süresi (1-3650). Ayarlanmazsa izinler, iptal edilene veya ait oldukları otomasyon değişene kadar geçerli kalır. Koşullar oluşturma anında sabitlenir; bu nedenle bu ayarın değiştirilmesi yalnızca gelecekteki izinleri etkiler.`}},"tools%2Eexec%2Ehost":{label:{"v1-6z76n1-b":`Yürütme hedefi`},help:{"v1-rno1mf-5q":`Kabuk komutları için yürütme hedefi stratejisini seçer. Çalışma zamanına duyarlı davranış için "auto" kullanın (varsa sandbox, yoksa gateway); sabit bir yürütme ortamına ihtiyaç duyduğunuzda ise açıkça sandbox/gateway/node seçin.`}},"tools%2Eexec%2Emode":{label:{"v1-luiaev-9":`Yürütme Modu`},help:{"v1-1wi6t4l-5q":`Normalleştirilmiş yürütme ilkesi seçicisi. Onay kapsamına girmeyen durumların sınıflandırıcı tarafından incelenmesi için "auto", insan tarafından incelenmesi için "ask", yalnızca deterministik olarak güvenli komutlar için "allowlist" veya güvenilir yerel çalışma için "full" kullanın.`}},"tools%2Eexec%2Enode":{label:{"v1-s03avl-h":`Yürütme Düğümü Bağlama`},help:{"v1-rfnz54-4s":`Komut yürütme bağlı düğümlere devredildiğinde yürütme araçları için kullanılan düğüm bağlama yapılandırması. Yalnızca çok düğümlü yönlendirme gerektiğinde açık düğüm bağlama kullanın.`}},"tools%2Eexec%2EnotifyOnExit":{label:{"v1-rwarum-j":`Yürütme Çıkışında Bildir`},help:{"v1-1ounlvx-3q":`true olduğunda (varsayılan), arka plandaki yürütme oturumlarının sonlanması ve düğüm yürütme yaşam döngüsü olayları, kuyruğa bir sistem olayı ekler ve bir canlılık sinyali ister.`}},"tools%2Eexec%2EnotifyOnExitEmptySuccess":{label:{"v1-1hs7mlg-s":`Çıktısız Başarılı Yürütmede Bildir`},help:{"v1-1wx4xxd-3d":`true olduğunda, arka plandaki yürütmelerin boş çıktıyla başarıyla sonlanması durumunda da kuyruğa bir tamamlanma sistem olayı eklenir (varsayılan: false).`}},"tools%2Eexec%2EpathPrepend":{label:{"v1-18ajzln-h":`Yürütme PATH Başına Ekleme`},help:{"v1-s1aimc-1r":`Yürütmeler (gateway/sandbox) için PATH başına eklenecek dizinler.`}},"tools%2Eexec%2Ereviewer":{label:{"v1-1dgtjz-d":`Yürütme İnceleyicisi`},help:{"v1-12y548k-4x":`Otomatik modda insan onayına başvurmadan önce kullanılan model destekli exec inceleyicisi. exec incelemesini ana ajan modelinden ayrı tutmak istiyorsanız burada yalnızca bu amaç için kullanılacak bir model belirleyin.`}},"tools%2Eexec%2Ereviewer%2EfastMode":{label:{"v1-hd75ia-n":`Komut Çalıştırma İnceleyicisi Hızlı Modu`},help:{"v1-175bx14-8u":`OpenClaw onay incelemeleri için isteğe bağlı hızlı mod: true, desteklenen OpenAI Responses ve ChatGPT/OAuth yollarında öncelikli işleme talep eder; false ise standart işleme talep eder. Sağlayıcının varsayılanlarını korumak için belirtmeyin. Hızlı mod daha maliyetli olabilir ve kullanılabilirliği sağlayıcıya bağlıdır. Yerel Codex Guardian yapılandırmasını değiştirmez.`}},"tools%2Eexec%2Ereviewer%2Emodel":{label:{"v1-90ol5u-j":`Exec İnceleyici Modeli`},help:{"v1-1lltiy5-3i":`exec inceleyici ajanı için isteğe bağlı sağlayıcı/model geçersiz kılma ayarı. Hedef ajan için yapılandırılmış birincil modeli yeniden kullanmak için boş bırakın.`}},"tools%2Eexec%2Ereviewer%2Ethinking":{label:{"v1-s17i85-m":`Komut Çalıştırma İnceleyicisi Düşünme Düzeyi`},help:{"v1-yg2gby-6u":`OpenClaw model destekli onay incelemeleri için isteğe bağlı akıl yürütme çabası: minimal, low, medium, high, xhigh veya max. Sağlayıcının varsayılanlarını korumak için belirtmeyin. Desteklenen düzeyler seçilen modele göre uyarlanır. Yerel Codex Guardian yapılandırmasını değiştirmez.`}},"tools%2Eexec%2Ereviewer%2EtimeoutMs":{label:{"v1-1shnxjr-q":`Exec İnceleyici Zaman Aşımı (ms)`},help:{"v1-1o30chi-3w":`İnsan onayına başvurmadan önce model hazırlığı ve yanıt üretimi için aşama başına uygulanan, milisaniye cinsinden exec inceleyici zaman aşımı (varsayılan: 30000).`}},"tools%2Eexec%2EsafeBinProfiles":{label:{"v1-ez9qvm-m":`Exec Güvenli Yürütülebilir Dosya Profilleri`},help:{"v1-4cdcwe-29":`Yürütülebilir dosya başına isteğe bağlı güvenli yürütme profilleri (konumsal bağımsız değişken sınırları + izin verilen/reddedilen bayraklar).`}},"tools%2Eexec%2EsafeBins":{label:{"v1-21op89-e":`Exec Güvenli Yürütülebilir Dosyaları`},help:{"v1-1of1m2s-21":`Yalnızca stdin kullanan güvenli yürütülebilir dosyaların izin listesine açıkça eklenmeden çalışmasına izin verin.`}},"tools%2Eexec%2EsafeBinTrustedDirs":{label:{"v1-vpqq4p-q":`Exec Güvenli Yürütülebilir Dosyaları İçin Güvenilen Dizinler`},help:{"v1-zljbcn-2v":`Güvenli yürütülebilir dosya yolu denetimleri için açıkça güvenilir olarak belirtilen ek dizinler (PATH girdilerine asla otomatik olarak güvenilmez).`}},"tools%2Eexec%2Esecurity":{label:{"v1-om3dyq-d":`Exec Güvenliği`}},"tools%2Eexec%2EstrictInlineEval":{label:{"v1-pzx6o5-s":`Satır İçi Kod Çalıştırma İçin Onay İste`},help:{"v1-jkmgo7-5z":"`python -c`, `node -e`, `ruby -e` veya `osascript -e` gibi yorumlayıcıların satır içi kod çalıştırma biçimleri için açık onay isteyin. İzin listesinin sessizce yeniden kullanılmasını önler ve bu biçimler için her zaman izin vermek yerine her seferinde onay sorulmasını sağlar."}},"tools%2Eexec%2EtimeoutSeconds":{label:{"v1-1d0xrlr-m":`Yürütme Zaman Aşımı (Saniye)`}},"tools%2Efs%2EworkspaceOnly":{label:{"v1-nx841l-n":`Yalnızca çalışma alanıyla sınırlı dosya sistemi araçları`},help:{"v1-1mhuvka-2s":`Dosya sistemi araçlarını (read/write/edit/apply_patch) çalışma alanı diziniyle sınırlandırın (varsayılan: false).`}},"tools%2Egithub":{label:{"v1-jfcpb6-y":`GitHub CLI Kimliği ve Git Yazarı`},help:{"v1-1fl77im-5s":`Ajan araçları için yönetilen yerel GitHub CLI profili ve isteğe bağlı Git yazarı. Gateway çalışma zamanı kullanıcısının mevcut hesabını ve yazar bilgilerini korumak için bu nesneyi eklemeyin; deponun uzak bağlantı kimlik bilgileri hiçbir zaman geçersiz kılınmaz.`}},"tools%2Egithub%2EgitAuthor%2Eemail":{label:{"v1-durd6y-g":`Git Yazarı E-postası`},help:{"v1-kol5g6-1i":`Yalnızca geçerli işlemde kullanılacak isteğe bağlı Git yazarı ve commit yapan kişi e-posta adresi.`}},"tools%2Egithub%2EgitAuthor%2Ename":{label:{"v1-pv12jh-f":`Git Yazarı Adı`},help:{"v1-z5bl1f-1h":`Yalnızca geçerli işlemde kullanılacak isteğe bağlı Git yazarı ve commit yapan kişi adı.`}},"tools%2Egithub%2Ekind":{label:{"v1-1ubt2yv-m":`GitHub Kimlik Bilgisi Türü`},help:{"v1-qi3qun-3q":`Dönüşümlü yenileme kimlik bilgisi Gateway tarafından yönetilen bir OAuth profilini işaretler. Bu alanın belirtilmediği profiller kişisel erişim belirteci kullanır.`}},"tools%2Egithub%2EprofileId":{label:{"v1-ssneaz-m":`GitHub Profil Sürümü`},help:{"v1-4lzl0-27":`Yönetilen kimlik bilgilerini atomik olarak değiştirmek için kullanılan, içeriği yorumlanmayan, oluşturulmuş profil sürümü.`}},"tools%2Elinks%2Eenabled":{label:{"v1-yims6g-p":`Bağlantı Anlamayı Etkinleştir`},help:{"v1-23t2io-59":`URL'lerin ajan akıl yürütmesinden önce özetlenebilmesi için otomatik bağlantı anlama ön işlemesini etkinleştirin. Daha zengin bağlam için etkin tutun; işlemenin kesinlikle en düşük düzeyde tutulması gerektiğinde devre dışı bırakın.`}},"tools%2Elinks%2EmaxLinks":{label:{"v1-l7d76c-s":`Bağlantı Anlama için Maksimum Bağlantı Sayısı`},help:{"v1-ksxmcv-52":`Bağlantı anlama sırasında her turda içeriği alınan maksimum bağlantı sayısı. Yoğun sohbetlerde gecikmeyi ve maliyeti kontrol altında tutmak için düşük değerler, birden fazla bağlantının sağladığı bağlam kritik olduğunda ise yüksek değerler kullanın.`}},"tools%2Elinks%2Emodels":{label:{"v1-t894bf-p":`Bağlantı Anlama Modelleri`},help:{"v1-6j3mnw-5a":`Bağlantı anlama görevleri için tercih edilen model listesi; desteklendiğinde modeller sırayla yedek seçenek olarak değerlendirilir. Rutin özetleme için önce hafif modelleri, daha ağır modelleri ise yalnızca gerektiğinde kullanın.`}},"tools%2Elinks%2Escope":{label:{"v1-x79nuj-o":`Bağlantı Anlama Kapsamı`},help:{"v1-183cwpa-55":`Sohbet bağlamına ve mesaj türüne göre bağlantı anlamanın ne zaman çalışacağını kontrol eder. Bağlantıların işleme alınmasının gerekmediği mesajlarda gereksiz içerik alımını önlemek için kapsamı dar tutun.`}},"tools%2Elinks%2EtimeoutSeconds":{label:{"v1-hh7o78-w":`Bağlantı Anlama Zaman Aşımı (sn)`},help:{"v1-61v30o-4p":`Çözümlenemeyen bağlantılar atlanmadan önce her bağlantının anlaşılması için saniye cinsinden tanınan süre. Harici siteler yavaş veya erişilemez olduğunda uzun beklemeleri önlemek için bu süreyi sınırlı tutun.`}},"tools%2EloopDetection%2Eenabled":{label:{"v1-c9sqnr-j":`Araç Döngüsü Algılama`},help:{"v1-1e3rls8-5g":`Kayan geçmişe dayalı araç döngüsü algılamasını ve bağlam sıkıştırma sonrası korumayı kontrol eder. Kayan geçmişe dayalı algılamayı kapalı, bağlam sıkıştırma sonrası korumayı açık tutmak için bu ayarı belirtmeyin. İkisini de etkinleştirmek için true, ikisini de devre dışı bırakmak için false olarak ayarlayın.`}},"tools%2Emedia%2Eaudio%2Eattachments":{label:{"v1-1r0kwy-11":`Ses Anlama Eki Politikası`},help:{"v1-1s3t9s5-3o":`Eşleşen ses eklerinden hangilerinin işleneceğini seçin. Birden fazla eki yazıya dökmeyi amaçlamıyorsanız yalnızca ilk eki işleyin.`}},"tools%2Emedia%2Eaudio%2EechoFormat":{label:{"v1-15fud4j-m":`Transkript Yansıtma Biçimi`},help:{"v1-glpdzh-3i":`Sohbete yansıtılan transkripti {transcript} yer tutucusuyla biçimlendirin. İletilen mesajın transkripti içermesi için yer tutucuyu olduğu gibi koruyun.`}},"tools%2Emedia%2Eaudio%2EechoTranscript":{label:{"v1-1gi9x8r-n":`Transkripti Sohbete Yansıt`},help:{"v1-1dedp8c-3r":`Ses transkriptini, ajan tarafından işlenmeden önce kaynak sohbete yansıtın. Kullanıcıların sistemin ne duyduğunu doğrulaması gerektiğinde bunu etkinleştirin.`}},"tools%2Emedia%2Eaudio%2Eenabled":{label:{"v1-1ne86nm-q":`Ses Anlamayı Etkinleştir`},help:{"v1-1v0x7te-2m":`Sesli notların veya ses kliplerinin ajan bağlamı için metne dönüştürülebilmesi amacıyla ses anlamayı etkinleştirin.`}},"tools%2Emedia%2Eaudio%2Elanguage":{label:{"v1-1jzzbi3-s":`Ses Anlama Dili`},help:{"v1-1ruqt97-3z":`Ses transkripsiyon sağlayıcıları için varsayılan dil ipucu. Konuşulan ana dil biliniyorsa ve sağlayıcının dil algılaması güvenilir değilse bunu ayarlayın.`}},"tools%2Emedia%2Eaudio%2EmaxBytes":{label:{"v1-hqnl72-t":`Ses Anlama için Azami Bayt Sayısı`},help:{"v1-1mcckc8-43":`Yapılandırılmış ve otomatik algılanan modeller için varsayılan ses girdisi boyut sınırı. Bunu, sağlayıcılarınızın ve ağınızın kabul etmesi gereken en büyük kayıt boyutuna ayarlayın.`}},"tools%2Emedia%2Eaudio%2EmaxChars":{label:{"v1-1vhezc0-t":`Ses Anlama için Azami Karakter Sayısı`},help:{"v1-eo1dp-43":`Yapılandırılmış ve otomatik algılanan modeller için varsayılan azami transkript uzunluğu. Uzun sesli notların ajan bağlamını genişletmesini önlemek için daha düşük bir değer kullanın.`}},"tools%2Emedia%2Eaudio%2EpreferredModel":{label:{"v1-1h7yz8z-z":`Tercih Edilen Ses Anlama Modeli`},help:{"v1-1n5zya1-3c":`Sesin metne dönüştürülmesinde, diğer uyumlu yedek seçeneklerden önce yetenek etiketi içeren bir tools.media.models girdisini tercih edin.`}},"tools%2Emedia%2Eaudio%2Eprompt":{label:{"v1-1gqi94r-q":`Ses Anlama İstemi`},help:{"v1-1v5jtay-4b":`Bir model girdisi tarafından geçersiz kılınmadığında kullanılan varsayılan ses dökümü istemi. Sonraki iş akışları dökümün üslubuna bağlıysa talimatı sabit tutun.`}},"tools%2Emedia%2Eaudio%2Escope":{label:{"v1-erazqj-p":`Ses Anlama Kapsamı`},help:{"v1-1pptfg0-3w":`Ses anlamayı kanala, sohbet türüne veya kaynak anahtarına göre kısıtlayın. Otomatik ses dökümünün hassas veya maliyetli olduğu durumlarda kapsamı dar tutun.`}},"tools%2Emedia%2Eaudio%2EtimeoutSeconds":{label:{"v1-1ja2x9w-x":`Ses Anlama Zaman Aşımı (sn)`},help:{"v1-n8wc6c-3b":`Ses anlama istekleri için varsayılan zaman aşımı. Uzun kayıtlar veya daha yavaş yerel ses dökümü modelleri için bu süreyi artırın.`}},"tools%2Emedia%2Econcurrency":{label:{"v1-1ru9noi-v":`Medya Anlama Eşzamanlılığı`},help:{"v1-13kr9np-58":`Görüntü, ses ve video görevlerinde tur başına eşzamanlı medya anlama işlemlerinin en yüksek sayısı. CPU ve ağ kapasitesinin aşılmasını önlemek için kaynakları kısıtlı dağıtımlarda bu değeri düşürün.`}},"tools%2Emedia%2Eimage%2Eattachments":{label:{"v1-19jrjw9-11":`Görüntü Anlama Ek Politikası`},help:{"v1-11hofbw-3e":`Eşleşen görüntü eklerinden hangilerinin işleneceğini seçin. Birden fazla görüntünün analizi amaçlanmıyorsa yalnızca ilk eki işleyin.`}},"tools%2Emedia%2Eimage%2Eenabled":{label:{"v1-dbw751-q":`Görüntü Anlamayı Etkinleştir`},help:{"v1-1b2zw34-50":`Eklenen veya referans verilen görsellerin metinsel bağlama dönüştürülebilmesi için görsel anlamayı etkinleştirin. Yalnızca metinle çalışmanız gerekiyorsa veya görsel işleme maliyetinden kaçınmak istiyorsanız devre dışı bırakın.`}},"tools%2Emedia%2Eimage%2EmaxBytes":{label:{"v1-943dvt-t":`Görsel Anlama Maksimum Bayt Sayısı`},help:{"v1-jwwpd1-3v":`Yapılandırılmış ve otomatik algılanan modeller için varsayılan görsel girdi boyutu sınırı. Bu değeri sağlayıcının veri yükü sınırlarına ve dağıtım ortamının bant genişliğine uygun şekilde ayarlayın.`}},"tools%2Emedia%2Eimage%2EmaxChars":{label:{"v1-1p6mqsn-t":`Görsel Anlama Maksimum Karakter Sayısı`},help:{"v1-ebnxhk-3q":`Varsayılan maksimum görsel açıklaması uzunluğu. Kısa bir bağlam için daha düşük, ayrıntılı OCR ve sahne analizi için daha yüksek bir değer kullanın.`}},"tools%2Emedia%2Eimage%2EpreferredModel":{label:{"v1-gy243w-z":`Tercih Edilen Görsel Anlama Modeli`},help:{"v1-1o2uwo6-3c":`Görsel anlama için yetenek etiketi olan bir tools.media.models girdisini diğer uyumlu yedek seçeneklerden önce tercih edin.`}},"tools%2Emedia%2Eimage%2Eprompt":{label:{"v1-i4kxh2-q":`Görsel Anlama İstemi`},help:{"v1-1jdcu8b-3u":`Bir girdi tarafından geçersiz kılınmadığında kullanılan varsayılan görsel anlama istemi. Çıktıyı kullanan bileşenler tutarlı açıklamalara dayanıyorsa bu istemi deterministik tutun.`}},"tools%2Emedia%2Eimage%2Escope":{label:{"v1-xpdk4k-p":`Görsel Anlama Kapsamı`},help:{"v1-tievo1-3s":`Görsel anlamayı kanala, sohbet türüne veya kaynak anahtarına göre kısıtlayın. İşlemeyi kontrol altında tutmak için yoğun veya güvenilmeyen kanallarda kapsamı dar tutun.`}},"tools%2Emedia%2Eimage%2EtimeoutSeconds":{label:{"v1-60t1jb-x":`Görsel Anlama Zaman Aşımı (sn)`},help:{"v1-1wcm84x-31":`Görüntü anlama istekleri için varsayılan zaman aşımı. Büyük görüntüler veya daha yavaş yerel görsel modeller için bu süreyi artırın.`}},"tools%2Emedia%2Emodels":{label:{"v1-b1r5p4-x":`Medya Anlama için Ortak Modeller`},help:{"v1-f34u65-47":`Medya anlama için temel model listesi. Her işleme hattının yalnızca uyumlu yedek modelleri seçmesi için her girdide görüntü, ses veya video yetenek etiketleri kullanın.`}},"tools%2Emedia%2Evideo%2Eattachments":{label:{"v1-e4yzf-11":`Video Anlama Ek Politikası`},help:{"v1-1qm1qrc-3e":`Eşleşen video eklerinden hangilerinin işleneceğini seçin. Birden fazla videoyu analiz etmeyi amaçlamıyorsanız yalnızca ilk eki işleyin.`}},"tools%2Emedia%2Evideo%2Eenabled":{label:{"v1-sg3427-q":`Video Anlamayı Etkinleştir`},help:{"v1-1ltx5gl-58":`Kliplerin sonraki akıl yürütme ve yanıt oluşturma aşamalarında kullanılmak üzere metin olarak özetlenebilmesi için video anlamayı etkinleştirin. Video işleme politikalara aykırıysa veya kurulumunuz için çok maliyetliyse devre dışı bırakın.`}},"tools%2Emedia%2Evideo%2EmaxBytes":{label:{"v1-wzauwr-t":`Video Anlama için Azami Bayt Sayısı`},help:{"v1-2mp77v-3v":`Yapılandırılmış ve otomatik algılanan modeller için varsayılan video girdisi boyut sınırı. Bu değeri sağlayıcının veri boyutu sınırlarına ve kurulumunuzun bant genişliğine uygun olarak ayarlayın.`}},"tools%2Emedia%2Evideo%2EmaxChars":{label:{"v1-gb00od-t":`Video Anlama için Azami Karakter Sayısı`},help:{"v1-1j0x40b-3j":`Varsayılan azami video açıklaması uzunluğu. Kısa bir bağlam için daha düşük, ayrıntılı sahne özetleri için daha yüksek bir değer kullanın.`}},"tools%2Emedia%2Evideo%2EpreferredModel":{label:{"v1-11pflaa-z":`Tercih Edilen Video Anlama Modeli`},help:{"v1-1cygq5k-3c":`Video anlama için diğer uyumlu alternatiflerden önce yetenek etiketi olan bir tools.media.models girdisini tercih edin.`}},"tools%2Emedia%2Evideo%2Eprompt":{label:{"v1-dq4his-q":`Video Anlama İstemi`},help:{"v1-ul2jx4-3r":`Bir girdi tarafından geçersiz kılınmadığında kullanılan varsayılan video anlama istemi. Sonuçları kullanan sistemler tutarlı özetlere ihtiyaç duyuyorsa bu istemi deterministik tutun.`}},"tools%2Emedia%2Evideo%2Escope":{label:{"v1-iwg12i-p":`Video Anlama Kapsamı`},help:{"v1-7gfrx3-3s":`Video anlamayı kanala, sohbet türüne veya kaynak anahtarına göre kısıtlayın. İşlemeyi kontrol altında tutmak için yoğun veya güvenilmeyen kanallarda kapsamı dar tutun.`}},"tools%2Emedia%2Evideo%2EtimeoutSeconds":{label:{"v1-syt2z1-x":`Video Anlama Zaman Aşımı (sn)`},help:{"v1-e8rzsy-33":`Video anlama istekleri için varsayılan zaman aşımı. Daha uzun klipler veya daha yavaş yerel analiz modelleri için bu süreyi artırın.`}},"tools%2Emessage%2Eactions%2Eallow":{label:{"v1-a6trwv-o":`İzin Verilen Mesaj Eylemleri Listesi`},help:{"v1-1iceqwa-5c":`Mesaj aracı için genel izin verilen mesaj eylemleri listesi. Yalnızca tüm çalışma ortamının sınırlı bir eylem kümesini sunması ve kabul etmesi gerektiğinde kullanın; herkese açık veya korumalı alanda çalışan ajanlar için ajan bazlı izin listelerini tercih edin.`}},"tools%2Emessage%2Ebroadcast%2Eenabled":{label:{"v1-awk06q-o":`Toplu Mesaj Yayınını Etkinleştir`},help:{"v1-1ms74z7-14":`Toplu yayın eylemini etkinleştirin (varsayılan: true).`}},"tools%2Emessage%2EcrossContext%2EallowAcrossProviders":{label:{"v1-lzee7y-12":`Bağlamlar Arası İşlemlere İzin Ver (Sağlayıcılar Arasında)`},help:{"v1-276qxo-2s":`Farklı sağlayıcılar arasında gönderime izin verin (varsayılan: true). Sağlayıcılar arası mesajlaşmayı engellemek için false olarak ayarlayın.`}},"tools%2Emessage%2EcrossContext%2EallowWithinProvider":{label:{"v1-1ujg1kq-z":`Bağlamlar Arası Gönderime İzin Ver (Aynı Sağlayıcı)`},help:{"v1-1sg4x49-1z":`Aynı sağlayıcı içindeki diğer kanallara gönderime izin ver (varsayılan: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eenabled":{label:{"v1-4n38r9-k":`Bağlamlar Arası Gönderim İşaretçisi`},help:{"v1-1fg6jrp-1z":`Bağlamlar arası gönderim yaparken kaynağı belirten görünür bir işaretçi ekle (varsayılan: true).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Eprefix":{label:{"v1-vaqy0z-r":`Bağlamlar Arası Gönderim İşaretçisi Ön Eki`},help:{"v1-eblsru-1p":`Bağlamlar arası gönderim işaretçileri için metin ön eki ("{channel}" desteklenir).`}},"tools%2Emessage%2EcrossContext%2Emarker%2Esuffix":{label:{"v1-wa9bei-r":`Bağlamlar Arası Gönderim İşaretçisi Son Eki`},help:{"v1-1nk0jub-1p":`Bağlamlar arası gönderim işaretçileri için metin son eki ("{channel}" desteklenir).`}},"tools%2Eprofile":{label:{"v1-89srgu-c":`Araç Profili`},help:{"v1-h6k98q-5k":`İzin verme/reddetme geçersiz kılmaları uygulanmadan önce önceden tanımlanmış bir temel araç politikası seçmek için kullanılan genel araç profili adı. Ajanlar arasında tutarlı bir ortam yapılandırması sağlamak için bunu kullanın ve profil adlarını sabit tutun.`}},"tools%2Esandbox":{label:{"v1-5qrg9w-j":`Korumalı Alan Araç Politikası`},help:{"v1-ea7awo-4k":`Korumalı alandaki ajan çalıştırmalarının farklı yetenek sınırlarına sahip olabilmesi için kullanılan araç politikası kapsayıcısı. Korumalı alan bağlamlarında daha güçlü güvenlik sağlamak için bunu kullanın.`}},"tools%2Esandbox%2Etools":{label:{"v1-y6y4ns-u":`Korumalı Alan Araç İzin Verme/Reddetme Politikası`},help:{"v1-ub701o-4t":`Ajanlar korumalı yürütme ortamlarında çalışırken uygulanan araç izin verme/reddetme politikası. Korumalı alan görevlerinin gereksiz harici eylemlere dönüşmesini önlemek için politikaları asgari düzeyde tutun.`}},"tools%2Esessions%2Evisibility":{label:{"v1-sk4wbc-o":`Oturum Araçlarının Görünürlüğü`},help:{"v1-1vtq2rh-c5":`sessions_list/sessions_history/sessions_search/sessions_send/session_status tarafından hangi oturumların hedeflenebileceğini belirler. (Varsayılan "all" = diğer ajanlar ve kullanıcılar dahil Gateway üzerindeki tüm oturumlar; "agent" = geçerli ajan kimliğindeki tüm oturumlar; "self" = yalnızca geçerli oturum; "tree" = geçerli oturum + oluşturulan alt ajan oturumları). Ajanlar arası erişim varsayılan olarak açıktır ve kapsamı tools.agentToAgent ile belirlenir; erişimi kısıtlamak için daha dar bir görünürlük kullanın.`}},"tools%2Esubagents":{label:{"v1-5a8obi-k":`Alt Ajan Araç Politikası`},help:{"v1-1xoug01-4z":`Oluşturulan alt ajanlar için, üst ajanın varsayılanlarına kıyasla araç kullanılabilirliğini kısıtlayan veya genişleten araç politikası katmanı. Görev devredilen ajanların yeteneklerini görevin amacıyla sınırlı tutmak için bunu kullanın.`}},"tools%2Esubagents%2Etools":{label:{"v1-m8ydym-v":`Alt Ajan Araç İzin/Ret Politikası`},help:{"v1-7vxsbf-5d":`Oluşturulan alt ajanların çalışma ortamlarına uygulanan araç izin/ret politikası. Bu kapsamı üst ajanın kapsamından daha dar tutun. progress_card gibi üst ajana ait araçlar, allow/alsoAllow üzerinden izin verilse bile her zaman reddedilir.`}},"tools%2Eswarm":{label:{"v1-1a8h35r-5":`Sürü`},help:{"v1-1q96vvs-45":`Toplayıcı modunda alt ajan düzenlemesi. Varsayılan olarak etkindir; devre dışı bırakmak için false olarak ayarlayın. Araç izinleri, agents_wait ve sürü oluşturma seçenekleri için geçerli olmaya devam eder.`}},"tools%2Eswarm%2EdefaultAgentId":{label:{"v1-wwvduv-j":`Sürünün Varsayılan Ajanı`},help:{"v1-p4alpg-2m":`agentId belirtilmeden yapılan sürü oluşturmaları için varsayılan hedef ajan. Alt ajan izin listesi geçerli olmaya devam eder.`}},"tools%2Eswarm%2Eenabled":{label:{"v1-1ppe1ta-c":`Sürüyü Etkinleştir`},help:{"v1-1nnnrq9-2e":`Toplayıcı modundaki alt ajanları ve agents_wait aracını etkinleştirir. Varsayılan olarak açıktır; devre dışı bırakmak için false olarak ayarlayın.`}},"tools%2Eswarm%2EmaxChildrenPerGroup":{label:{"v1-1vzvgye-t":`Sürü Grubu Başına Etkin Alt Ajan Sayısı`},help:{"v1-kfx6qp-1c":`Sürü grubu başına en fazla etkin toplayıcı alt ajan sayısı.`}},"tools%2Eswarm%2EmaxConcurrent":{label:{"v1-1dmgf1f-p":`Sürü Eşzamanlı Alt Ajan Sayısı`},help:{"v1-1d46jtm-1s":`Sürü grubu başına eşzamanlı çalışan en fazla toplayıcı alt ajan sayısı.`}},"tools%2Eswarm%2EmaxTotalPerGroup":{label:{"v1-1r1vzms-u":`Sürü Grubu Başına Toplam Alt Ajan Sayısı`},help:{"v1-1gc9vl1-1e":`Sürü grubu başına yaşam süresi boyunca oluşturulabilecek en fazla toplayıcı sayısı.`}},"tools%2Eswarm%2EwaitTimeoutSecondsMax":{label:{"v1-1naot35-q":`Sürü İçin En Uzun Bekleme Zaman Aşımı`},help:{"v1-bog18y-1g":`agents_wait tarafından kabul edilen saniye cinsinden en uzun zaman aşımı.`}},"tools%2EtoolSearch":{label:{"v1-pq1rnt-b":`Araç Arama`},help:{"v1-s0kx04-7y":`Büyük OpenClaw, MCP ve istemci araç kataloglarını kompakt hâle getirin. Ayarlanmadığında OpenClaw çalışma ortamları yapılandırılmış Tool Search özelliğini otomatik olarak kullanır; etkin Code Mode önceliklidir ve Codex kendi yerleşik aramasını kullanır. Devre dışı bırakmak için false, kod köprüsü için true olarak ayarlayın veya bir mod seçmek için nesne biçimini kullanın.`}},"tools%2EtoolSearch%2EcodeTimeoutMs":{label:{"v1-yyul8h-o":`Araç Arama Kodu Zaman Aşımı`},help:{"v1-105r499-34":"Tek bir `tool_search_code` yürütmesi için milisaniye cinsinden en uzun süre. Çalışma ortamı, değerleri desteklenen 1s..60s aralığıyla sınırlar."}},"tools%2EtoolSearch%2Eenabled":{label:{"v1-14qildc-i":`Araç Aramayı Etkinleştir`},help:{"v1-1vm3hfr-4h":"Araç Aramayı etkinleştirir. Açık olduğunda OpenClaw, gömülü çalışma ortamındaki yürütmeler sırasında büyük araç kataloglarını `tool_search_code` veya yapılandırılmış arama/açıklama/çağırma araçlarının arkasında gizler."}},"tools%2EtoolSearch%2EmaxSearchLimit":{label:{"v1-396rdd-n":`Araç Arama En Fazla Sonuç Sayısı`},help:{"v1-7du4kh-32":`Bir modelin isteyebileceği en fazla araç arama sonucu sayısı. Çalışma zamanı, değerleri desteklenen 1..50 aralığıyla sınırlar.`}},"tools%2EtoolSearch%2Emode":{label:{"v1-1qs9bxi-j":`Araç Arama Arayüzü`},help:{"v1-jybcbe-7x":'Modele sunulan arayüzü seçin: "code", `tool_search_code` aracını sunar; "tools", yedek olarak yapılandırılmış arama/açıklama/çağırma araçlarını sunar; "directory", sınırlı bir araç dizinini görünür tutar, olası veya gerekli şemaların sınırlı bir kümesini sunar ve geri kalanına erişimi arama/açıklama/çağırma işlemlerine bırakır.'}},"tools%2EtoolSearch%2EsearchDefaultLimit":{label:{"v1-fq001m-r":`Varsayılan Araç Arama Sonucu Sayısı`},help:{"v1-1uchq7t-39":"Model bir sınır belirtmediğinde döndürülen varsayılan araç arama sonucu sayısı. Çalışma zamanı bu sayıyı `maxSearchLimit` ile sınırlar."}},"tools%2EupdatePlan":{label:{"v1-1u23ymq-r":`Yapılandırılmış Plan Aracını Etkinleştir`},help:{"v1-1xgegme-4o":"Üst oturumlardaki kalıcı planlar ve açıklayıcı notlar için birleşik `progress_card` durum aracı. Varsayılan olarak etkindir; devre dışı bırakmak için false olarak ayarlayın. Alt ajanlar tarafından hiçbir zaman kullanılamaz."}},"tools%2Eweb":{label:{"v1-3b07wa-9":`Web Araçları`},help:{"v1-fpsy5-4y":`Arama/getirme sağlayıcılarını, sınırları ve yedek davranışları ayarlamak için web aracı ilkeleri grubu. Etkin ayarları API anahtarlarının kullanılabilirliği ve dış ağ bağlantısı ilkesiyle uyumlu tutun.`}},"tools%2Eweb%2Efetch%2EcacheTtlMinutes":{label:{"v1-1odhu2w-p":`Web Getirme Önbelleği TTL Süresi (dk)`},help:{"v1-1hk89qp-17":`web_fetch sonuçları için dakika cinsinden önbellek TTL süresi.`}},"tools%2Eweb%2Efetch%2Eenabled":{label:{"v1-zuwpji-l":`Web Getirme Aracını Etkinleştir`},help:{"v1-yrswld-1f":`web_fetch aracını etkinleştirin (hafif HTTP getirme).`}},"tools%2Eweb%2Efetch%2Eheaders":{label:{"v1-3129be-p":`Web İçeriği Getirme İstek Başlıkları`},help:{"v1-16bjkv5-me":"Doğrudan web_fetch istekleriyle gönderilen ek istek başlıkları; örneğin ağ geçidi yönlendirme veya kimlik doğrulama başlıkları. Yapılandırılan her değer hassas kabul edilir ve dışa sunulan yapılandırmalarda ve hata ayıklama kayıtlarında maskelenir. Değerler düz metin dizeleridir, ${VAR} değişken ikamesini ve genel $${VAR} değişmez metin kaçışını destekler ve modelin seçtiği URL'lere gönderilir. Girdiler yapılandırma yüklenirken değil, istek oluşturulurken doğrulanır; bu nedenle geçersiz bir ad veya gönderilemeyen bir değer, işlevi devre dışı bırakmak yerine atılır ve günlüğe kaydedilir. Accept, Accept-Language, User-Agent ve Transfer-Encoding gibi çerçeveleme başlıkları da atılır. Kullanıcı aracısını değiştirmek için tools.web.fetch.userAgent kullanın. Farklı kökenlere yönlendirmelerde yalnızca guarded-fetch güvenli başlık izin listesindeki başlıklar korunur ve fiilen gönderilen başlıkların değiştirilmesi, getirme önbelleğini ayrı bölümlere ayırır."}},"tools%2Eweb%2Efetch%2EmaxChars":{label:{"v1-1wbzc7m-j":`Web İçeriği Getirme Azami Karakter Sayısı`},help:{"v1-12d1fw7-1d":`web_fetch tarafından döndürülen azami karakter sayısı (fazlası kırpılır).`}},"tools%2Eweb%2Efetch%2EmaxCharsCap":{label:{"v1-141potx-o":`Web İçeriği Getirme Kesin Karakter Üst Sınırı`},help:{"v1-cl2mf1-1v":`web_fetch maxChars için kesin üst sınır (yapılandırma ve araç çağrıları için geçerlidir).`}},"tools%2Eweb%2Efetch%2EmaxRedirects":{label:{"v1-81lxou-n":`Web İçeriği Getirme Azami Yönlendirme Sayısı`},help:{"v1-t6eak9-1h":`web_fetch için izin verilen azami yönlendirme sayısı (varsayılan: 3).`}},"tools%2Eweb%2Efetch%2EmaxResponseBytes":{label:{"v1-uabe8-z":`Web İçeriği Getirme Azami İndirme Boyutu (bayt)`},help:{"v1-q6ld9c-10":`Kırpma öncesindeki azami indirme boyutu.`}},"tools%2Eweb%2Efetch%2Eprovider":{label:{"v1-1xu05t2-i":`Web İçeriği Getirme Sağlayıcısı`},help:{"v1-6pb3nv-v":`Web içeriği getirme için yedek sağlayıcı kimliği.`}},"tools%2Eweb%2Efetch%2Ereadability":{label:{"v1-32zds-w":`Web İçeriği Getirmede Readability ile İçerik Çıkarma`},help:{"v1-19exqzx-2c":`HTML'den ana içeriği çıkarmak için Readability kullanın (başarısız olursa temel HTML temizliğine başvurulur).`}},"tools%2Eweb%2Efetch%2EssrfPolicy":{label:{"v1-jaq5z9-l":`Web İçeriği Getirme SSRF İlkesi`},help:{"v1-qtn7zx-3c":`web_fetch için kapsamı sınırlı SSRF ilkesi geçersiz kılmaları. Kapsamı dar tutun ve yalnızca bilinen yerel ağ proxy ortamları için etkinleştirin.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowedHostnames":{label:{"v1-1r9zld3-r":`Web İçeriği Getirmede İzin Verilen Ana Makine Adları`},help:{"v1-1j9ctya-35":`Normalde engellenen hedefler de dahil olmak üzere web_fetch için izin verilen tam ana makine adları veya doğrudan IP adresleri. Listeyi olabildiğince kısa tutun.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowIpv6UniqueLocalRange":{label:{"v1-t82ara-13":`Web İçeriği Getirmede IPv6 Benzersiz Yerel Adres Aralığına İzin Ver`},help:{"v1-1eyz55i-3b":`sing-box, Clash veya Surge gibi güvenilir sahte IP proxy'leriyle uyumluluk için IPv6 Benzersiz Yerel Adreslerine (fc00::/7) izin verin.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EallowRfc2544BenchmarkRange":{label:{"v1-4hkyhg-14":`Web İçeriği Getirmede RFC 2544 Performans Testi Aralığına İzin Ver`},help:{"v1-u5asdb-2y":`Clash veya Surge gibi sahte IP proxy'leriyle uyumluluk için RFC 2544 performans testi aralığındaki IP adreslerine (198.18.0.0/15) izin verin.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EblockedHostnames":{label:{"v1-1gm3p1b-r":`Web İçeriği Getirmede Engellenen Ana Makine Adları`},help:{"v1-1164vvk-66":`Her web_fetch yönlendirmesinde DNS ve izin kurallarından önce reddedilen ana makine adı kalıpları. Tam ana makine adlarını ve yalnızca alt alan adları için "*.example.com" kalıbını destekler; kök alan adını engellemek için "example.com" adresini ayrıca ekleyin. Boş bırakılırsa veya ayarlanmazsa ek engelleme uygulanmaz.`}},"tools%2Eweb%2Efetch%2EssrfPolicy%2EdangerouslyAllowPrivateNetwork":{label:{"v1-1rhrboq-17":`Web İçeriği Getirmede Özel Ağa Tehlikeli Erişime İzin Ver`},help:{"v1-2s6mv7-3t":`web_fetch aracının özel ve dahili ağ hedeflerine erişmesine izin verir. Bu dağıtımda modelin seçtiği URL'lere güvenilmiyorsa devre dışı bırakın.`}},"tools%2Eweb%2Efetch%2EtimeoutSeconds":{label:{"v1-ry7npa-n":`Web İçeriği Getirme Zaman Aşımı (sn)`},help:{"v1-1c3yfr4-16":`web_fetch istekleri için saniye cinsinden zaman aşımı.`}},"tools%2Eweb%2Efetch%2EuserAgent":{label:{"v1-5t3azc-k":`Web İçeriği Getirme User-Agent Değeri`},help:{"v1-s7pe8j-1e":`web_fetch istekleri için User-Agent üst bilgisini geçersiz kılın.`}},"tools%2Eweb%2Efetch%2EuseTrustedEnvProxy":{label:{"v1-1pkpnd9-r":`Web İçeriği Getirme İçin Güvenilir Ortam Proxy'si`},help:{"v1-1ypkqj7-54":`web_fetch isteklerini ortam değişkenleriyle tanımlanan güvenilir bir HTTP(S) proxy'si üzerinden yönlendirin ve DNS çözümlemesini proxy'ye bırakın. Yalnızca bu proxy operatörün denetimindeyse ve DNS çözümlemesinden sonra giden trafik politikasını uyguluyorsa etkinleştirin.`}},"tools%2Eweb%2Esearch%2EcacheTtlMinutes":{label:{"v1-14u7axu-q":`Web Araması Önbellek TTL Değeri (dk)`},help:{"v1-6trzlf-18":`web_search sonuçları için dakika cinsinden önbellek TTL değeri.`}},"tools%2Eweb%2Esearch%2Eenabled":{label:{"v1-1yn3rki-m":`Web Arama Aracını Etkinleştir`},help:{"v1-n1cm4y-27":`Uygun modeller için yönetilen web_search aracını ve isteğe bağlı Codex yerleşik aramasını etkinleştirin.`}},"tools%2Eweb%2Esearch%2EmaxResults":{label:{"v1-jy940f-m":`Web Araması Maksimum Sonuç Sayısı`},help:{"v1-mrw7mi-z":`Döndürülecek sonuç sayısı (1-10).`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EallowedDomains":{label:{"v1-aqtmld-l":`Codex İzin Verilen Alan Adları`},help:{"v1-1cv4y44-43":`Yerleşik Codex web_search için izin verilen alan adları listesi. Yerleşik olarak barındırılan arama turlarında, yönetilen web_fetch erişimini de sınırlar; yönetilen sağlayıcı turları değişmez.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EcontextSize":{label:{"v1-1s2nw4o-p":`Codex Arama Bağlamı Boyutu`},help:{"v1-antack-1u":`Yerleşik Codex arama bağlamı boyutu ipucu: "low", "medium" veya "high".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Eenabled":{label:{"v1-1eejtq4-u":`Yerleşik Codex Web Aramasını Etkinleştir`},help:{"v1-ek2jzd-1k":`Codex destekleyen modeller için yerleşik Codex web aramasını etkinleştirin.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2Emode":{label:{"v1-1eic0y9-l":`Codex Web Arama Modu`},help:{"v1-1ahyq9f-32":`Yerleşik Codex web araması tercihi: "cached" (varsayılan; kısıtlanmamış Codex turlarında "live" olarak uygulanır) veya "live".`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecity":{label:{"v1-1p5e722-f":`Codex Kullanıcısının Şehri`},help:{"v1-1y95orp-1d":`Yerleşik Codex web aramasına gönderilen yaklaşık şehir bilgisi.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Ecountry":{label:{"v1-u0nthl-i":`Codex Kullanıcısının Ülkesi`},help:{"v1-1xkm5ms-1g":`Yerleşik Codex web aramasına gönderilen yaklaşık ülke bilgisi.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Eregion":{label:{"v1-1pmca79-h":`Codex Kullanıcısının Bölgesi`},help:{"v1-lhar02-1l":`Codex'in yerleşik web aramasına gönderilen yaklaşık bölge/eyalet.`}},"tools%2Eweb%2Esearch%2EopenaiCodex%2EuserLocation%2Etimezone":{label:{"v1-by3d62-j":`Codex Kullanıcısının Saat Dilimi`},help:{"v1-fgv9fh-1h":`Codex'in yerleşik web aramasına gönderilen yaklaşık saat dilimi.`}},"tools%2Eweb%2Esearch%2Eprovider":{label:{"v1-rztytk-j":`Web Arama Sağlayıcısı`},help:{"v1-10omglr-1x":`Arama sağlayıcısının kimliği. Belirtilmezse mevcut API anahtarlarından otomatik olarak algılanır.`}},"tools%2Eweb%2Esearch%2EtimeoutSeconds":{label:{"v1-2gxsb4-o":`Web Araması Zaman Aşımı (sn)`},help:{"v1-i0egvw-17":`web_search istekleri için saniye cinsinden zaman aşımı.`}},transcripts:{label:{"v1-1iqk6o8-b":`Transkriptler`},help:{"v1-1i0sc09-66":`Toplantı notları, kayıt yapabilen ajan araçları ve yapılandırılmış canlı toplantı otomatik başlatma kaynakları için temel transkript kaydı ayarları. Toplantı eklentileri varsayılan olarak kalıcı notlar kaydeder; bunu genel olarak devre dışı bırakmak için enabled değerini false olarak ayarlayın.`}},"transcripts%2EautoStart":{label:{"v1-1ocjrmc-u":`Transkript Otomatik Başlatma Kaynakları`},help:{"v1-1mzsl79-5s":`Gateway başlangıcından itibaren otomatik olarak yönetilen canlı transkript kaynakları. Her girdi, mevcut olmasıyla etkinleşir; ilgili kaynağı devre dışı bırakmak için girdiyi kaldırın. whenOccupied etkinleştirilmedikçe kaynaklar sürekli kayıt yapar.`}},"transcripts%2EautoStart%5B%5D%2EaccountId":{label:{"v1-1ffe8lp-l":`Transkript Hesap Kimliği`},help:{"v1-6g2kjj-4b":`Hesapların birbirinden ayırt edilmesini gerektiren transkript kaynakları için isteğe bağlı sağlayıcı hesabı veya çalışma alanı tanımlayıcısı. Sağlayıcının belgelerinde belirtilen hesap kimliği biçimini kullanın.`}},"transcripts%2EautoStart%5B%5D%2EchannelId":{label:{"v1-ujvqt-l":`Transkript Kanal Kimliği`},help:{"v1-1lk9d5o-4u":`Discord ses kanalı veya Slack sesli görüşme kanalı gibi canlı transkript kaynağının sağlayıcı kanal kimliği. Otomatik başlatmayı etkinleştirmeden önce sağlayıcıya özgü kimliklerin anlamını doğrulayın.`}},"transcripts%2EautoStart%5B%5D%2EguildId":{label:{"v1-tdpg2t-g":`Discord Sunucu Kimliği`},help:{"v1-fyfgnk-4l":`Discord sesli transkript kaynakları için isteğe bağlı Discord sunucu kimliği. Sağlayıcının sunucu kapsamında ses kanalı araması yapması gerektiğinde bunu eşleşen channelId ile yapılandırın.`}},"transcripts%2EautoStart%5B%5D%2EmeetingUrl":{label:{"v1-f1fo9f-m":`Transkript Toplantı URL'si`},help:{"v1-1xtt9ci-4f":`Kanal kimliği yerine URL ile katılan sağlayıcılar için isteğe bağlı toplantı URL'si. Otomatik başlatma bu toplantıya katılıp toplantıyı kaydedebileceğinden yalnızca güvenilir toplantı bağlantılarını kullanın.`}},"transcripts%2EautoStart%5B%5D%2EproviderId":{label:{"v1-1dnfgvi-t":`Transkript Kaynağı Sağlayıcı Kimliği`},help:{"v1-1uur06p-3s":`Discord sesli görüşme sağlayıcısı veya gelecekteki bir Slack sesli görüşme sağlayıcısı gibi transkript kaynağı sağlayıcısının kimliği. Sağlayıcı eklentisinin sunduğu kimliği tam olarak kullanın.`}},"transcripts%2EautoStart%5B%5D%2EsessionId":{label:{"v1-1q57lkc-l":`Transkript Oturum Kimliği`},help:{"v1-xyo4x5-5o":`Bu otomatik başlatma kaynağı için isteğe bağlı sabit transkript oturum kimliği. whenOccupied değeri true olduğunda yok sayılır. Sabit bir günlük seçiciye ihtiyacınız yoksa veya aynı gün içindeki çakışmaları önleyemiyorsanız kimliklerin otomatik oluşturulması için ayarlanmamış bırakın.`}},"transcripts%2EautoStart%5B%5D%2Etitle":{label:{"v1-11w5opp-g":`Transkript Başlığı`},help:{"v1-ycjnmp-5y":`Gelecekteki transkript kayıtları için isteğe bağlı başlık. Yalnızca başlıkların değiştirilmesi mevcut kayıtları çalışır durumda tutar ve başlangıçta atanan başlıklarını veya kaydedilmiş notlarını yeniden adlandırmaz. Diğer kaynak değişikliklerinde normal yeniden başlatma davranışı korunur.`}},"transcripts%2EautoStart%5B%5D%2EwhenOccupied":{label:{"v1-12ewhvp-w":`Katılımcı Varken Transkript Kaydı`},help:{"v1-34jid4-78":`Kaynakta insan katılımcılar her bulunduğunda yeni bir transkript oturumu başlatır ve son insan katılımcı ayrıldıktan sonra notlar oluşturarak oturumu durdurur. discord-voice gibi katılımcı varlığını bildiren bir sağlayıcı gerektirir. Varsayılan: false (gateway başlatıldığından itibaren sürekli kayıt yapar).`}},"transcripts%2Eenabled":{label:{"v1-d2c4ax-j":`Transkriptler Etkin`},help:{"v1-fyqqr0-6d":`Kalıcı otomatik toplantı notlarını, transcripts ajan aracını ve yapılandırılmış otomatik başlatma kaynaklarını etkinleştirir. Varsayılan: true. Kalıcı kaydı ve aracı devre dışı bırakmak için false olarak ayarlayın; açıkça seçilen toplantı transkripsiyon modu, sınırlı canlı son bölümünü korur.`}},tts:{label:{"v1-bmxkk9-e":`Metinden Konuşmaya`},help:{"v1-1o27tk2-4n":`Desteklenen sesli arayüzlerde ajan yanıtlarının sesli okunmasına yönelik metinden konuşmaya politikası. Sesli oynatma, operatör/kullanıcı iş akışınızın bir parçası değilse devre dışı bırakın.`}},"tts%2Epersona":{label:{"v1-118fea6-b":`TTS Kişiliği`},help:{"v1-1r0opcb-29":`Varsayılan TTS kişiliği kimliği. Yerel TTS kişiliği tercihleri, ana makine bazında bu ayarı geçersiz kılabilir.`}},"tts%2Epersonas":{label:{"v1-1gi7idj-c":`TTS Kişilikleri`},help:{"v1-19aybhl-2l":`Tutarlı bir konuşma kimliği ve sağlayıcıya özgü konuşma eşlemeleri tanımlayan adlandırılmış TTS kişilikleri.`}},"tts%2Epersonas%2E*":{label:{"v1-118fea6-b":`TTS Kişiliği`},help:{"v1-10s52ah-2l":`Tek bir TTS kişiliği. Belirli sesler/modeller ve istem şablonları için sağlayıcıya özgü eşlemeleri kullanın.`}},"tts%2Epersonas%2E*%2Eproviders":{label:{"v1-dji537-t":`TTS Persona Sağlayıcı Eşlemeleri`},help:{"v1-993jop-3e":`Konuşma sağlayıcısı kimliğine göre anahtarlanan, sağlayıcıya özgü TTS persona eşlemeleri. Etkin persona için tts.providers ile birleştirilir ve mevcut değerlerin üzerine yazılır.`}},"tts%2Eproviders":{label:{"v1-1y7c1ro-l":`TTS Sağlayıcı Ayarları`},help:{"v1-1k80nl4-4y":`Konuşma sağlayıcısı kimliğine göre anahtarlanan, sağlayıcıya özgü TTS ayarları. Konuşma eklentilerinin temel yapılandırma şemasından bağımsız kalması için yerleşik, sağlayıcıya özgü üst düzey anahtarlar yerine bunu kullanın.`}},"tts%2Eproviders%2E*":{label:{"v1-15ged0b-j":`TTS Sağlayıcı Yapılandırması`},help:{"v1-dwapva-3d":`Tek bir konuşma sağlayıcısı kimliği için sağlayıcıya özgü TTS yapılandırması. Alanları, bu sağlayıcının sahibi olan eklentinin kapsamıyla sınırlı tutun.`}},"tts%2Eproviders%2E*%2EapiKey":{label:{"v1-68k8k0-k":`TTS Sağlayıcı API Anahtarı`},help:{"v1-1m2fj0i-2o":`Eklentisi kimlik doğrulamalı TTS erişimi gerektirdiğinde ilgili konuşma sağlayıcısının kullandığı sağlayıcı API anahtarı.`}},tui:{label:{"v1-c8hus1-b":`Terminal Arayüzü`},help:{"v1-1fg9vw2-3s":`Terminal arayüzü görüntüleme ayarları. Gateway veya diğer arayüzlerin davranışını değiştirmeden, yalnızca terminale yönelik görünüm tercihleri için bu bölümü kullanın.`}},"tui%2Efooter":{label:{"v1-1nnfi3c-i":`Terminal Arayüzü Alt Bilgisi`},help:{"v1-6e12l3-3k":`Terminal arayüzü alt bilgisi görüntüleme ayarları. Oturum, model, hedef ve token bilgilerinin okunabilir kalması için isteğe bağlı bağlamı kısa tutun.`}},ui:{label:{"v1-ye4dff-2":`Kullanıcı arayüzü`},help:{"v1-dt1924-42":`Vurgu ve operatörün görüntüleme tercihleri için arayüz görünüm ayarları. Çalışma zamanı davranışını değiştirmeden okunabilirliği özelleştirmek için bunu kullanın.`}},"ui%2Eprefs%2Eaccent":{label:{"v1-1e4sxpj-h":`Kullanıcı Vurgu Rengi`},help:{"v1-16klzws-4z":`Control UI vurgu rengi: özel bir renk için #RRGGBB veya seçili temanın paleti için 'theme'. ui.seamColor değerini geçersiz kılar; yapılandırılmış birleşim çizgisi rengini veya temanın varsayılanını devralmak için bu alanı temizleyin.`}},"ui%2EseamColor":{label:{"v1-1ddt13c-c":`Vurgu Rengi`},help:{"v1-14q3r4h-4g":`Arayüz alanlarında vurgulama, rozetler ve görsel kimlik öğeleri için kullanılan birincil vurgu rengi. Açık ve koyu temalarda okunabilirliği koruyan yüksek kontrastlı değerler kullanın.`}},update:{label:{"v1-k12u1x-7":`Güncellemeler`},help:{"v1-11c5k8v-5c":`OpenClaw çalışma zamanı sürümlerini güncel tutmak için güncelleme kanalı ve başlangıç denetimi davranışı. Üretim ortamlarında daha temkinli kanalları, daha deneysel kanalları ise yalnızca kontrollü ortamlarda kullanın.`}},"update%2Eauto%2Eenabled":{label:{"v1-1ahdhbe-j":`Otomatik Güncelleme Etkin`},help:{"v1-49xs2h-3c":`stable ve beta paket kurulumları için arka planda otomatik güncellemeyi etkinleştirir; extended-stable güncellemeleri hiçbir zaman otomatik uygulanmaz (varsayılan: false).`}},"update%2Echannel":{label:{"v1-zk8ncv-e":`Güncelleme Kanalı`},help:{"v1-lqtdvf-5b":`git + npm kurulumları için güncelleme kanalı ("stable", "extended-stable", "beta" veya "dev"). extended-stable yalnızca paket kurulumları içindir: kurulum yalnızca ön planda yapılır ve isteğe bağlı olarak başlangıçta salt okunur ipuçları gösterilir.`}},"update%2EcheckOnStart":{label:{"v1-10js111-l":`Başlangıçta Güncelleme Denetimi`},help:{"v1-qy3q9g-5v":`Gateway başlatıldığında, salt okunur extended-stable bildirimleri de dahil olmak üzere güncellemeleri kontrol eder (varsayılan: true). Gateway ve grafik arayüzü olmayan düğümler için otomatik güncelleme kontrollerini, güncellemelerin uygulanmasını ve anonim güncelleme sinyallerini devre dışı bırakmak için false olarak ayarlayın.`}},voicewake:{label:{"v1-txt1wb-a":`Sesle uyandırma`}},web:{label:{"v1-1ae9z56-b":`Web Kanalı`}},wizard:{label:{"v1-28jonk-h":`Kurulum Tercihleri`},help:{"v1-14jh6rm-3b":`Kullanıcıya ait kurulum tercihleri. Makineye ait sihirbaz geçmişi ve onay durumu, paylaşılan durum veritabanında saklanır.`}},"wizard%2EaccessMode":{label:{"v1-1ayx2hy-m":`Kurulum Keşfi Erişimi`},help:{"v1-1nqxt0w-38":`Rehberli kurulum için keşif izni: "full" sessizce tarama yapar, "guarded" ise yerel uygulamaları incelemeden önce izin ister.`}},"wizard%2EappRecommendations":{label:{"v1-jc89qd-p":`Kurulum Uygulama Önerileri`},help:{"v1-ub8uoi-30":`Rehberli kurulumun ilgili eklentileri ve becerileri önermek için yüklü uygulamaların etiketlerini kullanıp kullanamayacağını belirler.`}},"wizard%2ElastRunAt":{label:{"v1-1puf3az-p":`Sihirbazın Son Çalıştırılma Zaman Damgası`},help:{"v1-1y0fbk-1k":`Sihirbazın başarıyla kaydedilen son çalıştırılmasının zaman damgası.`}},"wizard%2ElastRunCommand":{label:{"v1-3f99ei-n":`Sihirbazın Son Çalıştırılma Komutu`},help:{"v1-x2pfkk-15":`Sihirbazın son çalıştırılmasını başlatan komut.`}},"wizard%2ElastRunCommit":{label:{"v1-1a2uglw-m":`Sihirbazın Son Çalıştırılmasındaki Commit`},help:{"v1-h0jkmt-1i":`Geliştirme sihirbazının son çalıştırılmasında kullanılan kaynak kod commit'i.`}},"wizard%2ElastRunMode":{label:{"v1-p2iydm-k":`Sihirbazın Son Çalıştırılma Modu`},help:{"v1-16508qy-1r":`Sihirbazın son çalıştırılmasında "local" veya "remote" kurulumun hangisinin hedeflendiği.`}},"wizard%2ElastRunVersion":{label:{"v1-1kvlwlr-n":`Sihirbazın Son Çalıştırılmasındaki Sürüm`},help:{"v1-1tr4z9d-19":`Sihirbazın son çalıştırılmasında kullanılan OpenClaw sürümü.`}},"wizard%2EsecurityAcknowledgedAt":{label:{"v1-17xanyw-15":`Sihirbaz Güvenlik Onayı Zaman Damgası`},help:{"v1-86i182-2a":`Hedef yapılandırmayla birlikte kaydedilen kurulum güvenlik onayının zaman damgası.`}},worktreeAcceleration:{label:{"v1-128z6h8-l":`Çalışma Ağacı Hızlandırma`},help:{"v1-9es3gc-4r":`Desteklendiğinde yeni yönetilen çalışma ağaçları için dosya sistemi hızlandırmasını kullanın (varsayılan: true). Normal Git checkout ve dosya kopyalama işlemlerini kullanmak için false olarak ayarlayın. Yalnızca yeni çalışma ağaçlarına uygulanır.`}},worktreeRoot:{label:{"v1-bqutg0-d":`Çalışma Ağacı Kök Dizini`},help:{"v1-1tgti9j-5d":`Yeni yönetilen çalışma ağaçları için genel dizin. Mutlak bir yol veya ana dizininiz için ~ kullanın; varsayılan değer <state-dir>/worktrees şeklindedir. Bu ayar değiştiğinde mevcut çalışma ağaçları kayıtlı yollarını korur.`}}}}})))()}export{t as n,n as t};